CREATE OR REPLACE FUNCTION "public"."accept_offer"("p_application_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_job_id UUID;
BEGIN
    SELECT job_id INTO v_job_id FROM public.job_applications WHERE id = p_application_id;
    UPDATE public.job_applications SET status = 'accepted' WHERE id = p_application_id;
    UPDATE public.jobs SET status = 'in_progress', hired_inspector_id = auth.uid() WHERE id = v_job_id;
    INSERT INTO public.conversations (job_id, client_id, inspector_id)
    SELECT id, client_id, hired_inspector_id FROM public.jobs WHERE id = v_job_id ON CONFLICT DO NOTHING;
END;
$$;


