CREATE OR REPLACE FUNCTION "public"."admin_accept_goods"("p_deal_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.nx_is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  UPDATE public.deals SET goods_accepted_at = COALESCE(goods_accepted_at, now()), goods_accepted_by = auth.uid()
   WHERE id = p_deal_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown_deal'; END IF;
  RETURN jsonb_build_object('deal_id', p_deal_id, 'goods_accepted', true);
END $$;


ALTER FUNCTION "public"."admin_accept_goods"("p_deal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_assign_inspector"("p_deal_id" "uuid", "p_inspector_id" "uuid", "p_payout_cents" bigint, "p_routing" "text" DEFAULT 'broker_assignment'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_routing text;
BEGIN
  IF NOT public.nx_is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  IF p_inspector_id IS NULL THEN RAISE EXCEPTION 'inspector_required'; END IF;
  IF p_payout_cents IS NULL OR p_payout_cents < 0 THEN RAISE EXCEPTION 'invalid_payout'; END IF;
  v_routing := CASE WHEN p_routing IN ('broker_assignment','algorithmic_match','client_selection')
                    THEN p_routing ELSE 'broker_assignment' END;
  RETURN public._brokered_create_engagement(p_deal_id, p_inspector_id, p_payout_cents, v_routing, 'pending');
END $$;


ALTER FUNCTION "public"."admin_assign_inspector"("p_deal_id" "uuid", "p_inspector_id" "uuid", "p_payout_cents" bigint, "p_routing" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_auto_match_inspector"("p_deal_id" "uuid", "p_payout_cents" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_top uuid; v_score numeric; v_res jsonb;
BEGIN
  IF NOT public.nx_is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  IF p_payout_cents IS NULL OR p_payout_cents < 0 THEN RAISE EXCEPTION 'invalid_payout'; END IF;
  SELECT s.inspector_id, s.score INTO v_top, v_score FROM public._brokered_score_inspectors(p_deal_id) s LIMIT 1;
  IF v_top IS NULL THEN RAISE EXCEPTION 'no_eligible_inspector'; END IF;
  v_res := public._brokered_create_engagement(p_deal_id, v_top, p_payout_cents, 'algorithmic_match', 'pending');
  RETURN v_res || jsonb_build_object('match_score', v_score, 'auto', true);
END $$;


ALTER FUNCTION "public"."admin_auto_match_inspector"("p_deal_id" "uuid", "p_payout_cents" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_cancel_job"("p_job_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor        uuid;
  v_actor_role   text;
  v_job          public.jobs%ROWTYPE;
  v_correlation  uuid := gen_random_uuid();
  v_clean_reason text;
BEGIN
  -- ── 1. Auth ────────────────────────────────────────────────────────
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT role INTO v_actor_role
  FROM public.profiles
  WHERE id = v_actor;

  IF v_actor_role IS DISTINCT FROM 'super_admin' THEN
    RAISE EXCEPTION 'Only super_admin can call admin_cancel_job' USING ERRCODE = '42501';
  END IF;

  -- ── 2. Input validation ───────────────────────────────────────────
  IF p_job_id IS NULL THEN
    RAISE EXCEPTION 'job_id is required' USING ERRCODE = '22000';
  END IF;
  v_clean_reason := NULLIF(TRIM(COALESCE(p_reason, '')), '');
  IF v_clean_reason IS NULL THEN
    RAISE EXCEPTION 'A reason is required when admin cancels a job' USING ERRCODE = '22000';
  END IF;
  IF length(v_clean_reason) > 500 THEN
    v_clean_reason := left(v_clean_reason, 500);
  END IF;

  -- ── 3. Audit annotation ───────────────────────────────────────────
  PERFORM public.audit_set_correlation(v_correlation);
  PERFORM public.audit_set_intent('Admin cancelled job — ' || v_clean_reason);

  -- ── 4. Lock + validate ────────────────────────────────────────────
  SELECT * INTO v_job FROM public.jobs WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Job not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_job.status IN ('completed', 'cancelled') THEN
    RAISE EXCEPTION 'Job is already in terminal state (%) and cannot be cancelled', v_job.status
      USING ERRCODE = '22000';
  END IF;

  -- ── 5. Flip status ────────────────────────────────────────────────
  UPDATE public.jobs
  SET status         = 'cancelled',
      cancelled_at   = now(),
      cancelled_by   = v_actor,
      cancel_reason  = v_clean_reason,
      updated_at     = now()
  WHERE id = p_job_id;

  RETURN jsonb_build_object(
    'ok',             true,
    'job_id',         p_job_id,
    'from_status',    v_job.status,
    'to_status',      'cancelled',
    'correlation_id', v_correlation
  );
END;
$$;


ALTER FUNCTION "public"."admin_cancel_job"("p_job_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_cancel_job"("p_job_id" "uuid", "p_reason" "text") IS 'Super_admin cancels a job from any non-terminal state. A reason is required and is captured into the audit event.';



CREATE OR REPLACE FUNCTION "public"."admin_counter_application"("p_application_id" "uuid", "p_counter_cents" bigint, "p_comment" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_app RECORD;
  v_uid uuid := auth.uid();
BEGIN
  IF NOT public.nx_is_admin() THEN
    RAISE EXCEPTION 'admin only';
  END IF;
  IF p_counter_cents IS NULL OR p_counter_cents < 0 THEN
    RAISE EXCEPTION 'counter must be non-negative';
  END IF;

  UPDATE public.applications SET
    admin_counter_cents = p_counter_cents,
    admin_comment       = p_comment,
    admin_countered_at  = NOW(),
    admin_countered_by  = v_uid,
    negotiation_status  = 'admin_countered',
    -- Reset any prior inspector decision when a new counter arrives
    inspector_decision      = NULL,
    inspector_decision_note = NULL,
    inspector_decision_at   = NULL
  WHERE id = p_application_id
  RETURNING * INTO v_app;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'application not found';
  END IF;

  -- Notify the inspector
  BEGIN
    PERFORM public.notify_safe(
      v_app.applicant_id,
      'application_status',
      'Counter offer received',
      'Admin proposed a new payout — open your dashboard to accept or decline.',
      '/inspector/assignments?app=' || v_app.id::text,
      v_app.job_id
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'notify failed: %', SQLERRM;
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'application_id', v_app.id,
    'admin_counter_cents', v_app.admin_counter_cents,
    'negotiation_status', v_app.negotiation_status
  );
END $$;


ALTER FUNCTION "public"."admin_counter_application"("p_application_id" "uuid", "p_counter_cents" bigint, "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_counter_revision"("p_revision_id" "uuid", "p_counter_amount_cents" bigint, "p_admin_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_r public.deal_revisions; v_n int;
BEGIN
  IF NOT public.nx_is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  IF p_counter_amount_cents IS NULL OR p_counter_amount_cents < 0 THEN RAISE EXCEPTION 'invalid_amount'; END IF;
  SELECT * INTO v_r FROM public.deal_revisions WHERE id = p_revision_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown_revision'; END IF;
  IF v_r.status <> 'requested' THEN RAISE EXCEPTION 'REVISION_NOT_OPEN_FOR_COUNTER: status=%', v_r.status; END IF;
  SELECT count(*) INTO v_n FROM public.deal_revision_events WHERE revision_id = p_revision_id;
  IF v_n >= 10 THEN RAISE EXCEPTION 'REVISION_ROUNDS_EXCEEDED'; END IF;

  UPDATE public.deal_revisions SET status = 'countered', counter_amount_cents = p_counter_amount_cents, decided_by = auth.uid()
   WHERE id = p_revision_id;
  PERFORM public._revision_log(p_revision_id, auth.uid(), 'nexpec', 'counter', p_counter_amount_cents, NULL, p_admin_note);
  PERFORM public._revision_notify(v_r.counterparty_id, 'NEXPEC countered your revision', 'NEXPEC has proposed a counter figure for your review.', v_r.deal_id);
  RETURN jsonb_build_object('revision_id', p_revision_id, 'status', 'countered');
END $$;


ALTER FUNCTION "public"."admin_counter_revision"("p_revision_id" "uuid", "p_counter_amount_cents" bigint, "p_admin_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_countersign_supplier_contract"("p_contract_id" "uuid", "p_typed_name" "text", "p_ip" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE v_c RECORD; v_seal text; v_when timestamptz := now();
BEGIN
  IF NOT public.nx_is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  SELECT * INTO v_c FROM public.supplier_contracts WHERE id = p_contract_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'contract_not_found'; END IF;
  IF v_c.status <> 'pending_admin_countersignature' THEN RAISE EXCEPTION 'contract not awaiting countersignature (status=%)', v_c.status; END IF;
  IF p_typed_name IS NULL OR length(trim(p_typed_name)) < 2 THEN RAISE EXCEPTION 'type your full legal name to countersign'; END IF;

  -- Tamper-evident seal over the executed terms (Trust-Spine style fingerprint).
  v_seal := encode(extensions.digest(convert_to(
      coalesce(v_c.id::text,'') || '|' || coalesce(v_c.quote_id::text,'') || '|' ||
      coalesce(v_c.supplier_id::text,'') || '|' || coalesce(v_c.amount_cents::text,'') || '|' ||
      coalesce(v_c.supplier_signed_name,'') || '|' || coalesce(v_c.supplier_signed_at::text,'') || '|' ||
      trim(p_typed_name) || '|' || coalesce(v_when::text,'') || '|' || coalesce(v_c.contract_text_md,''),
      'utf8'), 'sha256'), 'hex');

  UPDATE public.supplier_contracts
     SET admin_signed_at = v_when, admin_signed_name = trim(p_typed_name), admin_signed_ip = p_ip,
         admin_signed_by = auth.uid(), status = 'executed', executed_at = v_when, content_sha256 = v_seal
   WHERE id = p_contract_id;

  BEGIN
    PERFORM public.create_system_notification(
      v_c.supplier_id, 'Agreement executed',
      'Your NEXPEC supplier agreement is fully signed. Brokered payouts can now be released.',
      'contract_assigned', '/suppliers/contracts/' || p_contract_id::text, v_c.job_id);
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object('ok', true, 'status', 'executed', 'content_sha256', v_seal);
END $$;


ALTER FUNCTION "public"."admin_countersign_supplier_contract"("p_contract_id" "uuid", "p_typed_name" "text", "p_ip" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_decide_revision"("p_revision_id" "uuid", "p_decision" "text", "p_admin_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_r public.deal_revisions;
BEGIN
  IF NOT public.nx_is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  IF p_decision NOT IN ('accept','reject') THEN RAISE EXCEPTION 'invalid_decision'; END IF;
  SELECT * INTO v_r FROM public.deal_revisions WHERE id = p_revision_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown_revision'; END IF;
  IF v_r.status <> 'requested' THEN RAISE EXCEPTION 'REVISION_NOT_OPEN: status=%', v_r.status; END IF;

  IF p_decision = 'reject' THEN
    UPDATE public.deal_revisions SET status = 'rejected', decided_by = auth.uid(), decided_at = now() WHERE id = p_revision_id;
    PERFORM public._revision_log(p_revision_id, auth.uid(), 'nexpec', 'reject', NULL, NULL, p_admin_note);
    PERFORM public._revision_notify(v_r.counterparty_id, 'Revision declined', 'NEXPEC has declined your price-revision request.', v_r.deal_id);
    RETURN jsonb_build_object('revision_id', p_revision_id, 'status', 'rejected');
  END IF;

  -- accept = NEXPEC consents to the party's latest proposal → apply
  PERFORM public._revision_log(p_revision_id, auth.uid(), 'nexpec', 'accept', v_r.proposed_amount_cents, NULL, p_admin_note);
  PERFORM public._apply_revision(p_revision_id, v_r.proposed_amount_cents, auth.uid());
  PERFORM public._revision_notify(v_r.counterparty_id, 'Revision accepted', 'NEXPEC accepted your revision; a superseding contract has been issued.', v_r.deal_id);
  RETURN jsonb_build_object('revision_id', p_revision_id, 'status', 'applied', 'agreed_amount_cents', v_r.proposed_amount_cents);
END $$;


ALTER FUNCTION "public"."admin_decide_revision"("p_revision_id" "uuid", "p_decision" "text", "p_admin_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_dispatch_job"("p_job_id" "uuid", "p_application_id" "uuid", "p_client_price_cents" bigint, "p_payout_cents" bigint, "p_payout_status" "text" DEFAULT 'unpaid'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor             uuid;
  v_actor_role        text;
  v_job               public.jobs%ROWTYPE;
  v_app               public.applications%ROWTYPE;
  v_correlation       uuid := gen_random_uuid();
  v_rejected_count    int  := 0;
BEGIN
  -- ── 1. Authentication ────────────────────────────────────────────
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  -- ── 2. Authorization: super_admin only ───────────────────────────
  SELECT role INTO v_actor_role
  FROM public.profiles
  WHERE id = v_actor;

  IF v_actor_role NOT IN ('admin','super_admin') THEN
    RAISE EXCEPTION 'Only super_admin can dispatch jobs' USING ERRCODE = '42501';
  END IF;

  -- ── 3. Input validation ──────────────────────────────────────────
  IF p_job_id IS NULL OR p_application_id IS NULL THEN
    RAISE EXCEPTION 'job_id and application_id are required' USING ERRCODE = '22000';
  END IF;
  IF p_client_price_cents IS NULL OR p_client_price_cents <= 0 THEN
    RAISE EXCEPTION 'Client price must be greater than zero' USING ERRCODE = '22000';
  END IF;
  IF p_payout_cents IS NULL OR p_payout_cents <= 0 THEN
    RAISE EXCEPTION 'Inspector payout must be greater than zero' USING ERRCODE = '22000';
  END IF;
  IF p_payout_cents > p_client_price_cents THEN
    RAISE EXCEPTION 'Inspector payout cannot exceed client price' USING ERRCODE = '22000';
  END IF;

  -- ── 4. Audit grouping (Phase 5 integration) ──────────────────────
  PERFORM public.audit_set_correlation(v_correlation);
  PERFORM public.audit_set_intent('Admin Confirm & Dispatch (Spread Editor)');

  -- ── 5. Lock the job row to prevent concurrent dispatch ───────────
  SELECT * INTO v_job FROM public.jobs WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Job not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_job.status <> 'open' THEN
    RAISE EXCEPTION 'Job is not in open state (current: %)', v_job.status
      USING ERRCODE = '22000';
  END IF;
  IF v_job.contractor_id IS NOT NULL THEN
    RAISE EXCEPTION 'Job already has a contractor assigned' USING ERRCODE = '22000';
  END IF;

  -- ── 6. Lock and validate the target application ──────────────────
  SELECT * INTO v_app
  FROM public.applications
  WHERE id = p_application_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Application not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_app.job_id IS DISTINCT FROM p_job_id THEN
    RAISE EXCEPTION 'Application does not belong to this job' USING ERRCODE = '22000';
  END IF;
  IF v_app.status <> 'CLIENT_SELECTED' THEN
    RAISE EXCEPTION 'Application is not in CLIENT_SELECTED state (current: %)', v_app.status
      USING ERRCODE = '22000';
  END IF;
  IF v_app.applicant_id IS NULL THEN
    RAISE EXCEPTION 'Application has no applicant_id' USING ERRCODE = '22000';
  END IF;

  -- ── 7. Promote target application: CLIENT_SELECTED → hired ───────
  UPDATE public.applications
  SET status     = 'hired',
      updated_at = now()
  WHERE id = p_application_id;

  -- ── 8. Lock job: open → assigned + contractor + confirmation ─────
  UPDATE public.jobs
  SET status              = 'assigned',
      contractor_id       = v_app.applicant_id,
      client_price_cents  = p_client_price_cents,
      payout_amount_cents = p_payout_cents,
      payout_status       = COALESCE(p_payout_status, 'unpaid'),
      admin_confirmed_at  = now(),
      admin_confirmed_by  = v_actor,
      updated_at          = now()
  WHERE id = p_job_id;

  -- ── 9. Reject every other non-terminal application on this job ───
  --     (HIRE-003: this was silently swallowed in the old path; now
  --     it's inside the transaction. If anything blocks it, the
  --     whole dispatch rolls back.)
  WITH rejected AS (
    UPDATE public.applications
    SET status     = 'rejected',
        updated_at = now()
    WHERE job_id = p_job_id
      AND id <> p_application_id
      AND status IN ('pending', 'shortlisted', 'CLIENT_SELECTED', 'offered')
    RETURNING id
  )
  SELECT count(*) INTO v_rejected_count FROM rejected;

  -- ── 10. Return summary ───────────────────────────────────────────
  RETURN jsonb_build_object(
    'ok',                true,
    'job_id',            p_job_id,
    'application_id',    p_application_id,
    'contractor_id',     v_app.applicant_id,
    'rejected_siblings', v_rejected_count,
    'correlation_id',    v_correlation
  );
END;
$$;


ALTER FUNCTION "public"."admin_dispatch_job"("p_job_id" "uuid", "p_application_id" "uuid", "p_client_price_cents" bigint, "p_payout_cents" bigint, "p_payout_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_forward_application_to_client"("p_application_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_app RECORD;
BEGIN
  IF NOT public.nx_is_admin() THEN
    RAISE EXCEPTION 'admin only';
  END IF;

  UPDATE public.applications SET
    status = 'CLIENT_SELECTED'
  WHERE id = p_application_id
    AND (
      negotiation_status IS NULL
      OR negotiation_status IN ('none', 'counter_accepted')
    )
  RETURNING * INTO v_app;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'cannot forward — application not found or counter still pending';
  END IF;

  -- Notify the client
  BEGIN
    DECLARE v_client uuid;
    BEGIN
      SELECT COALESCE(client_id, agency_id) INTO v_client
        FROM public.jobs WHERE id = v_app.job_id;
      IF v_client IS NOT NULL THEN
        PERFORM public.notify_safe(
          v_client,
          'assignment',
          'Inspector ready for your review',
          'Admin has vetted an inspector for your job. Open the applications page to confirm.',
          '/client/jobs/' || v_app.job_id::text || '/applications',
          v_app.job_id
        );
      END IF;
    END;
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object(
    'ok', true,
    'application_id', v_app.id,
    'status', v_app.status
  );
END $$;


ALTER FUNCTION "public"."admin_forward_application_to_client"("p_application_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_fund_advance"("p_id" "uuid", "p_funded_by" "text" DEFAULT 'platform'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_adv public.payout_advances%ROWTYPE;
  v_gross_d numeric(12,2);
  v_net_d numeric(12,2);
BEGIN
  IF NOT public.nx_is_admin() THEN RAISE EXCEPTION 'NOT_AUTHORIZED' USING ERRCODE = '42501'; END IF;
  IF p_funded_by NOT IN ('platform','partner') THEN RAISE EXCEPTION 'INVALID_FUNDER'; END IF;

  SELECT * INTO v_adv FROM public.payout_advances WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ADVANCE_NOT_FOUND' USING ERRCODE = 'P0002'; END IF;
  IF v_adv.status = 'funded' THEN RETURN jsonb_build_object('ok', true, 'idempotent', true, 'advance_id', p_id); END IF;
  IF v_adv.status NOT IN ('requested','approved') THEN RAISE EXCEPTION 'INVALID_STATE: %', v_adv.status; END IF;

  v_gross_d := round(v_adv.gross_cents::numeric / 100.0, 2);
  v_net_d   := round(v_adv.net_cents::numeric / 100.0, 2);

  -- Consume the accrued (pending) amount; pay the inspector NET into available now.
  -- The fee (gross - net) is retained by the platform as advance revenue.
  PERFORM 1 FROM public.wallets WHERE user_id = v_adv.requester_id FOR UPDATE;
  UPDATE public.wallets
     SET pending_amount    = GREATEST(COALESCE(pending_amount,0) - v_gross_d, 0),
         available_balance = COALESCE(available_balance,0) + v_net_d,
         updated_at = now()
   WHERE user_id = v_adv.requester_id;

  INSERT INTO public.transactions(user_id, inspector_id, job_id, type, amount,
        gross_amount_halalas, platform_fee_halalas, net_amount_halalas, status, description)
  VALUES (v_adv.requester_id, v_adv.requester_id, v_adv.job_id, 'advance', v_net_d,
        v_adv.gross_cents, v_adv.fee_cents, v_adv.net_cents, 'completed',
        'Early payout advance (net of fee) — recovered on client settlement');

  UPDATE public.payout_advances
     SET status = 'funded', funded_at = now(), funded_by = p_funded_by, decided_by = auth.uid(), updated_at = now()
   WHERE id = p_id;

  RETURN jsonb_build_object('ok', true, 'advance_id', p_id, 'net_paid_cents', v_adv.net_cents, 'fee_cents', v_adv.fee_cents);
END $$;


ALTER FUNCTION "public"."admin_fund_advance"("p_id" "uuid", "p_funded_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_generate_job_contract"("p_application_id" "uuid", "p_client_price_cents" bigint, "p_inspector_payout_cents" bigint, "p_contract_text_md" "text" DEFAULT NULL::"text", "p_custom_contract_url" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_app  RECORD;
  v_id   uuid;
BEGIN
  IF NOT public.nx_is_admin() THEN
    RAISE EXCEPTION 'admin only';
  END IF;
  IF p_client_price_cents < 0 OR p_inspector_payout_cents < 0 THEN
    RAISE EXCEPTION 'prices must be non-negative';
  END IF;

  SELECT a.id, a.job_id, a.applicant_id, j.client_id
    INTO v_app
    FROM public.applications a
    JOIN public.jobs j ON j.id = a.job_id
   WHERE a.id = p_application_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'application not found';
  END IF;

  -- Void any prior active contract for this job
  UPDATE public.job_contracts
     SET status = 'voided',
         voided_at = NOW(),
         voided_by = auth.uid(),
         voided_reason = 'Superseded by new generation'
   WHERE job_id = v_app.job_id AND status <> 'voided';

  INSERT INTO public.job_contracts(
    job_id, application_id, client_id, inspector_id,
    client_price_cents, inspector_payout_cents,
    contract_text_md, custom_contract_url,
    status, generated_by
  )
  VALUES (
    v_app.job_id, v_app.id, v_app.client_id, v_app.applicant_id,
    p_client_price_cents, p_inspector_payout_cents,
    p_contract_text_md, p_custom_contract_url,
    'pending_client_signature', auth.uid()
  )
  RETURNING id INTO v_id;

  -- Notify client
  PERFORM public.create_system_notification(
    v_app.client_id,
    'Contract ready for signature',
    'Admin has prepared the contract for your job. Review and sign to commit funds.',
    'contract_assigned',
    '/client/contracts/job/' || v_id::text,
    v_app.job_id
  );

  RETURN jsonb_build_object('ok', true, 'contract_id', v_id);
END $$;


ALTER FUNCTION "public"."admin_generate_job_contract"("p_application_id" "uuid", "p_client_price_cents" bigint, "p_inspector_payout_cents" bigint, "p_contract_text_md" "text", "p_custom_contract_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_generate_supplier_contract"("p_quote_id" "uuid", "p_contract_text_md" "text" DEFAULT NULL::"text", "p_custom_contract_url" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_q RECORD; v_job uuid; v_amount bigint; v_text text; v_id uuid; v_title text;
BEGIN
  IF NOT public.nx_is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;

  SELECT q.id, q.supplier_id, q.rfq_id, q.status, q.quote, r.title, r.spawned_job_id
    INTO v_q
    FROM public.supplier_quotes q
    JOIN public.supplier_rfqs r ON r.id = q.rfq_id
   WHERE q.id = p_quote_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'quote_not_found'; END IF;
  IF v_q.status <> 'accepted' THEN RAISE EXCEPTION 'CONTRACT_REQUIRES_AWARD: quote is not accepted'; END IF;

  v_amount := public._supplier_quote_cents(v_q.quote);
  v_job := v_q.spawned_job_id;
  v_title := COALESCE(v_q.title, 'Awarded contract');

  -- Default brokered agreement template (admin may override via p_contract_text_md).
  v_text := COALESCE(p_contract_text_md, format(
$md$# NEXPEC Supplier Agreement

**Parties:** NEXPEC (the "Broker") and the awarded Supplier.
**Engagement:** %s
**Awarded value:** $%s

1. **Scope.** The Supplier shall furnish the goods/services described in the referenced RFQ, to the agreed specifications and standards.
2. **Brokered settlement.** Payment is administered by NEXPEC and released against verified milestones to the Supplier's connected payout account. The Supplier holds no claim to funds prior to NEXPEC's release.
3. **Source / FAT inspection.** Where the RFQ requires it, the Supplier shall grant a NEXPEC-dispatched inspector reasonable access for source/FAT inspection prior to shipment.
4. **Confidentiality & non-circumvention.** The Supplier shall not solicit or transact directly with the end client introduced through NEXPEC; all coordination runs through the NEXPEC platform.
5. **Quality & provenance.** Certificates and evidence supplied are sealed into NEXPEC's Trust Spine and must be accurate and current.
6. **Term & termination.** This agreement governs the awarded engagement and may be terminated for material breach.

By signing, the Supplier accepts these terms. NEXPEC countersigns to execute.$md$,
    v_title, to_char(v_amount / 100.0, 'FM999,999,990.00')));

  -- supersede any prior non-void contract for this quote
  UPDATE public.supplier_contracts
     SET status = 'voided', voided_at = now(), voided_by = auth.uid(), voided_reason = 'Superseded by new generation'
   WHERE quote_id = p_quote_id AND status <> 'voided';

  INSERT INTO public.supplier_contracts(
    quote_id, rfq_id, job_id, supplier_id, amount_cents,
    contract_text_md, custom_contract_url, status, generated_by
  ) VALUES (
    p_quote_id, v_q.rfq_id, v_job, v_q.supplier_id, v_amount,
    v_text, p_custom_contract_url, 'pending_supplier_signature', auth.uid()
  ) RETURNING id INTO v_id;

  BEGIN
    PERFORM public.create_system_notification(
      v_q.supplier_id, 'Agreement ready to sign',
      'Review and e-sign your NEXPEC supplier agreement to proceed to payout.',
      'contract_assigned', '/suppliers/contracts/' || v_id::text, v_job);
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object('ok', true, 'contract_id', v_id, 'status', 'pending_supplier_signature');
END $_$;


ALTER FUNCTION "public"."admin_generate_supplier_contract"("p_quote_id" "uuid", "p_contract_text_md" "text", "p_custom_contract_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_invite_org_member"("p_org_id" "uuid", "p_email" "text", "p_role" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor       uuid;
  v_actor_role  text;
  v_clean_email text;
  v_correlation uuid := gen_random_uuid();
  v_invitation_id uuid;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT role INTO v_actor_role FROM public.profiles WHERE id = v_actor;
  IF v_actor_role IS DISTINCT FROM 'super_admin' THEN
    RAISE EXCEPTION 'Only super_admin can invite org members' USING ERRCODE = '42501';
  END IF;

  IF p_org_id IS NULL THEN
    RAISE EXCEPTION 'org_id is required' USING ERRCODE = '22000';
  END IF;

  v_clean_email := lower(NULLIF(TRIM(COALESCE(p_email, '')), ''));
  IF v_clean_email IS NULL OR position('@' in v_clean_email) < 2 THEN
    RAISE EXCEPTION 'A valid email is required' USING ERRCODE = '22000';
  END IF;

  IF p_role NOT IN ('owner', 'procurement_admin', 'project_lead', 'viewer') THEN
    RAISE EXCEPTION 'role must be one of: owner, procurement_admin, project_lead, viewer (got: %)', p_role
      USING ERRCODE = '22000';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = p_org_id) THEN
    RAISE EXCEPTION 'Organization not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM public.audit_set_correlation(v_correlation);
  PERFORM public.audit_set_intent('Org invite issued — ' || v_clean_email || ' as ' || p_role);

  -- Upsert: re-invite a previously-revoked or expired row resets it.
  INSERT INTO public.org_invitations (org_id, email, role, invited_by, status, expires_at)
    VALUES (p_org_id, v_clean_email, p_role::public.org_member_role, v_actor, 'pending', now() + interval '14 days')
    ON CONFLICT (org_id, email) DO UPDATE
      SET role = EXCLUDED.role,
          status = 'pending',
          invited_by = EXCLUDED.invited_by,
          expires_at = EXCLUDED.expires_at,
          created_at = now(),
          accepted_at = NULL
    RETURNING id INTO v_invitation_id;

  RETURN jsonb_build_object(
    'ok',             true,
    'invitation_id',  v_invitation_id,
    'org_id',         p_org_id,
    'email',          v_clean_email,
    'role',           p_role,
    'correlation_id', v_correlation
  );
END;
$$;


ALTER FUNCTION "public"."admin_invite_org_member"("p_org_id" "uuid", "p_email" "text", "p_role" "text") OWNER TO "postgres";


