ALTER FUNCTION "public"."admin_mark_goods_delivered"("p_deal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_mark_payout_processed"("p_job_id" "uuid", "p_stripe_reference" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor        uuid;
  v_actor_role   text;
  v_job          public.jobs%ROWTYPE;
  v_correlation  uuid := gen_random_uuid();
  v_clean_ref    text;
  v_clean_notes  text;
BEGIN
  -- ── 1. Auth ────────────────────────────────────────────────────────
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT role INTO v_actor_role
  FROM public.profiles
  WHERE id = v_actor;

  IF v_actor_role IS DISTINCT FROM 'super_admin' THEN
    RAISE EXCEPTION 'Only super_admin can mark payouts processed' USING ERRCODE = '42501';
  END IF;

  -- ── 2. Input validation ────────────────────────────────────────────
  IF p_job_id IS NULL THEN
    RAISE EXCEPTION 'job_id is required' USING ERRCODE = '22000';
  END IF;

  v_clean_ref := NULLIF(TRIM(COALESCE(p_stripe_reference, '')), '');
  IF v_clean_ref IS NULL THEN
    RAISE EXCEPTION 'A reference is required (Stripe transfer id, or "manual:<context>")'
      USING ERRCODE = '22000';
  END IF;
  IF length(v_clean_ref) > 200 THEN
    v_clean_ref := left(v_clean_ref, 200);
  END IF;

  v_clean_notes := NULLIF(TRIM(COALESCE(p_notes, '')), '');
  IF v_clean_notes IS NOT NULL AND length(v_clean_notes) > 1000 THEN
    v_clean_notes := left(v_clean_notes, 1000);
  END IF;

  -- ── 3. Audit annotation ────────────────────────────────────────────
  PERFORM public.audit_set_correlation(v_correlation);
  PERFORM public.audit_set_intent(
    'Payout marked processed — ref ' || v_clean_ref ||
    COALESCE(' — ' || v_clean_notes, '')
  );

  -- ── 4. Lock + state guard ──────────────────────────────────────────
  SELECT * INTO v_job
  FROM public.jobs
  WHERE id = p_job_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Job not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_job.status <> 'completed' THEN
    RAISE EXCEPTION 'Job is not in completed state (current: %)', v_job.status
      USING ERRCODE = '22000',
            HINT = 'Only completed jobs can be marked as paid.';
  END IF;

  IF v_job.payout_status = 'paid' THEN
    RAISE EXCEPTION 'Job payout is already marked paid'
      USING ERRCODE = '22000',
            HINT = 'Refresh the queue — this row should not be visible.';
  END IF;

  -- ── 5. Settle ──────────────────────────────────────────────────────
  UPDATE public.jobs
  SET payout_status    = 'paid',
      payout_paid_at   = now(),
      payout_reference = v_clean_ref,
      payout_notes     = v_clean_notes,
      payout_marked_by = v_actor,
      updated_at       = now()
  WHERE id = p_job_id;

  RETURN jsonb_build_object(
    'ok',             true,
    'job_id',         p_job_id,
    'payout_status',  'paid',
    'reference',      v_clean_ref,
    'paid_at',        now(),
    'correlation_id', v_correlation
  );
END;
$$;


ALTER FUNCTION "public"."admin_mark_payout_processed"("p_job_id" "uuid", "p_stripe_reference" "text", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_mark_payout_processed"("p_job_id" "uuid", "p_stripe_reference" "text", "p_notes" "text") IS 'Super_admin records that an inspector payout has been settled. Stripe transfer ref or manual:<context> is required. Audit-annotated. FOR UPDATE locked.';



