CREATE OR REPLACE FUNCTION "public"."admin_mark_withdrawal_paid"("p_id" "uuid", "p_reference" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_req public.withdrawal_requests%ROWTYPE;
  v_dollars numeric(12,2);
BEGIN
  IF NOT public.nx_is_admin() THEN RAISE EXCEPTION 'NOT_AUTHORIZED' USING ERRCODE = '42501'; END IF;

  SELECT * INTO v_req FROM public.withdrawal_requests WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'REQUEST_NOT_FOUND' USING ERRCODE = 'P0002'; END IF;
  IF v_req.status = 'paid' THEN RETURN jsonb_build_object('ok', true, 'idempotent', true, 'request_id', p_id); END IF;
  IF v_req.status NOT IN ('requested','approved') THEN RAISE EXCEPTION 'INVALID_STATE: %', v_req.status; END IF;

  v_dollars := round(v_req.amount_cents::numeric / 100.0, 2);

  IF v_req.requester_role = 'inspector' THEN
    UPDATE public.wallets
       SET pending_payouts = GREATEST(COALESCE(pending_payouts,0) - v_dollars, 0),
           total_spent     = COALESCE(total_spent,0) + v_dollars,
           updated_at = now()
     WHERE user_id = v_req.requester_id;
    INSERT INTO public.transactions(user_id, inspector_id, type, amount,
          gross_amount_halalas, platform_fee_halalas, net_amount_halalas, status, description, reference_id)
    VALUES (v_req.requester_id, v_req.requester_id, 'payout', v_dollars,
          v_req.amount_cents, 0, v_req.amount_cents, 'completed',
          'Manual payout — admin confirmed', p_reference);
  ELSE
    UPDATE public.supplier_earnings
       SET pending_halalas = GREATEST(COALESCE(pending_halalas,0) - v_req.amount_cents, 0),
           updated_at = now()
     WHERE supplier_id = v_req.requester_id;
    INSERT INTO public.transactions(user_id, type, amount,
          gross_amount_halalas, platform_fee_halalas, net_amount_halalas, status, description, reference_id)
    VALUES (v_req.requester_id, 'payout', v_dollars,
          v_req.amount_cents, 0, v_req.amount_cents, 'completed',
          'Manual supplier payout — admin confirmed', p_reference);
  END IF;

  UPDATE public.withdrawal_requests
     SET status = 'paid', paid_at = now(), marked_paid_by = auth.uid(),
         external_reference = p_reference, decided_at = now(), decided_by = auth.uid(), updated_at = now()
   WHERE id = p_id;

  RETURN jsonb_build_object('ok', true, 'request_id', p_id, 'paid_cents', v_req.amount_cents);
END $$;


ALTER FUNCTION "public"."admin_mark_withdrawal_paid"("p_id" "uuid", "p_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_match_preview"("p_deal_id" "uuid", "p_n" integer DEFAULT 5) RETURNS TABLE("inspector_id" "uuid", "handle" "text", "score" numeric, "cap_hits" integer, "cert_hits" integer, "region_hit" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  IF NOT public.nx_is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  RETURN QUERY
    SELECT s.inspector_id,
           'NX-' || upper(substr(encode(extensions.digest(s.inspector_id::text,'sha256'),'hex'),1,8)) AS handle,
           s.score, s.cap_hits, s.cert_hits, s.region_hit
    FROM public._brokered_score_inspectors(p_deal_id) s
    LIMIT greatest(1, COALESCE(p_n,5));
END $$;


ALTER FUNCTION "public"."admin_match_preview"("p_deal_id" "uuid", "p_n" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_offer_inspector_shortlist"("p_deal_id" "uuid", "p_payout_cents" bigint, "p_inspector_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_n" integer DEFAULT 3) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_d public.deals; v_title text; v_supplier_id uuid; v_supplier_handle text;
  v_ids uuid[]; v_id uuid; v_slot text; i int := 0; v_art jsonb; v_handle text; v_score numeric;
BEGIN
  IF NOT public.nx_is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  IF p_payout_cents IS NULL OR p_payout_cents < 0 THEN RAISE EXCEPTION 'invalid_payout'; END IF;
  SELECT * INTO v_d FROM public.deals WHERE id = p_deal_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown_deal'; END IF;
  IF EXISTS (SELECT 1 FROM public.deal_inspector_candidates WHERE deal_id = p_deal_id AND status = 'selected') THEN
    RAISE EXCEPTION 'ALREADY_SELECTED: the client has already chosen an inspector for this deal';
  END IF;

  SELECT r.title INTO v_title FROM public.supplier_rfqs r WHERE r.id = v_d.rfq_id;
  SELECT supplier_id INTO v_supplier_id FROM public.supplier_quotes WHERE id = v_d.awarded_quote_id;
  v_supplier_handle := CASE WHEN v_supplier_id IS NULL THEN NULL
    ELSE 'NX-' || upper(substr(encode(extensions.digest(v_supplier_id::text,'sha256'),'hex'),1,6)) END;

  IF p_inspector_ids IS NOT NULL AND cardinality(p_inspector_ids) > 0 THEN
    v_ids := p_inspector_ids[1:3];
  ELSE
    v_ids := ARRAY(SELECT s.inspector_id FROM public._brokered_score_inspectors(p_deal_id) s
                   LIMIT greatest(1, least(COALESCE(p_n,3), 3)));
  END IF;
  IF COALESCE(cardinality(v_ids),0) = 0 THEN RAISE EXCEPTION 'no_eligible_inspector'; END IF;

  DELETE FROM public.deal_inspector_candidates WHERE deal_id = p_deal_id AND status IN ('offered','declined');
  UPDATE public.deals SET inspector_routing = 'client_selection' WHERE id = p_deal_id;

  FOREACH v_id IN ARRAY v_ids LOOP
    i := i + 1;
    EXIT WHEN i > 3;
    v_slot := chr(64 + i);  -- 1->A, 2->B, 3->C
    v_handle := 'NX-' || upper(substr(encode(extensions.digest(v_id::text,'sha256'),'hex'),1,8));
    v_art := public._brokered_build_trust_artifacts(v_id, v_supplier_handle, v_title, v_d.transparency_tier);
    SELECT s.score INTO v_score FROM public._brokered_score_inspectors(p_deal_id) s WHERE s.inspector_id = v_id;
    INSERT INTO public.deal_inspector_candidates (deal_id, slot, inspector_id, handle, dossier, certificate, independence, score, payout_cents, status)
    VALUES (p_deal_id, v_slot, v_id, v_handle, v_art->'dossier', v_art->'certificate', v_art->'independence', v_score, p_payout_cents, 'offered')
    ON CONFLICT (deal_id, slot) DO UPDATE SET
      inspector_id = EXCLUDED.inspector_id, handle = EXCLUDED.handle, dossier = EXCLUDED.dossier,
      certificate = EXCLUDED.certificate, independence = EXCLUDED.independence, score = EXCLUDED.score,
      payout_cents = EXCLUDED.payout_cents, status = 'offered';
  END LOOP;

  RETURN jsonb_build_object('deal_id', p_deal_id, 'offered', i, 'routing', 'client_selection');
END $$;


ALTER FUNCTION "public"."admin_offer_inspector_shortlist"("p_deal_id" "uuid", "p_payout_cents" bigint, "p_inspector_ids" "uuid"[], "p_n" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_present_agreement"("p_agreement_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_a public.agreements; v_title text; v_body text; v_sha text;
BEGIN
  IF NOT public.nx_is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  SELECT * INTO v_a FROM public.agreements WHERE id = p_agreement_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown_agreement'; END IF;
  IF v_a.status NOT IN ('draft','presented') THEN RAISE EXCEPTION 'AGREEMENT_NOT_PRESENTABLE: status=%', v_a.status; END IF;

  SELECT r.title INTO v_title FROM public.deals d LEFT JOIN public.supplier_rfqs r ON r.id = d.rfq_id WHERE d.id = v_a.deal_id;

  v_body := CASE v_a.kind
    WHEN 'supplier_supply'       THEN public._brokered_supplier_supply_md(v_title, v_a.amount_cents, v_a.currency)
    WHEN 'inspector_engagement'  THEN public._brokered_inspector_engagement_md(v_title, v_a.amount_cents, v_a.currency)
    ELSE coalesce(v_a.body_md, '') END;
  v_sha := encode(extensions.digest(v_body, 'sha256'), 'hex');

  UPDATE public.agreements
     SET body_md = v_body, content_sha256 = v_sha, status = 'presented', presented_at = now()
   WHERE id = p_agreement_id;
  RETURN jsonb_build_object('agreement_id', p_agreement_id, 'status', 'presented');
END $$;


ALTER FUNCTION "public"."admin_present_agreement"("p_agreement_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_present_quote"("p_quote_id" "uuid", "p_client_price_cents" bigint, "p_admin_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_q RECORD; v_rfq RECORD; v_cost bigint;
BEGIN
  IF NOT public.nx_is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  IF p_client_price_cents IS NULL OR p_client_price_cents <= 0 THEN
    RAISE EXCEPTION 'INVALID_PRICE: enter a positive client price';
  END IF;

  SELECT * INTO v_q FROM public.supplier_quotes WHERE id = p_quote_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'quote_not_found'; END IF;
  IF v_q.status NOT IN ('submitted','shortlisted','presented') THEN
    RAISE EXCEPTION 'quote_not_presentable: status=%', v_q.status;
  END IF;

  SELECT * INTO v_rfq FROM public.supplier_rfqs WHERE id = v_q.rfq_id;
  IF v_rfq.status NOT IN ('open','quoted') THEN
    RAISE EXCEPTION 'rfq_not_open: status=%', v_rfq.status;
  END IF;

  -- Never sell below cost — protect the margin.
  v_cost := public._quote_raw_cents(v_q.quote);
  IF v_cost > 0 AND p_client_price_cents < v_cost THEN
    RAISE EXCEPTION 'BELOW_COST: client price % is below supplier cost %', p_client_price_cents, v_cost;
  END IF;

  UPDATE public.supplier_quotes
     SET client_price_cents = p_client_price_cents,
         status             = 'presented',
         presented_at       = now(),
         presented_by       = auth.uid(),
         admin_note         = COALESCE(p_admin_note, admin_note)
   WHERE id = p_quote_id;

  BEGIN
    PERFORM public.create_system_notification(
      v_rfq.client_id,
      'A curated offer is ready',
      'NEXPEC has reviewed the market and prepared an offer on your RFQ. Review and accept to proceed.',
      'rfq_offer', '/rfqs/' || v_rfq.id::text, NULL);
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object('ok', true, 'quote_id', p_quote_id,
    'client_price_cents', p_client_price_cents, 'status', 'presented');
END $$;


ALTER FUNCTION "public"."admin_present_quote"("p_quote_id" "uuid", "p_client_price_cents" bigint, "p_admin_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_reject_withdrawal"("p_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_req public.withdrawal_requests%ROWTYPE;
  v_dollars numeric(12,2);
BEGIN
  IF NOT public.nx_is_admin() THEN RAISE EXCEPTION 'NOT_AUTHORIZED' USING ERRCODE = '42501'; END IF;

  SELECT * INTO v_req FROM public.withdrawal_requests WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'REQUEST_NOT_FOUND' USING ERRCODE = 'P0002'; END IF;
  IF v_req.status IN ('rejected','cancelled') THEN RETURN jsonb_build_object('ok', true, 'idempotent', true, 'request_id', p_id); END IF;
  IF v_req.status NOT IN ('requested','approved') THEN RAISE EXCEPTION 'INVALID_STATE: %', v_req.status; END IF;

  v_dollars := round(v_req.amount_cents::numeric / 100.0, 2);

  IF v_req.requester_role = 'inspector' THEN
    UPDATE public.wallets
       SET pending_payouts   = GREATEST(COALESCE(pending_payouts,0) - v_dollars, 0),
           available_balance = COALESCE(available_balance,0) + v_dollars,
           updated_at = now()
     WHERE user_id = v_req.requester_id;
  ELSE
    UPDATE public.supplier_earnings
       SET pending_halalas           = GREATEST(COALESCE(pending_halalas,0) - v_req.amount_cents, 0),
           available_balance_halalas = available_balance_halalas + v_req.amount_cents,
           updated_at = now()
     WHERE supplier_id = v_req.requester_id;
  END IF;

  UPDATE public.withdrawal_requests
     SET status = 'rejected', reject_reason = p_reason, decided_at = now(), decided_by = auth.uid(), updated_at = now()
   WHERE id = p_id;

  RETURN jsonb_build_object('ok', true, 'request_id', p_id, 'returned_cents', v_req.amount_cents);
END $$;


ALTER FUNCTION "public"."admin_reject_withdrawal"("p_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_remove_org_member"("p_member_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor       uuid;
  v_actor_role  text;
  v_correlation uuid := gen_random_uuid();
  v_clean       text;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT role INTO v_actor_role FROM public.profiles WHERE id = v_actor;
  IF v_actor_role IS DISTINCT FROM 'super_admin' THEN
    RAISE EXCEPTION 'Only super_admin can remove org members' USING ERRCODE = '42501';
  END IF;

  v_clean := NULLIF(TRIM(COALESCE(p_reason, '')), '');
  IF v_clean IS NULL THEN
    RAISE EXCEPTION 'A reason is required for member removal' USING ERRCODE = '22000';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.org_members WHERE id = p_member_id) THEN
    RAISE EXCEPTION 'Member not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM public.audit_set_correlation(v_correlation);
  PERFORM public.audit_set_intent('Org member removed — ' || v_clean);

  DELETE FROM public.org_members WHERE id = p_member_id;

  RETURN jsonb_build_object(
    'ok',             true,
    'member_id',      p_member_id,
    'correlation_id', v_correlation
  );
END;
$$;


ALTER FUNCTION "public"."admin_remove_org_member"("p_member_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_resolve_dispute"("p_job_id" "uuid", "p_resolution" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor        uuid;
  v_actor_role   text;
  v_job          public.jobs%ROWTYPE;
  v_correlation  uuid := gen_random_uuid();
  v_clean_reason text;
  v_intent       text;
BEGIN
  -- ── 1. Auth ────────────────────────────────────────────────────────
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT role INTO v_actor_role
  FROM public.profiles
  WHERE id = v_actor;

  IF v_actor_role IS DISTINCT FROM 'super_admin' THEN
    RAISE EXCEPTION 'Only super_admin can resolve disputes' USING ERRCODE = '42501';
  END IF;

  -- ── 2. Input validation ────────────────────────────────────────────
  IF p_job_id IS NULL THEN
    RAISE EXCEPTION 'job_id is required' USING ERRCODE = '22000';
  END IF;

  IF p_resolution NOT IN ('completed', 'cancelled', 'in_progress') THEN
    RAISE EXCEPTION 'resolution must be one of: completed, cancelled, in_progress (got: %)', p_resolution
      USING ERRCODE = '22000';
  END IF;

  v_clean_reason := NULLIF(TRIM(COALESCE(p_reason, '')), '');
  IF v_clean_reason IS NULL THEN
    RAISE EXCEPTION 'A reason is required for dispute resolution' USING ERRCODE = '22000';
  END IF;
  IF length(v_clean_reason) > 1000 THEN
    v_clean_reason := left(v_clean_reason, 1000);
  END IF;

  -- ── 3. Audit annotation ────────────────────────────────────────────
  v_intent := CASE p_resolution
    WHEN 'completed'   THEN 'Dispute resolved → pay inspector — '   || v_clean_reason
    WHEN 'cancelled'   THEN 'Dispute resolved → refund client — '   || v_clean_reason
    WHEN 'in_progress' THEN 'Dispute resolved → return to work — '  || v_clean_reason
    ELSE                    'Dispute resolved — '                   || v_clean_reason
  END;

  PERFORM public.audit_set_correlation(v_correlation);
  PERFORM public.audit_set_intent(v_intent);

  -- ── 4. Lock + state guard ──────────────────────────────────────────
  SELECT * INTO v_job
  FROM public.jobs
  WHERE id = p_job_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Job not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_job.status <> 'disputed' THEN
    RAISE EXCEPTION 'Job is not in disputed state (current: %)', v_job.status
      USING ERRCODE = '22000',
            HINT = 'Only disputed jobs can be resolved via this RPC.';
  END IF;

  -- ── 5. Flip status ─────────────────────────────────────────────────
  -- guard_jobs_status_transition validates the disputed→{x} transition
  -- one more time at the trigger layer. Belt + braces.
  UPDATE public.jobs
  SET status        = p_resolution,
      updated_at    = now(),
      completed_at  = CASE WHEN p_resolution = 'completed' THEN now() ELSE completed_at END,
      cancelled_at  = CASE WHEN p_resolution = 'cancelled' THEN now() ELSE cancelled_at END,
      cancelled_by  = CASE WHEN p_resolution = 'cancelled' THEN v_actor ELSE cancelled_by END,
      cancel_reason = CASE WHEN p_resolution = 'cancelled' THEN v_clean_reason ELSE cancel_reason END
  WHERE id = p_job_id;

  RETURN jsonb_build_object(
    'ok',             true,
    'job_id',         p_job_id,
    'from_status',    'disputed',
    'to_status',      p_resolution,
    'correlation_id', v_correlation
  );
END;
$$;


ALTER FUNCTION "public"."admin_resolve_dispute"("p_job_id" "uuid", "p_resolution" "text", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_resolve_dispute"("p_job_id" "uuid", "p_resolution" "text", "p_reason" "text") IS 'Super_admin resolves a disputed job. p_resolution ∈ {completed, cancelled, in_progress}. Reason required, audit-annotated. FOR UPDATE lock prevents concurrent resolutions.';



CREATE OR REPLACE FUNCTION "public"."admin_review_credential"("p_credential_id" "uuid", "p_decision" "text", "p_notes" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor        uuid;
  v_actor_role   text;
  v_cred         public.inspector_credentials%ROWTYPE;
  v_correlation  uuid := gen_random_uuid();
  v_clean_notes  text;
  v_intent       text;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT role INTO v_actor_role FROM public.profiles WHERE id = v_actor;
  IF v_actor_role IS DISTINCT FROM 'super_admin' THEN
    RAISE EXCEPTION 'Only super_admin can review credentials' USING ERRCODE = '42501';
  END IF;

  IF p_credential_id IS NULL THEN
    RAISE EXCEPTION 'credential_id is required' USING ERRCODE = '22000';
  END IF;
  IF p_decision NOT IN ('approved', 'rejected', 'suspended') THEN
    RAISE EXCEPTION 'decision must be one of: approved, rejected, suspended (got: %)', p_decision
      USING ERRCODE = '22000';
  END IF;

  v_clean_notes := NULLIF(TRIM(COALESCE(p_notes, '')), '');
  IF v_clean_notes IS NULL THEN
    RAISE EXCEPTION 'Decision notes are required' USING ERRCODE = '22000';
  END IF;
  IF length(v_clean_notes) > 1000 THEN
    v_clean_notes := left(v_clean_notes, 1000);
  END IF;

  v_intent := CASE p_decision
    WHEN 'approved'  THEN 'Credential approved — ' || v_clean_notes
    WHEN 'rejected'  THEN 'Credential rejected — ' || v_clean_notes
    WHEN 'suspended' THEN 'Credential suspended — ' || v_clean_notes
  END;
  PERFORM public.audit_set_correlation(v_correlation);
  PERFORM public.audit_set_intent(v_intent);

  SELECT * INTO v_cred
  FROM public.inspector_credentials
  WHERE id = p_credential_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Credential not found' USING ERRCODE = 'P0002';
  END IF;

  -- Terminal-state guard: reject cannot be reversed by this RPC; admin
  -- must create a new credential row to re-evaluate.
  IF v_cred.status = 'rejected' AND p_decision = 'approved' THEN
    RAISE EXCEPTION 'Rejected credentials cannot be approved — the inspector must reapply'
      USING ERRCODE = '22000';
  END IF;

  -- Idempotent same-state writes — useful for re-recording notes.
  UPDATE public.inspector_credentials
  SET status              = p_decision::public.cci_credential_status,
      decided_at          = now(),
      decided_by_admin_id = v_actor,
      decision_notes      = v_clean_notes
  WHERE id = p_credential_id;

  RETURN jsonb_build_object(
    'ok',             true,
    'credential_id',  p_credential_id,
    'from_status',    v_cred.status,
    'to_status',      p_decision,
    'correlation_id', v_correlation
  );
END;
$$;


ALTER FUNCTION "public"."admin_review_credential"("p_credential_id" "uuid", "p_decision" "text", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_review_credential"("p_credential_id" "uuid", "p_decision" "text", "p_notes" "text") IS 'Super_admin approves / rejects / suspends an inspector credential. Notes required, audit-annotated, FOR UPDATE locked.';



CREATE OR REPLACE FUNCTION "public"."admin_review_job"("p_job_id" "uuid", "p_decision" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_job             RECORD;
  v_correlation_id  uuid := gen_random_uuid();
  v_new_job_status  text;
BEGIN
  IF NOT public.nx_is_admin() THEN
    RAISE EXCEPTION 'admin only';
  END IF;
  -- Decision still has to be one of the three values understood by the
  -- jobs.moderation_status enum; otherwise the UPDATE itself would reject.
  -- We keep this lone validation because it's a schema-level constraint,
  -- not a business rule.
  IF p_decision NOT IN ('approved','edits_requested','rejected') THEN
    RAISE EXCEPTION 'invalid decision (must be approved | edits_requested | rejected)';
  END IF;

  SELECT * INTO v_job FROM public.jobs WHERE id = p_job_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'job not found';
  END IF;

  v_new_job_status := CASE
    WHEN p_decision = 'rejected' THEN 'cancelled'
    ELSE v_job.status
  END;

  UPDATE public.jobs SET
    moderation_status      = p_decision,
    moderation_notes       = p_notes,
    moderation_reviewed_at = NOW(),
    moderation_reviewed_by = auth.uid(),
    status                 = v_new_job_status,
    cancelled_at           = CASE WHEN p_decision='rejected' THEN NOW() ELSE v_job.cancelled_at END,
    cancelled_by           = CASE WHEN p_decision='rejected' THEN auth.uid() ELSE v_job.cancelled_by END,
    cancel_reason          = CASE WHEN p_decision='rejected' THEN p_notes ELSE v_job.cancel_reason END,
    updated_at             = NOW()
  WHERE id = p_job_id;

  BEGIN
    PERFORM public.notify_safe(
      COALESCE(v_job.client_id, v_job.agency_id),
      'job_moderated',
      CASE p_decision
        WHEN 'approved'        THEN 'Job approved'
        WHEN 'edits_requested' THEN 'Edits requested on your job'
        WHEN 'rejected'        THEN 'Job rejected'
        ELSE 'Job moderation update'
      END,
      COALESCE(p_notes, v_job.title),
      '/client/jobs/' || v_job.id::text,
      v_job.id
    );
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object(
    'ok',                true,
    'job_id',            v_job.id,
    'moderation_status', p_decision,
    'job_status',        v_new_job_status,
    'correlation_id',    v_correlation_id::text
  );
END $$;


ALTER FUNCTION "public"."admin_review_job"("p_job_id" "uuid", "p_decision" "text", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_review_job"("p_job_id" "uuid", "p_decision" "text", "p_notes" "text") IS 'Super_admin reviews a job: approve / request edits / reject. Rejection cascades through admin_cancel_job. Audit-stamped.';



CREATE OR REPLACE FUNCTION "public"."admin_set_fee_schedule"("p_client_commission_bps" integer, "p_stripe_application_fee_bps" integer, "p_dispute_fee_cents" integer, "p_payout_fee_bps" integer, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor        uuid;
  v_actor_role   text;
  v_old          public.platform_settings%ROWTYPE;
  v_correlation  uuid := gen_random_uuid();
  v_clean_reason text;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT role INTO v_actor_role FROM public.profiles WHERE id = v_actor;
  IF v_actor_role IS DISTINCT FROM 'super_admin' THEN
    RAISE EXCEPTION 'Only super_admin can change fee schedule' USING ERRCODE = '42501';
  END IF;

  v_clean_reason := NULLIF(TRIM(COALESCE(p_reason, '')), '');
  IF v_clean_reason IS NULL THEN
    RAISE EXCEPTION 'A reason is required for fee changes (audit-critical)' USING ERRCODE = '22000';
  END IF;
  IF length(v_clean_reason) > 1000 THEN
    v_clean_reason := left(v_clean_reason, 1000);
  END IF;

  -- Bounds validation (defense in depth — CHECK constraints also enforce).
  IF p_client_commission_bps NOT BETWEEN 0 AND 5000 THEN
    RAISE EXCEPTION 'client_commission_bps out of range (0-5000)' USING ERRCODE = '22000';
  END IF;
  IF p_stripe_application_fee_bps NOT BETWEEN 0 AND 2000 THEN
    RAISE EXCEPTION 'stripe_application_fee_bps out of range (0-2000)' USING ERRCODE = '22000';
  END IF;
  IF p_dispute_fee_cents NOT BETWEEN 0 AND 100000 THEN
    RAISE EXCEPTION 'dispute_fee_cents out of range (0-100000)' USING ERRCODE = '22000';
  END IF;
  IF p_payout_fee_bps NOT BETWEEN 0 AND 1000 THEN
    RAISE EXCEPTION 'payout_fee_bps out of range (0-1000)' USING ERRCODE = '22000';
  END IF;

  PERFORM public.audit_set_correlation(v_correlation);
  PERFORM public.audit_set_intent('Fee schedule updated — ' || v_clean_reason);

  SELECT * INTO v_old FROM public.platform_settings WHERE id = 'global' FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO public.platform_settings (id) VALUES ('global');
    SELECT * INTO v_old FROM public.platform_settings WHERE id = 'global' FOR UPDATE;
  END IF;

  UPDATE public.platform_settings
  SET client_commission_bps      = p_client_commission_bps,
      stripe_application_fee_bps = p_stripe_application_fee_bps,
      dispute_fee_cents          = p_dispute_fee_cents,
      payout_fee_bps             = p_payout_fee_bps,
      updated_at                 = now(),
      updated_by                 = v_actor
  WHERE id = 'global';

  RETURN jsonb_build_object(
    'ok',             true,
    'correlation_id', v_correlation,
    'before', jsonb_build_object(
      'client_commission_bps',      v_old.client_commission_bps,
      'stripe_application_fee_bps', v_old.stripe_application_fee_bps,
      'dispute_fee_cents',          v_old.dispute_fee_cents,
      'payout_fee_bps',             v_old.payout_fee_bps
    ),
    'after', jsonb_build_object(
      'client_commission_bps',      p_client_commission_bps,
      'stripe_application_fee_bps', p_stripe_application_fee_bps,
      'dispute_fee_cents',          p_dispute_fee_cents,
      'payout_fee_bps',             p_payout_fee_bps
    )
  );
END;
$$;


ALTER FUNCTION "public"."admin_set_fee_schedule"("p_client_commission_bps" integer, "p_stripe_application_fee_bps" integer, "p_dispute_fee_cents" integer, "p_payout_fee_bps" integer, "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_set_fee_schedule"("p_client_commission_bps" integer, "p_stripe_application_fee_bps" integer, "p_dispute_fee_cents" integer, "p_payout_fee_bps" integer, "p_reason" "text") IS 'Super_admin updates the global fee schedule. Reason required. Audit-correlated with before/after in the return jsonb.';



CREATE OR REPLACE FUNCTION "public"."admin_set_job_pricing"("p_job_id" "uuid", "p_inspector_payout_cents" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_job RECORD;
BEGIN
  IF NOT public.nx_is_admin() THEN
    RAISE EXCEPTION 'admin only';
  END IF;

  UPDATE public.jobs SET
    inspector_payout_cents = p_inspector_payout_cents,
    payout_amount_cents    = p_inspector_payout_cents,
    updated_at             = NOW()
  WHERE id = p_job_id
  RETURNING * INTO v_job;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'job not found';
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'job_id', v_job.id,
    'inspector_payout_cents', v_job.inspector_payout_cents
  );
END $$;


ALTER FUNCTION "public"."admin_set_job_pricing"("p_job_id" "uuid", "p_inspector_payout_cents" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_suspend_user"("p_user_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF NOT public.nx_is_admin() THEN
    RAISE EXCEPTION 'admin only';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_user_id) THEN
    RAISE EXCEPTION 'user not found';
  END IF;

  UPDATE public.profiles SET
    status            = 'suspended',
    suspension_reason = p_reason,
    suspended_at      = NOW(),
    suspended_by      = v_uid,
    updated_at        = NOW()
  WHERE id = p_user_id;

  BEGIN
    PERFORM public.notify_safe(
      p_user_id, 'system',
      'Account suspended',
      COALESCE(p_reason, 'Contact support for details.'),
      '/contact', NULL
    );
  EXCEPTION WHEN OTHERS THEN NULL; END;
END $$;


ALTER FUNCTION "public"."admin_suspend_user"("p_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_unsuspend_user"("p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT public.nx_is_admin() THEN
    RAISE EXCEPTION 'admin only';
  END IF;

  UPDATE public.profiles SET
    status            = 'active',
    suspension_reason = NULL,
    suspended_at      = NULL,
    suspended_by      = NULL,
    updated_at        = NOW()
  WHERE id = p_user_id;

  BEGIN
    PERFORM public.notify(
      p_user_id,
      'system',
      'Account reinstated',
      'Welcome back. Your account is active again.',
      '/',
      NULL
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'admin_unsuspend_user notify failed: %', SQLERRM;
  END;
END $$;


ALTER FUNCTION "public"."admin_unsuspend_user"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_update_org_member_role"("p_member_id" "uuid", "p_role" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor       uuid;
  v_actor_role  text;
  v_old_role    public.org_member_role;
  v_correlation uuid := gen_random_uuid();
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT role INTO v_actor_role FROM public.profiles WHERE id = v_actor;
  IF v_actor_role IS DISTINCT FROM 'super_admin' THEN
    RAISE EXCEPTION 'Only super_admin can change org member roles' USING ERRCODE = '42501';
  END IF;

  IF p_role NOT IN ('owner', 'procurement_admin', 'project_lead', 'viewer') THEN
    RAISE EXCEPTION 'role must be one of: owner, procurement_admin, project_lead, viewer (got: %)', p_role
      USING ERRCODE = '22000';
  END IF;

  SELECT role INTO v_old_role FROM public.org_members WHERE id = p_member_id FOR UPDATE;
  IF v_old_role IS NULL THEN
    RAISE EXCEPTION 'Member not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM public.audit_set_correlation(v_correlation);
  PERFORM public.audit_set_intent('Org member role changed — ' || v_old_role::text || ' → ' || p_role);

  UPDATE public.org_members
  SET role = p_role::public.org_member_role
  WHERE id = p_member_id;

  RETURN jsonb_build_object(
    'ok',             true,
    'member_id',      p_member_id,
    'from_role',      v_old_role::text,
    'to_role',        p_role,
    'correlation_id', v_correlation
  );
END;
$$;


ALTER FUNCTION "public"."admin_update_org_member_role"("p_member_id" "uuid", "p_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_verify_user"("p_user_id" "uuid", "p_status" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF NOT public.nx_is_admin() THEN
    RAISE EXCEPTION 'admin only';
  END IF;
  IF p_status NOT IN ('verified','pending','rejected','unverified') THEN
    RAISE EXCEPTION 'invalid status (verified | pending | rejected | unverified)';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_user_id) THEN
    RAISE EXCEPTION 'user not found';
  END IF;

  UPDATE public.profiles SET
    verification_status = p_status,
    verified_at         = CASE WHEN p_status = 'verified' THEN NOW() ELSE verified_at END,
    verified_by         = CASE WHEN p_status = 'verified' THEN v_uid ELSE verified_by END,
    rejection_reason    = CASE WHEN p_status = 'rejected' THEN p_reason ELSE NULL END,
    updated_at          = NOW()
  WHERE id = p_user_id;

  BEGIN
    PERFORM public.notify_safe(
      p_user_id,
      'system',
      CASE p_status
        WHEN 'verified' THEN 'Account verified'
        WHEN 'rejected' THEN 'Verification did not pass'
        WHEN 'pending'  THEN 'Verification under review'
        ELSE 'Verification status updated'
      END,
      CASE
        WHEN p_status = 'rejected' THEN COALESCE(p_reason, 'Contact support for details.')
        WHEN p_status = 'verified' THEN 'You can now accept assignments without restriction.'
        ELSE NULL
      END,
      '/inspector/compliance',
      NULL
    );
  EXCEPTION WHEN OTHERS THEN NULL; END;
END $$;


ALTER FUNCTION "public"."admin_verify_user"("p_user_id" "uuid", "p_status" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_onboarding_role"("p_role" "text", "p_full_name" "text" DEFAULT NULL::"text", "p_company_name" "text" DEFAULT NULL::"text", "p_contact_person_name" "text" DEFAULT NULL::"text", "p_specialty_slugs" "text"[] DEFAULT NULL::"text"[], "p_terms_accepted_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_terms_version" "text" DEFAULT NULL::"text") RETURNS TABLE("applied_role" "text", "profile_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid          uuid := auth.uid();
  v_current_role text;
  v_final_role   text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'apply_onboarding_role: no auth.uid() — caller is not authenticated';
  END IF;

  IF p_role IS NULL
     OR p_role NOT IN ('client', 'inspector', 'agency', 'enterprise')
  THEN
    RAISE EXCEPTION 'apply_onboarding_role: invalid p_role: %', p_role;
  END IF;

  -- Read the existing role (if any). The profile row may not exist yet — the
  -- AFTER-auth.users trigger might still be running on a Postgres replica.
  -- We handle both cases with an UPSERT below.
  SELECT role INTO v_current_role FROM public.profiles WHERE id = v_uid;

  -- One-way guard: do NOT downgrade an existing operator/inspector via the
  -- public onboarding path. Promotions to those roles happen through the
  -- admin Users surface, not through self-service signup.
  IF v_current_role IS NOT NULL
     AND v_current_role IN ('admin', 'super_admin', 'inspector')
     AND v_current_role <> p_role
  THEN
    RAISE NOTICE
      'apply_onboarding_role: refusing to flip protected role % -> % for uid %',
      v_current_role, p_role, v_uid;
    RETURN QUERY SELECT v_current_role, v_uid;
    RETURN;
  END IF;

  -- Idempotent upsert. If the profile already exists, we UPDATE the
  -- onboarding-owned columns. If it doesn't, we INSERT — this covers the
  -- race window between auth.users INSERT and the BEFORE INSERT trigger
  -- on profiles completing on a hot replica.
  INSERT INTO public.profiles AS p (
    id,
    role,
    onboarding_role,
    full_name,
    company_name,
    contact_person_name,
    specialty_slugs,
    terms_accepted_at,
    terms_version,
    onboarding_completed_at
  ) VALUES (
    v_uid,
    p_role,
    p_role,
    NULLIF(trim(coalesce(p_full_name, '')), ''),
    NULLIF(trim(coalesce(p_company_name, '')), ''),
    NULLIF(trim(coalesce(p_contact_person_name, '')), ''),
    p_specialty_slugs,
    p_terms_accepted_at,
    p_terms_version,
    now()
  )
  ON CONFLICT (id) DO UPDATE SET
    role                    = EXCLUDED.role,
    onboarding_role         = COALESCE(EXCLUDED.onboarding_role, p.onboarding_role),
    full_name               = COALESCE(EXCLUDED.full_name, p.full_name),
    company_name            = COALESCE(EXCLUDED.company_name, p.company_name),
    contact_person_name     = COALESCE(EXCLUDED.contact_person_name, p.contact_person_name),
    specialty_slugs         = COALESCE(EXCLUDED.specialty_slugs, p.specialty_slugs),
    terms_accepted_at       = COALESCE(EXCLUDED.terms_accepted_at, p.terms_accepted_at),
    terms_version           = COALESCE(EXCLUDED.terms_version, p.terms_version),
    onboarding_completed_at = COALESCE(p.onboarding_completed_at, EXCLUDED.onboarding_completed_at);

  -- Re-read so we return the canonical post-upsert value.
  SELECT role INTO v_final_role FROM public.profiles WHERE id = v_uid;
  RETURN QUERY SELECT v_final_role, v_uid;
END
$$;


ALTER FUNCTION "public"."apply_onboarding_role"("p_role" "text", "p_full_name" "text", "p_company_name" "text", "p_contact_person_name" "text", "p_specialty_slugs" "text"[], "p_terms_accepted_at" timestamp with time zone, "p_terms_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_inspection_report"("p_job_id" "uuid", "p_approved" boolean, "p_comment" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller     uuid := auth.uid();
  v_client_id  uuid;
  v_agency_id  uuid;
  v_report_id  uuid;
  v_new_status text;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT j.client_id, j.agency_id
    INTO v_client_id, v_agency_id
    FROM public.jobs j
   WHERE j.id = p_job_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'job % not found', p_job_id USING ERRCODE = 'P0002';
  END IF;

  IF v_caller IS DISTINCT FROM v_client_id AND v_caller IS DISTINCT FROM v_agency_id THEN
    RAISE EXCEPTION 'caller % is not the owner of job %', v_caller, p_job_id
      USING ERRCODE = '42501';
  END IF;

  v_new_status := CASE WHEN p_approved THEN 'approved' ELSE 'revision_requested' END;

  UPDATE public.inspection_reports
     SET status        = v_new_status,
         is_published  = p_approved,
         reviewer_id   = v_caller,
         reviewer_note = p_comment,
         reviewed_at   = NOW(),
         updated_at    = NOW()
   WHERE job_id = p_job_id
   RETURNING id INTO v_report_id;

  IF v_report_id IS NULL THEN
    RAISE EXCEPTION 'no inspection report exists for job %', p_job_id
      USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO public.job_events (job_id, kind, actor_id, payload)
  VALUES (
    p_job_id,
    CASE WHEN p_approved THEN 'report_approved' ELSE 'report_revision_requested' END,
    v_caller,
    jsonb_build_object(
      'report_id', v_report_id,
      'comment',   p_comment,
      'approved',  p_approved
    )
  );

  RETURN jsonb_build_object(
    'ok',         true,
    'report_id',  v_report_id,
    'new_status', v_new_status,
    'approved',   p_approved
  );
END;
$$;


ALTER FUNCTION "public"."approve_inspection_report"("p_job_id" "uuid", "p_approved" boolean, "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_job_and_pay"("p_job_id" "uuid", "p_inspector_id" "uuid", "p_amount" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_job RECORD;
BEGIN
    SELECT * INTO v_job FROM public.jobs WHERE id = p_job_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'message', 'Job not found'); END IF;
    IF v_job.client_id != auth.uid() THEN RETURN jsonb_build_object('success', false, 'message', 'Unauthorized'); END IF;
    
    UPDATE public.jobs SET status = 'completed', updated_at = NOW() WHERE id = p_job_id;
    UPDATE public.profiles SET balance = balance + (p_amount * 0.90) WHERE id = p_inspector_id;
    
    INSERT INTO public.transactions (user_id, amount, type, description, job_id)
    VALUES (p_inspector_id, (p_amount * 0.90), 'earning', 'Job Payment', p_job_id);
    
    RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."approve_job_and_pay"("p_job_id" "uuid", "p_inspector_id" "uuid", "p_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assemble_evidence_pack"("p_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor       uuid := auth.uid();
  v_actor_role  text;
  v_actor_lbl   text;
  v_job         jsonb;
  v_parties     jsonb;
  v_department  jsonb;
  v_contracts   jsonb;
  v_approvals   jsonb;
  v_invoices    jsonb;
  v_audit       jsonb;
  v_seals       jsonb;
  v_vendor_coordination jsonb;
  v_ai_detections jsonb;
  v_document_intelligence jsonb;
  v_correlation uuid := gen_random_uuid();
  v_has_inv     boolean := to_regclass('public.invoices')              IS NOT NULL;
  v_has_contr   boolean := to_regclass('public.job_contracts')         IS NOT NULL;
  v_has_appr    boolean := to_regclass('public.approval_requests')     IS NOT NULL;
  v_has_seals   boolean := to_regclass('public.pi_report_seals')       IS NOT NULL;
  v_has_bridge  boolean := to_regclass('public.coordination_bridges')  IS NOT NULL;
  v_has_ai      boolean := to_regclass('public.ai_detections')         IS NOT NULL;
  v_has_doc     boolean := to_regclass('public.doc_validations')       IS NOT NULL;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;
  IF NOT public.can_assemble_evidence_for(p_job_id, v_actor) THEN
    RAISE EXCEPTION 'You do not have permission to assemble an evidence pack for this job'
      USING ERRCODE = '42501';
  END IF;

  -- ── 1. Job snapshot ──
  SELECT jsonb_build_object(
    'id', j.id, 'title', j.title, 'description', j.description,
    'status', j.status, 'moderation_status', j.moderation_status,
    'urgency', j.urgency, 'job_type', j.job_type, 'location_city', j.location_city,
    'client_id', j.client_id, 'agency_id', j.agency_id, 'contractor_id', j.contractor_id,
    'budget_cents', j.budget_cents, 'client_price_cents', j.client_price_cents,
    'inspector_payout_cents', j.inspector_payout_cents,
    'department_id', j.department_id, 'specialty_slugs', j.specialty_slugs,
    'requires_cci', j.requires_cci, 'created_at', j.created_at, 'updated_at', j.updated_at
  )
    INTO v_job FROM public.jobs j WHERE j.id = p_job_id;
  IF v_job IS NULL THEN
    RAISE EXCEPTION 'Job not found' USING ERRCODE = 'P0002';
  END IF;

  -- ── 2. Parties ──
  SELECT jsonb_build_object(
    'client', (SELECT jsonb_build_object('id', p.id, 'full_name', p.full_name, 'email', p.email, 'role', p.role)
                 FROM public.profiles p WHERE p.id = (v_job->>'client_id')::uuid),
    'contractor', (SELECT jsonb_build_object('id', p.id, 'full_name', p.full_name, 'email', p.email, 'role', p.role)
                 FROM public.profiles p WHERE p.id = (v_job->>'contractor_id')::uuid)
  ) INTO v_parties;

  -- ── 3. Department ──
  IF (v_job->>'department_id') IS NOT NULL THEN
    SELECT jsonb_build_object('id', d.id, 'org_id', d.org_id, 'name', d.name,
      'cost_center', d.cost_center, 'parent_department_id', d.parent_department_id, 'created_at', d.created_at)
      INTO v_department FROM public.departments d WHERE d.id = (v_job->>'department_id')::uuid;
  ELSE v_department := NULL; END IF;

  -- ── 4. Contracts ──
  IF v_has_contr THEN
    SELECT COALESCE(jsonb_agg(row ORDER BY ord), '[]'::jsonb) INTO v_contracts
      FROM (SELECT row_number() OVER (ORDER BY c.id) AS ord,
          jsonb_build_object('id', c.id, 'job_id', c.job_id, 'application_id', c.application_id,
            'client_id', c.client_id, 'inspector_id', c.inspector_id,
            'client_price_cents', c.client_price_cents, 'inspector_payout_cents', c.inspector_payout_cents,
            'contract_text_md', c.contract_text_md, 'custom_contract_url', c.custom_contract_url, 'status', c.status,
            'client_signed_at', c.client_signed_at, 'client_signed_name', c.client_signed_name,
            'client_signed_ip', c.client_signed_ip, 'inspector_signed_at', c.inspector_signed_at,
            'inspector_signed_name', c.inspector_signed_name, 'inspector_signed_ip', c.inspector_signed_ip,
            'created_at', COALESCE(to_jsonb((row_to_json(c) ->> 'created_at')), 'null'::jsonb)) AS row
          FROM public.job_contracts c WHERE c.job_id = p_job_id) sub;
  ELSE v_contracts := '[]'::jsonb; END IF;

  -- ── 5. Approval request + decisions ──
  IF v_has_appr THEN
    SELECT CASE WHEN r.id IS NULL THEN NULL
      ELSE jsonb_build_object('id', r.id, 'org_id', r.org_id, 'job_id', r.job_id,
        'department_id', r.department_id, 'policy_id', r.policy_id, 'requested_by', r.requested_by,
        'requested_at', r.requested_at, 'amount_cents', r.amount_cents, 'currency', r.currency, 'status', r.status,
        'min_approvers_required', r.min_approvers_required, 'required_approver_roles', r.required_approver_roles,
        'requires_sod', r.requires_sod, 'final_decision_at', r.final_decision_at,
        'final_decision_by', r.final_decision_by, 'rejection_reason', r.rejection_reason,
        'decisions', (SELECT COALESCE(jsonb_agg(d ORDER BY d->>'decided_at'), '[]'::jsonb)
          FROM (SELECT jsonb_build_object('id', ad.id, 'decided_by', ad.decided_by, 'decided_at', ad.decided_at,
              'decision', ad.decision, 'comment', ad.comment, 'decider_role_at_time', ad.decider_role_at_time) AS d
            FROM public.approval_decisions ad WHERE ad.approval_request_id = r.id ORDER BY ad.decided_at) sub)) END
      INTO v_approvals FROM public.approval_requests r WHERE r.job_id = p_job_id;
  ELSE v_approvals := NULL; END IF;

  -- ── 6. Invoices ──
  IF v_has_inv THEN
    SELECT COALESCE(jsonb_agg(row ORDER BY row->>'issued_at' NULLS LAST, row->>'id'), '[]'::jsonb) INTO v_invoices
      FROM (SELECT jsonb_build_object('id', i.id, 'invoice_number', i.invoice_number, 'job_id', i.job_id,
          'contract_id', i.contract_id, 'client_id', i.client_id, 'inspector_id', i.inspector_id,
          'client_amount_cents', i.client_amount_cents, 'inspector_amount_cents', i.inspector_amount_cents,
          'platform_fee_cents', i.platform_fee_cents, 'total_cents', i.total_cents, 'currency', i.currency,
          'status', i.status, 'issued_at', i.issued_at, 'due_date', i.due_date, 'approved_at', i.approved_at,
          'disputed_at', i.disputed_at, 'dispute_reason', i.dispute_reason, 'paid_at', i.paid_at,
          'paid_reference', i.paid_reference, 'voided_at', i.voided_at, 'voided_reason', i.voided_reason,
          'department_id', i.department_id, 'cost_center_snapshot', i.cost_center_snapshot,
          'line_items', COALESCE(i.line_items_json, '[]'::jsonb)) AS row
        FROM public.invoices i WHERE i.job_id = p_job_id) sub;
  ELSE v_invoices := '[]'::jsonb; END IF;

  -- ── 7. Audit events ──
  WITH related_subjects AS (
    SELECT p_job_id AS subject_id
    UNION SELECT id FROM public.job_contracts     WHERE v_has_contr AND job_id = p_job_id
    UNION SELECT id FROM public.invoices          WHERE v_has_inv   AND job_id = p_job_id
    UNION SELECT id FROM public.approval_requests WHERE v_has_appr  AND job_id = p_job_id
    UNION SELECT id FROM public.coordination_bridges WHERE v_has_bridge AND job_id = p_job_id
  )
  SELECT COALESCE(jsonb_agg(row ORDER BY row->>'created_at', row->>'id'), '[]'::jsonb) INTO v_audit
    FROM (SELECT jsonb_build_object('id', a.id, 'created_at', a.created_at, 'event_type', a.event_type,
        'severity', a.severity, 'actor_id', a.actor_id, 'actor_role', a.actor_role, 'actor_label', a.actor_label,
        'subject_table', a.subject_table, 'subject_id', a.subject_id, 'summary', a.summary, 'delta', a.delta,
        'metadata', a.metadata, 'correlation_id', a.correlation_id) AS row
      FROM public.audit_events a
       WHERE a.subject_id IN (SELECT subject_id FROM related_subjects)
          OR (a.metadata ? 'job_id' AND a.metadata->>'job_id' = p_job_id::text)
       ORDER BY a.created_at, a.id) sub;

  -- ── 8. Inspection seals (now exposes ai_root + doc_root) ──
  IF v_has_seals THEN
    SELECT COALESCE(jsonb_agg(row ORDER BY row->>'inspector_sealed_at', row->>'id'), '[]'::jsonb) INTO v_seals
      FROM (SELECT jsonb_build_object('id', s.id, 'report_id', s.report_id, 'job_id', s.job_id, 'inspector_id', s.inspector_id,
          'algorithm', s.algorithm, 'root_sha256', s.root_sha256,
          'captures_root_sha256', s.captures_root_sha256, 'items_root_sha256', s.items_root_sha256,
          'report_meta_sha256', s.report_meta_sha256,
          'ai_root_sha256', s.ai_root_sha256, 'ai_count', s.ai_count,
          'doc_root_sha256', s.doc_root_sha256, 'doc_count', s.doc_count,
          'captures_count', s.captures_count, 'items_count', s.items_count,
          'chain_verified', s.chain_verified, 'chain_break_at_capture_id', s.chain_break_at_capture_id,
          'inspector_sealed_at', s.inspector_sealed_at, 'inspector_signature_sha256', s.inspector_signature_sha256,
          'client_signed_at', s.client_signed_at, 'client_signed_by', s.client_signed_by,
          'client_signature_sha256', s.client_signature_sha256, 'audit_event_id', s.audit_event_id) AS row
        FROM public.pi_report_seals s
        JOIN public.inspection_reports ir ON ir.id = s.report_id
       WHERE ir.job_id = p_job_id) sub;
  ELSE v_seals := '[]'::jsonb; END IF;

  -- ── 9. Vendor coordination ──
  IF v_has_bridge THEN
    SELECT CASE WHEN cb.id IS NULL THEN NULL
      ELSE jsonb_build_object(
        'bridge', jsonb_build_object('id', cb.id, 'status', cb.status, 'created_at', cb.created_at,
          'completed_at', cb.completed_at, 'cancelled_at', cb.cancelled_at, 'token_issued_at', cb.token_issued_at,
          'token_expires_at', cb.token_expires_at, 'token_revoked_at', cb.token_revoked_at,
          'vendor_first_seen_at', cb.vendor_first_seen_at, 'vendor_last_seen_at', cb.vendor_last_seen_at,
          'vendor_session_count', cb.vendor_session_count),
        'vendor', (SELECT jsonb_build_object('id', vc.id, 'company_name', vc.company_name,
            'contact_name', vc.contact_name, 'contact_email', vc.contact_email, 'country_code', vc.country_code,
            'timezone', vc.timezone, 'language_code', vc.language_code)
          FROM public.vendor_contacts vc WHERE vc.id = cb.vendor_contact_id),
        'slots', (SELECT COALESCE(jsonb_agg(row ORDER BY row->>'sort_order', row->>'created_at'), '[]'::jsonb)
          FROM (SELECT jsonb_build_object('id', s.id, 'kind', s.kind, 'status', s.status, 'title', s.title,
              'description', s.description, 'required', s.required, 'sort_order', s.sort_order, 'payload', s.payload_json,
              'created_at', s.created_at, 'last_action_at', s.last_action_at, 'completed_at', s.completed_at,
              'rejected_at', s.rejected_at, 'rejected_reason', s.rejected_reason) AS row
            FROM public.bridge_slots s WHERE s.bridge_id = cb.id) sub),
        'documents', (SELECT COALESCE(jsonb_agg(row ORDER BY row->>'created_at'), '[]'::jsonb)
          FROM (SELECT jsonb_build_object('id', d.id, 'slot_id', d.slot_id,
              'uploaded_by_actor_kind', d.uploaded_by_actor_kind, 'filename', d.original_filename,
              'mime_type', d.mime_type, 'size_bytes', d.file_size_bytes,
              'sha256_client_computed', d.sha256_client_computed, 'sha256_server_verified', d.sha256_server_verified,
              'sha256_match', d.sha256_match, 'created_at', d.created_at,
              'accepted_at', d.accepted_at, 'accepted_by_user_id', d.accepted_by_user_id,
              'rejected_at', d.rejected_at, 'rejected_reason', d.rejected_reason) AS row
            FROM public.bridge_documents d WHERE d.bridge_id = cb.id) sub)) END
      INTO v_vendor_coordination FROM public.coordination_bridges cb WHERE cb.job_id = p_job_id;
  ELSE v_vendor_coordination := NULL; END IF;

  -- ── 9b. AI detections (visual, Provable AI) ──
  IF v_has_ai THEN
    SELECT COALESCE(jsonb_agg(row ORDER BY row->>'created_at', row->>'id'), '[]'::jsonb) INTO v_ai_detections
      FROM (SELECT jsonb_build_object('id', d.id, 'job_id', d.job_id, 'report_id', d.report_id, 'capture_id', d.capture_id,
          'defect_id', d.defect_id, 'label', d.label, 'confidence', d.confidence, 'severity', d.severity,
          'severity_scale', d.severity_scale, 'standard_refs', d.standard_refs,
          'model_slug', d.model_slug, 'model_version', d.model_version, 'model_sha256', d.model_sha256,
          'accepted_by_human', d.accepted_by_human, 'created_at', d.created_at) AS row
        FROM public.ai_detections d WHERE d.job_id = p_job_id) sub;
  ELSE v_ai_detections := '[]'::jsonb; END IF;

  -- ── 9c. Document intelligence (NEW) — verdicts bound to signed model + rubric ──
  IF v_has_doc THEN
    SELECT COALESCE(jsonb_agg(row ORDER BY row->>'created_at', row->>'id'), '[]'::jsonb) INTO v_document_intelligence
      FROM (SELECT jsonb_build_object('id', dv.id, 'job_id', dv.job_id, 'report_id', dv.report_id,
          'template_id', dv.template_id, 'model_slug', dv.model_slug, 'model_version', dv.model_version,
          'model_sha256', dv.model_sha256, 'conformance_score', dv.conformance_score, 'verdict', dv.verdict,
          'report_file_sha256', dv.report_file_sha256, 'extracted_sha256', dv.extracted_sha256,
          'template_sha256', dv.template_sha256, 'result_sha256', dv.result_sha256,
          'flagged_for_review', dv.flagged_for_review, 'accepted_by_human', dv.accepted_by_human,
          'created_at', dv.created_at) AS row
        FROM public.doc_validations dv WHERE dv.job_id = p_job_id) sub;
  ELSE v_document_intelligence := '[]'::jsonb; END IF;

  -- ── 10. Audit row for this assembly ──
  IF to_regclass('public.audit_events') IS NOT NULL THEN
    SELECT role, COALESCE(NULLIF(TRIM(full_name), ''), email, 'Unknown')
      INTO v_actor_role, v_actor_lbl FROM public.profiles WHERE id = v_actor;
    INSERT INTO public.audit_events (event_type, actor_id, actor_role, actor_label,
      subject_table, subject_id, summary, delta, metadata, correlation_id)
    VALUES ('compliance.evidence_pack.assembled', v_actor, COALESCE(v_actor_role, 'authenticated'), v_actor_lbl,
      'jobs', p_job_id, format('SOX evidence pack assembled for job %s', p_job_id::text),
      jsonb_build_object('contracts_count', jsonb_array_length(v_contracts), 'invoices_count', jsonb_array_length(v_invoices),
        'audit_count', jsonb_array_length(v_audit), 'seals_count', jsonb_array_length(v_seals),
        'ai_detections_count', COALESCE(jsonb_array_length(v_ai_detections), 0),
        'doc_validations_count', COALESCE(jsonb_array_length(v_document_intelligence), 0),
        'has_approval', v_approvals IS NOT NULL, 'has_vendor_coordination', v_vendor_coordination IS NOT NULL),
      jsonb_build_object('job_id', p_job_id), v_correlation);
  END IF;

  RETURN jsonb_build_object('ok', true, 'correlation_id', v_correlation,
    'artifacts', jsonb_build_object(
      'job', v_job, 'parties', v_parties, 'department', v_department, 'contracts', v_contracts,
      'approvals', v_approvals, 'invoices', v_invoices, 'audit_events', v_audit,
      'inspection_seals', v_seals, 'vendor_coordination', v_vendor_coordination,
      'ai_detections', v_ai_detections, 'document_intelligence', v_document_intelligence));
END;
$$;


ALTER FUNCTION "public"."assemble_evidence_pack"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_job_payable"("p_job_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_status  text;
  v_deleted timestamptz;
BEGIN
  SELECT status, deleted_at INTO v_status, v_deleted
  FROM public.jobs WHERE id = p_job_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Job % not found', p_job_id USING ERRCODE = 'P0002';
  END IF;
  IF v_deleted IS NOT NULL THEN
    RAISE EXCEPTION 'Job % is deleted; payout blocked', p_job_id
      USING ERRCODE = 'P0001';
  END IF;
  IF v_status = 'disputed' THEN
    RAISE EXCEPTION 'Job % is in dispute; payout frozen', p_job_id
      USING ERRCODE = 'P0001';
  END IF;
  IF v_status = 'cancelled' THEN
    RAISE EXCEPTION 'Job % was cancelled; payout blocked', p_job_id
      USING ERRCODE = 'P0001';
  END IF;
  IF v_status <> 'completed' THEN
    RAISE EXCEPTION 'Job % is not in payable state (current: %)',
      p_job_id, v_status USING ERRCODE = 'P0001';
  END IF;
END;
$$;


ALTER FUNCTION "public"."assert_job_payable"("p_job_id" "uuid") OWNER TO "postgres";

SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."jobs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "title" "text" NOT NULL,
    "description" "text",
    "location" "text",
    "price_cents" bigint DEFAULT 0 NOT NULL,
    "status" "text" DEFAULT 'pending_approval'::"text" NOT NULL,
    "client_id" "uuid",
    "contractor_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "is_senior_review" boolean DEFAULT false NOT NULL,
    "is_featured" boolean DEFAULT false,
    "budget_cents" bigint,
    "budget_min_cents" bigint,
    "budget_max_cents" bigint,
    "budget_type" "text" DEFAULT 'fixed'::"text",
    "location_city" "text",
    "urgency" "text" DEFAULT 'normal'::"text",
    "job_type" "text" DEFAULT 'on_site'::"text",
    "required_certifications" "text"[],
    "scheduled_date" timestamp with time zone,
    "applications_count" integer DEFAULT 0,
    "template_url" "text",
    "contractor_payout_amount_cents" bigint DEFAULT 0,
    "contract_id" "uuid",
    "contract_generated_at" timestamp with time zone,
    "inspector_id" "uuid",
    "client_price_cents" bigint DEFAULT 0,
    "payout_amount_cents" bigint DEFAULT 0,
    "latitude" double precision,
    "longitude" double precision,
    "inspection_type" "text",
    "calendar_event_id" "text",
    "calendar_synced_at" timestamp with time zone,
    "hired_inspector_id" "uuid",
    "agency_id" "uuid",
    "inspector_payout_cents" bigint DEFAULT 0,
    "admin_confirmed_at" timestamp with time zone,
    "admin_confirmed_by" "uuid",
    "payout_status" "text" DEFAULT 'unpaid'::"text",
    "currency" "text",
    "estimated_duration" "text",
    "escrow_status" "text" DEFAULT 'pending'::"text",
    "deleted_at" timestamp with time zone,
    "platform_spread_cents" bigint GENERATED ALWAYS AS ((COALESCE("client_price_cents", (0)::bigint) - COALESCE("inspector_payout_cents", (0)::bigint))) STORED,
    "geog" "public"."geography"(Point,4326) GENERATED ALWAYS AS (
CASE
    WHEN (("latitude" IS NOT NULL) AND ("longitude" IS NOT NULL)) THEN ("public"."st_setsrid"("public"."st_makepoint"("longitude", "latitude"), 4326))::"public"."geography"
    ELSE NULL::"public"."geography"
END) STORED,
    "report_template_id" "uuid",
    "specialty_slugs" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "job_country" "text",
    "sponsorship_offered" "text" DEFAULT 'none'::"text" NOT NULL,
    "accepts_remote_inspectors" boolean DEFAULT false NOT NULL,
    "scope_template_id" "uuid",
    "claimed_address_text" "text",
    "claimed_address_geocoded" "public"."geography"(Point,4326),
    "started_at" timestamp with time zone,
    "cancelled_at" timestamp with time zone,
    "cancelled_by" "uuid",
    "cancel_reason" "text",
    "payout_paid_at" timestamp with time zone,
    "payout_reference" "text",
    "payout_notes" "text",
    "payout_marked_by" "uuid",
    "moderation_status" "text" DEFAULT 'pending_review'::"text" NOT NULL,
    "moderation_reviewed_at" timestamp with time zone,
    "moderation_reviewed_by" "uuid",
    "moderation_notes" "text",
    "requires_cci" boolean DEFAULT false NOT NULL,
    "client_op_id" "uuid",
    "report_signed_docs_url" "text",
    "report_signed_docs_notes" "text",
    "department_id" "uuid",
    "domain" "public"."inspection_domain" DEFAULT 'industrial_ndt'::"public"."inspection_domain" NOT NULL,
    "source_rfq_id" "uuid",
    "payment_mode" "text" DEFAULT 'prepay'::"text" NOT NULL,
    "client_invoiced_at" timestamp with time zone,
    "client_settled_at" timestamp with time zone,
    CONSTRAINT "jobs_compliance_requires_template" CHECK (((("inspection_type" = 'compliance'::"text") AND ("scope_template_id" IS NOT NULL)) OR (("inspection_type" = 'quality'::"text") AND ("scope_template_id" IS NULL)))),
    CONSTRAINT "jobs_latitude_range" CHECK ((("latitude" IS NULL) OR (("latitude" >= ('-90'::integer)::double precision) AND ("latitude" <= (90)::double precision)))),
    CONSTRAINT "jobs_latlng_paired" CHECK ((("latitude" IS NULL) = ("longitude" IS NULL))),
    CONSTRAINT "jobs_longitude_range" CHECK ((("longitude" IS NULL) OR (("longitude" >= ('-180'::integer)::double precision) AND ("longitude" <= (180)::double precision)))),
    CONSTRAINT "jobs_moderation_status_check" CHECK (("moderation_status" = ANY (ARRAY['pending_review'::"text", 'approved'::"text", 'edits_requested'::"text", 'rejected'::"text"]))),
    CONSTRAINT "jobs_owner_xor" CHECK (((("client_id" IS NOT NULL) AND ("agency_id" IS NULL)) OR (("client_id" IS NULL) AND ("agency_id" IS NOT NULL)))),
    CONSTRAINT "jobs_payout_status_check" CHECK (("payout_status" = ANY (ARRAY['unpaid'::"text", 'processing'::"text", 'paid'::"text", 'disputed'::"text"]))),
    CONSTRAINT "jobs_sponsorship_offered_check" CHECK (("sponsorship_offered" = ANY (ARRAY['none'::"text", 'visa_assist'::"text", 'full_sponsorship'::"text"]))),
    CONSTRAINT "jobs_status_check" CHECK (("status" = ANY (ARRAY['pending_approval'::"text", 'open'::"text", 'assigned'::"text", 'in_progress'::"text", 'completed'::"text", 'paid'::"text", 'cancelled'::"text", 'disputed'::"text"])))
);


ALTER TABLE "public"."jobs" OWNER TO "postgres";


COMMENT ON COLUMN "public"."jobs"."contractor_payout_amount_cents" IS 'The manually negotiated payout for the inspector, allowing for flexible service commissions.';



COMMENT ON COLUMN "public"."jobs"."specialty_slugs" IS 'Canonical specialty taxonomy slugs (see src/data/specialties.ts). Set by clients/agencies on job creation; matched server-side against profiles.specialty_slugs for the inspector feed.';



COMMENT ON COLUMN "public"."jobs"."job_country" IS 'JURISDICTION-001: Country (ISO 3166-1 α-2) where the work physically takes place. Nullable in Phase 1; becomes mandatory after Phase 2 capture is rolled out.';



COMMENT ON COLUMN "public"."jobs"."sponsorship_offered" IS 'JURISDICTION-001: Client''s sponsorship policy. none = inspector must already be authorized; visa_assist = client handles paperwork; full_sponsorship = client covers paperwork + relocation.';



COMMENT ON COLUMN "public"."jobs"."accepts_remote_inspectors" IS 'JURISDICTION-001: Future-proof flag for desk-review / report-only work. Out of scope for v1 matching but reserved to avoid a future migration.';



COMMENT ON COLUMN "public"."jobs"."requires_cci" IS 'When true, this job requires a CCI-certified inspector.';



COMMENT ON COLUMN "public"."jobs"."department_id" IS 'Optional department the buyer attributed this job to at post-time. Soft suggestion — invoices inherit this at issuance but procurement can reassign.';



COMMENT ON COLUMN "public"."jobs"."domain" IS 'Inspection domain for this job. Defaults to industrial_ndt so existing jobs and existing job-post code paths are not affected. Set explicitly when posting a civil, electrical, or mechanical job.';



COMMENT ON COLUMN "public"."jobs"."payment_mode" IS 'prepay = client funds escrow up front; net_terms = B2B credit, inspector funds clear only after client_settled_at.';



COMMENT ON COLUMN "public"."jobs"."client_settled_at" IS 'When the client actually paid NEXPEC. On net_terms jobs this is the event that moves inspector earnings Pending → Available (Phase 2).';



COMMENT ON CONSTRAINT "jobs_compliance_requires_template" ON "public"."jobs" IS 'Compliance jobs require a scope template; quality jobs never carry one. Together with inspection_type enum-text values, this is the schema-layer enforcement of the dual-track architecture.';



COMMENT ON CONSTRAINT "jobs_owner_xor" ON "public"."jobs" IS 'Ownership invariant: a job is owned by exactly one of (client, agency). Both NULL is rejected (no ownership); both set is rejected (ambiguous).';



COMMENT ON CONSTRAINT "jobs_status_check" ON "public"."jobs" IS 'Sprint 8: pending_approval added as the parked-pre-marketplace state for jobs that breached an approval gate.';



CREATE OR REPLACE FUNCTION "public"."assign_job_contractor"("p_job_id" "uuid", "p_contractor_id" "uuid") RETURNS "public"."jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_actor      uuid    := auth.uid();
  v_is_admin   boolean := false;
  v_job        public.jobs%ROWTYPE;
  v_role       text;
BEGIN
  -- 0. Auth gate
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  -- 1. Lock the row, read latest state. FOR UPDATE blocks any
  --    concurrent writer until this transaction commits/rolls back.
  SELECT * INTO v_job FROM public.jobs WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Job % not found', p_job_id USING ERRCODE = 'P0002';
  END IF;

  -- 2. Pre-state guard (after lock — guaranteed fresh)
  IF v_job.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'Job % is deleted', p_job_id USING ERRCODE = 'P0001';
  END IF;
  IF v_job.status IS DISTINCT FROM 'open' THEN
    RAISE EXCEPTION 'Job % is not assignable (status=%)', p_job_id, v_job.status
      USING ERRCODE = 'P0001';
  END IF;
  IF v_job.contractor_id IS NOT NULL THEN
    RAISE EXCEPTION 'Job % already has a contractor', p_job_id
      USING ERRCODE = 'P0001';
  END IF;

  -- 3. Caller authorization (super-admin / client / agency only)
  v_is_admin := is_super_admin();
  IF NOT (
       v_is_admin
    OR v_job.client_id = v_actor
    OR v_job.agency_id = v_actor
  ) THEN
    RAISE EXCEPTION 'Not allowed to assign this job'
      USING ERRCODE = '42501';
  END IF;

  -- 4. Validate target contractor exists and is the right kind of profile
  SELECT role INTO v_role FROM public.profiles WHERE id = p_contractor_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Contractor % does not exist', p_contractor_id
      USING ERRCODE = 'P0002';
  END IF;
  IF v_role NOT IN ('inspector','agency') THEN
    RAISE EXCEPTION 'Profile % is not a valid contractor (role=%)',
      p_contractor_id, v_role USING ERRCODE = 'P0001';
  END IF;

  -- 5. Atomic forward transition. Task 2's trigger logs both the
  --    status_change and contractor_assigned events automatically.
  UPDATE public.jobs
     SET contractor_id      = p_contractor_id,
         status             = 'assigned',
         admin_confirmed_at = CASE WHEN v_is_admin THEN now()    ELSE admin_confirmed_at END,
         admin_confirmed_by = CASE WHEN v_is_admin THEN v_actor  ELSE admin_confirmed_by END,
         updated_at         = now()
   WHERE id = p_job_id
   RETURNING * INTO v_job;

  RETURN v_job;
END;
$$;


ALTER FUNCTION "public"."assign_job_contractor"("p_job_id" "uuid", "p_contractor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_member_to_department"("p_department_id" "uuid", "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor       uuid := auth.uid();
  v_actor_role  text;
  v_actor_label text;
  v_org_id      uuid;
  v_assignment_id uuid;
  v_user_label  text;
  v_dept_name   text;
  v_correlation uuid := gen_random_uuid();
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT org_id, name INTO v_org_id, v_dept_name
    FROM public.departments WHERE id = p_department_id;
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Department not found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.can_manage_org_structure(v_org_id, v_actor) THEN
    RAISE EXCEPTION 'You do not have permission to manage this organization''s structure'
      USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.org_members
    WHERE org_id = v_org_id AND user_id = p_user_id
  ) THEN
    RAISE EXCEPTION 'User is not a member of this organization' USING ERRCODE = '22000';
  END IF;

  INSERT INTO public.department_members (department_id, user_id)
    VALUES (p_department_id, p_user_id)
    ON CONFLICT (department_id, user_id) DO UPDATE
      SET created_at = public.department_members.created_at
    RETURNING id INTO v_assignment_id;

  SELECT COALESCE(NULLIF(TRIM(full_name), ''), email, 'Unknown') INTO v_user_label
    FROM public.profiles WHERE id = p_user_id;

  SELECT actor_role, actor_label INTO v_actor_role, v_actor_label
    FROM public._dept_actor_profile(v_actor);

  INSERT INTO public.audit_events (
    event_type, actor_id, actor_role, actor_label,
    subject_table, subject_id, summary, delta, metadata, correlation_id
  ) VALUES (
    'department_member.assigned',
    v_actor,
    v_actor_role,
    v_actor_label,
    'department_members',
    v_assignment_id,
    format('%s assigned to %L', COALESCE(v_user_label, 'User'), v_dept_name),
    jsonb_build_object(
      'department_id', p_department_id,
      'department_name', v_dept_name,
      'user_id', p_user_id,
      'user_label', v_user_label
    ),
    jsonb_build_object('org_id', v_org_id),
    v_correlation
  );

  RETURN jsonb_build_object(
    'ok', true,
    'assignment_id', v_assignment_id,
    'department_id', p_department_id,
    'user_id', p_user_id,
    'correlation_id', v_correlation
  );
END;
$$;


ALTER FUNCTION "public"."assign_member_to_department"("p_department_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audit_capture"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_actor_id       uuid;
  v_actor_role     text;
  v_actor_label    text;
  v_event_type     text;
  v_severity       text := 'info';
  v_summary        text;
  v_delta          jsonb := '{}'::jsonb;
  v_job_id         uuid;
  v_subject_id     uuid;
  v_intent         text;
  v_correlation    uuid;
  v_changed_keys   text[];
  v_before_full    jsonb;
  v_after_full     jsonb;
  v_before_slim    jsonb;
  v_after_slim     jsonb;
BEGIN
  -- ── 1. Resolve actor ───────────────────────────────────────────────
  -- Prefer Supabase's auth.uid() (JWT); fall back to app-set GUC for
  -- system-initiated mutations (Edge Functions, scheduled jobs, etc).
  BEGIN
    v_actor_id := auth.uid();
  EXCEPTION WHEN OTHERS THEN
    v_actor_id := NULL;
  END;

  IF v_actor_id IS NULL THEN
    v_actor_id := NULLIF(current_setting('app.actor_id', true), '')::uuid;
  END IF;

  -- Snapshot the actor's role + display label.
  IF v_actor_id IS NOT NULL THEN
    SELECT
      p.role,
      COALESCE(
        NULLIF(p.company_name, ''),
        NULLIF(p.full_name, ''),
        NULLIF(TRIM(COALESCE(p.first_name, '') || ' ' || COALESCE(p.last_name, '')), ''),
        NULLIF(split_part(COALESCE(p.email, ''), '@', 1), ''),
        'User'
      )
    INTO v_actor_role, v_actor_label
    FROM public.profiles p
    WHERE p.id = v_actor_id;

    -- Profile join may miss (deleted user, race) — fall back gracefully.
    v_actor_role  := COALESCE(v_actor_role, 'unknown');
    v_actor_label := COALESCE(v_actor_label, 'User');
  ELSE
    v_actor_role  := 'system';
    v_actor_label := 'System';
  END IF;

  -- ── 2. GUC-supplied context ────────────────────────────────────────
  v_intent      := NULLIF(current_setting('app.actor_intent',  true), '');
  v_correlation := NULLIF(current_setting('app.correlation_id', true), '')::uuid;

  -- ── 3. Subject + job ids ───────────────────────────────────────────
  IF TG_TABLE_NAME = 'jobs' THEN
    v_subject_id := COALESCE(NEW.id, OLD.id);
    v_job_id     := v_subject_id;
  ELSIF TG_TABLE_NAME IN ('applications', 'contracts', 'payout_requests') THEN
    v_subject_id := COALESCE(NEW.id, OLD.id);
    v_job_id     := COALESCE(
                      (CASE WHEN TG_OP <> 'DELETE' THEN (to_jsonb(NEW)->>'job_id')::uuid END),
                      (CASE WHEN TG_OP <> 'INSERT' THEN (to_jsonb(OLD)->>'job_id')::uuid END)
                    );
  ELSE
    v_subject_id := COALESCE(NEW.id, OLD.id);
    v_job_id     := NULL;
  END IF;

  -- ── 4. Build delta + classify event ────────────────────────────────
  IF TG_OP = 'INSERT' THEN
    v_after_full := to_jsonb(NEW);
    v_delta      := jsonb_build_object('after', v_after_full);
    v_event_type := TG_TABLE_NAME || '.created';
    v_summary    := 'Created ' || TG_TABLE_NAME;

    IF TG_TABLE_NAME = 'jobs' THEN
      v_summary := 'Job posted: ' || COALESCE(NEW.title, 'Untitled');
    ELSIF TG_TABLE_NAME = 'applications' THEN
      v_summary := 'Application submitted';
    ELSIF TG_TABLE_NAME = 'contracts' THEN
      v_summary := 'Contract created';
    ELSIF TG_TABLE_NAME = 'payout_requests' THEN
      v_summary := 'Payout request opened';
    END IF;

  ELSIF TG_OP = 'UPDATE' THEN
    v_before_full := to_jsonb(OLD);
    v_after_full  := to_jsonb(NEW);

    -- Diff: which top-level keys actually changed?
    SELECT array_agg(key ORDER BY key)
    INTO v_changed_keys
    FROM jsonb_each(v_after_full) e(key, val)
    WHERE v_before_full -> e.key IS DISTINCT FROM v_after_full -> e.key
      AND e.key NOT IN ('updated_at');  -- ignore mechanical timestamps

    -- No meaningful change → drop this event entirely.
    IF v_changed_keys IS NULL OR array_length(v_changed_keys, 1) = 0 THEN
      RETURN NEW;
    END IF;

    -- Minimal before/after — only the keys that actually changed.
    SELECT jsonb_object_agg(k, v_before_full -> k)
      INTO v_before_slim
      FROM unnest(v_changed_keys) k;
    SELECT jsonb_object_agg(k, v_after_full -> k)
      INTO v_after_slim
      FROM unnest(v_changed_keys) k;
    v_delta := jsonb_build_object('before', v_before_slim, 'after', v_after_slim);

    -- Per-table event classification ------------------------------------
    IF TG_TABLE_NAME = 'jobs' THEN
      IF 'status' = ANY(v_changed_keys) THEN
        v_event_type := 'job.status_changed';
        v_summary    := 'Status: ' || OLD.status || ' → ' || NEW.status;
        IF NEW.status IN ('disputed', 'cancelled') THEN
          v_severity := 'critical';
        ELSIF NEW.status = 'completed' THEN
          v_severity := 'info';
          v_event_type := 'job.completed';
          v_summary    := 'Job marked completed';
        END IF;

      ELSIF 'contractor_id' = ANY(v_changed_keys) THEN
        IF OLD.contractor_id IS NULL AND NEW.contractor_id IS NOT NULL THEN
          v_event_type := 'job.assigned';
          v_summary    := 'Inspector assigned';
        ELSIF OLD.contractor_id IS NOT NULL AND NEW.contractor_id IS NULL THEN
          v_event_type := 'job.unassigned';
          v_summary    := 'Inspector removed';
          v_severity   := 'warning';
        ELSE
          v_event_type := 'job.reassigned';
          v_summary    := 'Inspector reassigned';
          v_severity   := 'warning';
        END IF;

      ELSIF v_changed_keys && ARRAY[
              'client_price_cents','payout_amount_cents',
              'platform_spread_cents','inspector_payout_cents'
            ]::text[] THEN
        v_event_type := 'job.price_updated';
        v_severity   := 'warning';
        IF 'client_price_cents' = ANY(v_changed_keys) THEN
          v_summary := 'Client price: $'
                    || to_char((COALESCE(OLD.client_price_cents, 0))::numeric / 100, 'FM999G999G999D00')
                    || ' → $'
                    || to_char((COALESCE(NEW.client_price_cents, 0))::numeric / 100, 'FM999G999G999D00');
        ELSE
          v_summary := 'Pricing updated';
        END IF;

      ELSIF 'scheduled_date' = ANY(v_changed_keys) THEN
        v_event_type := 'job.scheduled';
        v_summary    := 'Schedule updated';

      ELSE
        v_event_type := 'job.updated';
        v_summary    := 'Job fields updated: ' || array_to_string(v_changed_keys, ', ');
      END IF;

    ELSIF TG_TABLE_NAME = 'applications' THEN
      IF 'status' = ANY(v_changed_keys) THEN
        IF NEW.status = 'accepted' THEN
          v_event_type := 'application.accepted';
          v_summary    := 'Application accepted';
        ELSIF NEW.status = 'rejected' THEN
          v_event_type := 'application.rejected';
          v_summary    := 'Application rejected';
        ELSE
          v_event_type := 'application.updated';
          v_summary    := 'Application status: ' || OLD.status || ' → ' || NEW.status;
        END IF;
      ELSE
        v_event_type := 'application.updated';
        v_summary    := 'Application fields updated';
      END IF;

    ELSIF TG_TABLE_NAME = 'contracts' THEN
      IF 'signed_at' = ANY(v_changed_keys)
         AND OLD.signed_at IS NULL
         AND NEW.signed_at IS NOT NULL THEN
        v_event_type := 'contract.signed';
        v_summary    := 'Contract signed';
        v_severity   := 'critical';
      ELSIF 'status' = ANY(v_changed_keys) AND NEW.status = 'terminated' THEN
        v_event_type := 'contract.terminated';
        v_summary    := 'Contract terminated';
        v_severity   := 'critical';
      ELSE
        v_event_type := 'contract.updated';
        v_summary    := 'Contract fields updated';
      END IF;

    ELSIF TG_TABLE_NAME = 'payout_requests' THEN
      IF 'status' = ANY(v_changed_keys) THEN
        IF NEW.status = 'paid' THEN
          v_event_type := 'payout_request.paid';
          v_summary    := 'Payout paid';
          v_severity   := 'critical';
        ELSIF NEW.status = 'approved' THEN
          v_event_type := 'payout_request.approved';
          v_summary    := 'Payout approved';
          v_severity   := 'warning';
        ELSIF NEW.status = 'failed' THEN
          v_event_type := 'payout_request.failed';
          v_summary    := 'Payout failed';
          v_severity   := 'critical';
        ELSE
          v_event_type := 'payout_request.updated';
          v_summary    := 'Payout status: ' || OLD.status || ' → ' || NEW.status;
        END IF;
      ELSE
        v_event_type := 'payout_request.updated';
        v_summary    := 'Payout fields updated';
      END IF;

    ELSE
      v_event_type := TG_TABLE_NAME || '.updated';
      v_summary    := TG_TABLE_NAME || ' updated: ' || array_to_string(v_changed_keys, ', ');
    END IF;

  ELSIF TG_OP = 'DELETE' THEN
    v_before_full := to_jsonb(OLD);
    v_delta       := jsonb_build_object('before', v_before_full);
    v_event_type  := TG_TABLE_NAME || '.deleted';
    v_summary     := TG_TABLE_NAME || ' deleted';
    v_severity    := 'critical';  -- deletes are always notable
  END IF;

  -- ── 5. Write the event ────────────────────────────────────────────
  INSERT INTO public.audit_events (
    event_type, severity,
    actor_id,   actor_role, actor_label,
    subject_table, subject_id, job_id,
    summary, delta, metadata, correlation_id
  ) VALUES (
    v_event_type, v_severity,
    v_actor_id,   v_actor_role, v_actor_label,
    TG_TABLE_NAME, v_subject_id, v_job_id,
    v_summary, v_delta,
    jsonb_build_object(
      'intent',       v_intent,
      'op',           TG_OP,
      'changed_keys', to_jsonb(v_changed_keys)
    ),
    v_correlation
  );

  -- ── 6. Fan-out signal for Edge Functions / AI hooks ───────────────
  PERFORM pg_notify(
    'audit_event_emitted',
    jsonb_build_object(
      'event_type', v_event_type,
      'severity',   v_severity,
      'job_id',     v_job_id,
      'actor_id',   v_actor_id
    )::text
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  ELSE
    RETURN NEW;
  END IF;
END;
$_$;


