CREATE OR REPLACE FUNCTION "public"."auto_expire_certifications"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    -- Update status to 'expired' when expiry_date has passed
    UPDATE public.contractor_certifications
    SET status = 'expired'
    WHERE status = 'active' 
      AND expiry_date < CURRENT_DATE;
    
    RETURN NULL;
END;
$$;


