CREATE OR REPLACE FUNCTION "public"."award_and_dispatch"("p_quote_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_q   public.supplier_quotes;
  v_rfq public.supplier_rfqs;
  v_deal_id uuid;
  v_agr_id  uuid;
  v_body text;
  v_sha  text;
  v_source_fat boolean;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT * INTO v_q FROM public.supplier_quotes WHERE id = p_quote_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown_quote'; END IF;
  SELECT * INTO v_rfq FROM public.supplier_rfqs WHERE id = v_q.rfq_id FOR UPDATE;
  IF NOT (v_rfq.client_id = v_uid OR public.nx_is_admin()) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF v_q.client_price_cents IS NULL THEN RAISE EXCEPTION 'QUOTE_NOT_PRICED'; END IF;
  IF NOT public.nx_is_admin() AND v_q.status <> 'presented' THEN RAISE EXCEPTION 'QUOTE_NOT_PRESENTED'; END IF;

  SELECT d.id INTO v_deal_id FROM public.deals d WHERE d.awarded_quote_id = p_quote_id LIMIT 1;
  IF v_deal_id IS NOT NULL THEN
    PERFORM public._brokered_ensure_payment_schedule(v_deal_id, v_q.client_price_cents, 'USD');
    SELECT a.id INTO v_agr_id FROM public.agreements a
     WHERE a.deal_id = v_deal_id AND a.kind = 'client_supply' ORDER BY a.version DESC LIMIT 1;
    RETURN jsonb_build_object('deal_id', v_deal_id, 'client_agreement_id', v_agr_id, 'reused', true);
  END IF;

  v_source_fat := coalesce(v_rfq.requires_source_inspection, true);

  INSERT INTO public.deals (rfq_id, client_id, client_price_cents, currency, awarded_quote_id, status, created_by)
  VALUES (v_rfq.id, v_rfq.client_id, v_q.client_price_cents, 'USD', p_quote_id, 'awaiting_client_signature', v_uid)
  RETURNING id INTO v_deal_id;

  PERFORM public._brokered_ensure_payment_schedule(v_deal_id, v_q.client_price_cents, 'USD');

  v_body := public._brokered_client_supply_md(v_rfq.title, v_q.client_price_cents, 'USD', 'standard', v_source_fat);
  v_sha  := encode(extensions.digest(v_body, 'sha256'), 'hex');

  INSERT INTO public.agreements (deal_id, kind, status, counterparty_id, amount_cents, currency,
                                 body_md, content_sha256, ots_status, presented_at, generated_by)
  VALUES (v_deal_id, 'client_supply', 'presented', v_rfq.client_id, v_q.client_price_cents, 'USD',
          v_body, v_sha, 'unsubmitted', now(), v_uid)
  RETURNING id INTO v_agr_id;

  RETURN jsonb_build_object('deal_id', v_deal_id, 'client_agreement_id', v_agr_id, 'reused', false);
END $$;


ALTER FUNCTION "public"."award_and_dispatch"("p_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."award_quote"("p_quote_id" "uuid") RETURNS "public"."jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_q public.supplier_quotes;
  v_rfq public.supplier_rfqs;
  v_job public.jobs;
  v_is_admin boolean := public.nx_is_admin();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT * INTO v_q FROM public.supplier_quotes WHERE id = p_quote_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown_quote'; END IF;
  SELECT * INTO v_rfq FROM public.supplier_rfqs WHERE id = v_q.rfq_id FOR UPDATE;
  IF NOT (v_rfq.client_id = v_uid OR v_is_admin) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF v_rfq.status NOT IN ('open','quoted') THEN RAISE EXCEPTION 'rfq_not_awardable'; END IF;

  -- INTERCEPT GATE: a client price must have been set by admin, and a client
  -- may only accept an offer that was explicitly PRESENTED to them. This makes
  -- it impossible to award a raw, un-marked-up quote.
  IF v_q.client_price_cents IS NULL THEN
    RAISE EXCEPTION 'QUOTE_NOT_PRICED: admin must set a client price before award';
  END IF;
  IF NOT v_is_admin AND v_q.status <> 'presented' THEN
    RAISE EXCEPTION 'QUOTE_NOT_PRESENTED: only admin-presented offers can be accepted';
  END IF;

  UPDATE public.supplier_quotes SET status = 'accepted' WHERE id = p_quote_id;  -- fires spawn trigger

  SELECT * INTO v_job FROM public.jobs WHERE source_rfq_id = v_rfq.id ORDER BY created_at DESC LIMIT 1;
  RETURN v_job;
END $$;


ALTER FUNCTION "public"."award_quote"("p_quote_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."bridge_slots" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "bridge_id" "uuid" NOT NULL,
    "kind" "public"."coordination_bridge_slot_kind" NOT NULL,
    "status" "public"."coordination_bridge_slot_status" DEFAULT 'pending'::"public"."coordination_bridge_slot_status" NOT NULL,
    "title" "text" NOT NULL,
    "description" "text",
    "required" boolean DEFAULT true NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "payload_json" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_by_user_id" "uuid",
    "created_by_actor_kind" "public"."coordination_bridge_actor_kind" DEFAULT 'inspector'::"public"."coordination_bridge_actor_kind" NOT NULL,
    "last_action_at" timestamp with time zone,
    "last_action_by_user_id" "uuid",
    "last_action_by_actor_kind" "public"."coordination_bridge_actor_kind",
    "last_action_note" "text",
    "completed_at" timestamp with time zone,
    "rejected_at" timestamp with time zone,
    "rejected_reason" "text",
    CONSTRAINT "bridge_slots_terminal_coherence" CHECK ((NOT (("completed_at" IS NOT NULL) AND ("rejected_at" IS NOT NULL))))
);


ALTER TABLE "public"."bridge_slots" OWNER TO "postgres";


COMMENT ON TABLE "public"."bridge_slots" IS 'Finite state-machine slots inside a Coordination Bridge. Each slot represents one structured negotiation surface (schedule, document request, site access, etc.).';



CREATE OR REPLACE FUNCTION "public"."bridge_accept_counter_schedule"("p_bridge_id" "uuid", "p_slot_id" "uuid") RETURNS "public"."bridge_slots"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller   uuid := auth.uid();
  v_admin    boolean;
  v_bridge   RECORD;
  v_slot     public.bridge_slots%ROWTYPE;
  v_result   public.bridge_slots%ROWTYPE;
  v_proposed timestamptz;
  v_role     text;
  v_label    text;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '28000';
  END IF;
  SELECT EXISTS (SELECT 1 FROM public.profiles WHERE id = v_caller AND role IN ('admin','super_admin'))
    INTO v_admin;

  SELECT id, job_id, inspector_id, status
    INTO v_bridge
    FROM public.coordination_bridges WHERE id = p_bridge_id;
  IF v_bridge.id IS NULL THEN
    RAISE EXCEPTION 'bridge not found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT v_admin AND v_bridge.inspector_id <> v_caller THEN
    RAISE EXCEPTION 'only the assigned inspector or NEXPEC Admin may accept a counter'
      USING ERRCODE = '42501';
  END IF;
  IF v_bridge.status IN ('completed','cancelled') THEN
    RAISE EXCEPTION 'bridge is %; cannot mutate', v_bridge.status USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_slot
    FROM public.bridge_slots
   WHERE id = p_slot_id AND bridge_id = p_bridge_id AND kind = 'schedule';
  IF v_slot.id IS NULL THEN
    RAISE EXCEPTION 'schedule slot not found' USING ERRCODE = 'P0002';
  END IF;
  -- There must be a pending vendor counter to accept.
  IF v_slot.status <> 'awaiting_inspector' THEN
    RAISE EXCEPTION 'no vendor counter awaiting your acceptance (slot is %)', v_slot.status
      USING ERRCODE = '22023';
  END IF;

  v_proposed := (v_slot.payload_json ->> 'proposed_at')::timestamptz;
  IF v_proposed IS NULL THEN
    RAISE EXCEPTION 'counter has no proposed time' USING ERRCODE = '22023';
  END IF;

  UPDATE public.bridge_slots
     SET status        = 'completed',
         completed_at  = now(),
         payload_json  = v_slot.payload_json
           || jsonb_build_object(
                'agreed_at',      v_proposed,
                'agreed_by_kind', 'inspector',
                'agreed_at_utc',  now()
              ),
         last_action_at            = now(),
         last_action_by_user_id    = v_caller,
         last_action_by_actor_kind = 'inspector'
   WHERE id = p_slot_id
   RETURNING * INTO v_result;
   -- → fires tg_notify_bridge_schedule_changed('completed') → pings inspector + client.

  SELECT actor_role, actor_label INTO v_role, v_label FROM public.cb_actor_profile(v_caller);

  PERFORM public.cb_emit_audit(
    'coordination_bridge.schedule_accepted',
    'info',
    v_caller, COALESCE(v_role,'inspector'), v_label,
    v_bridge.id, v_bridge.job_id,
    format('Inspector accepted the vendor''s counter for %s', v_proposed),
    jsonb_build_object('slot_id', p_slot_id, 'agreed_at', v_proposed, 'agreed_by_kind','inspector'),
    jsonb_build_object('job_id', v_bridge.job_id::text, 'bridge_id', v_bridge.id::text)
  );

  RETURN v_result;
END
$$;


ALTER FUNCTION "public"."bridge_accept_counter_schedule"("p_bridge_id" "uuid", "p_slot_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."bridge_documents" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "bridge_id" "uuid" NOT NULL,
    "slot_id" "uuid",
    "uploaded_by_actor_kind" "public"."coordination_bridge_actor_kind" NOT NULL,
    "uploaded_via_token" boolean DEFAULT false NOT NULL,
    "uploaded_by_user_id" "uuid",
    "uploaded_by_vendor_contact_id" "uuid",
    "storage_bucket" "text" DEFAULT 'bridge-documents'::"text" NOT NULL,
    "storage_path" "text" NOT NULL,
    "original_filename" "text" NOT NULL,
    "mime_type" "text",
    "file_size_bytes" bigint,
    "sha256_client_computed" "text" NOT NULL,
    "sha256_server_verified" "text",
    "sha256_verified_at" timestamp with time zone,
    "sha256_match" boolean,
    "accepted_at" timestamp with time zone,
    "accepted_by_user_id" "uuid",
    "rejected_at" timestamp with time zone,
    "rejected_by_user_id" "uuid",
    "rejected_reason" "text",
    CONSTRAINT "bridge_documents_sha256_format" CHECK (("sha256_client_computed" ~ '^[a-f0-9]{64}$'::"text")),
    CONSTRAINT "bridge_documents_terminal_coherence" CHECK ((NOT (("accepted_at" IS NOT NULL) AND ("rejected_at" IS NOT NULL)))),
    CONSTRAINT "bridge_documents_uploader_coherence" CHECK (((("uploaded_by_actor_kind" = 'vendor'::"public"."coordination_bridge_actor_kind") AND ("uploaded_by_vendor_contact_id" IS NOT NULL)) OR (("uploaded_by_actor_kind" = 'inspector'::"public"."coordination_bridge_actor_kind") AND ("uploaded_by_user_id" IS NOT NULL)) OR (("uploaded_by_actor_kind" = ANY (ARRAY['client'::"public"."coordination_bridge_actor_kind", 'platform_owner'::"public"."coordination_bridge_actor_kind", 'system'::"public"."coordination_bridge_actor_kind"])) AND ("uploaded_by_user_id" IS NOT NULL))))
);


ALTER TABLE "public"."bridge_documents" OWNER TO "postgres";


COMMENT ON TABLE "public"."bridge_documents" IS 'Documents exchanged through a Coordination Bridge. Each row carries a SHA-256 hash that will be folded into the inspection report seal (Sprint C).';



CREATE OR REPLACE FUNCTION "public"."bridge_accept_document"("p_document_id" "uuid") RETURNS "public"."bridge_documents"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller  uuid := auth.uid();
  v_admin   boolean;
  v_doc     public.bridge_documents%ROWTYPE;
  v_bridge  RECORD;
  v_result  public.bridge_documents%ROWTYPE;
  v_role    text;
  v_label   text;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE='28000';
  END IF;
  SELECT EXISTS (SELECT 1 FROM public.profiles WHERE id=v_caller AND role IN ('admin','super_admin')) INTO v_admin;
  SELECT * INTO v_doc FROM public.bridge_documents WHERE id = p_document_id;
  IF v_doc.id IS NULL THEN
    RAISE EXCEPTION 'document not found' USING ERRCODE='P0002';
  END IF;
  SELECT * INTO v_bridge FROM public.coordination_bridges WHERE id = v_doc.bridge_id;
  IF NOT v_admin AND v_bridge.inspector_id <> v_caller THEN
    RAISE EXCEPTION 'not authorised' USING ERRCODE='42501';
  END IF;
  IF v_doc.accepted_at IS NOT NULL THEN
    RETURN v_doc; -- idempotent
  END IF;
  IF v_doc.rejected_at IS NOT NULL THEN
    RAISE EXCEPTION 'document was rejected; vendor must resubmit' USING ERRCODE='22023';
  END IF;

  UPDATE public.bridge_documents
     SET accepted_at = now(),
         accepted_by_user_id = v_caller
   WHERE id = p_document_id
   RETURNING * INTO v_result;

  -- Mark associated slot completed if it was a document_request slot.
  IF v_result.slot_id IS NOT NULL THEN
    UPDATE public.bridge_slots
       SET status = 'completed',
           completed_at = now(),
           last_action_at = now(),
           last_action_by_user_id = v_caller,
           last_action_by_actor_kind = 'inspector'
     WHERE id = v_result.slot_id AND kind = 'document_request';
  END IF;

  SELECT actor_role, actor_label INTO v_role, v_label FROM public.cb_actor_profile(v_caller);

  PERFORM public.cb_emit_audit(
    'coordination_bridge.document_accepted',
    'info',
    v_caller, COALESCE(v_role,'inspector'), v_label,
    v_bridge.id, v_bridge.job_id,
    format('Inspector accepted document %s', v_doc.original_filename),
    jsonb_build_object(
      'document_id',  v_doc.id,
      'slot_id',      v_doc.slot_id,
      'filename',     v_doc.original_filename,
      'sha256',       v_doc.sha256_client_computed
    ),
    jsonb_build_object('job_id', v_bridge.job_id::text, 'bridge_id', v_bridge.id::text)
  );

  RETURN v_result;
END
$$;


ALTER FUNCTION "public"."bridge_accept_document"("p_document_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bridge_add_document_request"("p_bridge_id" "uuid", "p_title" "text", "p_description" "text" DEFAULT NULL::"text", "p_required" boolean DEFAULT true, "p_max_size_mb" integer DEFAULT 50) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller   uuid := auth.uid();
  v_is_admin boolean;
  v_bridge   RECORD;
  v_slot_id  uuid;
  v_next_so  integer;
  v_role     text;
  v_label    text;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.profiles WHERE id = v_caller AND role IN ('admin','super_admin')
  ) INTO v_is_admin;

  SELECT id, job_id, inspector_id, status
    INTO v_bridge
    FROM public.coordination_bridges WHERE id = p_bridge_id;
  IF v_bridge.id IS NULL THEN
    RAISE EXCEPTION 'bridge % not found', p_bridge_id USING ERRCODE = 'P0002';
  END IF;
  IF NOT v_is_admin AND v_bridge.inspector_id <> v_caller THEN
    RAISE EXCEPTION 'only the assigned inspector or NEXPEC Admin may add document requests'
      USING ERRCODE = '42501';
  END IF;
  IF v_bridge.status IN ('completed','cancelled') THEN
    RAISE EXCEPTION 'bridge is %; cannot mutate', v_bridge.status USING ERRCODE = '22023';
  END IF;
  IF p_title IS NULL OR length(trim(p_title)) = 0 THEN
    RAISE EXCEPTION 'title required' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(MAX(sort_order), 0) + 10
    INTO v_next_so
    FROM public.bridge_slots
   WHERE bridge_id = p_bridge_id AND kind = 'document_request';

  INSERT INTO public.bridge_slots (
    bridge_id, kind, status, title, description, required, sort_order,
    payload_json, created_by_user_id, created_by_actor_kind
  )
  VALUES (
    p_bridge_id, 'document_request', 'awaiting_vendor',
    trim(p_title),
    NULLIF(trim(p_description), ''),
    COALESCE(p_required, true),
    40 + v_next_so,
    jsonb_build_object(
      'max_size_bytes', GREATEST(1, COALESCE(p_max_size_mb, 50)) * 1024 * 1024,
      'mime_hints',     ARRAY[]::text[]
    ),
    v_caller, 'inspector'
  )
  RETURNING id INTO v_slot_id;

  SELECT actor_role, actor_label INTO v_role, v_label FROM public.cb_actor_profile(v_caller);

  PERFORM public.cb_emit_audit(
    'coordination_bridge.document_requested',
    'info',
    v_caller, COALESCE(v_role, 'inspector'), v_label,
    p_bridge_id, v_bridge.job_id,
    format('Inspector requested document "%s"', trim(p_title)),
    jsonb_build_object(
      'slot_id',  v_slot_id,
      'title',    trim(p_title),
      'required', COALESCE(p_required, true)
    ),
    jsonb_build_object('job_id', v_bridge.job_id::text, 'bridge_id', p_bridge_id::text)
  );

  RETURN v_slot_id;
END
$$;


ALTER FUNCTION "public"."bridge_add_document_request"("p_bridge_id" "uuid", "p_title" "text", "p_description" "text", "p_required" boolean, "p_max_size_mb" integer) OWNER TO "postgres";


