    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "job_id" "uuid" NOT NULL,
    "vendor_contact_id" "uuid" NOT NULL,
    "inspector_id" "uuid" NOT NULL,
    "client_id" "uuid",
    "status" "public"."coordination_bridge_status" DEFAULT 'pending_invite'::"public"."coordination_bridge_status" NOT NULL,
    "token_sha256" "text" NOT NULL,
    "token_issued_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "token_expires_at" timestamp with time zone NOT NULL,
    "token_revoked_at" timestamp with time zone,
    "vendor_first_seen_at" timestamp with time zone,
    "vendor_last_seen_at" timestamp with time zone,
    "vendor_session_count" integer DEFAULT 0 NOT NULL,
    "ready_for_inspection_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "cancelled_at" timestamp with time zone,
    "cancelled_by_user_id" "uuid",
    "cancellation_reason" "text",
    "inspector_private_notes" "text",
    CONSTRAINT "coordination_bridges_token_expiry_future" CHECK (("token_expires_at" > "token_issued_at"))
);


ALTER TABLE "public"."coordination_bridges" OWNER TO "postgres";


COMMENT ON TABLE "public"."coordination_bridges" IS 'One Coordination Bridge per job. The vendor accesses this via a signed magic-link token. All mutations route through SECURITY DEFINER RPCs.';



COMMENT ON COLUMN "public"."coordination_bridges"."token_sha256" IS 'SHA-256 hash of the raw magic-link token. The raw token is delivered to the vendor by email exactly once and is NEVER stored. This column lets the Edge Function validate a presented token by hashing and lookup.';



COMMENT ON COLUMN "public"."coordination_bridges"."inspector_private_notes" IS 'Inspector working notes. Never visible to vendor, client, or auditor. Visible only to the inspector themselves and to Platform Owner.';



CREATE OR REPLACE FUNCTION "public"."bridge_cancel"("p_bridge_id" "uuid", "p_reason" "text") RETURNS "public"."coordination_bridges"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller  uuid := auth.uid();
  v_admin   boolean;
  v_bridge  public.coordination_bridges%ROWTYPE;
  v_result  public.coordination_bridges%ROWTYPE;
  v_role    text;
  v_label   text;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE='28000';
  END IF;
  SELECT EXISTS (SELECT 1 FROM public.profiles WHERE id=v_caller AND role IN ('admin','super_admin')) INTO v_admin;
  SELECT * INTO v_bridge FROM public.coordination_bridges WHERE id = p_bridge_id;
  IF v_bridge.id IS NULL THEN
    RAISE EXCEPTION 'bridge not found' USING ERRCODE='P0002';
  END IF;
  IF NOT v_admin
     AND v_bridge.inspector_id <> v_caller
     AND v_bridge.client_id    IS DISTINCT FROM v_caller
  THEN
    RAISE EXCEPTION 'not authorised' USING ERRCODE='42501';
  END IF;
  IF v_bridge.status = 'cancelled' THEN
    RETURN v_bridge;
  END IF;
  IF v_bridge.status = 'completed' THEN
    RAISE EXCEPTION 'cannot cancel a completed bridge' USING ERRCODE='22023';
  END IF;

  UPDATE public.coordination_bridges
     SET status = 'cancelled',
         cancelled_at = now(),
         cancelled_by_user_id = v_caller,
         cancellation_reason  = NULLIF(trim(p_reason), ''),
         token_revoked_at     = COALESCE(token_revoked_at, now())
   WHERE id = p_bridge_id
   RETURNING * INTO v_result;

  SELECT actor_role, actor_label INTO v_role, v_label FROM public.cb_actor_profile(v_caller);

  PERFORM public.cb_emit_audit(
    'coordination_bridge.cancelled',
    'warning',
    v_caller, COALESCE(v_role, 'inspector'), v_label,
    p_bridge_id, v_bridge.job_id,
    format('Coordination Bridge cancelled — %s', COALESCE(NULLIF(trim(p_reason),''), 'no reason')),
    jsonb_build_object('reason', NULLIF(trim(p_reason),'')),
    jsonb_build_object('job_id', v_bridge.job_id::text, 'bridge_id', p_bridge_id::text)
  );

  RETURN v_result;
END
$$;


ALTER FUNCTION "public"."bridge_cancel"("p_bridge_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bridge_complete"("p_bridge_id" "uuid") RETURNS "public"."coordination_bridges"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller  uuid := auth.uid();
  v_admin   boolean;
  v_bridge  public.coordination_bridges%ROWTYPE;
  v_result  public.coordination_bridges%ROWTYPE;
  v_role    text;
  v_label   text;
  v_unresolved int;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE='28000';
  END IF;
  SELECT EXISTS (SELECT 1 FROM public.profiles WHERE id=v_caller AND role IN ('admin','super_admin')) INTO v_admin;
  SELECT * INTO v_bridge FROM public.coordination_bridges WHERE id = p_bridge_id;
  IF v_bridge.id IS NULL THEN
    RAISE EXCEPTION 'bridge not found' USING ERRCODE='P0002';
  END IF;
  IF NOT v_admin AND v_bridge.inspector_id <> v_caller THEN
    RAISE EXCEPTION 'not authorised' USING ERRCODE='42501';
  END IF;
  IF v_bridge.status = 'completed' THEN
    RETURN v_bridge;
  END IF;

  -- Don't enforce required-slots-complete at the schema level — allow the
  -- inspector to explicitly close out even with imperfect coordination.
  -- The audit trail records what was open at close time.
  SELECT count(*) INTO v_unresolved
    FROM public.bridge_slots
   WHERE bridge_id = p_bridge_id
     AND required = true
     AND status NOT IN ('completed','rejected');

  UPDATE public.coordination_bridges
     SET status = 'completed',
         completed_at = now(),
         token_revoked_at = COALESCE(token_revoked_at, now())
   WHERE id = p_bridge_id
   RETURNING * INTO v_result;

  SELECT actor_role, actor_label INTO v_role, v_label FROM public.cb_actor_profile(v_caller);

  PERFORM public.cb_emit_audit(
    'coordination_bridge.completed',
    CASE WHEN v_unresolved > 0 THEN 'warning' ELSE 'info' END,
    v_caller, COALESCE(v_role,'inspector'), v_label,
    p_bridge_id, v_bridge.job_id,
    format('Coordination Bridge completed (%s unresolved required slot%s)',
      v_unresolved, CASE WHEN v_unresolved = 1 THEN '' ELSE 's' END),
    jsonb_build_object('unresolved_required_slots', v_unresolved),
    jsonb_build_object('job_id', v_bridge.job_id::text, 'bridge_id', p_bridge_id::text)
  );

  RETURN v_result;
END
$$;


ALTER FUNCTION "public"."bridge_complete"("p_bridge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bridge_create"("p_job_id" "uuid", "p_company_name" "text", "p_contact_name" "text", "p_contact_email" "text", "p_contact_phone" "text" DEFAULT NULL::"text", "p_country_code" "text" DEFAULT NULL::"text", "p_timezone" "text" DEFAULT NULL::"text", "p_language_code" "text" DEFAULT 'en'::"text", "p_token_ttl_days" integer DEFAULT 60) RETURNS TABLE("bridge_id" "uuid", "raw_token" "text", "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
  v_caller       uuid := auth.uid();
  v_is_admin     boolean;
  v_job          RECORD;
  v_existing_vc  uuid;
  v_vendor_id    uuid;
  v_bridge_id    uuid := gen_random_uuid();
  v_raw_token    text;
  v_token_hash   text;
  v_expires_at   timestamptz;
  v_actor_role   text;
  v_actor_label  text;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.profiles WHERE id = v_caller AND role IN ('admin','super_admin')
  ) INTO v_is_admin;

  -- Validate the job + caller authorisation.
  SELECT id, client_id, contractor_id, title
    INTO v_job
    FROM public.jobs WHERE id = p_job_id;
  IF v_job.id IS NULL THEN
    RAISE EXCEPTION 'job % not found', p_job_id USING ERRCODE = 'P0002';
  END IF;

  IF NOT v_is_admin AND v_job.contractor_id IS DISTINCT FROM v_caller THEN
    RAISE EXCEPTION 'only the assigned inspector or NEXPEC Admin may open a Coordination Bridge'
      USING ERRCODE = '42501';
  END IF;

  -- One bridge per job (UNIQUE constraint).
  IF EXISTS (SELECT 1 FROM public.coordination_bridges WHERE job_id = p_job_id) THEN
    RAISE EXCEPTION 'a Coordination Bridge already exists for job %; cancel it first', p_job_id
      USING ERRCODE = '23505';
  END IF;

  -- Validate inputs.
  IF p_company_name IS NULL OR length(trim(p_company_name)) = 0 THEN
    RAISE EXCEPTION 'company_name required' USING ERRCODE = '22023';
  END IF;
  IF p_contact_email IS NULL OR p_contact_email !~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' THEN
    RAISE EXCEPTION 'valid contact_email required' USING ERRCODE = '22023';
  END IF;
  IF p_token_ttl_days IS NULL OR p_token_ttl_days < 1 OR p_token_ttl_days > 365 THEN
    p_token_ttl_days := 60;
  END IF;

  -- Reuse vendor_contact if the same inspector previously invited the same email.
  -- Falls back to creating a fresh row.
  SELECT id INTO v_existing_vc
    FROM public.vendor_contacts
   WHERE created_by_user_id = COALESCE(v_job.contractor_id, v_caller)
     AND lower(contact_email) = lower(p_contact_email)
     AND deleted_at IS NULL
   LIMIT 1;

  IF v_existing_vc IS NOT NULL THEN
    v_vendor_id := v_existing_vc;
    UPDATE public.vendor_contacts
       SET company_name   = COALESCE(NULLIF(trim(p_company_name), ''), company_name),
           contact_name   = COALESCE(NULLIF(trim(p_contact_name), ''),  contact_name),
           contact_phone  = COALESCE(NULLIF(trim(p_contact_phone), ''), contact_phone),
           country_code   = COALESCE(NULLIF(trim(p_country_code), ''),  country_code),
           timezone       = COALESCE(NULLIF(trim(p_timezone), ''),      timezone),
           language_code  = COALESCE(NULLIF(trim(p_language_code), ''), language_code)
     WHERE id = v_vendor_id;
  ELSE
    INSERT INTO public.vendor_contacts (
      company_name, contact_name, contact_email, contact_phone,
      country_code, timezone, language_code, created_by_user_id
    )
    VALUES (
      trim(p_company_name),
      NULLIF(trim(p_contact_name), ''),
      lower(trim(p_contact_email)),
      NULLIF(trim(p_contact_phone), ''),
      NULLIF(trim(p_country_code), ''),
      NULLIF(trim(p_timezone), ''),
      COALESCE(NULLIF(trim(p_language_code), ''), 'en'),
      COALESCE(v_job.contractor_id, v_caller)
    )
    RETURNING id INTO v_vendor_id;
  END IF;

  -- Generate the magic-link token.
  v_raw_token  := encode(extensions.gen_random_bytes(32), 'hex');
  v_token_hash := encode(digest(v_raw_token, 'sha256'), 'hex');
  v_expires_at := now() + (p_token_ttl_days || ' days')::interval;

  -- Create the bridge.
  INSERT INTO public.coordination_bridges (
    id, job_id, vendor_contact_id, inspector_id, client_id,
    status, token_sha256, token_issued_at, token_expires_at
  )
  VALUES (
    v_bridge_id, p_job_id, v_vendor_id,
    COALESCE(v_job.contractor_id, v_caller),
    v_job.client_id,
    'pending_invite', v_token_hash, now(), v_expires_at
  );

  -- Seed standard slots.
  INSERT INTO public.bridge_slots (bridge_id, kind, status, title, description, required, sort_order, created_by_user_id, created_by_actor_kind)
  VALUES
    (v_bridge_id, 'schedule',          'awaiting_vendor', 'Confirm inspection date',
     'Propose or confirm the date and time the inspector will visit your site.', true, 10,
     v_caller, 'inspector'),
    (v_bridge_id, 'site_access',       'awaiting_vendor', 'Declare site access requirements',
     'PPE requirements, escort needs, badge protocol, entry hours.', true, 20,
     v_caller, 'inspector'),
    (v_bridge_id, 'pre_inspection_ack','awaiting_vendor', 'Acknowledge inspection scope',
     'Confirm the scope of work and that you are ready to host the inspection.', true, 30,
     v_caller, 'inspector'),
    (v_bridge_id, 'arrival_ack',       'pending',         'Sign inspector arrival',
     'Sign on the day of the inspection to confirm the inspector arrived on site.', true, 90,
     v_caller, 'inspector');

  -- Audit emit.
  SELECT actor_role, actor_label INTO v_actor_role, v_actor_label
    FROM public.cb_actor_profile(v_caller);

  PERFORM public.cb_emit_audit(
    'coordination_bridge.created',
    'info',
    v_caller,
    COALESCE(v_actor_role, 'inspector'),
    v_actor_label,
    v_bridge_id,
    p_job_id,
    format('Inspector opened a Coordination Bridge for vendor %s', p_company_name),
    jsonb_build_object(
      'vendor_contact_id', v_vendor_id,
      'vendor_company',    trim(p_company_name),
      'vendor_email',      lower(trim(p_contact_email)),
      'token_expires_at',  v_expires_at,
      'token_ttl_days',    p_token_ttl_days
    ),
    jsonb_build_object('job_id', p_job_id::text, 'bridge_id', v_bridge_id::text)
  );

  RETURN QUERY SELECT v_bridge_id, v_raw_token, v_expires_at;
END
$_$;


ALTER FUNCTION "public"."bridge_create"("p_job_id" "uuid", "p_company_name" "text", "p_contact_name" "text", "p_contact_email" "text", "p_contact_phone" "text", "p_country_code" "text", "p_timezone" "text", "p_language_code" "text", "p_token_ttl_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bridge_fetch_for_inspector"("p_bridge_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_admin  boolean;
  v_bridge public.coordination_bridges%ROWTYPE;
  v_vendor public.vendor_contacts%ROWTYPE;
  v_slots jsonb;
  v_docs  jsonb;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE='28000';
  END IF;
  SELECT EXISTS (SELECT 1 FROM public.profiles WHERE id=v_caller AND role IN ('admin','super_admin')) INTO v_admin;
  SELECT * INTO v_bridge FROM public.coordination_bridges WHERE id = p_bridge_id;
  IF v_bridge.id IS NULL THEN
    RAISE EXCEPTION 'bridge not found' USING ERRCODE='P0002';
  END IF;
  IF NOT v_admin AND v_bridge.inspector_id <> v_caller THEN
    RAISE EXCEPTION 'not authorised' USING ERRCODE='42501';
  END IF;

  SELECT * INTO v_vendor FROM public.vendor_contacts WHERE id = v_bridge.vendor_contact_id;

  SELECT COALESCE(jsonb_agg(row ORDER BY row->>'sort_order', row->>'created_at'), '[]'::jsonb)
    INTO v_slots
    FROM (
      SELECT to_jsonb(s) AS row FROM public.bridge_slots s
       WHERE s.bridge_id = p_bridge_id
    ) sub;

  SELECT COALESCE(jsonb_agg(row ORDER BY row->>'created_at' DESC), '[]'::jsonb)
    INTO v_docs
    FROM (
      SELECT to_jsonb(d) AS row FROM public.bridge_documents d
       WHERE d.bridge_id = p_bridge_id
    ) sub;

  RETURN jsonb_build_object(
    'bridge',    to_jsonb(v_bridge),
    'vendor',    to_jsonb(v_vendor),
    'slots',     v_slots,
    'documents', v_docs
  );
END
$$;


ALTER FUNCTION "public"."bridge_fetch_for_inspector"("p_bridge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bridge_propose_schedule"("p_bridge_id" "uuid", "p_proposed_at" timestamp with time zone, "p_timezone" "text" DEFAULT 'UTC'::"text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller  uuid := auth.uid();
  v_admin   boolean;
  v_bridge  RECORD;
  v_slot    RECORD;
  v_role    text;
  v_label   text;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '28000';
  END IF;
  SELECT EXISTS (SELECT 1 FROM public.profiles WHERE id=v_caller AND role IN ('admin','super_admin')) INTO v_admin;
  SELECT * INTO v_bridge FROM public.coordination_bridges WHERE id = p_bridge_id;
  IF v_bridge.id IS NULL THEN
    RAISE EXCEPTION 'bridge not found' USING ERRCODE='P0002';
  END IF;
  IF NOT v_admin AND v_bridge.inspector_id <> v_caller THEN
    RAISE EXCEPTION 'not authorised' USING ERRCODE='42501';
  END IF;
  IF v_bridge.status IN ('completed','cancelled') THEN
    RAISE EXCEPTION 'bridge is %; cannot mutate', v_bridge.status USING ERRCODE='22023';
  END IF;
  IF p_proposed_at IS NULL OR p_proposed_at < now() - interval '1 day' THEN
    RAISE EXCEPTION 'proposed_at must be a near-future timestamp' USING ERRCODE='22023';
  END IF;

  SELECT * INTO v_slot
    FROM public.bridge_slots
   WHERE bridge_id = p_bridge_id AND kind = 'schedule'
   LIMIT 1;
  IF v_slot.id IS NULL THEN
    RAISE EXCEPTION 'schedule slot missing — bridge corrupted' USING ERRCODE='P0002';
  END IF;

  UPDATE public.bridge_slots
     SET status                   = 'awaiting_vendor',
         payload_json             = jsonb_build_object(
           'proposed_at',       p_proposed_at,
           'timezone',          COALESCE(p_timezone, 'UTC'),
           'proposed_by_kind',  'inspector',
           'notes',             p_notes
         ),
         last_action_at           = now(),
         last_action_by_user_id   = v_caller,
         last_action_by_actor_kind = 'inspector',
         last_action_note         = p_notes
   WHERE id = v_slot.id;

  SELECT actor_role, actor_label INTO v_role, v_label FROM public.cb_actor_profile(v_caller);

  PERFORM public.cb_emit_audit(
    'coordination_bridge.schedule_proposed',
    'info',
    v_caller, COALESCE(v_role, 'inspector'), v_label,
    p_bridge_id, v_bridge.job_id,
    format('Inspector proposed inspection at %s (%s)', p_proposed_at, p_timezone),
    jsonb_build_object(
      'slot_id',     v_slot.id,
      'proposed_at', p_proposed_at,
      'timezone',    p_timezone
    ),
    jsonb_build_object('job_id', v_bridge.job_id::text, 'bridge_id', p_bridge_id::text)
  );

  RETURN v_slot.id;
END
$$;


ALTER FUNCTION "public"."bridge_propose_schedule"("p_bridge_id" "uuid", "p_proposed_at" timestamp with time zone, "p_timezone" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bridge_reject_document"("p_document_id" "uuid", "p_reason" "text") RETURNS "public"."bridge_documents"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller  uuid := auth.uid();
  v_admin   boolean;
  v_doc     public.bridge_documents%ROWTYPE;
  v_bridge  RECORD;
  v_result  public.bridge_documents%ROWTYPE;
  v_role    text;
  v_label   text;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE='28000';
  END IF;
  IF p_reason IS NULL OR length(trim(p_reason)) < 3 THEN
    RAISE EXCEPTION 'rejection reason required (>= 3 chars)' USING ERRCODE='22023';
  END IF;
  SELECT EXISTS (SELECT 1 FROM public.profiles WHERE id=v_caller AND role IN ('admin','super_admin')) INTO v_admin;
  SELECT * INTO v_doc FROM public.bridge_documents WHERE id = p_document_id;
  IF v_doc.id IS NULL THEN
    RAISE EXCEPTION 'document not found' USING ERRCODE='P0002';
  END IF;
  SELECT * INTO v_bridge FROM public.coordination_bridges WHERE id = v_doc.bridge_id;
  IF NOT v_admin AND v_bridge.inspector_id <> v_caller THEN
    RAISE EXCEPTION 'not authorised' USING ERRCODE='42501';
  END IF;
  IF v_doc.accepted_at IS NOT NULL THEN
    RAISE EXCEPTION 'document already accepted; cannot reject' USING ERRCODE='22023';
  END IF;

  UPDATE public.bridge_documents
     SET rejected_at = now(),
         rejected_by_user_id = v_caller,
         rejected_reason = trim(p_reason)
   WHERE id = p_document_id
   RETURNING * INTO v_result;

  -- Re-open the slot so the vendor can resubmit.
  IF v_result.slot_id IS NOT NULL THEN
    UPDATE public.bridge_slots
       SET status = 'awaiting_vendor',
           last_action_at = now(),
           last_action_by_user_id = v_caller,
           last_action_by_actor_kind = 'inspector',
           last_action_note = format('Document rejected: %s', trim(p_reason))
     WHERE id = v_result.slot_id;
  END IF;

  SELECT actor_role, actor_label INTO v_role, v_label FROM public.cb_actor_profile(v_caller);

  PERFORM public.cb_emit_audit(
    'coordination_bridge.document_rejected',
    'warning',
    v_caller, COALESCE(v_role,'inspector'), v_label,
    v_bridge.id, v_bridge.job_id,
    format('Inspector rejected document %s — %s', v_doc.original_filename, trim(p_reason)),
    jsonb_build_object(
      'document_id', v_doc.id,
      'slot_id',     v_doc.slot_id,
      'reason',      trim(p_reason)
    ),
    jsonb_build_object('job_id', v_bridge.job_id::text, 'bridge_id', v_bridge.id::text)
  );

  RETURN v_result;
END
$$;


ALTER FUNCTION "public"."bridge_reject_document"("p_document_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bridge_rotate_token"("p_bridge_id" "uuid", "p_token_ttl_days" integer DEFAULT 60) RETURNS TABLE("raw_token" "text", "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_caller    uuid := auth.uid();
  v_admin     boolean;
  v_bridge    RECORD;
  v_raw       text;
  v_hash      text;
  v_expires   timestamptz;
  v_role      text;
  v_label     text;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE='28000';
  END IF;
  SELECT EXISTS (SELECT 1 FROM public.profiles WHERE id=v_caller AND role IN ('admin','super_admin')) INTO v_admin;
  SELECT * INTO v_bridge FROM public.coordination_bridges WHERE id = p_bridge_id;
  IF v_bridge.id IS NULL THEN
    RAISE EXCEPTION 'bridge not found' USING ERRCODE='P0002';
  END IF;
  IF NOT v_admin AND v_bridge.inspector_id <> v_caller THEN
    RAISE EXCEPTION 'not authorised' USING ERRCODE='42501';
  END IF;
  IF v_bridge.status IN ('completed','cancelled') THEN
    RAISE EXCEPTION 'cannot rotate token for a % bridge', v_bridge.status USING ERRCODE='22023';
  END IF;
  IF p_token_ttl_days IS NULL OR p_token_ttl_days < 1 OR p_token_ttl_days > 365 THEN
    p_token_ttl_days := 60;
  END IF;

  v_raw     := encode(extensions.gen_random_bytes(32), 'hex');
  v_hash    := encode(digest(v_raw, 'sha256'), 'hex');
  v_expires := now() + (p_token_ttl_days || ' days')::interval;

  UPDATE public.coordination_bridges
     SET token_sha256     = v_hash,
         token_issued_at  = now(),
         token_expires_at = v_expires,
         token_revoked_at = NULL
   WHERE id = p_bridge_id;

  SELECT actor_role, actor_label INTO v_role, v_label FROM public.cb_actor_profile(v_caller);

  PERFORM public.cb_emit_audit(
    'coordination_bridge.token_rotated',
    'info',
    v_caller, COALESCE(v_role,'inspector'), v_label,
    p_bridge_id, v_bridge.job_id,
    'Magic-link token rotated (previous token now invalid).',
    jsonb_build_object('token_expires_at', v_expires),
    jsonb_build_object('job_id', v_bridge.job_id::text, 'bridge_id', p_bridge_id::text)
  );

  RETURN QUERY SELECT v_raw, v_expires;
END
$$;


ALTER FUNCTION "public"."bridge_rotate_token"("p_bridge_id" "uuid", "p_token_ttl_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bridge_send_invitation"("p_bridge_id" "uuid", "p_raw_token" "text", "p_portal_base" "text" DEFAULT 'https://app.nexpec.com/bridge'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_admin  boolean;
  v_bridge RECORD;
  v_vendor RECORD;
  v_job    RECORD;
  v_inspector RECORD;
  v_recipient_dummy_id uuid;
  v_notification_id uuid;
  v_portal_url text;
  v_template_data jsonb;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE='28000';
  END IF;
  SELECT EXISTS (SELECT 1 FROM public.profiles WHERE id=v_caller AND role IN ('admin','super_admin')) INTO v_admin;

  SELECT * INTO v_bridge FROM public.coordination_bridges WHERE id = p_bridge_id;
  IF v_bridge.id IS NULL THEN
    RAISE EXCEPTION 'bridge not found' USING ERRCODE='P0002';
  END IF;
  IF NOT v_admin AND v_bridge.inspector_id <> v_caller THEN
    RAISE EXCEPTION 'not authorised' USING ERRCODE='42501';
  END IF;
  IF p_raw_token IS NULL OR length(p_raw_token) < 32 THEN
    RAISE EXCEPTION 'raw_token required (64 hex chars)' USING ERRCODE='22023';
  END IF;
  -- Verify the presented raw token actually matches this bridge's stored hash.
  IF encode(digest(p_raw_token, 'sha256'), 'hex') <> v_bridge.token_sha256 THEN
    RAISE EXCEPTION 'raw_token does not match this bridge' USING ERRCODE='42501';
  END IF;

  SELECT * INTO v_vendor FROM public.vendor_contacts WHERE id = v_bridge.vendor_contact_id;
  SELECT id, title INTO v_job FROM public.jobs WHERE id = v_bridge.job_id;
  SELECT id, COALESCE(NULLIF(full_name, ''), email) AS display_name, email
    INTO v_inspector FROM public.profiles WHERE id = v_bridge.inspector_id;

  v_portal_url := rtrim(p_portal_base, '/') || '/' || p_raw_token;

  v_template_data := jsonb_build_object(
    'bridge_id',         v_bridge.id,
    'job_id',            v_bridge.job_id,
    'job_title',         COALESCE(NULLIF(v_job.title, ''), 'Inspection'),
    'inspector_name',    v_inspector.display_name,
    'vendor_company',    v_vendor.company_name,
    'vendor_contact',    v_vendor.contact_name,
    'vendor_email',      v_vendor.contact_email,
    'portal_url',        v_portal_url,
    'token_expires_at',  v_bridge.token_expires_at,
    'language_code',     v_vendor.language_code
  );

  -- The recipient is the vendor — they don't have a profile.id. We route
  -- the email through the inspector's profile as the "recipient_id" of
  -- record (this lets the existing notifications table accept the row)
  -- but the actual delivery email is the vendor's, embedded in the
  -- template kind. The dispatcher renders the vendor template and sends
  -- to vendor_email (NOT to the recipient profile's email).
  --
  -- Implementation detail: we use 'inspection_sealed_awaiting_countersign'-
  -- style approach where the template controls who actually receives the
  -- email. For vendor invitation we add a new path that overrides.
  --
  -- For Sprint B simplicity: we directly INSERT a notifications row
  -- targeted at the inspector and let the template_data carry the
  -- vendor's email address. The renderer at templates.ts:
  -- 'coordination_bridge.invitation' will be sent TO the vendor address.
  --
  -- This requires a small extension of dispatch-notification-emails:
  -- if template_data contains 'override_to', send to that address
  -- instead of the recipient profile's email.
  --
  -- That extension is delivered in the templates.ts patch in this sprint.

  INSERT INTO public.notifications (
    recipient_id, kind, title, body, link_href, job_id,
    email_required, email_template_kind, email_template_data
  )
  VALUES (
    v_bridge.inspector_id,
    'bridge_invitation_sent',
    format('Vendor invitation sent: %s', v_vendor.company_name),
    format('We emailed %s at %s with the Coordination Bridge link for %s.',
      COALESCE(v_vendor.contact_name, v_vendor.company_name),
      v_vendor.contact_email,
      COALESCE(NULLIF(v_job.title, ''), 'this inspection')),
    '/inspector/coordination-bridge?bridge_id=' || v_bridge.id::text,
    v_bridge.job_id,
    true,
    'coordination_bridge.invitation',
    v_template_data || jsonb_build_object('override_to', v_vendor.contact_email)
  )
  RETURNING id INTO v_notification_id;

  -- bump unread counter best-effort
  BEGIN
    UPDATE public.profiles
       SET unread_notifications_count = COALESCE(unread_notifications_count, 0) + 1
     WHERE id = v_bridge.inspector_id;
  EXCEPTION WHEN OTHERS THEN NULL; END;

  PERFORM public.cb_emit_audit(
    'coordination_bridge.invitation_sent',
    'info',
    v_caller, 'inspector', v_inspector.display_name,
    v_bridge.id, v_bridge.job_id,
    format('Magic-link invitation queued for delivery to %s', v_vendor.contact_email),
    jsonb_build_object('notification_id', v_notification_id, 'vendor_email', v_vendor.contact_email),
    jsonb_build_object('job_id', v_bridge.job_id::text, 'bridge_id', v_bridge.id::text)
  );

  RETURN v_notification_id;
END
$$;


ALTER FUNCTION "public"."bridge_send_invitation"("p_bridge_id" "uuid", "p_raw_token" "text", "p_portal_base" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bridge_vendor_accept_schedule"("p_raw_token" "text", "p_slot_id" "uuid") RETURNS "public"."bridge_slots"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_hash    text;
  v_bridge  RECORD;
  v_slot    public.bridge_slots%ROWTYPE;
  v_result  public.bridge_slots%ROWTYPE;
  v_proposed timestamptz;
BEGIN
  v_hash := encode(digest(p_raw_token, 'sha256'), 'hex');

  SELECT cb.id, cb.job_id, cb.status, cb.token_expires_at, cb.token_revoked_at, cb.inspector_id
    INTO v_bridge
    FROM public.coordination_bridges cb
   WHERE cb.token_sha256 = v_hash;
  IF v_bridge.id IS NULL THEN
    RAISE EXCEPTION 'invalid token' USING ERRCODE='42501';
  END IF;
  IF v_bridge.token_revoked_at IS NOT NULL THEN
    RAISE EXCEPTION 'token revoked' USING ERRCODE='42501';
  END IF;
  IF v_bridge.token_expires_at < now() THEN
    RAISE EXCEPTION 'token expired' USING ERRCODE='42501';
  END IF;
  IF v_bridge.status IN ('completed','cancelled') THEN
    RAISE EXCEPTION 'bridge is %; cannot mutate', v_bridge.status USING ERRCODE='22023';
  END IF;

  SELECT * INTO v_slot
    FROM public.bridge_slots
   WHERE id = p_slot_id AND bridge_id = v_bridge.id AND kind = 'schedule';
  IF v_slot.id IS NULL THEN
    RAISE EXCEPTION 'schedule slot not found' USING ERRCODE='P0002';
  END IF;

  v_proposed := (v_slot.payload_json ->> 'proposed_at')::timestamptz;
  IF v_proposed IS NULL THEN
    RAISE EXCEPTION 'no scheduled time has been proposed yet' USING ERRCODE='22023';
  END IF;

  UPDATE public.bridge_slots
     SET status = 'completed',
         completed_at = now(),
         payload_json = v_slot.payload_json
           || jsonb_build_object(
                'agreed_at',        v_proposed,
                'agreed_by_kind',   'vendor',
                'agreed_at_utc',    now()
              ),
         last_action_at = now(),
         last_action_by_actor_kind = 'vendor'
   WHERE id = p_slot_id
   RETURNING * INTO v_result;

  PERFORM public.cb_emit_audit(
    'coordination_bridge.schedule_accepted',
    'info',
    NULL, 'vendor', NULL,
    v_bridge.id, v_bridge.job_id,
    format('Vendor accepted scheduled inspection at %s', v_proposed),
    jsonb_build_object('slot_id', p_slot_id, 'agreed_at', v_proposed),
    jsonb_build_object('job_id', v_bridge.job_id::text, 'bridge_id', v_bridge.id::text)
  );

  RETURN v_result;
END
$$;


ALTER FUNCTION "public"."bridge_vendor_accept_schedule"("p_raw_token" "text", "p_slot_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bridge_vendor_acknowledge_scope"("p_raw_token" "text", "p_slot_id" "uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."bridge_slots"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_hash   text;
  v_bridge RECORD;
  v_slot   public.bridge_slots%ROWTYPE;
  v_result public.bridge_slots%ROWTYPE;
BEGIN
  v_hash := encode(digest(p_raw_token, 'sha256'), 'hex');
  SELECT cb.id, cb.job_id, cb.status, cb.token_expires_at, cb.token_revoked_at
    INTO v_bridge
    FROM public.coordination_bridges cb
   WHERE cb.token_sha256 = v_hash;
  IF v_bridge.id IS NULL OR v_bridge.token_revoked_at IS NOT NULL OR v_bridge.token_expires_at < now() THEN
    RAISE EXCEPTION 'invalid or expired token' USING ERRCODE = '42501';
  END IF;
  IF v_bridge.status IN ('completed','cancelled') THEN
    RAISE EXCEPTION 'bridge is %; cannot mutate', v_bridge.status USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_slot
    FROM public.bridge_slots
   WHERE id = p_slot_id AND bridge_id = v_bridge.id AND kind = 'pre_inspection_ack';
  IF v_slot.id IS NULL THEN
    RAISE EXCEPTION 'pre_inspection_ack slot not found' USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.bridge_slots
     SET status        = 'completed',
         completed_at  = now(),
         payload_json  = COALESCE(p_payload, '{}'::jsonb)
           || jsonb_build_object('acknowledged_at', now(), 'by_kind', 'vendor'),
         last_action_at            = now(),
         last_action_by_actor_kind = 'vendor'
   WHERE id = p_slot_id
   RETURNING * INTO v_result;

  PERFORM public.cb_emit_audit(
    'coordination_bridge.scope_acknowledged',
    'info',
    NULL, 'vendor', NULL,
    v_bridge.id, v_bridge.job_id,
    'Vendor acknowledged the inspection scope and confirmed readiness.',
    jsonb_build_object('slot_id', p_slot_id, 'payload', COALESCE(p_payload,'{}'::jsonb)),
    jsonb_build_object('job_id', v_bridge.job_id::text, 'bridge_id', v_bridge.id::text)
  );

  RETURN v_result;
END
$$;


ALTER FUNCTION "public"."bridge_vendor_acknowledge_scope"("p_raw_token" "text", "p_slot_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bridge_vendor_counter_schedule"("p_raw_token" "text", "p_slot_id" "uuid", "p_proposed_at" timestamp with time zone, "p_timezone" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "public"."bridge_slots"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_hash    text;
  v_bridge  RECORD;
  v_slot    public.bridge_slots%ROWTYPE;
  v_result  public.bridge_slots%ROWTYPE;
BEGIN
  v_hash := encode(digest(p_raw_token, 'sha256'), 'hex');
  SELECT cb.id, cb.job_id, cb.status, cb.token_expires_at, cb.token_revoked_at
    INTO v_bridge
    FROM public.coordination_bridges cb
   WHERE cb.token_sha256 = v_hash;
  IF v_bridge.id IS NULL OR v_bridge.token_revoked_at IS NOT NULL OR v_bridge.token_expires_at < now() THEN
    RAISE EXCEPTION 'invalid or expired token' USING ERRCODE='42501';
  END IF;
  IF v_bridge.status IN ('completed','cancelled') THEN
    RAISE EXCEPTION 'bridge is %; cannot mutate', v_bridge.status USING ERRCODE='22023';
  END IF;
  IF p_proposed_at IS NULL OR p_proposed_at < now() - interval '1 day' THEN
    RAISE EXCEPTION 'proposed_at must be a near-future timestamp' USING ERRCODE='22023';
  END IF;

  SELECT * INTO v_slot
    FROM public.bridge_slots
   WHERE id = p_slot_id AND bridge_id = v_bridge.id AND kind = 'schedule';
  IF v_slot.id IS NULL THEN
    RAISE EXCEPTION 'schedule slot not found' USING ERRCODE='P0002';
  END IF;

  UPDATE public.bridge_slots
     SET status = 'awaiting_inspector',
         payload_json = jsonb_build_object(
           'proposed_at',      p_proposed_at,
           'timezone',         COALESCE(p_timezone, 'UTC'),
           'proposed_by_kind', 'vendor',
           'notes',            p_notes,
           'previous_payload', v_slot.payload_json
         ),
         last_action_at = now(),
         last_action_by_actor_kind = 'vendor',
         last_action_note = p_notes
   WHERE id = p_slot_id
   RETURNING * INTO v_result;

  PERFORM public.cb_emit_audit(
    'coordination_bridge.schedule_counter_proposed',
    'info',
    NULL, 'vendor', NULL,
    v_bridge.id, v_bridge.job_id,
    format('Vendor counter-proposed inspection at %s', p_proposed_at),
    jsonb_build_object('slot_id', p_slot_id, 'proposed_at', p_proposed_at, 'timezone', p_timezone),
    jsonb_build_object('job_id', v_bridge.job_id::text, 'bridge_id', v_bridge.id::text)
  );

  RETURN v_result;
END
$$;


ALTER FUNCTION "public"."bridge_vendor_counter_schedule"("p_raw_token" "text", "p_slot_id" "uuid", "p_proposed_at" timestamp with time zone, "p_timezone" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bridge_vendor_declare_site_access"("p_raw_token" "text", "p_slot_id" "uuid", "p_payload" "jsonb") RETURNS "public"."bridge_slots"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_hash   text;
  v_bridge RECORD;
  v_slot   public.bridge_slots%ROWTYPE;
  v_result public.bridge_slots%ROWTYPE;
BEGIN
  v_hash := encode(digest(p_raw_token, 'sha256'), 'hex');
  SELECT cb.id, cb.job_id, cb.status, cb.token_expires_at, cb.token_revoked_at
    INTO v_bridge
    FROM public.coordination_bridges cb
   WHERE cb.token_sha256 = v_hash;
  IF v_bridge.id IS NULL OR v_bridge.token_revoked_at IS NOT NULL OR v_bridge.token_expires_at < now() THEN
    RAISE EXCEPTION 'invalid or expired token' USING ERRCODE='42501';
  END IF;
  IF v_bridge.status IN ('completed','cancelled') THEN
    RAISE EXCEPTION 'bridge is %; cannot mutate', v_bridge.status USING ERRCODE='22023';
  END IF;
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'payload must be a JSON object' USING ERRCODE='22023';
  END IF;

  SELECT * INTO v_slot
    FROM public.bridge_slots
   WHERE id = p_slot_id AND bridge_id = v_bridge.id AND kind = 'site_access';
  IF v_slot.id IS NULL THEN
    RAISE EXCEPTION 'site_access slot not found' USING ERRCODE='P0002';
  END IF;

  UPDATE public.bridge_slots
     SET status = 'awaiting_inspector',
         payload_json = p_payload || jsonb_build_object('declared_at', now()),
         last_action_at = now(),
         last_action_by_actor_kind = 'vendor'
   WHERE id = p_slot_id
   RETURNING * INTO v_result;

  PERFORM public.cb_emit_audit(
    'coordination_bridge.site_access_declared',
    'info',
    NULL, 'vendor', NULL,
    v_bridge.id, v_bridge.job_id,
    'Vendor declared site access requirements.',
    jsonb_build_object('slot_id', p_slot_id, 'payload', p_payload),
    jsonb_build_object('job_id', v_bridge.job_id::text, 'bridge_id', v_bridge.id::text)
  );

  RETURN v_result;
END
$$;


ALTER FUNCTION "public"."bridge_vendor_declare_site_access"("p_raw_token" "text", "p_slot_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bridge_vendor_get_state"("p_raw_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_hash text;
  v_bridge RECORD;
  v_job RECORD;
  v_inspector RECORD;
  v_slots jsonb;
  v_documents jsonb;
  v_vendor RECORD;
BEGIN
  v_hash := encode(digest(p_raw_token, 'sha256'), 'hex');

  SELECT * INTO v_bridge
    FROM public.coordination_bridges
   WHERE token_sha256 = v_hash;
  IF v_bridge.id IS NULL THEN
    RAISE EXCEPTION 'invalid token' USING ERRCODE='42501';
  END IF;

  SELECT id, title, location_city, scheduled_date
    INTO v_job FROM public.jobs WHERE id = v_bridge.job_id;
  SELECT id, COALESCE(NULLIF(full_name, ''), email) AS display_name
    INTO v_inspector FROM public.profiles WHERE id = v_bridge.inspector_id;
  SELECT id, company_name, contact_name, contact_email, language_code, timezone
    INTO v_vendor FROM public.vendor_contacts WHERE id = v_bridge.vendor_contact_id;

  SELECT COALESCE(jsonb_agg(row ORDER BY row->>'sort_order', row->>'created_at'), '[]'::jsonb)
    INTO v_slots
    FROM (
      SELECT jsonb_build_object(
        'id',           s.id,
        'kind',         s.kind,
        'status',       s.status,
        'title',        s.title,
        'description',  s.description,
        'required',     s.required,
        'sort_order',   s.sort_order,
        'payload',      s.payload_json,
        'created_at',   s.created_at,
        'last_action_at', s.last_action_at,
        'completed_at', s.completed_at
      ) AS row
        FROM public.bridge_slots s
       WHERE s.bridge_id = v_bridge.id
    ) sub;

  SELECT COALESCE(jsonb_agg(row ORDER BY row->>'created_at' DESC), '[]'::jsonb)
    INTO v_documents
    FROM (
      SELECT jsonb_build_object(
        'id',          d.id,
        'slot_id',     d.slot_id,
        'filename',    d.original_filename,
        'mime_type',   d.mime_type,
        'size_bytes',  d.file_size_bytes,
        'sha256',      d.sha256_client_computed,
        'created_at',  d.created_at,
        'accepted_at', d.accepted_at,
        'rejected_at', d.rejected_at,
        'rejected_reason', d.rejected_reason
      ) AS row
        FROM public.bridge_documents d
       WHERE d.bridge_id = v_bridge.id
         AND d.uploaded_by_actor_kind = 'vendor'
    ) sub;

  RETURN jsonb_build_object(
    'bridge', jsonb_build_object(
      'id',                v_bridge.id,
      'status',            v_bridge.status,
      'token_expires_at',  v_bridge.token_expires_at,
      'token_revoked_at',  v_bridge.token_revoked_at,
      'created_at',        v_bridge.created_at,
      'completed_at',      v_bridge.completed_at,
      'cancelled_at',      v_bridge.cancelled_at
    ),
    'job', jsonb_build_object(
      'id',             v_job.id,
      'title',          COALESCE(v_job.title, 'Inspection'),
      'location_city',  v_job.location_city,
      'scheduled_date', v_job.scheduled_date
    ),
    'inspector', jsonb_build_object(
      'display_name', v_inspector.display_name
    ),
    'vendor', jsonb_build_object(
      'id',            v_vendor.id,
      'company_name',  v_vendor.company_name,
      'contact_name',  v_vendor.contact_name,
      'contact_email', v_vendor.contact_email,
      'language_code', v_vendor.language_code,
      'timezone',      v_vendor.timezone
    ),
    'slots',     v_slots,
    'documents', v_documents
  );
END
$$;


ALTER FUNCTION "public"."bridge_vendor_get_state"("p_raw_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bridge_vendor_register_uploaded_document"("p_raw_token" "text", "p_slot_id" "uuid", "p_storage_path" "text", "p_filename" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_sha256" "text") RETURNS "public"."bridge_documents"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $_$
DECLARE
  v_hash    text;
  v_bridge  RECORD;
  v_slot    public.bridge_slots%ROWTYPE;
  v_doc_id  uuid := gen_random_uuid();
  v_result  public.bridge_documents%ROWTYPE;
BEGIN
  v_hash := encode(digest(p_raw_token, 'sha256'), 'hex');
  SELECT cb.id, cb.job_id, cb.status, cb.token_expires_at, cb.token_revoked_at,
         cb.vendor_contact_id
    INTO v_bridge
    FROM public.coordination_bridges cb
   WHERE cb.token_sha256 = v_hash;
  IF v_bridge.id IS NULL OR v_bridge.token_revoked_at IS NOT NULL OR v_bridge.token_expires_at < now() THEN
    RAISE EXCEPTION 'invalid or expired token' USING ERRCODE='42501';
  END IF;
  IF v_bridge.status IN ('completed','cancelled') THEN
    RAISE EXCEPTION 'bridge is %; cannot mutate', v_bridge.status USING ERRCODE='22023';
  END IF;
  IF p_sha256 IS NULL OR p_sha256 !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'sha256 must be 64 lowercase hex chars' USING ERRCODE='22023';
  END IF;

  SELECT * INTO v_slot
    FROM public.bridge_slots
   WHERE id = p_slot_id AND bridge_id = v_bridge.id AND kind = 'document_request';
  IF v_slot.id IS NULL THEN
    RAISE EXCEPTION 'document_request slot not found' USING ERRCODE='P0002';
  END IF;

  INSERT INTO public.bridge_documents (
    id, bridge_id, slot_id,
    uploaded_by_actor_kind, uploaded_via_token,
    uploaded_by_vendor_contact_id,
    storage_bucket, storage_path,
    original_filename, mime_type, file_size_bytes,
    sha256_client_computed
  )
  VALUES (
    v_doc_id, v_bridge.id, p_slot_id,
    'vendor', true,
    v_bridge.vendor_contact_id,
    'bridge-documents', p_storage_path,
    p_filename, p_mime_type, p_size_bytes,
    lower(p_sha256)
  )
  RETURNING * INTO v_result;

  UPDATE public.bridge_slots
     SET status = 'awaiting_inspector',
         last_action_at = now(),
         last_action_by_actor_kind = 'vendor'
   WHERE id = p_slot_id;

  PERFORM public.cb_emit_audit(
    'coordination_bridge.document_uploaded',
    'info',
    NULL, 'vendor', NULL,
    v_bridge.id, v_bridge.job_id,
    format('Vendor uploaded document %s (%s bytes)', p_filename, COALESCE(p_size_bytes::text, '?')),
    jsonb_build_object(
      'document_id',   v_doc_id,
      'slot_id',       p_slot_id,
      'filename',      p_filename,
      'mime_type',     p_mime_type,
      'size_bytes',    p_size_bytes,
      'sha256',        lower(p_sha256)
    ),
    jsonb_build_object('job_id', v_bridge.job_id::text, 'bridge_id', v_bridge.id::text)
  );

  RETURN v_result;
END
$_$;


ALTER FUNCTION "public"."bridge_vendor_register_uploaded_document"("p_raw_token" "text", "p_slot_id" "uuid", "p_storage_path" "text", "p_filename" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_sha256" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bridge_vendor_resolve_token"("p_raw_token" "text") RETURNS TABLE("bridge_id" "uuid", "job_id" "uuid", "vendor_contact_id" "uuid", "status" "public"."coordination_bridge_status", "token_expires_at" timestamp with time zone, "token_revoked_at" timestamp with time zone, "inspector_id" "uuid", "client_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_hash text;
BEGIN
  IF p_raw_token IS NULL OR length(p_raw_token) < 32 THEN
    RAISE EXCEPTION 'invalid token' USING ERRCODE='42501';
  END IF;
  v_hash := encode(digest(p_raw_token, 'sha256'), 'hex');

  RETURN QUERY
  SELECT cb.id, cb.job_id, cb.vendor_contact_id, cb.status,
         cb.token_expires_at, cb.token_revoked_at,
         cb.inspector_id, cb.client_id
    FROM public.coordination_bridges cb
   WHERE cb.token_sha256 = v_hash;
END
$$;


ALTER FUNCTION "public"."bridge_vendor_resolve_token"("p_raw_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bridge_vendor_sign_arrival"("p_raw_token" "text", "p_slot_id" "uuid", "p_typed_name" "text", "p_ip" "text" DEFAULT NULL::"text") RETURNS "public"."bridge_slots"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_hash   text;
  v_bridge RECORD;
  v_slot   public.bridge_slots%ROWTYPE;
  v_result public.bridge_slots%ROWTYPE;
BEGIN
  IF p_typed_name IS NULL OR length(trim(p_typed_name)) < 2 THEN
    RAISE EXCEPTION 'typed_name required' USING ERRCODE='22023';
  END IF;

  v_hash := encode(digest(p_raw_token, 'sha256'), 'hex');
  SELECT cb.id, cb.job_id, cb.status, cb.token_expires_at, cb.token_revoked_at
    INTO v_bridge
    FROM public.coordination_bridges cb
   WHERE cb.token_sha256 = v_hash;
  IF v_bridge.id IS NULL OR v_bridge.token_revoked_at IS NOT NULL OR v_bridge.token_expires_at < now() THEN
    RAISE EXCEPTION 'invalid or expired token' USING ERRCODE='42501';
  END IF;
  IF v_bridge.status IN ('completed','cancelled') THEN
    RAISE EXCEPTION 'bridge is %; cannot mutate', v_bridge.status USING ERRCODE='22023';
  END IF;

  SELECT * INTO v_slot
    FROM public.bridge_slots
   WHERE id = p_slot_id AND bridge_id = v_bridge.id AND kind = 'arrival_ack';
  IF v_slot.id IS NULL THEN
    RAISE EXCEPTION 'arrival_ack slot not found' USING ERRCODE='P0002';
  END IF;

  UPDATE public.bridge_slots
     SET status = 'completed',
         completed_at = now(),
         payload_json = jsonb_build_object(
           'typed_name', trim(p_typed_name),
           'ip',         p_ip,
           'signed_at',  now(),
           'by_kind',    'vendor'
         ),
         last_action_at = now(),
         last_action_by_actor_kind = 'vendor'
   WHERE id = p_slot_id
   RETURNING * INTO v_result;

  PERFORM public.cb_emit_audit(
    'coordination_bridge.arrival_signed',
    'info',
    NULL, 'vendor', NULL,
    v_bridge.id, v_bridge.job_id,
    format('Vendor "%s" signed inspector arrival.', trim(p_typed_name)),
    jsonb_build_object(
      'slot_id', p_slot_id,
      'typed_name', trim(p_typed_name),
      'ip', p_ip
    ),
    jsonb_build_object('job_id', v_bridge.job_id::text, 'bridge_id', v_bridge.id::text)
  );

  RETURN v_result;
END
$$;


ALTER FUNCTION "public"."bridge_vendor_sign_arrival"("p_raw_token" "text", "p_slot_id" "uuid", "p_typed_name" "text", "p_ip" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bridge_vendor_touch"("p_raw_token" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_hash text;
  v_bridge_id uuid;
  v_job_id uuid;
BEGIN
  v_hash := encode(digest(p_raw_token, 'sha256'), 'hex');
  SELECT id, job_id INTO v_bridge_id, v_job_id
    FROM public.coordination_bridges WHERE token_sha256 = v_hash;
  IF v_bridge_id IS NULL THEN RETURN; END IF;

  UPDATE public.coordination_bridges
     SET vendor_first_seen_at = COALESCE(vendor_first_seen_at, now()),
         vendor_last_seen_at  = now(),
         vendor_session_count = vendor_session_count + 1,
         status               = CASE
                                  WHEN status = 'pending_invite' THEN 'in_progress'
                                  ELSE status
                                END
   WHERE id = v_bridge_id;

  PERFORM public.cb_emit_audit(
    'coordination_bridge.vendor_session',
    'info',
    NULL, 'vendor', NULL,
    v_bridge_id, v_job_id,
    'Vendor opened the Coordination Bridge.',
    '{}'::jsonb,
    jsonb_build_object('job_id', v_job_id::text, 'bridge_id', v_bridge_id::text)
  );
END
$$;


ALTER FUNCTION "public"."bridge_vendor_touch"("p_raw_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bulk_update_inspector_specialties"("p_inspector_ids" "uuid"[], "p_add_slugs" "text"[] DEFAULT ARRAY[]::"text"[], "p_remove_slugs" "text"[] DEFAULT ARRAY[]::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_updated integer;
BEGIN
  IF NOT public.nx_is_admin() THEN
    RAISE EXCEPTION 'Super admin only' USING ERRCODE = '42501';
  END IF;

  IF cardinality(coalesce(p_inspector_ids, ARRAY[]::uuid[])) = 0 THEN
    RETURN jsonb_build_object('updated', 0, 'reason', 'no_inspectors');
  END IF;
  IF cardinality(coalesce(p_add_slugs, ARRAY[]::text[])) = 0
     AND cardinality(coalesce(p_remove_slugs, ARRAY[]::text[])) = 0 THEN
    RETURN jsonb_build_object('updated', 0, 'reason', 'no_changes');
  END IF;

  -- Eligibility filter now uses suspended_at (the actual soft-delete
  -- signal on profiles) instead of the non-existent deleted_at column.
  WITH updated AS (
    UPDATE public.profiles p
       SET specialty_slugs = (
             SELECT coalesce(array_agg(DISTINCT s ORDER BY s), ARRAY[]::text[])
               FROM unnest(
                 coalesce(p.specialty_slugs, ARRAY[]::text[])
                 || coalesce(p_add_slugs, ARRAY[]::text[])
               ) AS s
              WHERE NOT (s = ANY(coalesce(p_remove_slugs, ARRAY[]::text[])))
           ),
           updated_at = now()
     WHERE p.id = ANY(p_inspector_ids)
       AND p.role = 'inspector'
       AND p.suspended_at IS NULL
     RETURNING p.id
  )
  SELECT count(*)::int INTO v_updated FROM updated;

  RETURN jsonb_build_object('updated', v_updated);
END;
$$;


ALTER FUNCTION "public"."bulk_update_inspector_specialties"("p_inspector_ids" "uuid"[], "p_add_slugs" "text"[], "p_remove_slugs" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."bulk_update_inspector_specialties"("p_inspector_ids" "uuid"[], "p_add_slugs" "text"[], "p_remove_slugs" "text"[]) IS 'Bulk add and/or remove canonical kebab specialty slugs across multiple inspector profiles. Operates with set semantics — duplicates collapsed, remove_slugs takes precedence over add_slugs. SECURITY DEFINER with an explicit nx_is_admin() check. Eligibility filter uses suspended_at IS NULL (the soft-delete signal on profiles). Returns jsonb { updated: int }.';



CREATE OR REPLACE FUNCTION "public"."can_access_job_messages"("p_job_id" "uuid", "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_client_id UUID;
  v_hired_applicant_id UUID;
BEGIN
  -- چک کردن صاحب کار (Client)
  SELECT client_id INTO v_client_id FROM public.jobs WHERE id = p_job_id;
  IF v_client_id = p_user_id THEN RETURN true; END IF;
  
  -- چک کردن بازرس استخدام شده (Hired Applicant)
  SELECT applicant_id INTO v_hired_applicant_id 
  FROM public.applications 
  WHERE job_id = p_job_id AND status = 'hired' LIMIT 1;
  
  IF v_hired_applicant_id = p_user_id THEN RETURN true; END IF;
  
  RETURN false;
END;
$$;


ALTER FUNCTION "public"."can_access_job_messages"("p_job_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_assemble_evidence_for"("p_job_id" "uuid", "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_job        record;
  v_dept_org   uuid;
  v_user_role  text;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN false;
  END IF;

  -- Platform Owner — universal.
  SELECT role INTO v_user_role FROM public.profiles WHERE id = p_user_id;
  IF v_user_role IN ('admin','super_admin') THEN
    RETURN true;
  END IF;

  -- Pull job's identifying ids.
  SELECT id, client_id, contractor_id, department_id
    INTO v_job
    FROM public.jobs WHERE id = p_job_id;
  IF v_job.id IS NULL THEN
    RETURN false;
  END IF;

  -- Job parties get their own evidence pack.
  IF v_job.client_id = p_user_id OR v_job.contractor_id = p_user_id THEN
    RETURN true;
  END IF;

  -- Enterprise Admin gate — elevated role on the org that owns the
  -- attributed department. Project leads + viewers are deliberately
  -- excluded (signature IPs + approval comments are need-to-know).
  IF v_job.department_id IS NOT NULL THEN
    SELECT org_id INTO v_dept_org FROM public.departments WHERE id = v_job.department_id;
    IF v_dept_org IS NOT NULL THEN
      IF EXISTS (
        SELECT 1 FROM public.org_members
         WHERE org_id  = v_dept_org
           AND user_id = p_user_id
           AND role IN ('owner', 'procurement_admin')
      ) THEN
        RETURN true;
      END IF;
    END IF;
  END IF;

  RETURN false;
END;
$$;


ALTER FUNCTION "public"."can_assemble_evidence_for"("p_job_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_manage_org_structure"("p_org_id" "uuid", "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    EXISTS (
      SELECT 1 FROM public.profiles
      WHERE id = p_user_id AND role IN ('admin','super_admin')
    )
    OR EXISTS (
      SELECT 1 FROM public.org_members
      WHERE org_id  = p_org_id
        AND user_id = p_user_id
        AND role IN ('owner', 'procurement_admin')
    );
$$;


ALTER FUNCTION "public"."can_manage_org_structure"("p_org_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_raise_dispute"("p_project_id" "uuid", "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_project RECORD;
    v_existing_dispute RECORD;
BEGIN
    -- Check project exists and user is client
    SELECT * INTO v_project
    FROM public.projects
    WHERE id = p_project_id;
    
    IF v_project IS NULL THEN
        RETURN jsonb_build_object('allowed', false, 'reason', 'Project not found');
    END IF;
    
    IF v_project.client_id != p_user_id THEN
        RETURN jsonb_build_object('allowed', false, 'reason', 'Only the project client can raise disputes');
    END IF;
    
    IF v_project.status IN ('disputed', 'cancelled') THEN
        RETURN jsonb_build_object('allowed', false, 'reason', 'Project already has an active dispute or is cancelled');
    END IF;
    
    -- Check for existing open dispute
    SELECT * INTO v_existing_dispute
    FROM public.disputes
    WHERE project_id = p_project_id
    AND status IN ('open', 'under_review')
    LIMIT 1;
    
    IF v_existing_dispute IS NOT NULL THEN
        RETURN jsonb_build_object('allowed', false, 'reason', 'An open dispute already exists for this project');
    END IF;
    
    RETURN jsonb_build_object('allowed', true, 'reason', NULL);
END;
$$;


ALTER FUNCTION "public"."can_raise_dispute"("p_project_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_review_job"("p_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_res RECORD;
  v_exists UUID;
BEGIN
  SELECT j.id, j.title, j.status, j.client_id, a.applicant_id, p.first_name, p.last_name, p.avatar_url, p.rating_average, p.rating_count
  INTO v_res
  FROM public.jobs j
  LEFT JOIN public.applications a ON a.job_id = j.id AND a.status = 'accepted'
  LEFT JOIN public.profiles p ON a.applicant_id = p.id
  WHERE j.id = p_job_id;

  IF v_res.id IS NULL THEN RETURN jsonb_build_object('can_review', false, 'reason', 'Job not found'); END IF;
  IF v_res.client_id != auth.uid() THEN RETURN jsonb_build_object('can_review', false, 'reason', 'Unauthorized'); END IF;
  IF v_res.status != 'completed' THEN RETURN jsonb_build_object('can_review', false, 'reason', 'Job not completed'); END IF;
  
  SELECT id INTO v_exists FROM public.reviews WHERE job_id = p_job_id;
  IF v_exists IS NOT NULL THEN RETURN jsonb_build_object('can_review', false, 'reason', 'Already reviewed', 'review_id', v_exists); END IF;

  RETURN jsonb_build_object(
    'can_review', true,
    'job_id', v_res.id,
    'job_title', v_res.title,
    'inspector_id', v_res.applicant_id,
    'inspector_name', v_res.first_name || ' ' || v_res.last_name,
    'inspector_avatar', v_res.avatar_url,
    'inspector_rating', v_res.rating_average,
    'inspector_reviews', v_res.rating_count
  );
END;
$$;


ALTER FUNCTION "public"."can_review_job"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_review_job"("p_job_id" "uuid", "p_direction" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_eligible boolean := false;
  v_already boolean := false;
BEGIN
  IF v_uid IS NULL THEN RETURN false; END IF;
  IF p_direction NOT IN ('client_to_inspector','inspector_to_client') THEN RETURN false; END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.jobs j
     WHERE j.id = p_job_id AND j.status = 'completed'
       AND (
         (p_direction = 'client_to_inspector' AND j.client_id = v_uid)
         OR (p_direction = 'inspector_to_client' AND j.contractor_id = v_uid)
       )
  ) INTO v_eligible;
  IF NOT v_eligible THEN RETURN false; END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.reviews
     WHERE job_id = p_job_id AND reviewer_id = v_uid AND direction = p_direction
  ) INTO v_already;
  RETURN NOT v_already;
END $$;


ALTER FUNCTION "public"."can_review_job"("p_job_id" "uuid", "p_direction" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_job_approval"("p_job_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor       uuid := auth.uid();
  v_actor_role  text;
  v_actor_lbl   text;
  v_request     record;
  v_now         timestamptz := now();
  v_correlation uuid := gen_random_uuid();
  v_reason      text;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  v_reason := NULLIF(TRIM(COALESCE(p_reason, '')), '');
  IF v_reason IS NULL THEN
    RAISE EXCEPTION 'A reason is required to cancel an approval request' USING ERRCODE = '22000';
  END IF;

  SELECT *
    INTO v_request
    FROM public.approval_requests
   WHERE job_id = p_job_id
   FOR UPDATE;

  IF v_request.id IS NULL THEN
    RAISE EXCEPTION 'No approval request found for this job' USING ERRCODE = 'P0002';
  END IF;

  IF v_request.status <> 'pending' THEN
    RAISE EXCEPTION 'Approval request is already %', v_request.status USING ERRCODE = '22000';
  END IF;

  IF v_request.requested_by <> v_actor AND NOT public._actor_is_super_admin() THEN
    RAISE EXCEPTION 'Only the original requester or the Platform Owner can cancel an approval request'
      USING ERRCODE = '42501';
  END IF;

  UPDATE public.approval_requests
     SET status            = 'cancelled',
         final_decision_at = v_now,
         final_decision_by = v_actor,
         rejection_reason  = v_reason,
         updated_at        = v_now
   WHERE id = v_request.id;

  UPDATE public.jobs SET status = 'cancelled' WHERE id = p_job_id;

  IF to_regclass('public.audit_events') IS NOT NULL THEN
    SELECT actor_role, actor_label INTO v_actor_role, v_actor_lbl
      FROM public._dept_actor_profile(v_actor);

    INSERT INTO public.audit_events (
      event_type, actor_id, actor_role, actor_label,
      subject_table, subject_id, summary, delta, metadata, correlation_id
    ) VALUES (
      'job.approval.cancelled_by_requester',
      v_actor, v_actor_role, v_actor_lbl,
      'approval_requests', v_request.id,
      format('Approval request withdrawn — %s', v_reason),
      jsonb_build_object('reason', v_reason),
      jsonb_build_object('org_id', v_request.org_id, 'job_id', p_job_id, 'request_id', v_request.id),
      v_correlation
    );
  END IF;

  RETURN jsonb_build_object(
    'ok',             true,
    'request_id',     v_request.id,
    'correlation_id', v_correlation
  );
END;
$$;


ALTER FUNCTION "public"."cancel_job_approval"("p_job_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_meeting"("p_meeting_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_m public.job_meetings;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT * INTO v_m FROM public.job_meetings WHERE id = p_meeting_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown_meeting'; END IF;
  IF NOT (v_m.organizer_id = v_uid OR public.nx_is_admin()) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  UPDATE public.job_meetings SET status = 'cancelled', updated_at = now() WHERE id = p_meeting_id;
END $$;


ALTER FUNCTION "public"."cancel_meeting"("p_meeting_id" "uuid") OWNER TO "postgres";


