CREATE OR REPLACE FUNCTION "public"."check_department_budget"("p_department_id" "uuid", "p_as_of" "date" DEFAULT CURRENT_DATE, "p_additional_cents" bigint DEFAULT 0, "p_additional_currency" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor      uuid := auth.uid();
  v_budget     record;
  v_committed  bigint := 0;
  v_paid       bigint := 0;
  v_addl       bigint := COALESCE(p_additional_cents, 0);
  v_org_id     uuid;
  v_has_inv    boolean := to_regclass('public.invoices') IS NOT NULL;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT org_id INTO v_org_id FROM public.departments WHERE id = p_department_id;
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Department not found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT (public._actor_is_super_admin() OR public.is_member_of_org(v_org_id)) THEN
    RAISE EXCEPTION 'You do not have permission to read this budget' USING ERRCODE = '42501';
  END IF;

  -- Pick the budget whose period contains p_as_of for this department.
  SELECT id, allocated_cents, currency, fiscal_period_start, fiscal_period_end
    INTO v_budget
    FROM public.department_budgets
   WHERE department_id = p_department_id
     AND fiscal_period_start <= p_as_of
     AND fiscal_period_end   >  p_as_of
   ORDER BY created_at DESC
   LIMIT 1;

  IF v_budget.id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'has_budget',         false,
      'department_id',      p_department_id,
      'org_id',             v_org_id
    );
  END IF;

  -- Sum committed via job.budget_cents (the buyer's commitment at post
  -- time). When invoices exist they take precedence for paid amounts.
  WITH RECURSIVE subtree AS (
    SELECT id FROM public.departments WHERE id = p_department_id
    UNION ALL
    SELECT d.id FROM public.departments d
      JOIN subtree s ON s.id = d.parent_department_id
  )
  SELECT
    COALESCE(SUM(
      public.convert_cents(
        COALESCE(j.client_price_cents, 0),
        'USD',  -- jobs are recorded in USD-cents in baseline
        v_budget.currency::text,
        j.created_at
      )
    ), 0)::bigint
    INTO v_committed
    FROM public.jobs j
   WHERE j.department_id IN (SELECT id FROM subtree)
     AND j.status IN ('pending_approval','open','assigned','in_progress','completed','paid');

  -- Paid totals from invoices when available.
  IF v_has_inv THEN
    WITH RECURSIVE subtree AS (
      SELECT id FROM public.departments WHERE id = p_department_id
      UNION ALL
      SELECT d.id FROM public.departments d
        JOIN subtree s ON s.id = d.parent_department_id
    )
    SELECT
      COALESCE(SUM(
        public.convert_cents(
          i.total_cents,
          COALESCE(i.currency, 'USD'),
          v_budget.currency::text,
          i.issued_at
        )
      ), 0)::bigint
      INTO v_paid
      FROM public.invoices i
     WHERE i.department_id IN (SELECT id FROM subtree)
       AND i.status = 'paid';
  END IF;

  -- Convert the requested additional amount into the budget's currency.
  IF v_addl > 0 AND p_additional_currency IS NOT NULL THEN
    v_addl := COALESCE(
      public.convert_cents(v_addl, p_additional_currency, v_budget.currency::text, now()),
      v_addl  -- if FX path missing, treat additional as already in budget ccy (best effort)
    );
  END IF;

  RETURN jsonb_build_object(
    'ok',                  true,
    'has_budget',          true,
    'budget_id',           v_budget.id,
    'department_id',       p_department_id,
    'org_id',              v_org_id,
    'currency',            v_budget.currency,
    'period_start',        v_budget.fiscal_period_start,
    'period_end',          v_budget.fiscal_period_end,
    'allocated_cents',     v_budget.allocated_cents,
    'committed_cents',     v_committed,
    'paid_cents',          v_paid,
    'available_cents',     v_budget.allocated_cents - v_committed,
    'additional_cents',    v_addl,
    'would_exceed',        (v_committed + v_addl) > v_budget.allocated_cents,
    'projected_remaining', v_budget.allocated_cents - (v_committed + v_addl)
  );
END;
$$;


ALTER FUNCTION "public"."check_department_budget"("p_department_id" "uuid", "p_as_of" "date", "p_additional_cents" bigint, "p_additional_currency" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_expert_badge_eligibility"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_inspection_count INTEGER;
    v_dispute_count INTEGER;
    v_badge_id UUID;
BEGIN
    -- شمارش پروژه‌های موفق و شکایت‌ها
    SELECT COUNT(*) INTO v_inspection_count FROM public.projects WHERE inspector_id = NEW.inspector_id AND status = 'completed';
    SELECT COUNT(*) INTO v_dispute_count FROM public.disputes WHERE project_id IN (SELECT id FROM public.projects WHERE inspector_id = NEW.inspector_id);

    -- اگر ۱۰ پروژه موفق و ۰ شکایت داشت
    IF v_inspection_count >= 10 AND v_dispute_count = 0 THEN
        SELECT id INTO v_badge_id FROM public.badges WHERE name = 'Expert Inspector';
        
        INSERT INTO public.user_badges (user_id, badge_id)
        VALUES (NEW.inspector_id, v_badge_id)
        ON CONFLICT DO NOTHING;
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."check_expert_badge_eligibility"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_project_completion_lock"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    -- اگر وضعیت جدید 'completed' باشد اما وضعیت قبلی 'disputed' باشد
    IF NEW.status = 'completed' AND OLD.status = 'disputed' THEN
        -- بررسی اینکه آیا اختلاف باز (Open) برای این پروژه وجود دارد یا خیر
        IF EXISTS (
            SELECT 1 FROM public.disputes 
            WHERE project_id = NEW.id AND status NOT IN ('resolved', 'rejected')
        ) THEN
            RAISE EXCEPTION 'Cannot complete project: There is an unresolved dispute for this project.';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."check_project_completion_lock"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."ai_analysis_queue" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "kind" "text" NOT NULL,
    "subject_id" "uuid" NOT NULL,
    "job_id" "uuid",
    "model_kind" "text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "attempts" integer DEFAULT 0 NOT NULL,
    "max_attempts" integer DEFAULT 5 NOT NULL,
    "client_op_id" "text",
    "last_error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "claimed_at" timestamp with time zone,
    "processed_at" timestamp with time zone,
    CONSTRAINT "ai_analysis_queue_kind_check" CHECK (("kind" = ANY (ARRAY['visual_capture'::"text", 'document'::"text"]))),
    CONSTRAINT "ai_analysis_queue_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'processing'::"text", 'done'::"text", 'failed'::"text"])))
);


ALTER TABLE "public"."ai_analysis_queue" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_ai_analysis_jobs"("p_limit" integer DEFAULT 10) RETURNS SETOF "public"."ai_analysis_queue"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_limit int := GREATEST(1, LEAST(COALESCE(p_limit,10), 50));
BEGIN
  RETURN QUERY
  WITH claimed AS (
    SELECT q.id FROM public.ai_analysis_queue q
     WHERE q.status = 'pending' AND q.attempts < q.max_attempts
     ORDER BY q.created_at ASC
     LIMIT v_limit
     FOR UPDATE SKIP LOCKED
  )
  UPDATE public.ai_analysis_queue q
     SET status = 'processing', attempts = q.attempts + 1, claimed_at = now()
    FROM claimed WHERE q.id = claimed.id
  RETURNING q.*;
END $$;


ALTER FUNCTION "public"."claim_ai_analysis_jobs"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_pending_notification_emails"("p_limit" integer DEFAULT 25) RETURNS TABLE("id" "uuid", "recipient_id" "uuid", "recipient_email" "text", "recipient_name" "text", "kind" "text", "title" "text", "body" "text", "link_href" "text", "job_id" "uuid", "email_template_kind" "text", "email_template_data" "jsonb", "email_attempts" integer, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_limit int := GREATEST(1, LEAST(COALESCE(p_limit, 25), 100));
BEGIN
  RETURN QUERY
  WITH claimed AS (
    SELECT n.id
      FROM public.notifications n
     WHERE n.email_required = true
       AND n.email_dispatched_at IS NULL
       AND n.email_attempts < 5
     ORDER BY n.created_at ASC
     LIMIT v_limit
     FOR UPDATE SKIP LOCKED
  ),
  bumped AS (
    UPDATE public.notifications n
       SET email_attempts        = n.email_attempts + 1,
           email_last_attempt_at = now()
      FROM claimed
     WHERE n.id = claimed.id
    RETURNING n.*
  )
  SELECT b.id,
         b.recipient_id,
         p.email                                          AS recipient_email,
         COALESCE(NULLIF(p.full_name, ''), p.email)        AS recipient_name,
         b.kind,
         b.title,
         b.body,
         b.link_href,
         b.job_id,
         b.email_template_kind,
         b.email_template_data,
         b.email_attempts,
         b.created_at
    FROM bumped b
    JOIN public.profiles p ON p.id = b.recipient_id
   ORDER BY b.created_at ASC;
END
$$;


ALTER FUNCTION "public"."claim_pending_notification_emails"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_stripe_webhook_event"("p_event_id" "text", "p_type" "text", "p_payload" "jsonb") RETURNS TABLE("claimed" boolean, "reason" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_row_status text;
BEGIN
  INSERT INTO public.stripe_webhook_events
    (event_id, type, payload, status, claimed_at)
  VALUES
    (p_event_id, p_type, p_payload, 'processing', now())
  ON CONFLICT (event_id) DO NOTHING;

  IF FOUND THEN
    RETURN QUERY SELECT true, 'newly_claimed'::text;
    RETURN;
  END IF;

  SELECT status INTO v_row_status
    FROM public.stripe_webhook_events
   WHERE event_id = p_event_id
   FOR UPDATE;

  IF v_row_status IN ('pending', 'failed_retryable') THEN
    UPDATE public.stripe_webhook_events
       SET status = 'processing', claimed_at = now()
     WHERE event_id = p_event_id;
    RETURN QUERY SELECT true, 'reclaimed'::text;
    RETURN;
  END IF;

  IF v_row_status = 'processing' THEN
    RETURN QUERY SELECT false, 'in_flight_elsewhere'::text;
    RETURN;
  END IF;

  IF v_row_status = 'completed' THEN
    RETURN QUERY SELECT false, 'already_completed'::text;
    RETURN;
  END IF;

  RETURN QUERY SELECT false, 'unknown_status'::text;
END;
$$;


ALTER FUNCTION "public"."claim_stripe_webhook_event"("p_event_id" "text", "p_type" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_old_notification_logs"("days_to_keep" integer DEFAULT 90) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    deleted_count INTEGER;
BEGIN
    DELETE FROM notification_logs
    WHERE created_at < (CURRENT_TIMESTAMP - (days_to_keep || ' days')::INTERVAL);
    
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    
    RETURN deleted_count;
END;
$$;


ALTER FUNCTION "public"."cleanup_old_notification_logs"("days_to_keep" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clear_active_org"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  UPDATE public.profiles SET active_org_id = NULL WHERE id = v_actor;

  RETURN jsonb_build_object('ok', true, 'active_org_id', NULL);
END;
$$;


ALTER FUNCTION "public"."clear_active_org"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."client_review_engagement"("p_deal_id" "uuid", "p_decision" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_is_client boolean; v_review text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT (client_id = v_uid) INTO v_is_client FROM public.deals WHERE id = p_deal_id;
  IF NOT (coalesce(v_is_client,false) OR public.nx_is_admin()) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF p_decision NOT IN ('approved','objected') THEN RAISE EXCEPTION 'invalid_decision'; END IF;
  v_review := p_decision;

  UPDATE public.inspector_engagement_meta
     SET client_review = v_review,
         object_reason = CASE WHEN v_review = 'objected' THEN coalesce(p_reason,'other') ELSE NULL END,
         reviewed_at = now()
   WHERE deal_id = p_deal_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'no_engagement'; END IF;
  RETURN jsonb_build_object('deal_id', p_deal_id, 'client_review', v_review);
END $$;


ALTER FUNCTION "public"."client_review_engagement"("p_deal_id" "uuid", "p_decision" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."client_select_inspector"("p_deal_id" "uuid", "p_candidate_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_is_client boolean; v_c public.deal_inspector_candidates; v_res jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT (client_id = v_uid) INTO v_is_client FROM public.deals WHERE id = p_deal_id;
  IF NOT (COALESCE(v_is_client,false) OR public.nx_is_admin()) THEN RAISE EXCEPTION 'not_authorized'; END IF;

  SELECT * INTO v_c FROM public.deal_inspector_candidates WHERE id = p_candidate_id AND deal_id = p_deal_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown_candidate'; END IF;
  IF v_c.status = 'declined' THEN RAISE EXCEPTION 'candidate_declined'; END IF;

  UPDATE public.deal_inspector_candidates SET status = 'selected' WHERE id = p_candidate_id;
  UPDATE public.deal_inspector_candidates SET status = 'declined'
   WHERE deal_id = p_deal_id AND id <> p_candidate_id AND status = 'offered';

  -- selection is the approval → engagement with client_review = 'approved'
  v_res := public._brokered_create_engagement(p_deal_id, v_c.inspector_id, v_c.payout_cents, 'client_selection', 'approved');
  RETURN v_res || jsonb_build_object('candidate_id', p_candidate_id, 'selected', true);
END $$;


ALTER FUNCTION "public"."client_select_inspector"("p_deal_id" "uuid", "p_candidate_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."client_sign_job_contract"("p_contract_id" "uuid", "p_typed_name" "text", "p_ip" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_c RECORD;
BEGIN
  SELECT * INTO v_c FROM public.job_contracts WHERE id = p_contract_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'contract not found'; END IF;
  IF v_c.client_id <> auth.uid() THEN
    RAISE EXCEPTION 'only the client can sign this contract';
  END IF;
  IF v_c.status <> 'pending_client_signature' THEN
    RAISE EXCEPTION 'contract not awaiting client signature (status=%)', v_c.status;
  END IF;
  IF p_typed_name IS NULL OR length(trim(p_typed_name)) < 2 THEN
    RAISE EXCEPTION 'type your full legal name to sign';
  END IF;

  UPDATE public.job_contracts SET
    client_signed_at   = NOW(),
    client_signed_name = trim(p_typed_name),
    client_signed_ip   = p_ip,
    status             = 'pending_inspector_signature'
  WHERE id = p_contract_id;

  -- Promote job: open → assigned (inspector is now formally chosen).
  -- Guarded by status='open' so re-signs / out-of-order events are no-ops.
  UPDATE public.jobs SET
    status             = 'assigned',
    hired_inspector_id = v_c.inspector_id,
    updated_at         = NOW()
  WHERE id = v_c.job_id AND status = 'open';

  -- Notify the inspector
  BEGIN
    PERFORM public.create_system_notification(
      v_c.inspector_id,
      'Client signed — your turn',
      'Open the contract to sign and accept the assignment.',
      'contract_assigned',
      '/inspector/contracts/job/' || p_contract_id::text,
      v_c.job_id);
  EXCEPTION WHEN OTHERS THEN NULL; END;

  -- Notify admins (audit)
  BEGIN
    PERFORM public.create_admin_notification(
      'Client signed a job contract',
      'Awaiting inspector signature. Job moved to assigned.',
      'contract_assigned',
      '/admin/jobs?inspect=' || v_c.job_id::text,
      v_c.job_id);
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object('ok', true, 'status', 'pending_inspector_signature');
END $$;


ALTER FUNCTION "public"."client_sign_job_contract"("p_contract_id" "uuid", "p_typed_name" "text", "p_ip" "text") OWNER TO "postgres";


