CREATE OR REPLACE FUNCTION "public"."create_admin_notification"("p_title" "text", "p_body" "text", "p_type" "text", "p_link" "text" DEFAULT NULL::"text", "p_job_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE r RECORD; v_count int := 0;
BEGIN
  FOR r IN SELECT id FROM public.profiles WHERE role IN ('admin', 'super_admin')
  LOOP
    PERFORM public.create_system_notification(r.id, p_title, p_body, p_type, p_link, p_job_id);
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END $$;


