CREATE OR REPLACE FUNCTION "public"."create_department"("p_org_id" "uuid", "p_parent_department_id" "uuid", "p_name" "text", "p_cost_center" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor       uuid := auth.uid();
  v_actor_role  text;
  v_actor_label text;
  v_name        text;
  v_cost        text;
  v_id          uuid;
  v_correlation uuid := gen_random_uuid();
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.can_manage_org_structure(p_org_id, v_actor) THEN
    RAISE EXCEPTION 'You do not have permission to manage this organization''s structure'
      USING ERRCODE = '42501';
  END IF;

  IF p_org_id IS NULL THEN
    RAISE EXCEPTION 'org_id is required' USING ERRCODE = '22000';
  END IF;

  v_name := NULLIF(TRIM(COALESCE(p_name, '')), '');
  IF v_name IS NULL THEN
    RAISE EXCEPTION 'Department name is required' USING ERRCODE = '22000';
  END IF;

  v_cost := NULLIF(TRIM(COALESCE(p_cost_center, '')), '');

  IF NOT EXISTS (SELECT 1 FROM public.organizations WHERE id = p_org_id) THEN
    RAISE EXCEPTION 'Organization not found' USING ERRCODE = 'P0002';
  END IF;

  IF p_parent_department_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.departments
      WHERE id = p_parent_department_id AND org_id = p_org_id
    ) THEN
      RAISE EXCEPTION 'Parent department not found in this organization' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  INSERT INTO public.departments (org_id, parent_department_id, name, cost_center)
    VALUES (p_org_id, p_parent_department_id, v_name, v_cost)
    RETURNING id INTO v_id;

  -- Audit -----------------------------------------------------------
  SELECT actor_role, actor_label INTO v_actor_role, v_actor_label
    FROM public._dept_actor_profile(v_actor);

  INSERT INTO public.audit_events (
    event_type, actor_id, actor_role, actor_label,
    subject_table, subject_id, summary, delta, metadata, correlation_id
  ) VALUES (
    'department.created',
    v_actor,
    v_actor_role,
    v_actor_label,
    'departments',
    v_id,
    format('Department %L created', v_name),
    jsonb_build_object(
      'name', v_name,
      'cost_center', v_cost,
      'parent_department_id', p_parent_department_id
    ),
    jsonb_build_object('org_id', p_org_id),
    v_correlation
  );

  RETURN jsonb_build_object(
    'ok', true,
    'department_id', v_id,
    'org_id', p_org_id,
    'parent_department_id', p_parent_department_id,
    'name', v_name,
    'cost_center', v_cost,
    'correlation_id', v_correlation
  );
END;
$$;


ALTER FUNCTION "public"."create_department"("p_org_id" "uuid", "p_parent_department_id" "uuid", "p_name" "text", "p_cost_center" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_organization"("p_name" "text", "p_kind" "text" DEFAULT 'enterprise'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid  uuid := auth.uid();
  v_name text := btrim(coalesce(p_name, ''));
  v_kind text := lower(btrim(coalesce(p_kind, 'enterprise')));
  v_org  uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '28000';
  END IF;
  IF char_length(v_name) < 2 OR char_length(v_name) > 120 THEN
    RAISE EXCEPTION 'Organization name must be 2-120 characters' USING ERRCODE = '22000';
  END IF;
  IF v_kind NOT IN ('enterprise', 'agency') THEN
    v_kind := 'enterprise';
  END IF;

  INSERT INTO public.organizations (name, kind, owner_id, is_active)
       VALUES (v_name, v_kind, v_uid, true)
    RETURNING id INTO v_org;

  -- The creator becomes the owner.
  INSERT INTO public.org_members (org_id, user_id, role)
       VALUES (v_org, v_uid, 'owner')
  ON CONFLICT (org_id, user_id) DO UPDATE SET role = 'owner';

  RETURN jsonb_build_object('ok', true, 'org_id', v_org, 'name', v_name, 'kind', v_kind);
END;
$$;


ALTER FUNCTION "public"."create_organization"("p_name" "text", "p_kind" "text") OWNER TO "postgres";


