CREATE OR REPLACE FUNCTION "public"."create_system_notification"("p_user_id" "uuid", "p_title" "text", "p_body" "text", "p_type" "text", "p_link" "text" DEFAULT NULL::"text", "p_job_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_id uuid;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN NULL;
  END IF;
  INSERT INTO public.notifications(recipient_id, kind, title, body, link_href, job_id)
    VALUES (p_user_id, p_type, p_title, p_body, p_link, p_job_id)
    RETURNING id INTO v_id;

  -- Bump the cached unread counter — try / catch so a missing column
  -- never blocks the notify.
  BEGIN
    UPDATE public.profiles
       SET unread_notifications_count = COALESCE(unread_notifications_count, 0) + 1
     WHERE id = p_user_id;
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'create_system_notification: counter bump failed: %', SQLERRM;
  END;

  RETURN v_id;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'create_system_notification(%, %): %', p_user_id, p_title, SQLERRM;
  RETURN NULL;
END $$;


ALTER FUNCTION "public"."create_system_notification"("p_user_id" "uuid", "p_title" "text", "p_body" "text", "p_type" "text", "p_link" "text", "p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."credit_inspector_earning_on_approval"("p_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_job public.jobs%ROWTYPE;
  v_inspector uuid;
  v_cents bigint;
  v_dollars numeric(12,2);
  v_cleared boolean;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.nx_is_admin() THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_job FROM public.jobs WHERE id = p_job_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'JOB_NOT_FOUND' USING ERRCODE = 'P0002'; END IF;

  v_inspector := v_job.contractor_id;                 -- canonical inspector link
  IF v_inspector IS NULL THEN RAISE EXCEPTION 'NO_CONTRACTOR_ON_JOB'; END IF;
  IF v_job.admin_confirmed_at IS NULL THEN RAISE EXCEPTION 'REPORT_NOT_CONFIRMED'; END IF;

  v_cents := COALESCE(v_job.inspector_payout_cents, 0);
  IF v_cents <= 0 THEN RAISE EXCEPTION 'NO_PAYOUT_AMOUNT'; END IF;
  v_dollars := round(v_cents::numeric / 100.0, 2);

  -- Idempotency: exactly one earning credit per job.
  IF EXISTS (SELECT 1 FROM public.transactions WHERE job_id = p_job_id AND inspector_id = v_inspector AND type = 'earning') THEN
    RETURN jsonb_build_object('ok', true, 'idempotent', true, 'job_id', p_job_id);
  END IF;

  INSERT INTO public.wallets(user_id) VALUES (v_inspector) ON CONFLICT (user_id) DO NOTHING;
  PERFORM 1 FROM public.wallets WHERE user_id = v_inspector FOR UPDATE;

  v_cleared := (COALESCE(v_job.payment_mode, 'prepay') = 'prepay');  -- prepay already funded

  IF v_cleared THEN
    UPDATE public.wallets
       SET available_balance = COALESCE(available_balance,0) + v_dollars,
           total_earned      = COALESCE(total_earned,0) + v_dollars,
           updated_at = now()
     WHERE user_id = v_inspector;
  ELSE
    UPDATE public.wallets
       SET pending_amount = COALESCE(pending_amount,0) + v_dollars,
           total_earned   = COALESCE(total_earned,0) + v_dollars,
           updated_at = now()
     WHERE user_id = v_inspector;
  END IF;

  INSERT INTO public.transactions(user_id, inspector_id, job_id, type, amount,
        gross_amount_halalas, platform_fee_halalas, net_amount_halalas, status, description)
  VALUES (v_inspector, v_inspector, p_job_id, 'earning', v_dollars,
        v_cents, 0, v_cents,
        CASE WHEN v_cleared THEN 'completed' ELSE 'pending' END,
        CASE WHEN v_cleared THEN 'Inspection earning (cleared)'
             ELSE 'Inspection earning (accrued — awaiting client settlement)' END);

  RETURN jsonb_build_object('ok', true, 'inspector_id', v_inspector, 'amount_cents', v_cents, 'cleared', v_cleared);
END $$;


ALTER FUNCTION "public"."credit_inspector_earning_on_approval"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cron_kickoff_email_dispatch"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  -- آدرس و رمز ثابت در اینجا قرار گرفتند
  v_base_url    text := 'https://sxqpjxhslzzcdrdctatm.supabase.co';
  v_cron_secret text := 'nexpec-super-secret-cron-key-2026';
  v_pending     int;
BEGIN
  SELECT count(*) INTO v_pending
    FROM public.notifications
   WHERE email_required = true
     AND email_dispatched_at IS NULL
     AND email_attempts < 5;

  IF v_pending = 0 THEN
    RETURN;
  END IF;

  PERFORM net.http_post(
    url     := v_base_url || '/functions/v1/dispatch-notification-emails',
    headers := jsonb_build_object(
                 'Content-Type',  'application/json',
                 'Authorization', 'Bearer ' || v_cron_secret
               ),
    body    := jsonb_build_object(
                 'triggered_by', 'pg_cron',
                 'triggered_at', now(),
                 'pending_estimate', v_pending
               ),
    timeout_milliseconds := 60000
  );
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'cron_kickoff_email_dispatch: %', SQLERRM;
END
$$;


ALTER FUNCTION "public"."cron_kickoff_email_dispatch"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cron_kickoff_fx_refresh"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  -- آدرس و رمز ثابت در اینجا قرار گرفتند
  v_base_url    text := 'https://sxqpjxhslzzcdrdctatm.supabase.co';
  v_cron_secret text := 'nexpec-super-secret-cron-key-2026';
  v_run_id      uuid := gen_random_uuid();
  v_request_id  bigint;
BEGIN
  INSERT INTO public.fx_refresh_runs (id, source, cron_jobid)
       VALUES (v_run_id, 'openexchangerates', NULLIF(current_setting('cron.job_id', true), '')::bigint);

  SELECT net.http_post(
    url     := v_base_url || '/functions/v1/refresh-fx-rates',
    headers := jsonb_build_object(
                 'Content-Type',  'application/json',
                 'Authorization', 'Bearer ' || v_cron_secret
               ),
    body    := jsonb_build_object(
                 'run_id', v_run_id,
                 'triggered_by', 'pg_cron',
                 'triggered_at', now()
               ),
    timeout_milliseconds := 30000
  ) INTO v_request_id;

  UPDATE public.fx_refresh_runs
     SET request_id = v_request_id
   WHERE id = v_run_id;

EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'cron_kickoff_fx_refresh: %', SQLERRM;
END
$$;


