CREATE TABLE IF NOT EXISTS "public"."fx_rates" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "base_currency" "public"."currency_code" NOT NULL,
    "quote_currency" "public"."currency_code" NOT NULL,
    "rate" numeric(20,10) NOT NULL,
    "effective_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "source" "text" DEFAULT 'manual'::"text" NOT NULL,
    CONSTRAINT "fx_rates_rate_check" CHECK (("rate" > (0)::numeric)),
    CONSTRAINT "fx_rates_self_is_one" CHECK ((("base_currency" <> "quote_currency") OR ("rate" = (1)::numeric)))
);


ALTER TABLE "public"."fx_rates" OWNER TO "postgres";


COMMENT ON TABLE "public"."fx_rates" IS 'Time-series exchange rates. Conversion is always read-time projection over immutable invoice native values.';



CREATE OR REPLACE FUNCTION "public"."cron_upsert_fx_rate"("p_base_currency" "text", "p_quote_currency" "text", "p_rate" numeric, "p_effective_date" "date" DEFAULT CURRENT_DATE, "p_source" "text" DEFAULT 'openexchangerates'::"text") RETURNS "public"."fx_rates"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_base  public.currency_code;
  v_quote public.currency_code;
  v_row   public.fx_rates;
BEGIN
  IF p_rate IS NULL OR p_rate <= 0 THEN
    RAISE EXCEPTION 'rate must be positive, got %', p_rate
      USING ERRCODE = '22023';
  END IF;

  -- Defensive enum casting.
  BEGIN
    v_base  := upper(p_base_currency)::public.currency_code;
    v_quote := upper(p_quote_currency)::public.currency_code;
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'unsupported currency pair: % → %', p_base_currency, p_quote_currency
      USING ERRCODE = '22023';
  END;

  -- Self-pair is always identity, and the table CHECK enforces this.
  IF v_base = v_quote AND p_rate <> 1 THEN
    RAISE EXCEPTION 'self-pair rate must be 1.0, got %', p_rate
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.fx_rates (
    base_currency,
    quote_currency,
    rate,
    effective_date,
    source
  )
  VALUES (
    v_base,
    v_quote,
    p_rate,
    COALESCE(p_effective_date, current_date),
    COALESCE(p_source, 'openexchangerates')
  )
  ON CONFLICT (base_currency, quote_currency, effective_date) DO UPDATE
    SET rate   = EXCLUDED.rate,
        source = EXCLUDED.source
  RETURNING * INTO v_row;

  RETURN v_row;
END
$$;


ALTER FUNCTION "public"."cron_upsert_fx_rate"("p_base_currency" "text", "p_quote_currency" "text", "p_rate" numeric, "p_effective_date" "date", "p_source" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cron_upsert_fx_rate"("p_base_currency" "text", "p_quote_currency" "text", "p_rate" numeric, "p_effective_date" "date", "p_source" "text") IS 'Service-role-only FX rate writer used by the refresh-fx-rates Edge Function. Called via PostgREST /rpc/ with the service-role key. Authenticated users must use upsert_fx_rate(...) instead.';



CREATE OR REPLACE FUNCTION "public"."debit_wallet_for_payout"("p_user_id" "uuid", "p_amount_cents" bigint) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_balance NUMERIC;
  v_amount_dollars NUMERIC;
  v_txn_id UUID;
BEGIN
  v_amount_dollars := p_amount_cents::numeric / 100.0;
  SELECT available_balance INTO v_balance FROM public.wallets WHERE user_id = p_user_id FOR UPDATE;
  IF v_balance IS NULL THEN RAISE EXCEPTION 'WALLET_NOT_FOUND' USING ERRCODE = 'P0002'; END IF;
  IF v_balance < v_amount_dollars THEN
    RAISE EXCEPTION 'INSUFFICIENT_BALANCE: % < %', v_balance, v_amount_dollars USING ERRCODE = 'P0001';
  END IF;
  UPDATE public.wallets SET available_balance = available_balance - v_amount_dollars, updated_at = now()
   WHERE user_id = p_user_id;
  INSERT INTO public.transactions (user_id, type, amount, gross_amount_halalas, platform_fee_halalas, status, description, created_at)
  VALUES (p_user_id, 'payout', v_amount_dollars, p_amount_cents, 0, 'processing', 'Stripe Connect payout to bank', now())
  RETURNING id INTO v_txn_id;
  RETURN v_txn_id;
END $$;


ALTER FUNCTION "public"."debit_wallet_for_payout"("p_user_id" "uuid", "p_amount_cents" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_department"("p_department_id" "uuid", "p_force" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor       uuid := auth.uid();
  v_actor_role  text;
  v_actor_label text;
  v_org_id      uuid;
  v_descendant_count int;
  v_member_count     int;
  v_name             text;
  v_correlation uuid := gen_random_uuid();
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT org_id, name INTO v_org_id, v_name
    FROM public.departments WHERE id = p_department_id FOR UPDATE;
  IF v_name IS NULL THEN
    RAISE EXCEPTION 'Department not found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.can_manage_org_structure(v_org_id, v_actor) THEN
    RAISE EXCEPTION 'You do not have permission to manage this organization''s structure'
      USING ERRCODE = '42501';
  END IF;

  WITH RECURSIVE descendants AS (
    SELECT id FROM public.departments WHERE id = p_department_id
    UNION ALL
    SELECT d.id FROM public.departments d
      JOIN descendants dx ON dx.id = d.parent_department_id
  )
  SELECT
    (SELECT count(*) - 1 FROM descendants),
    (SELECT count(*) FROM public.department_members WHERE department_id IN (SELECT id FROM descendants))
  INTO v_descendant_count, v_member_count;

  IF (v_member_count > 0 OR v_descendant_count > 0) AND COALESCE(p_force, false) IS FALSE THEN
    RAISE EXCEPTION 'Department has % descendants and % members. Pass p_force=true to delete.',
      v_descendant_count, v_member_count
      USING ERRCODE = '22000';
  END IF;

  DELETE FROM public.departments WHERE id = p_department_id;

  SELECT actor_role, actor_label INTO v_actor_role, v_actor_label
    FROM public._dept_actor_profile(v_actor);

  INSERT INTO public.audit_events (
    event_type, actor_id, actor_role, actor_label,
    subject_table, subject_id, summary, delta, metadata, correlation_id, severity
  ) VALUES (
    'department.deleted',
    v_actor,
    v_actor_role,
    v_actor_label,
    'departments',
    p_department_id,
    format('Department %L deleted (cascade: %s descendants, %s member assignments)',
      v_name, v_descendant_count, v_member_count),
    jsonb_build_object(
      'name', v_name,
      'descendants_removed', v_descendant_count,
      'members_orphaned', v_member_count
    ),
    jsonb_build_object('org_id', v_org_id),
    v_correlation,
    CASE WHEN v_descendant_count > 0 OR v_member_count > 0 THEN 'warning' ELSE 'info' END
  );

  RETURN jsonb_build_object(
    'ok', true,
    'department_id', p_department_id,
    'descendants_removed', v_descendant_count,
    'members_orphaned', v_member_count,
    'correlation_id', v_correlation
  );
END;
$$;


ALTER FUNCTION "public"."delete_department"("p_department_id" "uuid", "p_force" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_user"() RETURNS "void"
