    AS $$
begin
  -- 1. پاک کردن پروفایل کاربر (اگر جدول profiles داری)
  delete from public.profiles where id = auth.uid();
  
  -- 2. پاک کردن اکانت اصلی از سیستم احراز هویت Supabase
  delete from auth.users where id = auth.uid();
end;
