CREATE OR REPLACE FUNCTION "public"."detect_band_evasion_pattern"("p_org_id" "uuid") RETURNS TABLE("severity" "text", "finding" "text", "metadata" "jsonb", "detected_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public._compliance_actor_can_read(p_org_id) THEN
    RAISE EXCEPTION 'You do not have permission to read this organization''s anomalies'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH bands AS (
    SELECT min_amount_cents, max_amount_cents, currency
      FROM public.approval_policies
     WHERE org_id = p_org_id AND is_active = true
  ),
  member_ids AS (
    SELECT user_id FROM public.org_members WHERE org_id = p_org_id
  ),
  near_misses AS (
    SELECT j.id, j.title, j.client_id, j.budget_cents, j.created_at, b.min_amount_cents
      FROM public.jobs j
      JOIN bands b ON
        j.budget_cents >= (b.min_amount_cents * 0.95)::bigint
        AND j.budget_cents < b.min_amount_cents
     WHERE j.created_at >= now() - interval '30 days'
       AND j.client_id IN (SELECT user_id FROM member_ids)
  ),
  by_poster AS (
    SELECT client_id, count(*) AS hits, array_agg(id) AS job_ids,
           array_agg(title) AS titles, max(budget_cents) AS max_budget
      FROM near_misses
     GROUP BY client_id
    HAVING count(*) >= 2
  )
  SELECT
    (CASE WHEN bp.hits >= 4 THEN 'critical'
          WHEN bp.hits >= 3 THEN 'warning'
          ELSE 'info' END)                                    AS severity,
    format(
      '%s posted %s job(s) within 5%% of an approval threshold in the last 30 days. Possible control circumvention.',
      coalesce(NULLIF(TRIM(p.full_name), ''), p.email, 'A buyer'),
      bp.hits
    )                                                          AS finding,
    jsonb_build_object(
      'poster_id',  bp.client_id,
      'poster_label', coalesce(NULLIF(TRIM(p.full_name), ''), p.email),
      'job_ids',    to_jsonb(bp.job_ids),
      'job_titles', to_jsonb(bp.titles),
      'max_budget_cents', bp.max_budget
    )                                                          AS metadata,
    now()                                                       AS detected_at
    FROM by_poster bp
    LEFT JOIN public.profiles p ON p.id = bp.client_id
   ORDER BY bp.hits DESC, bp.max_budget DESC;
END;
$$;


ALTER FUNCTION "public"."detect_band_evasion_pattern"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."detect_client_cancellation_spam"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_recent     int;
  v_threshold  int := 3;
BEGIN
  -- Fire only on the actual transition INTO 'cancelled'.
  IF NOT (OLD.status IS DISTINCT FROM NEW.status AND NEW.status = 'cancelled') THEN
    RETURN NEW;
  END IF;

  IF NEW.client_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Count this client's currently-cancelled jobs whose last UPDATE was
  -- in the past hour. The just-cancelled row is included (AFTER UPDATE).
  SELECT count(*) INTO v_recent
  FROM public.jobs
  WHERE client_id = NEW.client_id
    AND status = 'cancelled'
    AND deleted_at IS NULL
    AND updated_at > now() - interval '1 hour';

  IF v_recent >= v_threshold THEN
    -- Emit a fraud_alert event. Push pipeline (Task 1) picks it up
    -- and notifies super-admins.
    INSERT INTO public.job_events (
      job_id, actor_id, event_type, metadata
    )
    VALUES (
      NEW.id,
      auth.uid(),
      'fraud_alert',
      jsonb_build_object(
        'kind',                  'cancellation_spam',
        'client_id',             NEW.client_id,
        'recent_cancellations',  v_recent,
        'window_minutes',        60,
        'threshold',             v_threshold,
        'detected_at',           now()
      )
    );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."detect_client_cancellation_spam"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."detect_concentration_risk"("p_org_id" "uuid") RETURNS TABLE("severity" "text", "finding" "text", "metadata" "jsonb", "detected_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
BEGIN
  IF NOT public._compliance_actor_can_read(p_org_id) THEN
    RAISE EXCEPTION 'You do not have permission to read this organization''s anomalies'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH member_ids AS (
    SELECT user_id FROM public.org_members WHERE org_id = p_org_id
  ),
  pairings AS (
    SELECT j.client_id, j.contractor_id, count(*) AS hire_count,
           sum(coalesce(j.client_price_cents, j.budget_cents, 0)) AS total_cents
      FROM public.jobs j
     WHERE j.created_at >= now() - interval '180 days'
       AND j.contractor_id IS NOT NULL
       AND j.client_id IN (SELECT user_id FROM member_ids)
     GROUP BY j.client_id, j.contractor_id
    HAVING count(*) >= 5
  )
  SELECT
    (CASE WHEN pa.hire_count >= 10 THEN 'critical'
          WHEN pa.hire_count >= 7  THEN 'warning'
          ELSE 'info' END)                                AS severity,
    format(
      '%s hired %s %s times in the last 180 days (total committed: $%s). Consider rotation or competitive bidding.',
      coalesce(NULLIF(TRIM(pb.full_name), ''), pb.email, 'A buyer'),
      coalesce(NULLIF(TRIM(pi.full_name), ''), pi.email, 'an inspector'),
      pa.hire_count,
      (pa.total_cents::numeric / 100)::text
    )                                                       AS finding,
    jsonb_build_object(
      'buyer_id', pa.client_id,
      'buyer_label', coalesce(NULLIF(TRIM(pb.full_name), ''), pb.email),
      'inspector_id', pa.contractor_id,
      'inspector_label', coalesce(NULLIF(TRIM(pi.full_name), ''), pi.email),
      'hire_count', pa.hire_count,
      'total_cents', pa.total_cents
    )                                                       AS metadata,
    now()                                                    AS detected_at
    FROM pairings pa
    LEFT JOIN public.profiles pb ON pb.id = pa.client_id
    LEFT JOIN public.profiles pi ON pi.id = pa.contractor_id
   ORDER BY pa.hire_count DESC;
END;
$_$;


ALTER FUNCTION "public"."detect_concentration_risk"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."detect_off_hours_decisions"("p_org_id" "uuid") RETURNS TABLE("severity" "text", "finding" "text", "metadata" "jsonb", "detected_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public._compliance_actor_can_read(p_org_id) THEN
    RAISE EXCEPTION 'You do not have permission to read this organization''s anomalies'
      USING ERRCODE = '42501';
  END IF;

  IF to_regclass('public.approval_requests') IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH base AS (
    SELECT ad.id, ad.decided_by, ad.decided_at,
           extract(hour FROM ad.decided_at AT TIME ZONE 'UTC') AS hr,
           extract(dow  FROM ad.decided_at AT TIME ZONE 'UTC') AS dow,
           r.amount_cents, r.currency
      FROM public.approval_decisions ad
      JOIN public.approval_requests r ON r.id = ad.approval_request_id
     WHERE r.org_id = p_org_id
       AND ad.decided_at >= now() - interval '90 days'
  ),
  off_hours AS (
    SELECT * FROM base
     WHERE hr < 6 OR hr >= 22 OR dow IN (0, 6)
  ),
  by_decider AS (
    SELECT decided_by, count(*) AS oh_count,
           max(amount_cents) AS biggest_cents,
           max(currency) AS sample_currency
      FROM off_hours
     GROUP BY decided_by
    HAVING count(*) >= 3
  )
  SELECT
    (CASE WHEN bd.oh_count >= 10 THEN 'warning' ELSE 'info' END) AS severity,
    format(
      '%s recorded %s decision(s) outside business hours (22:00–06:00 UTC or weekends) in the last 90 days. Largest: %s %s.',
      coalesce(NULLIF(TRIM(p.full_name), ''), p.email, 'An approver'),
      bd.oh_count, bd.sample_currency,
      (bd.biggest_cents::numeric / 100)::text
    )                                                          AS finding,
    jsonb_build_object(
      'decider_id', bd.decided_by,
      'decider_label', coalesce(NULLIF(TRIM(p.full_name), ''), p.email),
      'off_hours_count', bd.oh_count,
      'biggest_cents', bd.biggest_cents
    )                                                          AS metadata,
    now()                                                       AS detected_at
    FROM by_decider bd
    LEFT JOIN public.profiles p ON p.id = bd.decided_by
   ORDER BY bd.oh_count DESC;
END;
$$;


ALTER FUNCTION "public"."detect_off_hours_decisions"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."detect_quarter_end_clustering"("p_org_id" "uuid") RETURNS TABLE("severity" "text", "finding" "text", "metadata" "jsonb", "detected_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public._compliance_actor_can_read(p_org_id) THEN
    RAISE EXCEPTION 'You do not have permission to read this organization''s anomalies'
      USING ERRCODE = '42501';
  END IF;

  IF to_regclass('public.audit_events') IS NULL THEN
    RETURN;
  END IF;

  -- "Quarter-end window" = last 5 days of any calendar quarter in the
  -- trailing 365 days. We count reassignments in that window vs the
  -- mid-quarter baseline.
  RETURN QUERY
  WITH reassignments AS (
    SELECT a.id, a.created_at,
           date_trunc('quarter', a.created_at) AS quarter_start,
           (date_trunc('quarter', a.created_at) + interval '3 months')::timestamptz AS quarter_end
      FROM public.audit_events a
     WHERE a.event_type = 'invoice.department.reassigned'
       AND a.metadata->>'org_id' = p_org_id::text
       AND a.created_at >= now() - interval '365 days'
  ),
  windowed AS (
    SELECT *,
           (quarter_end - created_at) <= interval '5 days' AS in_quarter_end
      FROM reassignments
  ),
  agg AS (
    SELECT
      count(*) FILTER (WHERE in_quarter_end) AS qe_count,
      count(*) FILTER (WHERE NOT in_quarter_end) AS mid_count
      FROM windowed
  )
  SELECT
    (CASE WHEN qe_count * 3 >= mid_count + qe_count AND qe_count >= 4 THEN 'critical'
          WHEN qe_count >= 3 AND qe_count > mid_count THEN 'warning'
          ELSE 'info' END)                                  AS severity,
    format(
      '%s of %s invoice reassignments in the last year landed in the final 5 days of a fiscal quarter. Investigate for period-end cost-center juggling.',
      qe_count, qe_count + mid_count
    )                                                        AS finding,
    jsonb_build_object(
      'quarter_end_count', qe_count,
      'mid_quarter_count', mid_count,
      'ratio',
        CASE WHEN (qe_count + mid_count) = 0 THEN 0
        ELSE round(100.0 * qe_count::numeric / (qe_count + mid_count), 1) END
    )                                                        AS metadata,
    now()                                                     AS detected_at
    FROM agg
   WHERE qe_count >= 3 AND qe_count > mid_count;
END;
$$;


ALTER FUNCTION "public"."detect_quarter_end_clustering"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."detect_rubber_stamping"("p_org_id" "uuid") RETURNS TABLE("severity" "text", "finding" "text", "metadata" "jsonb", "detected_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public._compliance_actor_can_read(p_org_id) THEN
    RAISE EXCEPTION 'You do not have permission to read this organization''s anomalies'
      USING ERRCODE = '42501';
  END IF;

  IF to_regclass('public.approval_requests') IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH base AS (
    SELECT ad.decided_by,
           ad.decided_at,
           ad.decision,
           ad.comment,
           length(coalesce(trim(ad.comment), '')) AS comment_len,
           r.amount_cents,
           r.currency
      FROM public.approval_decisions ad
      JOIN public.approval_requests r ON r.id = ad.approval_request_id
     WHERE r.org_id = p_org_id
       AND ad.decided_at >= now() - interval '30 days'
  ),
  by_decider AS (
    SELECT decided_by,
           count(*) FILTER (WHERE comment_len < 5) AS empty_count,
           count(*) AS total_count,
           max(amount_cents) AS biggest_decision_cents,
           max(currency) AS sample_currency
      FROM base
     GROUP BY decided_by
    HAVING count(*) FILTER (WHERE comment_len < 5) >= 3
  )
  SELECT
    (CASE WHEN bd.empty_count * 2 >= bd.total_count THEN 'critical'
          WHEN bd.empty_count >= 5 THEN 'warning'
          ELSE 'info' END)                                  AS severity,
    format(
      '%s recorded %s decision(s) with effectively no comment in the last 30 days (of %s total). Largest such decision: %s %s.',
      coalesce(NULLIF(TRIM(p.full_name), ''), p.email, 'An approver'),
      bd.empty_count, bd.total_count,
      bd.sample_currency,
      (bd.biggest_decision_cents::numeric / 100)::text
    )                                                        AS finding,
    jsonb_build_object(
      'decider_id',  bd.decided_by,
      'decider_label', coalesce(NULLIF(TRIM(p.full_name), ''), p.email),
      'empty_count', bd.empty_count,
      'total_count', bd.total_count,
      'biggest_decision_cents', bd.biggest_decision_cents
    )                                                        AS metadata,
    now()                                                     AS detected_at
    FROM by_decider bd
    LEFT JOIN public.profiles p ON p.id = bd.decided_by
   ORDER BY bd.empty_count DESC;
END;
$$;


ALTER FUNCTION "public"."detect_rubber_stamping"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."detect_silent_overrides"("p_org_id" "uuid") RETURNS TABLE("severity" "text", "finding" "text", "metadata" "jsonb", "detected_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public._compliance_actor_can_read(p_org_id) THEN
    RAISE EXCEPTION 'You do not have permission to read this organization''s anomalies'
      USING ERRCODE = '42501';
  END IF;

  IF to_regclass('public.audit_events') IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    'critical'::text AS severity,
    format(
      'Audit event %s of type %L written without a correlation_id. This indicates a direct table write that bypassed the SECURITY DEFINER RPC layer. Investigate immediately.',
      a.id, a.event_type
    )                AS finding,
    jsonb_build_object(
      'audit_event_id', a.id,
      'event_type',     a.event_type,
      'actor_id',       a.actor_id,
      'subject_table',  a.subject_table,
      'subject_id',     a.subject_id,
      'created_at',     a.created_at
    )                AS metadata,
    now()             AS detected_at
    FROM public.audit_events a
   WHERE a.metadata->>'org_id' = p_org_id::text
     AND a.event_type LIKE 'invoice.department.%'
     AND a.correlation_id IS NULL
     AND a.created_at >= now() - interval '180 days'
   ORDER BY a.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."detect_silent_overrides"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."detect_vendor_coordination_latency"("p_org_id" "uuid", "p_lookback_days" integer DEFAULT 90) RETURNS TABLE("vendor_contact_id" "uuid", "vendor_company" "text", "bridges_count" integer, "median_doc_days" numeric, "max_counter_rounds" integer, "severity" "text", "evidence" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_admin  boolean;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE='28000';
  END IF;
  SELECT EXISTS (SELECT 1 FROM public.profiles WHERE id=v_caller AND role IN ('admin','super_admin')) INTO v_admin;
  IF NOT v_admin
     AND NOT EXISTS (
       SELECT 1 FROM public.org_members
        WHERE org_id = p_org_id AND user_id = v_caller
          AND role IN ('owner', 'procurement_admin')
     )
  THEN
    RAISE EXCEPTION 'not authorised to read compliance posture for this org' USING ERRCODE='42501';
  END IF;

  RETURN QUERY
  WITH org_jobs AS (
    SELECT j.id AS job_id, j.created_at
      FROM public.jobs j
      JOIN public.departments d ON d.id = j.department_id
     WHERE d.org_id = p_org_id
       AND j.created_at >= now() - (GREATEST(1, COALESCE(p_lookback_days, 90)) || ' days')::interval
  ),
  org_bridges AS (
    SELECT cb.id, cb.vendor_contact_id, cb.job_id, cb.created_at, cb.completed_at, cb.cancelled_at
      FROM public.coordination_bridges cb
      JOIN org_jobs oj ON oj.job_id = cb.job_id
  ),
  doc_latency AS (
    SELECT b.vendor_contact_id,
           b.id AS bridge_id,
           extract(epoch from (d.accepted_at - s.created_at)) / 86400.0 AS days_to_accept
      FROM org_bridges b
      JOIN public.bridge_slots s     ON s.bridge_id = b.id AND s.kind = 'document_request'
      JOIN public.bridge_documents d ON d.slot_id = s.id AND d.accepted_at IS NOT NULL
  ),
  schedule_counters AS (
    SELECT b.vendor_contact_id, b.id AS bridge_id,
           COUNT(*) FILTER (
             WHERE a.event_type = 'coordination_bridge.schedule_counter_proposed'
                OR a.event_type = 'coordination_bridge.schedule_proposed'
           ) AS rounds
      FROM org_bridges b
      LEFT JOIN public.audit_events a
             ON a.subject_table = 'coordination_bridges'
            AND a.subject_id = b.id
     GROUP BY b.vendor_contact_id, b.id
  ),
  vendor_agg AS (
    SELECT
      ob.vendor_contact_id,
      COUNT(DISTINCT ob.id)::int AS bridges_count,
      COALESCE(percentile_cont(0.5) WITHIN GROUP (ORDER BY dl.days_to_accept), 0) AS median_doc_days,
      COALESCE(MAX(sc.rounds), 0)::int AS max_counter_rounds
    FROM org_bridges ob
    LEFT JOIN doc_latency       dl ON dl.vendor_contact_id = ob.vendor_contact_id
    LEFT JOIN schedule_counters sc ON sc.bridge_id = ob.id
   GROUP BY ob.vendor_contact_id
  )
  SELECT
    va.vendor_contact_id,
    vc.company_name AS vendor_company,
    va.bridges_count,
    round(va.median_doc_days::numeric, 2) AS median_doc_days,
    va.max_counter_rounds,
    CASE
      WHEN va.median_doc_days > 14 OR va.max_counter_rounds >= 5 THEN 'critical'
      WHEN va.median_doc_days > 5  OR va.max_counter_rounds >= 3 THEN 'warning'
      ELSE 'info'
    END AS severity,
    jsonb_build_object(
      'vendor_company',     vc.company_name,
      'vendor_email',       vc.contact_email,
      'bridges_count',      va.bridges_count,
      'median_doc_days',    round(va.median_doc_days::numeric, 2),
      'max_counter_rounds', va.max_counter_rounds,
      'lookback_days',      COALESCE(p_lookback_days, 90)
    ) AS evidence
    FROM vendor_agg va
    JOIN public.vendor_contacts vc ON vc.id = va.vendor_contact_id
   WHERE va.bridges_count >= 1
     AND (va.median_doc_days > 5 OR va.max_counter_rounds >= 3)
   ORDER BY severity DESC, va.median_doc_days DESC;
END
$$;


ALTER FUNCTION "public"."detect_vendor_coordination_latency"("p_org_id" "uuid", "p_lookback_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."discover_jobs"("p_inspector_id" "uuid", "p_lat" numeric DEFAULT NULL::numeric, "p_lng" numeric DEFAULT NULL::numeric, "p_radius_km" integer DEFAULT NULL::integer, "p_city_query" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("job" "jsonb", "distance_km" numeric, "has_applied" boolean)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_bbox_deg     numeric;
  v_city_pattern text;
BEGIN
  IF p_radius_km IS NOT NULL AND p_lat IS NOT NULL AND p_lng IS NOT NULL THEN
    v_bbox_deg := p_radius_km::numeric / 111.045;
  END IF;

  IF p_city_query IS NOT NULL AND length(trim(p_city_query)) > 0 THEN
    v_city_pattern := '%' || trim(p_city_query) || '%';
  END IF;

  RETURN QUERY
  WITH candidates AS (
    SELECT
      j.*,
      CASE
        WHEN p_lat IS NULL OR p_lng IS NULL
          OR j.latitude IS NULL OR j.longitude IS NULL
        THEN NULL::numeric
        ELSE public.haversine_km(p_lat, p_lng, j.latitude, j.longitude)
      END AS dist_km
    FROM public.jobs j
    WHERE j.status = 'open'
      AND j.contractor_id IS NULL
      AND (
        v_city_pattern IS NULL
        OR j.location ILIKE v_city_pattern
        OR j.title    ILIKE v_city_pattern
      )
      AND (
        v_bbox_deg IS NULL
        OR (
          j.latitude  BETWEEN p_lat - v_bbox_deg AND p_lat + v_bbox_deg
          AND j.longitude BETWEEN p_lng - v_bbox_deg AND p_lng + v_bbox_deg
        )
      )
      -- ★ STEP 5.5 — CCI tier gating.
      --   Quality jobs (inspection_type NULL or 'quality') are unfiltered.
      --   Compliance jobs are gated by the scope template's required tier:
      --   inspector must hold an active CCI credential ≥ that tier.
      AND (
        COALESCE(j.inspection_type, 'quality') <> 'compliance'
        OR (
          j.scope_template_id IS NOT NULL
          AND public.is_active_cci(
            p_inspector_id,
            (
              SELECT t.requires_credential_tier
                FROM public.inspection_scope_templates t
               WHERE t.id = j.scope_template_id
            )
          )
        )
      )
  )
  SELECT
    to_jsonb(c) - 'dist_km' AS job,
    c.dist_km                AS distance_km,
    EXISTS (
      SELECT 1
      FROM public.applications a
      WHERE a.job_id       = c.id
        AND a.applicant_id = p_inspector_id
    ) AS has_applied
  FROM candidates c
  WHERE
    p_radius_km IS NULL
    OR (c.dist_km IS NOT NULL AND c.dist_km <= p_radius_km::numeric)
  ORDER BY
    (c.dist_km IS NULL) ASC,
    c.dist_km            ASC NULLS LAST,
    c.created_at         DESC
  LIMIT  GREATEST(p_limit,  1)
  OFFSET GREATEST(p_offset, 0);
END;
$$;


ALTER FUNCTION "public"."discover_jobs"("p_inspector_id" "uuid", "p_lat" numeric, "p_lng" numeric, "p_radius_km" integer, "p_city_query" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."discover_jobs"("p_inspector_id" "uuid", "p_lat" numeric, "p_lng" numeric, "p_radius_km" integer, "p_city_query" "text", "p_limit" integer, "p_offset" integer) IS 'Inspector job-discovery feed. Returns open & unassigned jobs sorted by proximity to (p_lat,p_lng), bounded by p_radius_km (NULL=unlimited), optionally narrowed by p_city_query. Each row carries distance_km and has_applied for the calling inspector.';



CREATE OR REPLACE FUNCTION "public"."enforce_application_rate_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_limit int;
  v_count int;
BEGIN
  -- Skip if no applicant (admin-injected rows, system imports, etc.)
  IF NEW.applicant_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Resolve effective limit (per-user override or system default)
  SELECT COALESCE(daily_application_limit, public._default_daily_application_limit())
    INTO v_limit
  FROM public.profiles
  WHERE id = NEW.applicant_id;

  IF v_limit IS NULL THEN
    v_limit := public._default_daily_application_limit();
  END IF;

  -- Count submissions in rolling 24-hour window.
  -- Counts every row inserted (withdrawn / rejected included) per spec.
  SELECT count(*) INTO v_count
  FROM public.applications
  WHERE applicant_id = NEW.applicant_id
    AND created_at > now() - interval '24 hours';

  IF v_count >= v_limit THEN
    RAISE EXCEPTION
      'Daily application limit reached (% submitted in the last 24 hours, limit %). '
      'Try again later or contact support to request a higher cap.',
      v_count, v_limit
      USING ERRCODE = 'P0001';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_application_rate_limit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_notification"("p_recipient" "uuid", "p_kind" "text", "p_title" "text", "p_body" "text" DEFAULT NULL::"text", "p_link" "text" DEFAULT NULL::"text", "p_job_id" "uuid" DEFAULT NULL::"uuid", "p_email_required" boolean DEFAULT false, "p_template_kind" "text" DEFAULT NULL::"text", "p_template_data" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  IF p_recipient IS NULL THEN
    RETURN NULL;
  END IF;

  -- Reuse notify_safe so the in-app push, realtime publication, and
  -- profile unread-count update all stay in one code path.
  v_id := public.notify_safe(
    p_recipient,
    p_kind,
    p_title,
    p_body,
    p_link,
    p_job_id
  );

  IF v_id IS NULL THEN
    RETURN NULL;
  END IF;

  -- Stamp the email overlay if requested.
  IF p_email_required IS TRUE THEN
    UPDATE public.notifications
       SET email_required      = true,
           email_template_kind = p_template_kind,
           email_template_data = COALESCE(p_template_data, '{}'::jsonb)
     WHERE id = v_id;
  END IF;

  RETURN v_id;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'enqueue_notification(%, %): %', p_kind, p_recipient, SQLERRM;
  RETURN NULL;
END
$$;


ALTER FUNCTION "public"."enqueue_notification"("p_recipient" "uuid", "p_kind" "text", "p_title" "text", "p_body" "text", "p_link" "text", "p_job_id" "uuid", "p_email_required" boolean, "p_template_kind" "text", "p_template_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_help_support_conversation"() RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_conv_id uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT id INTO v_conv_id FROM public.conversations
   WHERE user_id = v_uid AND kind = 'help_support' LIMIT 1;
  IF v_conv_id IS NULL THEN
    INSERT INTO public.conversations(kind, user_id, title)
      VALUES ('help_support', v_uid, 'Help & Support')
      RETURNING id INTO v_conv_id;
  END IF;
  RETURN v_conv_id;
END $$;


ALTER FUNCTION "public"."ensure_help_support_conversation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_job_conversation"("p_job_id" "uuid", "p_kind" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_role text;
  v_conv_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;
  IF p_kind NOT IN ('job_client_admin','job_inspector_admin') THEN
    RAISE EXCEPTION 'invalid conversation kind';
  END IF;

  -- Caller-role gate. Client/agency/enterprise → job_client_admin only.
  -- Inspector (must be the *assigned* one) → job_inspector_admin only.
  IF p_kind = 'job_client_admin' THEN
    IF NOT EXISTS (SELECT 1 FROM public.jobs WHERE id = p_job_id AND client_id = v_uid) THEN
      RAISE EXCEPTION 'not authorised: only the job''s client may open a job_client_admin room';
    END IF;
  ELSE -- job_inspector_admin
    IF NOT EXISTS (SELECT 1 FROM public.jobs WHERE id = p_job_id AND contractor_id = v_uid) THEN
      RAISE EXCEPTION 'not authorised: only the assigned inspector may open a job_inspector_admin room';
    END IF;
  END IF;

  SELECT id INTO v_conv_id FROM public.conversations
   WHERE job_id = p_job_id AND kind = p_kind::public.conversation_kind AND user_id = v_uid
   LIMIT 1;
  IF v_conv_id IS NULL THEN
    INSERT INTO public.conversations(kind, user_id, job_id, title)
      VALUES (
        p_kind::public.conversation_kind, v_uid, p_job_id,
        CASE p_kind
          WHEN 'job_client_admin'    THEN 'Job chat · client side'
          WHEN 'job_inspector_admin' THEN 'Job chat · inspector side'
        END
      )
      RETURNING id INTO v_conv_id;
  END IF;
  RETURN v_conv_id;
END $$;


ALTER FUNCTION "public"."ensure_job_conversation"("p_job_id" "uuid", "p_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."evaluate_job_for_approval"("p_org_id" "uuid", "p_department_id" "uuid", "p_amount_cents" bigint, "p_currency" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor    uuid := auth.uid();
  v_policy   record;
  v_currency public.currency_code;
  v_amount_in_policy_ccy bigint;
  v_budget   jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.is_member_of_org(p_org_id) AND NOT public._actor_is_super_admin() THEN
    RAISE EXCEPTION 'You are not a member of this organization' USING ERRCODE = '42501';
  END IF;

  -- Defensive cast — invalid currency code shouldn't even reach here.
  v_currency := COALESCE(p_currency, 'USD')::public.currency_code;

  -- Convert the requested amount into each candidate band's currency
  -- on the fly. To stay simple we keep this lookup currency-by-currency
  -- — we resolve the policy at the input currency first; if no policy
  -- in that currency matches, we widen to USD for cross-currency cases.
  WITH candidates AS (
    SELECT
      p.id,
      p.name,
      p.currency,
      p.min_amount_cents,
      p.max_amount_cents,
      p.required_approver_roles,
      p.min_approvers_count,
      p.requires_sod,
      p.scope_department_id,
      -- Convert the requested amount into THIS band's currency for the
      -- range check. Same FX primitive everywhere; same now()-based rate.
      public.convert_cents(p_amount_cents, v_currency::text, p.currency::text, now())
        AS amt_in_band_ccy
      FROM public.approval_policies p
     WHERE p.org_id = p_org_id
       AND p.is_active = true
       -- Scope match: either no scope (org-wide) OR the job's department
       -- is the policy's scope or a descendant.
       AND (
            p.scope_department_id IS NULL
         OR p.scope_department_id = p_department_id
         OR EXISTS (
              WITH RECURSIVE ancestors AS (
                SELECT id, parent_department_id
                  FROM public.departments WHERE id = p_department_id
                UNION ALL
                SELECT d.id, d.parent_department_id
                  FROM public.departments d
                  JOIN ancestors a ON a.parent_department_id = d.id
              )
              SELECT 1 FROM ancestors WHERE id = p.scope_department_id
            )
       )
  )
  SELECT id, name, currency::text AS currency,
         min_amount_cents, max_amount_cents,
         required_approver_roles, min_approvers_count, requires_sod,
         scope_department_id, amt_in_band_ccy
    INTO v_policy
    FROM candidates c
   WHERE c.amt_in_band_ccy IS NOT NULL
     AND c.amt_in_band_ccy >= c.min_amount_cents
     AND (c.max_amount_cents IS NULL OR c.amt_in_band_ccy < c.max_amount_cents)
   ORDER BY
     -- Narrowest scope first (dept-scoped beats org-wide at same amount).
     (c.scope_department_id IS NOT NULL) DESC,
     -- Tightest amount band wins ties (higher min beats lower min).
     c.min_amount_cents DESC
   LIMIT 1;

  -- Budget context — always returned even when no approval is required,
  -- so the UI can warn at job-post time before the user fills out the form.
  v_budget := public.check_department_budget(
    p_department_id, current_date, p_amount_cents, p_currency
  );

  IF v_policy.id IS NULL THEN
    -- No band matched → auto-post.
    RETURN jsonb_build_object(
      'ok',                 true,
      'requires_approval',  false,
      'reason',             'no_policy_matches',
      'budget',             v_budget
    );
  END IF;

  RETURN jsonb_build_object(
    'ok',                       true,
    'requires_approval',        true,
    'policy_id',                v_policy.id,
    'policy_name',              v_policy.name,
    'policy_currency',          v_policy.currency,
    'amount_in_policy_ccy',     v_policy.amt_in_band_ccy,
    'required_approver_roles',  to_jsonb(v_policy.required_approver_roles),
    'min_approvers_count',      v_policy.min_approvers_count,
    'requires_sod',             v_policy.requires_sod,
    'scope_department_id',      v_policy.scope_department_id,
    'budget',                   v_budget
  );
END;
$$;


ALTER FUNCTION "public"."evaluate_job_for_approval"("p_org_id" "uuid", "p_department_id" "uuid", "p_amount_cents" bigint, "p_currency" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."execute_auto_payout"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_project_price DECIMAL(12,2);
BEGIN
    -- فقط وقتی وضعیت به completed تغییر کرد
    IF NEW.status = 'completed' AND OLD.status != 'completed' THEN
        
        -- ۱. دریافت قیمت پروژه
        SELECT price INTO v_project_price FROM public.projects WHERE id = NEW.id;

        -- ۲. افزایش موجودی بازرس
        UPDATE public.wallets 
        SET balance = balance + v_project_price 
        WHERE user_id = NEW.inspector_id;

        -- ۳. ثبت سابقه در تراکنش‌ها
        INSERT INTO public.transactions (user_id, project_id, amount, type)
        VALUES (NEW.inspector_id, NEW.id, v_project_price, 'payout');

    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."execute_auto_payout"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."expire_old_certifications"() RETURNS TABLE("expired_count" integer, "certification_ids" "uuid"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    expired_ids UUID[];
    count INTEGER;
BEGIN
    -- Get IDs of certifications being expired
    SELECT ARRAY_AGG(id) INTO expired_ids
    FROM contractor_certifications
    WHERE status = 'active' 
      AND expiry_date < CURRENT_DATE;
    
    -- Update status
    UPDATE contractor_certifications
    SET status = 'expired'
    WHERE status = 'active' 
      AND expiry_date < CURRENT_DATE;
    
    GET DIAGNOSTICS count = ROW_COUNT;
    
    RETURN QUERY SELECT count, COALESCE(expired_ids, ARRAY[]::UUID[]);
END;
$$;


ALTER FUNCTION "public"."expire_old_certifications"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fetch_affidavit_by_verify_token"("p_token" "text") RETURNS TABLE("affidavit_id" "uuid", "status" "public"."affidavit_status", "valid_from" timestamp with time zone, "valid_until" timestamp with time zone, "issued_at" timestamp with time zone, "revoked_at" timestamp with time zone, "revoked_reason" "text", "scope_name" "text", "scope_slug" "text", "scope_category" "text", "scope_region" "text", "scope_version" integer, "subject_name" "text", "inspector_tier" "public"."cci_credential_tier", "buyer_type" "text", "total_captures" integer, "total_documents" integer, "external_evidence_count" integer, "chain_intact" boolean, "html_storage_path" "text", "html_sha256" "text", "pdf_storage_path" "text", "pdf_sha256" "text", "json_payload_sha256" "text", "platform_signature" "text", "platform_signing_key_id" "text", "vca_version" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    a.id, a.status, a.valid_from, a.valid_until, a.issued_at,
    a.revoked_at, a.revoked_reason,
    t.name, t.slug, t.category, t.region, t.version,
    j.title,
    (SELECT ic.tier FROM public.inspector_credentials ic WHERE ic.id = a.signed_by_inspector_credential),
    CASE WHEN j.client_id IS NOT NULL THEN 'client' ELSE 'agency' END,
    (SELECT COUNT(*)::int FROM public.inspection_captures   WHERE job_id = j.id),
    (SELECT COUNT(*)::int FROM public.compliance_documents WHERE job_id = j.id),
    (SELECT COUNT(*)::int FROM public.compliance_documents
       WHERE job_id = j.id AND document_url IS NOT NULL),
    COALESCE((a.json_payload->'chain_of_custody'->>'chain_intact')::boolean, false),
    a.html_storage_path, a.html_sha256,
    a.pdf_storage_path,  a.pdf_sha256,
    a.json_payload_sha256,
    a.json_payload->'tamper_evidence'->>'platform_signature',
    a.json_payload->'tamper_evidence'->>'platform_signing_key_id',
    a.json_payload->>'vca_version'
  FROM public.verification_affidavits a
  JOIN public.jobs j                          ON j.id = a.job_id
  JOIN public.inspection_scope_templates t    ON t.id = j.scope_template_id
  WHERE a.public_verify_token = p_token
    AND a.status IN ('issued', 'countersigned')
  LIMIT 1;
$$;


ALTER FUNCTION "public"."fetch_affidavit_by_verify_token"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fetch_cert_by_slug"("p_slug" "text") RETURNS TABLE("cert_id" "uuid", "scope_name" "text", "scope_slug" "text", "scope_category" "text", "scope_region" "text", "supplier_display_name" "text", "valid_from" timestamp with time zone, "valid_until" timestamp with time zone, "revoked_at" timestamp with time zone, "is_public_directory_listed" boolean, "affidavit_verify_token" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    c.id,
    t.name, t.slug, t.category, t.region,
    COALESCE(p.full_name, p.first_name || ' ' || p.last_name) AS supplier_display_name,
    c.valid_from,
    c.valid_until,
    c.revoked_at,
    c.is_public_directory_listed,
    a.public_verify_token
  FROM public.trust_certificates c
  JOIN public.inspection_scope_templates t ON t.id = c.scope_template_id
  JOIN public.profiles p                   ON p.id = c.supplier_profile_id
  JOIN public.verification_affidavits a    ON a.id = c.affidavit_id
  WHERE c.public_slug = p_slug
    AND c.revoked_at IS NULL
    AND c.valid_until > NOW()
  LIMIT 1;
$$;


ALTER FUNCTION "public"."fetch_cert_by_slug"("p_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fetch_department_audit_trail"("p_org_id" "uuid", "p_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "created_at" timestamp with time zone, "event_type" "text", "severity" "text", "actor_id" "uuid", "actor_role" "text", "actor_label" "text", "subject_table" "text", "subject_id" "uuid", "summary" "text", "delta" "jsonb", "metadata" "jsonb", "correlation_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor       uuid := auth.uid();
  v_actor_role  text;
  v_limit       int := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 200);
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT role INTO v_actor_role FROM public.profiles WHERE id = v_actor;
  IF v_actor_role IS DISTINCT FROM 'super_admin' THEN
    RAISE EXCEPTION 'Only super_admin can read the department audit trail'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
    SELECT a.id, a.created_at, a.event_type, a.severity,
           a.actor_id, a.actor_role, a.actor_label,
           a.subject_table, a.subject_id,
           a.summary, a.delta, a.metadata, a.correlation_id
      FROM public.audit_events a
     WHERE a.event_type IN (
             'department.created',
             'department.renamed',
             'department.moved',
             'department.deleted',
             'department_member.assigned',
             'department_member.unassigned'
           )
       AND a.metadata->>'org_id' = p_org_id::text
     ORDER BY a.created_at DESC
     LIMIT v_limit;
END;
$$;


ALTER FUNCTION "public"."fetch_department_audit_trail"("p_org_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fetch_department_budget_rollup"("p_org_id" "uuid", "p_window" "text" DEFAULT 'all_time'::"text", "p_display_currency" "text" DEFAULT NULL::"text") RETURNS TABLE("department_id" "uuid", "parent_department_id" "uuid", "name" "text", "cost_center" "text", "depth" integer, "currency" "text", "direct_committed_cents" bigint, "direct_paid_cents" bigint, "rollup_committed_cents" bigint, "rollup_paid_cents" bigint, "direct_invoice_count" integer, "rollup_invoice_count" integer, "last_invoice_at" timestamp with time zone, "display_currency" "text", "display_committed_cents" bigint, "display_paid_cents" bigint, "rate_unavailable" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor      uuid := auth.uid();
  v_window_lo  timestamptz := public._budget_window_start(p_window);
  v_has_inv    boolean := to_regclass('public.invoices') IS NOT NULL;
  v_display    text;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT (
       public._actor_is_super_admin()
    OR public.is_member_of_org(p_org_id)
  ) THEN
    RAISE EXCEPTION 'You do not have permission to view this organization''s spend'
      USING ERRCODE = '42501';
  END IF;

  v_display := public._resolve_display_currency(p_org_id, p_display_currency);

  IF NOT v_has_inv THEN
    -- Empty skeleton — same shape, all zero numbers, no rate flag.
    RETURN QUERY
      WITH RECURSIVE tree AS (
        SELECT d.id, d.parent_department_id, d.name, d.cost_center, 0 AS depth
          FROM public.departments d
         WHERE d.org_id = p_org_id AND d.parent_department_id IS NULL
        UNION ALL
        SELECT d.id, d.parent_department_id, d.name, d.cost_center, t.depth + 1
          FROM public.departments d
          JOIN tree t ON t.id = d.parent_department_id
      )
      SELECT t.id, t.parent_department_id, t.name, t.cost_center, t.depth,
             v_display, 0::bigint, 0::bigint, 0::bigint, 0::bigint,
             0, 0, NULL::timestamptz,
             v_display, 0::bigint, 0::bigint, false
        FROM tree t
       ORDER BY t.depth, lower(t.name);
    RETURN;
  END IF;

  -- ── Main aggregation (same CTE shape as the pre-currency version). ──
  RETURN QUERY
  WITH RECURSIVE
  dept_tree AS (
    SELECT d.id, d.parent_department_id, d.name, d.cost_center, 0 AS depth
      FROM public.departments d
     WHERE d.org_id = p_org_id AND d.parent_department_id IS NULL
    UNION ALL
    SELECT d.id, d.parent_department_id, d.name, d.cost_center, t.depth + 1
      FROM public.departments d
      JOIN dept_tree t ON t.id = d.parent_department_id
  ),
  descendant_of AS (
    SELECT d.id AS dept_id, d.id AS ancestor_id
      FROM public.departments d
     WHERE d.org_id = p_org_id
    UNION ALL
    SELECT df.dept_id, d.parent_department_id
      FROM descendant_of df
      JOIN public.departments d ON d.id = df.ancestor_id
     WHERE d.parent_department_id IS NOT NULL
  ),
  direct_totals AS (
    SELECT
      i.department_id                           AS dept_id,
      COALESCE(i.currency, 'USD')               AS currency,
      SUM(CASE WHEN i.status <> 'voided' THEN i.total_cents ELSE 0 END)::bigint AS committed_cents,
      SUM(CASE WHEN i.status =  'paid'   THEN i.total_cents ELSE 0 END)::bigint AS paid_cents,
      COUNT(*)::int                             AS invoice_count,
      MAX(i.issued_at)                          AS last_at
      FROM public.invoices i
     WHERE i.department_id IN (SELECT id FROM dept_tree)
       AND (v_window_lo IS NULL OR i.issued_at >= v_window_lo)
     GROUP BY i.department_id, COALESCE(i.currency, 'USD')
  ),
  rollup_totals AS (
    SELECT
      df.ancestor_id          AS dept_id,
      dt.currency             AS currency,
      SUM(dt.committed_cents)::bigint AS committed_cents,
      SUM(dt.paid_cents)::bigint      AS paid_cents,
      SUM(dt.invoice_count)::int      AS invoice_count,
      MAX(dt.last_at)                 AS last_at
      FROM descendant_of df
      JOIN direct_totals dt ON dt.dept_id = df.dept_id
     GROUP BY df.ancestor_id, dt.currency
  ),
  row_keys AS (
    SELECT dept_id, currency FROM direct_totals
    UNION
    SELECT dept_id, currency FROM rollup_totals
  )
  SELECT
    t.id                                                AS department_id,
    t.parent_department_id                              AS parent_department_id,
    t.name                                              AS name,
    t.cost_center                                       AS cost_center,
    t.depth                                             AS depth,
    rk.currency                                         AS currency,
    COALESCE(dt.committed_cents, 0)::bigint             AS direct_committed_cents,
    COALESCE(dt.paid_cents,      0)::bigint             AS direct_paid_cents,
    COALESCE(rt.committed_cents, 0)::bigint             AS rollup_committed_cents,
    COALESCE(rt.paid_cents,      0)::bigint             AS rollup_paid_cents,
    COALESCE(dt.invoice_count,   0)::int                AS direct_invoice_count,
    COALESCE(rt.invoice_count,   0)::int                AS rollup_invoice_count,
    GREATEST(dt.last_at, rt.last_at)                    AS last_invoice_at,
    -- ── Display projection ──
    v_display                                           AS display_currency,
    public.convert_cents(
      COALESCE(rt.committed_cents, 0)::bigint,
      rk.currency, v_display,
      COALESCE(GREATEST(dt.last_at, rt.last_at), now())
    )                                                   AS display_committed_cents,
    public.convert_cents(
      COALESCE(rt.paid_cents, 0)::bigint,
      rk.currency, v_display,
      COALESCE(GREATEST(dt.last_at, rt.last_at), now())
    )                                                   AS display_paid_cents,
    (
      rk.currency <> v_display
      AND public.convert_cents(1, rk.currency, v_display, now()) IS NULL
    )                                                   AS rate_unavailable
    FROM row_keys rk
    JOIN dept_tree t ON t.id = rk.dept_id
    LEFT JOIN direct_totals dt ON dt.dept_id = rk.dept_id AND dt.currency = rk.currency
    LEFT JOIN rollup_totals rt ON rt.dept_id = rk.dept_id AND rt.currency = rk.currency

  UNION ALL

  -- ── Synthetic "Unattributed" rows ──
  SELECT
    NULL::uuid                                          AS department_id,
    NULL::uuid                                          AS parent_department_id,
    'Unattributed'::text                                AS name,
    NULL::text                                          AS cost_center,
    -1                                                  AS depth,
    COALESCE(i.currency, 'USD')                         AS currency,
    SUM(CASE WHEN i.status <> 'voided' THEN i.total_cents ELSE 0 END)::bigint AS direct_committed_cents,
    SUM(CASE WHEN i.status =  'paid'   THEN i.total_cents ELSE 0 END)::bigint AS direct_paid_cents,
    SUM(CASE WHEN i.status <> 'voided' THEN i.total_cents ELSE 0 END)::bigint AS rollup_committed_cents,
    SUM(CASE WHEN i.status =  'paid'   THEN i.total_cents ELSE 0 END)::bigint AS rollup_paid_cents,
    COUNT(*)::int                                       AS direct_invoice_count,
    COUNT(*)::int                                       AS rollup_invoice_count,
    MAX(i.issued_at)                                    AS last_invoice_at,
    v_display                                           AS display_currency,
    public.convert_cents(
      SUM(CASE WHEN i.status <> 'voided' THEN i.total_cents ELSE 0 END)::bigint,
      COALESCE(i.currency, 'USD'), v_display, MAX(i.issued_at)
    )                                                   AS display_committed_cents,
    public.convert_cents(
      SUM(CASE WHEN i.status =  'paid'   THEN i.total_cents ELSE 0 END)::bigint,
      COALESCE(i.currency, 'USD'), v_display, MAX(i.issued_at)
    )                                                   AS display_paid_cents,
    (
      COALESCE(i.currency, 'USD') <> v_display
      AND public.convert_cents(1, COALESCE(i.currency, 'USD'), v_display, now()) IS NULL
    )                                                   AS rate_unavailable
    FROM public.invoices i
    JOIN public.jobs j ON j.id = i.job_id
   WHERE i.department_id IS NULL
     AND (v_window_lo IS NULL OR i.issued_at >= v_window_lo)
     AND j.client_id IN (
       SELECT user_id FROM public.org_members WHERE org_id = p_org_id
     )
   GROUP BY COALESCE(i.currency, 'USD')
   HAVING COUNT(*) > 0

   ORDER BY depth, lower(name), currency;
END;
$$;


ALTER FUNCTION "public"."fetch_department_budget_rollup"("p_org_id" "uuid", "p_window" "text", "p_display_currency" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fetch_department_spend_summary"("p_department_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT public.fetch_department_spend_summary(p_department_id, NULL);
$$;


ALTER FUNCTION "public"."fetch_department_spend_summary"("p_department_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fetch_department_spend_summary"("p_department_id" "uuid", "p_display_currency" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor       uuid := auth.uid();
  v_org_id      uuid;
  v_dept_name   text;
  v_cost_center text;
  v_has_inv     boolean := to_regclass('public.invoices') IS NOT NULL;
  v_predom      text;
  v_currency_count int;
  v_direct      jsonb;
  v_rollup      jsonb;
  v_recent      jsonb;
  v_display     text;
  v_display_direct jsonb;
  v_display_rollup jsonb;
  v_window_mtd  timestamptz := date_trunc('month',   now());
  v_window_qtd  timestamptz := date_trunc('quarter', now());
  v_window_ytd  timestamptz := date_trunc('year',    now());
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT org_id, name, cost_center
    INTO v_org_id, v_dept_name, v_cost_center
    FROM public.departments WHERE id = p_department_id;
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Department not found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT (
       public._actor_is_super_admin()
    OR public.is_member_of_org(v_org_id)
  ) THEN
    RAISE EXCEPTION 'You do not have permission to view this department''s spend'
      USING ERRCODE = '42501';
  END IF;

  v_display := public._resolve_display_currency(v_org_id, p_display_currency);

  IF NOT v_has_inv THEN
    RETURN jsonb_build_object(
      'ok', true,
      'department_id', p_department_id,
      'department_name', v_dept_name,
      'cost_center', v_cost_center,
      'currency', 'USD',
      'mixed_currencies', false,
      'display_currency', v_display,
      'direct',  jsonb_build_object(
        'all_time_committed_cents', 0, 'all_time_paid_cents', 0,
        'mtd_committed_cents', 0, 'qtd_committed_cents', 0, 'ytd_committed_cents', 0,
        'invoice_count', 0, 'last_invoice_at', null
      ),
      'rollup', jsonb_build_object(
        'all_time_committed_cents', 0, 'all_time_paid_cents', 0,
        'mtd_committed_cents', 0, 'qtd_committed_cents', 0, 'ytd_committed_cents', 0,
        'invoice_count', 0, 'last_invoice_at', null
      ),
      'display_direct',  jsonb_build_object(
        'all_time_committed_cents', 0, 'all_time_paid_cents', 0,
        'mtd_committed_cents', 0, 'qtd_committed_cents', 0, 'ytd_committed_cents', 0,
        'rate_unavailable', false
      ),
      'display_rollup', jsonb_build_object(
        'all_time_committed_cents', 0, 'all_time_paid_cents', 0,
        'mtd_committed_cents', 0, 'qtd_committed_cents', 0, 'ytd_committed_cents', 0,
        'rate_unavailable', false
      ),
      'recent_invoices', '[]'::jsonb
    );
  END IF;

  -- ── currency mix + predominant ──
  WITH RECURSIVE subtree AS (
    SELECT id FROM public.departments WHERE id = p_department_id
    UNION ALL
    SELECT d.id FROM public.departments d
      JOIN subtree s ON s.id = d.parent_department_id
  ),
  currency_mix AS (
    SELECT COALESCE(i.currency, 'USD') AS currency, COUNT(*)::int AS n
      FROM public.invoices i
     WHERE i.department_id IN (SELECT id FROM subtree)
     GROUP BY COALESCE(i.currency, 'USD')
     ORDER BY n DESC
  )
  SELECT (SELECT currency FROM currency_mix LIMIT 1),
         (SELECT count(*) FROM currency_mix)
    INTO v_predom, v_currency_count;

  v_predom := COALESCE(v_predom, 'USD');

  -- ── Native direct/rollup (predominant currency only) ──
  SELECT jsonb_build_object(
    'all_time_committed_cents',
      COALESCE(SUM(CASE WHEN i.status <> 'voided' THEN i.total_cents ELSE 0 END), 0),
    'all_time_paid_cents',
      COALESCE(SUM(CASE WHEN i.status =  'paid'   THEN i.total_cents ELSE 0 END), 0),
    'mtd_committed_cents',
      COALESCE(SUM(CASE WHEN i.status <> 'voided' AND i.issued_at >= v_window_mtd THEN i.total_cents ELSE 0 END), 0),
    'qtd_committed_cents',
      COALESCE(SUM(CASE WHEN i.status <> 'voided' AND i.issued_at >= v_window_qtd THEN i.total_cents ELSE 0 END), 0),
    'ytd_committed_cents',
      COALESCE(SUM(CASE WHEN i.status <> 'voided' AND i.issued_at >= v_window_ytd THEN i.total_cents ELSE 0 END), 0),
    'invoice_count', COUNT(*)::int,
    'last_invoice_at', MAX(i.issued_at)
  )
    INTO v_direct
    FROM public.invoices i
   WHERE i.department_id = p_department_id
     AND COALESCE(i.currency, 'USD') = v_predom;

  WITH RECURSIVE subtree AS (
    SELECT id FROM public.departments WHERE id = p_department_id
    UNION ALL
    SELECT d.id FROM public.departments d
      JOIN subtree s ON s.id = d.parent_department_id
  )
  SELECT jsonb_build_object(
    'all_time_committed_cents',
      COALESCE(SUM(CASE WHEN i.status <> 'voided' THEN i.total_cents ELSE 0 END), 0),
    'all_time_paid_cents',
      COALESCE(SUM(CASE WHEN i.status =  'paid'   THEN i.total_cents ELSE 0 END), 0),
    'mtd_committed_cents',
      COALESCE(SUM(CASE WHEN i.status <> 'voided' AND i.issued_at >= v_window_mtd THEN i.total_cents ELSE 0 END), 0),
    'qtd_committed_cents',
      COALESCE(SUM(CASE WHEN i.status <> 'voided' AND i.issued_at >= v_window_qtd THEN i.total_cents ELSE 0 END), 0),
    'ytd_committed_cents',
      COALESCE(SUM(CASE WHEN i.status <> 'voided' AND i.issued_at >= v_window_ytd THEN i.total_cents ELSE 0 END), 0),
    'invoice_count', COUNT(*)::int,
    'last_invoice_at', MAX(i.issued_at)
  )
    INTO v_rollup
    FROM public.invoices i
   WHERE i.department_id IN (SELECT id FROM subtree)
     AND COALESCE(i.currency, 'USD') = v_predom;

  -- ── Display projection — converts EVERY currency in the subtree
  --    into v_display via convert_cents, then sums. This handles
  --    multi-currency invoice mixes correctly. ──
  WITH RECURSIVE subtree AS (
    SELECT id FROM public.departments WHERE id = p_department_id
    UNION ALL
    SELECT d.id FROM public.departments d
      JOIN subtree s ON s.id = d.parent_department_id
  ),
  display_direct AS (
    SELECT
      SUM(CASE WHEN i.status <> 'voided'
               THEN public.convert_cents(i.total_cents, COALESCE(i.currency,'USD'), v_display, i.issued_at)
               ELSE 0 END)::bigint AS all_time_committed_cents,
      SUM(CASE WHEN i.status = 'paid'
               THEN public.convert_cents(i.total_cents, COALESCE(i.currency,'USD'), v_display, i.issued_at)
               ELSE 0 END)::bigint AS all_time_paid_cents,
      SUM(CASE WHEN i.status <> 'voided' AND i.issued_at >= v_window_mtd
               THEN public.convert_cents(i.total_cents, COALESCE(i.currency,'USD'), v_display, i.issued_at)
               ELSE 0 END)::bigint AS mtd_committed_cents,
      SUM(CASE WHEN i.status <> 'voided' AND i.issued_at >= v_window_qtd
               THEN public.convert_cents(i.total_cents, COALESCE(i.currency,'USD'), v_display, i.issued_at)
               ELSE 0 END)::bigint AS qtd_committed_cents,
      SUM(CASE WHEN i.status <> 'voided' AND i.issued_at >= v_window_ytd
               THEN public.convert_cents(i.total_cents, COALESCE(i.currency,'USD'), v_display, i.issued_at)
               ELSE 0 END)::bigint AS ytd_committed_cents,
      bool_or(public.convert_cents(i.total_cents, COALESCE(i.currency,'USD'), v_display, i.issued_at) IS NULL
              AND i.total_cents IS NOT NULL) AS rate_unavailable
      FROM public.invoices i
     WHERE i.department_id = p_department_id
  )
  SELECT jsonb_build_object(
    'all_time_committed_cents', COALESCE(all_time_committed_cents, 0),
    'all_time_paid_cents',      COALESCE(all_time_paid_cents, 0),
    'mtd_committed_cents',      COALESCE(mtd_committed_cents, 0),
    'qtd_committed_cents',      COALESCE(qtd_committed_cents, 0),
    'ytd_committed_cents',      COALESCE(ytd_committed_cents, 0),
    'rate_unavailable',         COALESCE(rate_unavailable, false)
  ) INTO v_display_direct FROM display_direct;

  WITH RECURSIVE subtree AS (
    SELECT id FROM public.departments WHERE id = p_department_id
    UNION ALL
    SELECT d.id FROM public.departments d
      JOIN subtree s ON s.id = d.parent_department_id
  ),
  display_rollup AS (
    SELECT
      SUM(CASE WHEN i.status <> 'voided'
               THEN public.convert_cents(i.total_cents, COALESCE(i.currency,'USD'), v_display, i.issued_at)
               ELSE 0 END)::bigint AS all_time_committed_cents,
      SUM(CASE WHEN i.status = 'paid'
               THEN public.convert_cents(i.total_cents, COALESCE(i.currency,'USD'), v_display, i.issued_at)
               ELSE 0 END)::bigint AS all_time_paid_cents,
      SUM(CASE WHEN i.status <> 'voided' AND i.issued_at >= v_window_mtd
               THEN public.convert_cents(i.total_cents, COALESCE(i.currency,'USD'), v_display, i.issued_at)
               ELSE 0 END)::bigint AS mtd_committed_cents,
      SUM(CASE WHEN i.status <> 'voided' AND i.issued_at >= v_window_qtd
               THEN public.convert_cents(i.total_cents, COALESCE(i.currency,'USD'), v_display, i.issued_at)
               ELSE 0 END)::bigint AS qtd_committed_cents,
      SUM(CASE WHEN i.status <> 'voided' AND i.issued_at >= v_window_ytd
               THEN public.convert_cents(i.total_cents, COALESCE(i.currency,'USD'), v_display, i.issued_at)
               ELSE 0 END)::bigint AS ytd_committed_cents,
      bool_or(public.convert_cents(i.total_cents, COALESCE(i.currency,'USD'), v_display, i.issued_at) IS NULL
              AND i.total_cents IS NOT NULL) AS rate_unavailable
      FROM public.invoices i
     WHERE i.department_id IN (SELECT id FROM subtree)
  )
  SELECT jsonb_build_object(
    'all_time_committed_cents', COALESCE(all_time_committed_cents, 0),
    'all_time_paid_cents',      COALESCE(all_time_paid_cents, 0),
    'mtd_committed_cents',      COALESCE(mtd_committed_cents, 0),
    'qtd_committed_cents',      COALESCE(qtd_committed_cents, 0),
    'ytd_committed_cents',      COALESCE(ytd_committed_cents, 0),
    'rate_unavailable',         COALESCE(rate_unavailable, false)
  ) INTO v_display_rollup FROM display_rollup;

  -- ── Recent invoices (each row includes its native + converted amount) ──
  WITH RECURSIVE subtree AS (
    SELECT id FROM public.departments WHERE id = p_department_id
    UNION ALL
    SELECT d.id FROM public.departments d
      JOIN subtree s ON s.id = d.parent_department_id
  )
  SELECT COALESCE(jsonb_agg(row), '[]'::jsonb)
    INTO v_recent
    FROM (
      SELECT jsonb_build_object(
        'invoice_id',           i.id,
        'invoice_number',       i.invoice_number,
        'job_id',                i.job_id,
        'total_cents',          i.total_cents,
        'currency',             COALESCE(i.currency, 'USD'),
        'status',               i.status,
        'issued_at',            i.issued_at,
        'department_id',        i.department_id,
        'cost_center_snapshot', i.cost_center_snapshot,
        -- Sprint 7 — display projection per row
        'display_currency',     v_display,
        'display_total_cents',  public.convert_cents(
                                  i.total_cents,
                                  COALESCE(i.currency, 'USD'),
                                  v_display,
                                  i.issued_at
                                )
      ) AS row
        FROM public.invoices i
       WHERE i.department_id IN (SELECT id FROM subtree)
       ORDER BY i.issued_at DESC NULLS LAST
       LIMIT 5
    ) sub;

  RETURN jsonb_build_object(
    'ok', true,
    'department_id', p_department_id,
    'department_name', v_dept_name,
    'cost_center', v_cost_center,
    'currency', v_predom,
    'mixed_currencies', COALESCE(v_currency_count, 0) > 1,
    'display_currency', v_display,
    'direct', COALESCE(v_direct, '{}'::jsonb),
    'rollup', COALESCE(v_rollup, '{}'::jsonb),
    'display_direct',  COALESCE(v_display_direct,  '{}'::jsonb),
    'display_rollup',  COALESCE(v_display_rollup,  '{}'::jsonb),
    'recent_invoices', COALESCE(v_recent, '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."fetch_department_spend_summary"("p_department_id" "uuid", "p_display_currency" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fetch_department_tree"("p_org_id" "uuid") RETURNS TABLE("id" "uuid", "org_id" "uuid", "parent_department_id" "uuid", "name" "text", "cost_center" "text", "depth" integer, "member_count" integer, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH RECURSIVE tree AS (
    SELECT d.id, d.org_id, d.parent_department_id, d.name, d.cost_center,
           0 AS depth, d.created_at, d.updated_at
      FROM public.departments d
     WHERE d.org_id = p_org_id
       AND d.parent_department_id IS NULL
    UNION ALL
    SELECT d.id, d.org_id, d.parent_department_id, d.name, d.cost_center,
           t.depth + 1, d.created_at, d.updated_at
      FROM public.departments d
      JOIN tree t ON t.id = d.parent_department_id
  ),
  counts AS (
    SELECT dm.department_id, count(*)::int AS n
      FROM public.department_members dm
     GROUP BY dm.department_id
  )
  SELECT t.id, t.org_id, t.parent_department_id, t.name, t.cost_center,
         t.depth,
         COALESCE(c.n, 0) AS member_count,
         t.created_at, t.updated_at
    FROM tree t
    LEFT JOIN counts c ON c.department_id = t.id
   ORDER BY t.depth, lower(t.name);
$$;


ALTER FUNCTION "public"."fetch_department_tree"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fetch_my_org_memberships"() RETURNS TABLE("org_id" "uuid", "org_name" "text", "org_slug" "text", "org_kind" "text", "org_logo_url" "text", "is_active_org" boolean, "role" "text", "member_since" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor      uuid := auth.uid();
  v_active     uuid;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT active_org_id INTO v_active FROM public.profiles WHERE id = v_actor;

  RETURN QUERY
    SELECT
      o.id           AS org_id,
      o.name         AS org_name,
      o.slug         AS org_slug,
      o.kind         AS org_kind,
      o.logo_url     AS org_logo_url,
      (o.id = v_active) AS is_active_org,
      m.role::text   AS role,
      m.created_at   AS member_since
      FROM public.org_members m
      JOIN public.organizations o ON o.id = m.org_id
     WHERE m.user_id = v_actor
       AND o.is_active = true
     ORDER BY (o.id = v_active) DESC, lower(o.name);
END;
$$;


ALTER FUNCTION "public"."fetch_my_org_memberships"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fetch_my_pending_approvals"() RETURNS TABLE("request_id" "uuid", "job_id" "uuid", "job_title" "text", "org_id" "uuid", "org_name" "text", "department_id" "uuid", "department_name" "text", "cost_center" "text", "requested_by" "uuid", "requested_by_label" "text", "requested_at" timestamp with time zone, "amount_cents" bigint, "currency" "text", "min_approvers_required" integer, "approved_count" integer, "required_approver_roles" "text"[])
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  RETURN QUERY
  SELECT
    r.id            AS request_id,
    r.job_id        AS job_id,
    j.title         AS job_title,
    r.org_id        AS org_id,
    o.name          AS org_name,
    r.department_id AS department_id,
    d.name          AS department_name,
    d.cost_center   AS cost_center,
    r.requested_by  AS requested_by,
    COALESCE(NULLIF(TRIM(p.full_name), ''), p.email, 'Unknown') AS requested_by_label,
    r.requested_at  AS requested_at,
    r.amount_cents  AS amount_cents,
    r.currency::text AS currency,
    r.min_approvers_required AS min_approvers_required,
    (SELECT COUNT(*)::int FROM public.approval_decisions ad
       WHERE ad.approval_request_id = r.id AND ad.decision = 'approved') AS approved_count,
    r.required_approver_roles AS required_approver_roles
    FROM public.approval_requests r
    JOIN public.organizations o ON o.id = r.org_id
    JOIN public.jobs j          ON j.id = r.job_id
    LEFT JOIN public.departments d ON d.id = r.department_id
    LEFT JOIN public.profiles p    ON p.id = r.requested_by
   WHERE r.status = 'pending'
     AND r.requested_by <> v_actor                                 -- SoD
     AND (
       public._actor_is_super_admin()                              -- Platform Owner sees all
       OR EXISTS (
         SELECT 1 FROM public.org_members m
          WHERE m.org_id  = r.org_id
            AND m.user_id = v_actor
            AND m.role::text = ANY(r.required_approver_roles)      -- role match
       )
     )
     -- Caller hasn't already decided.
     AND NOT EXISTS (
       SELECT 1 FROM public.approval_decisions ad
        WHERE ad.approval_request_id = r.id AND ad.decided_by = v_actor
     )
   ORDER BY r.requested_at ASC;
END;
$$;


ALTER FUNCTION "public"."fetch_my_pending_approvals"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."file_dispute"("p_job_id" "uuid", "p_category" "text", "p_body" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid        uuid := auth.uid();
  v_role       text;
  v_dispute_id uuid;
  v_admin_id   uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;
  IF p_category NOT IN ('scope','quality','payment','communication','other') THEN
    RAISE EXCEPTION 'invalid category';
  END IF;
  IF char_length(p_body) < 20 OR char_length(p_body) > 8000 THEN
    RAISE EXCEPTION 'body must be 20-8000 characters';
  END IF;

  SELECT role INTO v_role FROM public.profiles WHERE id = v_uid;
  IF v_role NOT IN ('client','agency','enterprise','inspector') THEN
    RAISE EXCEPTION 'role % not authorised to file disputes', v_role;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.jobs
     WHERE id = p_job_id
       AND (client_id = v_uid OR contractor_id = v_uid)
  ) THEN
    RAISE EXCEPTION 'not a party to this job';
  END IF;

  INSERT INTO public.disputes (job_id, opener_id, opener_role, category, body)
    VALUES (p_job_id, v_uid, v_role, p_category, p_body)
    RETURNING id INTO v_dispute_id;

  -- Pause escrow release
  UPDATE public.jobs
     SET escrow_paused = true,
         escrow_paused_reason = format('Dispute filed: %s', p_category)
   WHERE id = p_job_id;

  -- Notify every admin / super_admin
  FOR v_admin_id IN
    SELECT id FROM public.profiles WHERE role IN ('admin','super_admin')
  LOOP
    PERFORM public.notify(
      v_admin_id,
      'dispute_filed',
      'New dispute filed',
      format('%s dispute on job (%s) by %s', p_category, p_job_id::text, v_role),
      format('/admin/disputes'),
      p_job_id
    );
  END LOOP;

  RETURN v_dispute_id;
END $$;


ALTER FUNCTION "public"."file_dispute"("p_job_id" "uuid", "p_category" "text", "p_body" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fin_visible_client_ids"("p_user_id" "uuid") RETURNS SETOF "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role text;
  v_org_id uuid;
BEGIN
  SELECT role, organization_id INTO v_role, v_org_id
  FROM public.profiles WHERE id = p_user_id;

  IF v_role IS NULL THEN RETURN; END IF;

  -- Admin / super_admin → every client on the platform
  IF v_role IN ('admin', 'super_admin') THEN
    RETURN QUERY SELECT id FROM public.profiles WHERE role IN ('client', 'enterprise', 'agency');
    RETURN;
  END IF;

  -- Org-rolled buyer (agency or enterprise) → every profile in same org
  IF v_role IN ('agency', 'enterprise') AND v_org_id IS NOT NULL THEN
    RETURN QUERY
      SELECT id FROM public.profiles
       WHERE organization_id = v_org_id;
    RETURN;
  END IF;

  -- Plain client → just themselves
  IF v_role = 'client' THEN
    RETURN QUERY SELECT p_user_id;
    RETURN;
  END IF;

  -- Inspector / unknown → empty set (no budget visibility)
  RETURN;
END
$$;


ALTER FUNCTION "public"."fin_visible_client_ids"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fin_visible_client_ids"("p_user_id" "uuid") IS 'Returns the set of client/buyer profile ids whose financial data the given user is authorised to view. Used by budget + invoice aggregation RPCs.';



