    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "job_id" "uuid" NOT NULL,
    "raised_by" "uuid" NOT NULL,
    "reason_category" "text" NOT NULL,
    "reason" "text" NOT NULL,
    "evidence_urls" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "resolution_notes" "text",
    "resolved_by" "uuid",
    "resolved_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    CONSTRAINT "job_disputes_reason_category_check" CHECK (("reason_category" = ANY (ARRAY['inspection_quality'::"text", 'no_show'::"text", 'incomplete_work'::"text", 'pricing'::"text", 'communication'::"text", 'safety'::"text", 'other'::"text"]))),
    CONSTRAINT "job_disputes_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'resolved_paid'::"text", 'resolved_refunded'::"text"])))
);


