CREATE OR REPLACE FUNCTION "public"."flag_job_dispute"("p_job_id" "uuid", "p_reason" "text", "p_reason_category" "text", "p_evidence_urls" "text"[] DEFAULT '{}'::"text"[]) RETURNS "public"."job_disputes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_actor   uuid := auth.uid();
  v_job     public.jobs%ROWTYPE;
  v_dispute public.job_disputes;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  -- Lock the job row
  SELECT * INTO v_job FROM public.jobs WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Job % not found', p_job_id USING ERRCODE = 'P0002';
  END IF;
  IF v_job.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'Job % is deleted', p_job_id USING ERRCODE = 'P0001';
  END IF;

  -- Authorize: client, contractor, or agency
  IF NOT (
       v_job.client_id     = v_actor
    OR v_job.contractor_id = v_actor
    OR v_job.agency_id     = v_actor
  ) THEN
    RAISE EXCEPTION 'Not allowed to flag this job' USING ERRCODE = '42501';
  END IF;

  -- State guard
  IF v_job.status NOT IN ('assigned','in_progress','completed') THEN
    RAISE EXCEPTION 'Cannot flag a job in % state', v_job.status
      USING ERRCODE = 'P0001';
  END IF;

  -- Reason guard (extra layer above the column NOT NULL)
  IF p_reason IS NULL OR length(trim(p_reason)) = 0 THEN
    RAISE EXCEPTION 'Reason cannot be empty' USING ERRCODE = 'P0001';
  END IF;

  -- Insert dispute (CHECK enforces category enum and status default)
  INSERT INTO public.job_disputes (
    job_id, raised_by, reason_category, reason, evidence_urls
  ) VALUES (
    p_job_id, v_actor, p_reason_category, trim(p_reason),
    COALESCE(p_evidence_urls, '{}')
  )
  RETURNING * INTO v_dispute;

  -- Freeze the job. Task 2's audit trigger logs status_change.
  UPDATE public.jobs
     SET status = 'disputed',
         updated_at = now()
   WHERE id = p_job_id;

  RETURN v_dispute;
END;
$$;


ALTER FUNCTION "public"."flag_job_dispute"("p_job_id" "uuid", "p_reason" "text", "p_reason_category" "text", "p_evidence_urls" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."flash_report_add_attachment"("p_flash_report_id" "uuid", "p_kind" "text", "p_storage_path" "text", "p_mime_type" "text" DEFAULT NULL::"text", "p_size_bytes" bigint DEFAULT NULL::bigint, "p_caption" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor      uuid;
  v_report     public.flash_reports%ROWTYPE;
  v_job        public.jobs%ROWTYPE;
  v_new_id     uuid;
  v_actor_role text;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_report FROM public.flash_reports WHERE id = p_flash_report_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Flash report not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_job FROM public.jobs WHERE id = v_report.job_id;

  IF v_actor = v_job.contractor_id THEN
    v_actor_role := 'inspector';
  ELSIF v_actor = v_job.client_id THEN
    v_actor_role := 'client';
  ELSIF v_actor = v_job.agency_id THEN
    v_actor_role := 'agency';
  ELSIF EXISTS (
    SELECT 1 FROM public.profiles p WHERE p.id = v_actor AND p.role IN ('admin','super_admin')
  ) THEN
    v_actor_role := 'super_admin';
  ELSE
    RAISE EXCEPTION 'Not a party to this report''s job' USING ERRCODE = '42501';
  END IF;

  -- Closed reports are immutable
  IF v_report.status = 'closed' THEN
    RAISE EXCEPTION 'Cannot attach evidence to a closed report' USING ERRCODE = '22000';
  END IF;

  -- Storage path must point at our bucket sub-tree for this report.
  IF split_part(p_storage_path, '/', 1) <> v_report.id::text THEN
    RAISE EXCEPTION 'Storage path does not belong to this report' USING ERRCODE = '22000';
  END IF;

  -- ★ IDEMPOTENT (offline outbox) ★ — a retry re-delivers the same
  -- (report, storage_path); dedup to the original row, skipping a duplicate
  -- evidence record + audit event.
  INSERT INTO public.flash_report_attachments (
    flash_report_id, uploader_id, kind, storage_path,
    mime_type, size_bytes, caption
  ) VALUES (
    p_flash_report_id, v_actor, p_kind, p_storage_path,
    p_mime_type, p_size_bytes, p_caption
  )
  ON CONFLICT (flash_report_id, storage_path) DO NOTHING
  RETURNING id INTO v_new_id;

  IF v_new_id IS NULL THEN
    SELECT id INTO v_new_id
      FROM public.flash_report_attachments
     WHERE flash_report_id = p_flash_report_id
       AND storage_path = p_storage_path;
    RETURN jsonb_build_object('ok', true, 'attachment_id', v_new_id);
  END IF;

  -- Audit
  PERFORM public.audit_set_correlation(v_report.correlation_id);
  PERFORM public.audit_set_intent('Flash Report attachment added');

  INSERT INTO public.audit_events (
    event_type, severity,
    actor_id, actor_role, actor_label,
    subject_table, subject_id, job_id,
    summary, delta, metadata, correlation_id
  ) VALUES (
    'flash_report.attachment_added',
    'info',
    v_actor, v_actor_role, NULL,
    'flash_reports', p_flash_report_id, v_report.job_id,
    'Evidence attached (' || p_kind || ')',
    '{}'::jsonb,
    jsonb_build_object(
      'flash_report_id', p_flash_report_id,
      'attachment_id', v_new_id,
      'kind', p_kind,
      'storage_path', p_storage_path,
      'mime_type', p_mime_type,
      'size_bytes', p_size_bytes
    ),
    v_report.correlation_id
  );

  RETURN jsonb_build_object('ok', true, 'attachment_id', v_new_id);
END;
$$;


ALTER FUNCTION "public"."flash_report_add_attachment"("p_flash_report_id" "uuid", "p_kind" "text", "p_storage_path" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_caption" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."flash_report_add_attachment"("p_flash_report_id" "uuid", "p_kind" "text", "p_storage_path" "text", "p_mime_type" "text", "p_size_bytes" bigint, "p_caption" "text") IS 'Records an uploaded evidence file against a flash report. Caller must be a party to the job and the storage path must live under this report''s bucket sub-tree. Closed reports are immutable.';



CREATE OR REPLACE FUNCTION "public"."flash_report_create"("p_job_id" "uuid", "p_category" "text", "p_severity" "text", "p_title" "text", "p_description" "text", "p_location_text" "text" DEFAULT NULL::"text", "p_occurred_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor           uuid;
  v_job             public.jobs%ROWTYPE;
  v_role_snapshot   text;
  v_new_id          uuid;
  v_correlation     uuid := gen_random_uuid();
  v_severity_label  text;
BEGIN
  -- 1. Auth
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  -- 2. Validate the job + caller is a party
  SELECT * INTO v_job FROM public.jobs WHERE id = p_job_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Job not found' USING ERRCODE = 'P0002';
  END IF;

  -- Determine reporter role snapshot. Order matters: contractor first,
  -- then client/agency, then super_admin.
  IF v_actor = v_job.contractor_id THEN
    v_role_snapshot := 'inspector';
  ELSIF v_actor = v_job.client_id THEN
    v_role_snapshot := 'client';
  ELSIF v_actor = v_job.agency_id THEN
    v_role_snapshot := 'agency';
  ELSIF EXISTS (
    SELECT 1 FROM public.profiles p WHERE p.id = v_actor AND p.role = 'super_admin'
  ) THEN
    v_role_snapshot := 'super_admin';
  ELSE
    RAISE EXCEPTION 'Only parties to the job (or super_admin) can raise a flash report'
      USING ERRCODE = '42501';
  END IF;

  -- 3. Set audit correlation + intent BEFORE the insert
  PERFORM public.audit_set_correlation(v_correlation);
  PERFORM public.audit_set_intent('Flash Report raised: ' || p_severity || '/' || p_category);

  -- 4. Insert the report
  INSERT INTO public.flash_reports (
    id, job_id, reporter_id, reporter_role,
    category, severity, title, description,
    location_text, occurred_at,
    status, correlation_id
  ) VALUES (
    gen_random_uuid(), p_job_id, v_actor, v_role_snapshot,
    p_category, p_severity, p_title, p_description,
    p_location_text, p_occurred_at,
    'open', v_correlation
  )
  RETURNING id INTO v_new_id;

  -- 5. Manual audit event — flash_reports has no audit trigger
  v_severity_label := CASE
    WHEN p_severity = 'critical' THEN 'critical'
    WHEN p_severity = 'major' THEN 'warning'
    ELSE 'info'
  END;

  INSERT INTO public.audit_events (
    event_type, severity,
    actor_id, actor_role, actor_label,
    subject_table, subject_id, job_id,
    summary, delta, metadata, correlation_id
  ) VALUES (
    'flash_report.raised',
    v_severity_label,
    v_actor, v_role_snapshot, NULL,
    'flash_reports', v_new_id, p_job_id,
    'Flash Report raised — ' || p_severity || ' / ' || p_category || ': ' || p_title,
    jsonb_build_object('after', jsonb_build_object(
      'severity', p_severity, 'category', p_category, 'title', p_title
    )),
    jsonb_build_object(
      'intent', 'Flash Report raised',
      'flash_report_id', v_new_id,
      'severity', p_severity,
      'category', p_category
    ),
    v_correlation
  );

  RETURN jsonb_build_object(
    'ok', true,
    'id', v_new_id,
    'correlation_id', v_correlation,
    'reporter_role', v_role_snapshot
  );
END;
$$;


ALTER FUNCTION "public"."flash_report_create"("p_job_id" "uuid", "p_category" "text", "p_severity" "text", "p_title" "text", "p_description" "text", "p_location_text" "text", "p_occurred_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."flash_report_create"("p_job_id" "uuid", "p_category" "text", "p_severity" "text", "p_title" "text", "p_description" "text", "p_location_text" "text", "p_occurred_at" timestamp with time zone) IS 'Authoritative entry for raising a Flash Report. Snapshots the reporter role, sets audit correlation/intent, and writes a flash_report.raised audit event with critical severity for severity=critical reports.';



CREATE OR REPLACE FUNCTION "public"."flash_report_create"("p_job_id" "uuid", "p_category" "text", "p_severity" "text", "p_title" "text", "p_description" "text", "p_location_text" "text" DEFAULT NULL::"text", "p_occurred_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_client_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor           uuid;
  v_job             public.jobs%ROWTYPE;
  v_role_snapshot   text;
  v_new_id          uuid;
  v_correlation     uuid := gen_random_uuid();
  v_severity_label  text;
BEGIN
  -- 1. Auth
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  -- 2. Validate the job + caller is a party
  SELECT * INTO v_job FROM public.jobs WHERE id = p_job_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Job not found' USING ERRCODE = 'P0002';
  END IF;

  -- Determine reporter role snapshot. Order matters: contractor first,
  -- then client/agency, then super_admin.
  IF v_actor = v_job.contractor_id THEN
    v_role_snapshot := 'inspector';
  ELSIF v_actor = v_job.client_id THEN
    v_role_snapshot := 'client';
  ELSIF v_actor = v_job.agency_id THEN
    v_role_snapshot := 'agency';
  ELSIF EXISTS (
    SELECT 1 FROM public.profiles p WHERE p.id = v_actor AND p.role IN ('admin','super_admin')
  ) THEN
    v_role_snapshot := 'super_admin';
  ELSE
    RAISE EXCEPTION 'Only parties to the job (or super_admin) can raise a flash report'
      USING ERRCODE = '42501';
  END IF;

  -- ★ IDEMPOTENT REPLAY (offline outbox) ★ — if the client supplied an id and
  -- the report already exists, return it unchanged (no second insert / audit).
  -- Gated behind the party check above so only a party can resolve an id.
  IF p_client_id IS NOT NULL THEN
    SELECT id, correlation_id, reporter_role
      INTO v_new_id, v_correlation, v_role_snapshot
      FROM public.flash_reports
     WHERE id = p_client_id;
    IF FOUND THEN
      RETURN jsonb_build_object(
        'ok', true,
        'id', v_new_id,
        'correlation_id', v_correlation,
        'reporter_role', v_role_snapshot
      );
    END IF;
  END IF;

  -- 3. Set audit correlation + intent BEFORE the insert
  PERFORM public.audit_set_correlation(v_correlation);
  PERFORM public.audit_set_intent('Flash Report raised: ' || p_severity || '/' || p_category);

  -- 4. Insert the report (client-supplied id when present → offline-known id)
  INSERT INTO public.flash_reports (
    id, job_id, reporter_id, reporter_role,
    category, severity, title, description,
    location_text, occurred_at,
    status, correlation_id
  ) VALUES (
    COALESCE(p_client_id, gen_random_uuid()), p_job_id, v_actor, v_role_snapshot,
    p_category, p_severity, p_title, p_description,
    p_location_text, p_occurred_at,
    'open', v_correlation
  )
  RETURNING id INTO v_new_id;

  -- 5. Manual audit event — flash_reports has no audit trigger
  v_severity_label := CASE
    WHEN p_severity = 'critical' THEN 'critical'
    WHEN p_severity = 'major' THEN 'warning'
    ELSE 'info'
  END;

  INSERT INTO public.audit_events (
    event_type, severity,
    actor_id, actor_role, actor_label,
    subject_table, subject_id, job_id,
    summary, delta, metadata, correlation_id
  ) VALUES (
    'flash_report.raised',
    v_severity_label,
    v_actor, v_role_snapshot, NULL,
    'flash_reports', v_new_id, p_job_id,
    'Flash Report raised — ' || p_severity || ' / ' || p_category || ': ' || p_title,
    jsonb_build_object('after', jsonb_build_object(
      'severity', p_severity, 'category', p_category, 'title', p_title
    )),
    jsonb_build_object(
      'intent', 'Flash Report raised',
      'flash_report_id', v_new_id,
      'severity', p_severity,
      'category', p_category
    ),
    v_correlation
  );

  RETURN jsonb_build_object(
    'ok', true,
    'id', v_new_id,
    'correlation_id', v_correlation,
    'reporter_role', v_role_snapshot
  );
END;
$$;


ALTER FUNCTION "public"."flash_report_create"("p_job_id" "uuid", "p_category" "text", "p_severity" "text", "p_title" "text", "p_description" "text", "p_location_text" "text", "p_occurred_at" timestamp with time zone, "p_client_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."flash_report_transition"("p_id" "uuid", "p_to_status" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor          uuid;
  v_actor_role     text;     -- effective role for THIS job + this caller
  v_actor_profile  text;     -- profiles.role
  v_report         public.flash_reports%ROWTYPE;
  v_job            public.jobs%ROWTYPE;
  v_legal          boolean := false;
  v_now            timestamptz := now();
  v_event_severity text := 'info';
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_report FROM public.flash_reports WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Flash report not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_job FROM public.jobs WHERE id = v_report.job_id;

  SELECT role INTO v_actor_profile FROM public.profiles WHERE id = v_actor;

  -- Caller's effective role on this job
  IF v_actor_profile IN ('admin','super_admin') THEN
    v_actor_role := 'super_admin';
  ELSIF v_actor = v_job.contractor_id THEN
    v_actor_role := 'inspector';
  ELSIF v_actor = v_job.client_id THEN
    v_actor_role := 'client';
  ELSIF v_actor = v_job.agency_id THEN
    v_actor_role := 'agency';
  ELSE
    RAISE EXCEPTION 'You are not a party to this report''s job'
      USING ERRCODE = '42501';
  END IF;

  -- ── State-machine guards ────────────────────────────────────────
  -- open → acknowledged   : any non-reporter party (so the reporter
  --                         can't ack their own report) or admin
  -- acknowledged → in_remediation : inspector or admin
  -- in_remediation → resolved     : inspector or admin
  -- resolved → closed             : admin only
  -- (open|acknowledged|in_remediation) → disputed : any party except admin
  -- disputed → acknowledged       : admin only

  IF v_report.status = 'open' AND p_to_status = 'acknowledged' THEN
    IF v_actor = v_report.reporter_id AND v_actor_role NOT IN ('admin','super_admin') THEN
      RAISE EXCEPTION 'Reporters cannot acknowledge their own report'
        USING ERRCODE = '42501';
    END IF;
    v_legal := true;

  ELSIF v_report.status = 'acknowledged' AND p_to_status = 'in_remediation' THEN
    IF v_actor_role NOT IN ('inspector','super_admin') THEN
      RAISE EXCEPTION 'Only the inspector or admin can move to in_remediation'
        USING ERRCODE = '42501';
    END IF;
    v_legal := true;

  ELSIF v_report.status = 'in_remediation' AND p_to_status = 'resolved' THEN
    IF v_actor_role NOT IN ('inspector','super_admin') THEN
      RAISE EXCEPTION 'Only the inspector or admin can resolve the report'
        USING ERRCODE = '42501';
    END IF;
    v_legal := true;

  ELSIF v_report.status = 'resolved' AND p_to_status = 'closed' THEN
    IF v_actor_role NOT IN ('admin','super_admin') THEN
      RAISE EXCEPTION 'Only admin can close a resolved report' USING ERRCODE = '42501';
    END IF;
    v_legal := true;

  ELSIF v_report.status IN ('open','acknowledged','in_remediation')
        AND p_to_status = 'disputed' THEN
    -- Anyone EXCEPT super_admin can raise a dispute (admin resolves disputes)
    IF v_actor_role IN ('admin','super_admin') THEN
      RAISE EXCEPTION 'Admin does not dispute reports — admin resolves disputes'
        USING ERRCODE = '42501';
    END IF;
    v_legal := true;
    v_event_severity := 'warning';

  ELSIF v_report.status = 'disputed' AND p_to_status = 'acknowledged' THEN
    IF v_actor_role NOT IN ('admin','super_admin') THEN
      RAISE EXCEPTION 'Only admin can resolve a dispute' USING ERRCODE = '42501';
    END IF;
    v_legal := true;
  END IF;

  IF NOT v_legal THEN
    RAISE EXCEPTION 'Illegal transition % → %', v_report.status, p_to_status
      USING ERRCODE = '22000';
  END IF;

  -- ── Apply the transition + side effects ─────────────────────────
  PERFORM public.audit_set_correlation(v_report.correlation_id);
  PERFORM public.audit_set_intent(
    'Flash Report transition: ' || v_report.status || ' → ' || p_to_status
  );

  -- Field updates depending on the destination status
  IF p_to_status = 'acknowledged' AND v_report.acknowledged_at IS NULL THEN
    UPDATE public.flash_reports
      SET status = p_to_status,
          acknowledged_at = v_now,
          acknowledged_by = v_actor,
          updated_at = v_now
    WHERE id = p_id;

  ELSIF p_to_status = 'resolved' THEN
    UPDATE public.flash_reports
      SET status = p_to_status,
          resolved_at = v_now,
          resolved_by = v_actor,
          resolution_notes = COALESCE(p_notes, resolution_notes),
          updated_at = v_now
    WHERE id = p_id;

  ELSE
    UPDATE public.flash_reports
      SET status = p_to_status,
          resolution_notes = COALESCE(p_notes, resolution_notes),
          updated_at = v_now
    WHERE id = p_id;
  END IF;

  -- Audit
  INSERT INTO public.audit_events (
    event_type, severity,
    actor_id, actor_role, actor_label,
    subject_table, subject_id, job_id,
    summary, delta, metadata, correlation_id
  ) VALUES (
    'flash_report.transition',
    v_event_severity,
    v_actor, v_actor_role, NULL,
    'flash_reports', p_id, v_report.job_id,
    'Flash Report ' || v_report.status || ' → ' || p_to_status,
    jsonb_build_object(
      'before', jsonb_build_object('status', v_report.status),
      'after',  jsonb_build_object('status', p_to_status)
    ),
    jsonb_build_object(
      'flash_report_id', p_id,
      'from', v_report.status,
      'to', p_to_status,
      'notes', p_notes
    ),
    v_report.correlation_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'id', p_id,
    'from', v_report.status,
    'to', p_to_status
  );
END;
$$;


ALTER FUNCTION "public"."flash_report_transition"("p_id" "uuid", "p_to_status" "text", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."flash_report_transition"("p_id" "uuid", "p_to_status" "text", "p_notes" "text") IS 'State-machine-enforced transitions for a Flash Report. Role guards: ack by non-reporter party, in_remediation/resolved by inspector or admin, close by admin only, dispute by any party except admin (admin resolves disputes).';



CREATE OR REPLACE FUNCTION "public"."format_amount_for_notification"("p_amount_cents" bigint, "p_currency" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $_$
DECLARE
  v_dollars numeric;
  v_symbol  text;
BEGIN
  IF p_amount_cents IS NULL THEN RETURN ''; END IF;
  v_dollars := (p_amount_cents::numeric) / 100.0;
  v_symbol  := CASE upper(COALESCE(p_currency, ''))
                 WHEN 'USD' THEN '$'
                 WHEN 'EUR' THEN '€'
                 WHEN 'GBP' THEN '£'
                 WHEN 'JPY' THEN '¥'
                 WHEN 'CHF' THEN 'CHF '
                 WHEN 'AED' THEN 'AED '
                 WHEN 'CAD' THEN 'CA$'
                 WHEN 'AUD' THEN 'A$'
                 WHEN 'SGD' THEN 'S$'
                 ELSE COALESCE(p_currency, '') || ' '
               END;
  RETURN v_symbol || trim(to_char(v_dollars, 'FM999,999,999,990.00'));
END
$_$;


ALTER FUNCTION "public"."format_amount_for_notification"("p_amount_cents" bigint, "p_currency" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fund_deal_balance"("p_deal_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_d public.deals; v_leg public.deal_money_legs; v_agr uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT * INTO v_d FROM public.deals WHERE id = p_deal_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown_deal'; END IF;
  IF NOT (v_d.client_id = v_uid OR public.nx_is_admin()) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF v_d.deposit_funded_at IS NULL THEN RAISE EXCEPTION 'DEPOSIT_NOT_FUNDED: sign and fund the mobilization deposit first'; END IF;
  IF v_d.balance_funded_at IS NOT NULL THEN
    RETURN jsonb_build_object('deal_id', p_deal_id, 'status', 'already_funded', 'reused', true);
  END IF;

  -- the executed client_supply gates the escrow hold
  SELECT id INTO v_agr FROM public.agreements
   WHERE deal_id = p_deal_id AND kind = 'client_supply' AND status = 'executed'
   ORDER BY version DESC LIMIT 1;
  IF v_agr IS NULL THEN RAISE EXCEPTION 'CLIENT_AGREEMENT_NOT_EXECUTED'; END IF;

  -- top the single client_escrow_in hold up to the full contract price
  SELECT * INTO v_leg FROM public.deal_money_legs WHERE deal_id = p_deal_id AND kind = 'client_escrow_in' FOR UPDATE;
  IF FOUND THEN
    UPDATE public.deal_money_legs SET amount_cents = v_d.client_price_cents, status = 'held'
     WHERE id = v_leg.id;
  ELSE
    INSERT INTO public.deal_money_legs (deal_id, agreement_id, kind, amount_cents, currency, status)
    VALUES (p_deal_id, v_agr, 'client_escrow_in', v_d.client_price_cents, v_d.currency, 'held');
  END IF;

  UPDATE public.deals SET balance_funded_at = now() WHERE id = p_deal_id;
  RETURN jsonb_build_object('deal_id', p_deal_id, 'status', 'balance_funded',
                            'escrowed_cents', v_d.client_price_cents);
END $$;


ALTER FUNCTION "public"."fund_deal_balance"("p_deal_id" "uuid") OWNER TO "postgres";


