CREATE OR REPLACE FUNCTION "public"."generate_contract_for_job"("job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    job_record RECORD;
    result JSONB;
BEGIN
    -- Verify job exists and is in hired status
    SELECT * INTO job_record FROM public.jobs WHERE id = job_id;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('error', 'Job not found');
    END IF;
    
    IF job_record.status != 'hired' THEN
        RETURN jsonb_build_object('error', 'Job must be in hired status');
    END IF;
    
    -- Check if contract already exists
    IF job_record.contract_id IS NOT NULL THEN
        RETURN jsonb_build_object('error', 'Contract already exists for this job');
    END IF;
    
    -- Trigger contract generation by updating the job
    UPDATE public.jobs 
    SET updated_at = NOW()
    WHERE id = job_id;
    
    RETURN jsonb_build_object(
        'success', true,
        'message', 'Contract generation triggered',
        'job_id', job_id
    );
END;
$$;


ALTER FUNCTION "public"."generate_contract_for_job"("job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_asset_timeline"("p_asset_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE v_org uuid; v_rows jsonb;
BEGIN
  SELECT org_id INTO v_org FROM public.inspection_assets WHERE id = p_asset_id;
  IF v_org IS NULL THEN RETURN NULL; END IF;
  IF NOT (public.is_member_of_org(v_org) OR public.nx_is_admin()) THEN
    RAISE EXCEPTION 'not authorized for this asset' USING errcode='42501';
  END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(o) ORDER BY o.observed_at), '[]'::jsonb) INTO v_rows
    FROM (SELECT defect_id, severity, severity_rank, confidence, observed_at, source
          FROM public.asset_defect_observations WHERE asset_id = p_asset_id) o;
  RETURN jsonb_build_object('asset_id', p_asset_id, 'observations', v_rows);
END; $$;


ALTER FUNCTION "public"."get_asset_timeline"("p_asset_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_budget_by_inspector"("p_limit" integer DEFAULT 10) RETURNS TABLE("inspector_id" "uuid", "inspector_name" "text", "job_count" bigint, "total_cents" bigint, "last_job_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_limit integer := GREATEST(1, LEAST(COALESCE(p_limit, 10), 50));
BEGIN
  RETURN QUERY
  SELECT
    p.id                                                  AS inspector_id,
    COALESCE(p.full_name, p.email, 'Unknown')             AS inspector_name,
    COUNT(j.id)::bigint                                   AS job_count,
    COALESCE(SUM(j.client_price_cents),0)::bigint         AS total_cents,
    MAX(j.created_at)                                     AS last_job_at
  FROM public.jobs j
  JOIN public.profiles p
    ON p.id = j.hired_inspector_id
  WHERE j.client_id IN (SELECT public.fin_visible_client_ids(auth.uid()))
    AND j.deleted_at IS NULL
    AND j.hired_inspector_id IS NOT NULL
    AND j.status NOT IN ('cancelled','voided')
    AND j.created_at >= date_trunc('year', NOW())
  GROUP BY p.id, p.full_name, p.email
  ORDER BY total_cents DESC
  LIMIT v_limit;
END
$$;


ALTER FUNCTION "public"."get_budget_by_inspector"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_budget_monthly"("p_months" integer DEFAULT 12) RETURNS TABLE("month_start" "date", "month_label" "text", "job_count" bigint, "committed_cents" bigint, "completed_cents" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_months integer := GREATEST(1, LEAST(COALESCE(p_months, 12), 24));
BEGIN
  RETURN QUERY
  WITH calendar AS (
    SELECT
      date_trunc('month', NOW() - (i || ' months')::interval)::date AS month_start
    FROM generate_series(0, v_months - 1) AS i
  ),
  visible AS (
    SELECT j.*
      FROM public.jobs j
     WHERE j.client_id IN (SELECT public.fin_visible_client_ids(auth.uid()))
       AND j.deleted_at IS NULL
       AND j.created_at >= date_trunc('month', NOW() - (v_months || ' months')::interval)
  )
  SELECT
    c.month_start,
    to_char(c.month_start, 'Mon YYYY')                                                  AS month_label,
    COALESCE(COUNT(v.id), 0)::bigint                                                    AS job_count,
    COALESCE(SUM(v.client_price_cents) FILTER (WHERE v.status NOT IN ('cancelled','voided')),0)::bigint AS committed_cents,
    COALESCE(SUM(v.client_price_cents) FILTER (WHERE v.status = 'completed'),0)::bigint AS completed_cents
  FROM calendar c
  LEFT JOIN visible v
         ON date_trunc('month', v.created_at)::date = c.month_start
  GROUP BY c.month_start
  ORDER BY c.month_start ASC;
END
$$;


ALTER FUNCTION "public"."get_budget_monthly"("p_months" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_budget_recent_activity"("p_limit" integer DEFAULT 25) RETURNS TABLE("job_id" "uuid", "job_title" "text", "status" "text", "client_price_cents" bigint, "client_id" "uuid", "client_name" "text", "inspector_id" "uuid", "inspector_name" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_limit integer := GREATEST(1, LEAST(COALESCE(p_limit, 25), 100));
BEGIN
  RETURN QUERY
  SELECT
    j.id                                            AS job_id,
    j.title                                         AS job_title,
    j.status                                        AS status,
    COALESCE(j.client_price_cents, 0)::bigint       AS client_price_cents,
    j.client_id                                     AS client_id,
    COALESCE(pc.full_name, pc.email, 'Client')      AS client_name,
    j.hired_inspector_id                            AS inspector_id,
    COALESCE(pi.full_name, pi.email, NULL)          AS inspector_name,
    j.created_at                                    AS created_at
  FROM public.jobs j
  LEFT JOIN public.profiles pc ON pc.id = j.client_id
  LEFT JOIN public.profiles pi ON pi.id = j.hired_inspector_id
  WHERE j.client_id IN (SELECT public.fin_visible_client_ids(auth.uid()))
    AND j.deleted_at IS NULL
  ORDER BY j.created_at DESC
  LIMIT v_limit;
END
$$;


ALTER FUNCTION "public"."get_budget_recent_activity"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_budget_summary"() RETURNS TABLE("total_jobs" bigint, "active_jobs" bigint, "completed_jobs" bigint, "disputed_jobs" bigint, "committed_cents" bigint, "in_escrow_cents" bigint, "paid_out_cents" bigint, "awaiting_payout_cents" bigint, "avg_job_cents" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  WITH visible AS (
    SELECT j.*
      FROM public.jobs j
     WHERE j.client_id IN (SELECT public.fin_visible_client_ids(auth.uid()))
       AND j.deleted_at IS NULL
  )
  SELECT
    COUNT(*)::bigint                                                                            AS total_jobs,
    COUNT(*) FILTER (WHERE status IN ('open','pending_approval','assigned','in_progress'))::bigint AS active_jobs,
    COUNT(*) FILTER (WHERE status = 'completed')::bigint                                        AS completed_jobs,
    COUNT(*) FILTER (WHERE status = 'disputed')::bigint                                         AS disputed_jobs,
    COALESCE(SUM(client_price_cents) FILTER (WHERE status NOT IN ('cancelled','voided')),0)::bigint AS committed_cents,
    COALESCE(SUM(client_price_cents) FILTER (WHERE status IN ('assigned','in_progress')),0)::bigint AS in_escrow_cents,
    COALESCE(SUM(client_price_cents) FILTER (WHERE status = 'completed' AND payout_status = 'paid'),0)::bigint AS paid_out_cents,
    COALESCE(SUM(client_price_cents) FILTER (WHERE status = 'completed' AND payout_status <> 'paid'),0)::bigint AS awaiting_payout_cents,
    CASE WHEN COUNT(*) FILTER (WHERE status NOT IN ('cancelled','voided')) > 0
         THEN (COALESCE(SUM(client_price_cents) FILTER (WHERE status NOT IN ('cancelled','voided')),0)
               / COUNT(*) FILTER (WHERE status NOT IN ('cancelled','voided')))::bigint
         ELSE 0 END                                                                             AS avg_job_cents
  FROM visible;
END
$$;


ALTER FUNCTION "public"."get_budget_summary"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_burn_rate"("p_project_id" "uuid", "p_months_back" integer DEFAULT 12) RETURNS TABLE("month" "date", "month_label" "text", "total_paid" numeric, "payment_count" bigint, "running_total" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
    WITH monthly_payments AS (
        SELECT
            DATE_TRUNC('month', p.paid_at)::DATE          AS month,
            TO_CHAR(p.paid_at, 'Mon YYYY')                AS month_label,
            COALESCE(SUM(p.amount), 0)::NUMERIC(15,2)     AS total_paid,
            COUNT(p.id)                                    AS payment_count
        FROM public.payments p
        WHERE p.project_id = p_project_id
          AND p.status = 'completed'
          AND p.paid_at >= (NOW() - (p_months_back || ' months')::INTERVAL)
        GROUP BY DATE_TRUNC('month', p.paid_at), TO_CHAR(p.paid_at, 'Mon YYYY')
    )
    SELECT
        mp.month,
        mp.month_label,
        mp.total_paid,
        mp.payment_count,
        SUM(mp.total_paid) OVER (
            ORDER BY mp.month
            ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
        )::NUMERIC(15,2) AS running_total
    FROM monthly_payments mp
    ORDER BY mp.month ASC;
$$;


ALTER FUNCTION "public"."get_burn_rate"("p_project_id" "uuid", "p_months_back" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_certification_expiry_summary"("p_contractor_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("expiry_window" "text", "count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        CASE 
            WHEN cc.expiry_date < CURRENT_DATE THEN 'expired'
            WHEN cc.expiry_date = CURRENT_DATE THEN 'expires_today'
            WHEN cc.expiry_date <= CURRENT_DATE + 7 THEN 'expires_within_7_days'
            WHEN cc.expiry_date <= CURRENT_DATE + 30 THEN 'expires_within_30_days'
            WHEN cc.expiry_date <= CURRENT_DATE + 90 THEN 'expires_within_90_days'
            ELSE 'valid'
        END AS expiry_window,
        COUNT(*) AS count
    FROM 
        contractor_certifications cc
    WHERE 
        cc.status = 'active'
        AND (p_contractor_id IS NULL OR cc.contractor_id = p_contractor_id)
    GROUP BY 
        expiry_window
    ORDER BY 
        CASE expiry_window
            WHEN 'expired' THEN 1
            WHEN 'expires_today' THEN 2
            WHEN 'expires_within_7_days' THEN 3
            WHEN 'expires_within_30_days' THEN 4
            WHEN 'expires_within_90_days' THEN 5
            ELSE 6
        END;
END;
$$;


ALTER FUNCTION "public"."get_certification_expiry_summary"("p_contractor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_client_branding"("p_uid" "uuid") RETURNS TABLE("company_logo_url" "text", "report_header_text" "text", "report_footer_text" "text", "use_custom_branding" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    p.company_logo_url,
    p.report_header_text,
    p.report_footer_text,
    COALESCE(p.use_custom_branding, false) AS use_custom_branding
  FROM public.profiles p
  WHERE p.id = p_uid
    AND (
      auth.uid() = p_uid
      OR public.nx_is_admin()
      OR EXISTS (
        SELECT 1
          FROM public.jobs j
         WHERE j.client_id = p_uid
           AND auth.uid() IN (j.contractor_id, j.agency_id)
      )
    )
  LIMIT 1;
$$;


ALTER FUNCTION "public"."get_client_branding"("p_uid" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_client_branding"("p_uid" "uuid") IS 'NX-AUTH-002 Step 2: SECURITY DEFINER read of a client''s report-branding fields. Authorized for the client themselves, the contractor or agency currently working on one of that client''s jobs, and admins.';



CREATE OR REPLACE FUNCTION "public"."get_dashboard_analytics"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  stats record;
  monthly json;
BEGIN
  -- 1. محاسبه آمارهای کلان
  SELECT 
    COALESCE(SUM(client_price), 0) as total_volume,
    COALESCE(SUM(CASE WHEN status = 'completed' THEN client_price - payout_amount ELSE 0 END), 0) as platform_profit,
    COALESCE(SUM(CASE WHEN status IN ('assigned', 'in_progress', 'under_review') THEN client_price - payout_amount ELSE 0 END), 0) as pending_profit,
    COUNT(*) as total_jobs,
    COUNT(CASE WHEN status = 'completed' THEN 1 END) as completed_jobs,
    COUNT(CASE WHEN status IN ('assigned', 'in_progress', 'under_review') THEN 1 END) as active_jobs,
    COALESCE(SUM(CASE WHEN status = 'completed' AND client_price > 0 THEN ((client_price - payout_amount) / client_price) * 100 ELSE 0 END), 0) as margin_sum
  INTO stats
  FROM public.jobs;

  -- 2. محاسبه درآمدهای 6 ماه اخیر برای نمودار
  SELECT COALESCE(json_agg(row_to_json(m)), '[]'::json) INTO monthly
  FROM (
    SELECT 
      TRIM(to_char(date_trunc('month', created_at), 'Month YYYY')) as month,
      TRIM(to_char(date_trunc('month', created_at), 'Mon')) as short_month,
      to_char(date_trunc('month', created_at), 'YYYY-MM') as month_key,
      COALESCE(SUM(client_price - payout_amount), 0) as profit,
      COALESCE(SUM(client_price), 0) as volume,
      COUNT(*) as job_count
    FROM public.jobs
    WHERE created_at >= date_trunc('month', CURRENT_DATE) - INTERVAL '5 months'
    GROUP BY date_trunc('month', created_at)
    ORDER BY date_trunc('month', created_at) ASC
  ) m;

  -- 3. ارسال خروجی یکپارچه به موبایل
  RETURN json_build_object(
    'totalVolume', stats.total_volume,
    'platformProfit', stats.platform_profit,
    'pendingProfit', stats.pending_profit,
    'totalJobs', stats.total_jobs,
    'completedJobs', stats.completed_jobs,
    'activeJobs', stats.active_jobs,
    'marginSum', stats.margin_sum,
    'monthlyData', monthly
  );
END;
$$;


ALTER FUNCTION "public"."get_dashboard_analytics"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_expiring_certifications"("reminder_days" integer[] DEFAULT ARRAY[30, 7, 1]) RETURNS TABLE("id" "uuid", "contractor_id" "uuid", "title" "text", "expiry_date" "date", "days_until_expiry" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    target_dates DATE[];
    day_value INTEGER;
BEGIN
    -- Calculate target dates based on reminder days
    target_dates := ARRAY[]::DATE[];
    
    FOREACH day_value IN ARRAY reminder_days
    LOOP
        target_dates := array_append(target_dates, (CURRENT_DATE + day_value)::DATE);
    END LOOP;

    RETURN QUERY
    SELECT 
        cc.id,
        cc.contractor_id,
        cc.title,
        cc.expiry_date,
        (cc.expiry_date - CURRENT_DATE)::INTEGER AS days_until_expiry
    FROM 
        contractor_certifications cc
    WHERE 
        cc.status = 'active'
        AND cc.expiry_date = ANY(target_dates)
    ORDER BY 
        cc.expiry_date ASC,
        cc.contractor_id;
END;
$$;


ALTER FUNCTION "public"."get_expiring_certifications"("reminder_days" integer[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_expiring_certifications_with_contractor"("reminder_days" integer[] DEFAULT ARRAY[30, 7, 1]) RETURNS TABLE("certification_id" "uuid", "contractor_id" "uuid", "contractor_name" "text", "contractor_email" "text", "expo_push_token" "text", "notification_preferences" "jsonb", "certification_title" "text", "expiry_date" "date", "days_until_expiry" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    target_dates DATE[];
    day_value INTEGER;
BEGIN
    -- Calculate target dates
    target_dates := ARRAY[]::DATE[];
    
    FOREACH day_value IN ARRAY reminder_days
    LOOP
        target_dates := array_append(target_dates, (CURRENT_DATE + day_value)::DATE);
    END LOOP;

    RETURN QUERY
    SELECT 
        cc.id AS certification_id,
        c.id AS contractor_id,
        c.full_name AS contractor_name,
        c.email AS contractor_email,
        c.expo_push_token,
        c.notification_preferences,
        cc.title AS certification_title,
        cc.expiry_date,
        (cc.expiry_date - CURRENT_DATE)::INTEGER AS days_until_expiry
    FROM 
        contractor_certifications cc
    INNER JOIN 
        contractors c ON cc.contractor_id = c.id
    WHERE 
        cc.status = 'active'
        AND c.status = 'active'
        AND cc.expiry_date = ANY(target_dates)
        -- Only include contractors with push notifications enabled
        AND (
            c.notification_preferences IS NULL 
            OR (c.notification_preferences->>'push_notifications')::boolean = true
        )
    ORDER BY 
        cc.expiry_date ASC,
        c.id;
END;
$$;


ALTER FUNCTION "public"."get_expiring_certifications_with_contractor"("reminder_days" integer[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_inspection_passport"("p_seal_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE v_s record; v_certs int; v_calib int; v_anchor record;
BEGIN
  SELECT id, root_sha256, algorithm, chain_verified, items_count, captures_count,
         inspector_sealed_at, inspector_id, job_id
    INTO v_s FROM public.pi_report_seals WHERE id = p_seal_id;
  IF v_s.id IS NULL THEN RETURN NULL; END IF;

  -- NOTE: inspector full_name is deliberately NOT read or returned (anti-poaching).
  SELECT count(*) INTO v_certs FROM public.inspector_certifications c
   WHERE c.inspector_id = v_s.inspector_id
     AND (c.expires_at IS NULL OR c.expires_at >= v_s.inspector_sealed_at::date);
  SELECT count(*) INTO v_calib FROM public.inspector_equipment e
   WHERE e.inspector_id = v_s.inspector_id
     AND (e.next_calibration_due IS NULL OR e.next_calibration_due >= v_s.inspector_sealed_at::date);

  SELECT status, confirmed_at, calendar INTO v_anchor
    FROM public.inspection_seal_anchors WHERE seal_id = p_seal_id;

  RETURN jsonb_build_object(
    'seal', jsonb_build_object('id', v_s.id, 'root_sha256', v_s.root_sha256,
       'algorithm', v_s.algorithm, 'chain_verified', v_s.chain_verified,
       'items_count', v_s.items_count, 'captures_count', v_s.captures_count,
       'sealed_at', v_s.inspector_sealed_at),
    -- Opaque UUID only — the client derives an NX- handle + sigil and links to
    -- the anonymized trust card. No name/contact/location.
    'inspector', jsonb_build_object('id', v_s.inspector_id),
    'credentials', jsonb_build_object('certifications_valid_at_seal', coalesce(v_certs,0),
       'equipment_in_calibration_at_seal', coalesce(v_calib,0)),
    'anchor', jsonb_build_object('status', coalesce(v_anchor.status,'pending'),
       'confirmed_at', v_anchor.confirmed_at, 'calendar', v_anchor.calendar)
  );
END; $$;


ALTER FUNCTION "public"."get_inspection_passport"("p_seal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_inspector_dashboard_stats"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  current_user_id uuid;
  result json;
BEGIN
  -- گرفتن ID کاربری که لاگین کرده
  current_user_id := auth.uid();

  SELECT json_build_object(
    'active_jobs', (SELECT count(*) FROM jobs WHERE hired_inspector_id = current_user_id AND status = 'in_progress'),
    'completed_jobs', (SELECT count(*) FROM jobs WHERE hired_inspector_id = current_user_id AND status = 'completed'),
    'pending_offers', (SELECT count(*) FROM job_applications WHERE inspector_id = current_user_id AND status = 'pending'),
    'total_reviews', 0, -- فعلا صفر
    'average_rating', 0, -- فعلا صفر
    'total_earned', 0, -- فعلا صفر
    'available_balance', 0 -- فعلا صفر
  ) INTO result;

  RETURN result;
END;
$$;


