CREATE TABLE IF NOT EXISTS "public"."reviews" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "job_id" "uuid" NOT NULL,
    "inspector_id" "uuid" NOT NULL,
    "client_id" "uuid" NOT NULL,
    "rating" integer NOT NULL,
    "comment" "text",
    "would_recommend" boolean DEFAULT true,
    "tags" "text"[] DEFAULT '{}'::"text"[],
    "is_public" boolean DEFAULT true,
    "inspector_response" "text",
    "inspector_response_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "client_op_id" "uuid",
    "reviewer_id" "uuid" NOT NULL,
    "reviewee_id" "uuid" NOT NULL,
    "reviewer_role_snap" "text" DEFAULT 'client'::"text" NOT NULL,
    "reviewee_role_snap" "text" DEFAULT 'inspector'::"text" NOT NULL,
    "reviewer_verified_snap" boolean DEFAULT false NOT NULL,
    "reviewer_jobs_count_snap" integer DEFAULT 0 NOT NULL,
    "weight" numeric(5,3) DEFAULT 1.0 NOT NULL,
    "moderation_status" "text" DEFAULT 'visible'::"text" NOT NULL,
    "hidden_at" timestamp with time zone,
    "hidden_by" "uuid",
    "moderator_notes" "text",
    "private_admin_note" "text",
    "disputed_at" timestamp with time zone,
    "disputed_reason" "text",
    "flagged_at" timestamp with time zone,
    "flagged_reason" "text",
    "last_moderated_at" timestamp with time zone,
    "last_moderated_by" "uuid",
    CONSTRAINT "reviews_comment_check" CHECK (("char_length"("comment") <= 2000)),
    CONSTRAINT "reviews_moderation_status_check" CHECK (("moderation_status" = ANY (ARRAY['visible'::"text", 'hidden'::"text", 'disputed'::"text", 'flagged'::"text"]))),
    CONSTRAINT "reviews_no_self_review_check" CHECK (("reviewer_id" <> "reviewee_id")),
    CONSTRAINT "reviews_rating_check" CHECK ((("rating" >= 1) AND ("rating" <= 5))),
    CONSTRAINT "reviews_rating_range_check" CHECK ((("rating" >= 1) AND ("rating" <= 5))),
    CONSTRAINT "reviews_role_snap_check" CHECK ((("reviewer_role_snap" = ANY (ARRAY['client'::"text", 'agency'::"text", 'enterprise'::"text", 'inspector'::"text"])) AND ("reviewee_role_snap" = ANY (ARRAY['client'::"text", 'agency'::"text", 'enterprise'::"text", 'inspector'::"text"]))))
);


ALTER TABLE "public"."reviews" OWNER TO "postgres";


COMMENT ON COLUMN "public"."reviews"."reviewer_id" IS 'Generalized reviewer (replaces legacy semantics where client_id was always the reviewer). Reviewer can be the inspector OR the client/agency/enterprise.';



COMMENT ON COLUMN "public"."reviews"."reviewee_id" IS 'Generalized reviewee. The OTHER party to the job.';



COMMENT ON COLUMN "public"."reviews"."reviewer_role_snap" IS 'Snapshot of reviewer''s role at write time. Used for weighting and survives later role changes.';



COMMENT ON COLUMN "public"."reviews"."weight" IS 'Anti-fraud / quality weighting. Computed at write time by compute_review_weight() so retroactive reviewer changes do not rewrite history.';



COMMENT ON COLUMN "public"."reviews"."moderation_status" IS 'visible | hidden | disputed | flagged. Only ''visible'' reviews count toward reputation.';



COMMENT ON COLUMN "public"."reviews"."private_admin_note" IS 'Strictly internal feedback channel. Masked from non-admin SELECTs by reviews_public view.';



CREATE MATERIALIZED VIEW "public"."mv_inspector_reputation" AS
 WITH "rated_completed_jobs" AS (
         SELECT "r"."inspector_id",
            "r"."rating",
            "j"."id" AS "job_id",
            "j"."client_price_cents",
            "j"."payout_amount_cents",
            "j"."updated_at" AS "completed_at"
           FROM ("public"."reviews" "r"
             JOIN "public"."jobs" "j" ON (("j"."id" = "r"."job_id")))
          WHERE (("j"."status" = 'completed'::"text") AND ("j"."deleted_at" IS NULL) AND ("r"."rating" IS NOT NULL) AND (COALESCE("j"."client_price_cents", (0)::bigint) > 0))
        )
 SELECT "inspector_id",
    ("count"(DISTINCT "job_id"))::integer AS "jobs_completed_count",
    ("count"(*))::integer AS "ratings_count",
    "round"("avg"("rating"), 2) AS "simple_avg_rating",
    "round"(("sum"((("rating")::numeric * ("client_price_cents")::numeric)) / NULLIF("sum"("client_price_cents"), (0)::numeric)), 2) AS "weighted_avg_rating",
    ("sum"("client_price_cents"))::bigint AS "total_revenue_handled_cents",
    (COALESCE("sum"("payout_amount_cents"), (0)::numeric))::bigint AS "total_payout_received_cents",
    "max"("completed_at") AS "last_completed_at",
    "now"() AS "refreshed_at"
   FROM "rated_completed_jobs"
  GROUP BY "inspector_id"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_inspector_reputation" OWNER TO "postgres";


