CREATE OR REPLACE FUNCTION "public"."get_marketplace_inspectors"("p_search" "text" DEFAULT NULL::"text", "p_min_rating" numeric DEFAULT NULL::numeric, "p_only_verified" boolean DEFAULT false, "p_only_available" boolean DEFAULT false, "p_location_city" "text" DEFAULT NULL::"text", "p_ndt_methods" "text"[] DEFAULT NULL::"text"[], "p_sort_by" "text" DEFAULT 'rating'::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "display_name" "text", "avatar_url" "text", "bio" "text", "is_verified" boolean, "is_available" boolean, "hourly_rate_cents" integer, "years_experience" integer, "skills" "text"[], "ndt_methods" "text"[], "certifications" "text"[], "location_city" "text", "location_province" "text", "rating_average" numeric, "rating_count" integer, "completed_jobs_count" integer, "response_time_hours" numeric, "is_featured" boolean, "availability_status" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_search_like text;
BEGIN
  IF p_search IS NOT NULL AND length(trim(p_search)) > 0 THEN
    v_search_like := '%' || trim(p_search) || '%';
  END IF;

  RETURN QUERY
  SELECT
    p.id,
    COALESCE(
      NULLIF(p.full_name, ''),
      NULLIF(
        TRIM(BOTH ' ' FROM
          COALESCE(p.first_name, '') || ' ' || COALESCE(p.last_name, '')
        ),
        ''
      ),
      'NEXPEC inspector'
    )::text AS display_name,
    p.avatar_url,
    p.bio,
    COALESCE(p.is_verified,  false),
    COALESCE(p.is_available, false),
    p.hourly_rate_cents,
    p.years_experience,
    p.skills,
    p.ndt_methods,
    p.certifications,
    p.location_city,
    p.location_province,
    COALESCE(p.rating_average, 0)::numeric,
    COALESCE(p.rating_count,   0)::integer,
    COALESCE(p.completed_jobs_count, 0)::integer,
    p.response_time_hours,
    COALESCE(p.is_featured, false),
    p.availability_status
  FROM public.profiles p
  WHERE p.role = 'inspector'
    AND COALESCE(p.is_active, false) = true
    AND (NOT p_only_verified  OR COALESCE(p.is_verified,  false) = true)
    AND (NOT p_only_available OR COALESCE(p.is_available, false) = true)
    AND (p_min_rating  IS NULL OR COALESCE(p.rating_average, 0) >= p_min_rating)
    AND (
      p_location_city IS NULL
      OR p.location_city ILIKE '%' || p_location_city || '%'
    )
    AND (
      p_ndt_methods IS NULL
      OR p.ndt_methods @> p_ndt_methods
    )
    AND (
      v_search_like IS NULL
      OR p.first_name ILIKE v_search_like
      OR p.last_name  ILIKE v_search_like
      OR p.bio        ILIKE v_search_like
      OR (p.skills IS NOT NULL AND p.skills && ARRAY[trim(p_search)]::text[])
    )
  ORDER BY
    CASE WHEN p_sort_by = 'rating'      THEN p.rating_average        END DESC NULLS LAST,
    CASE WHEN p_sort_by = 'reviews'     THEN p.rating_count          END DESC NULLS LAST,
    CASE WHEN p_sort_by = 'experience'  THEN p.years_experience      END DESC NULLS LAST,
    CASE WHEN p_sort_by = 'jobs'        THEN p.completed_jobs_count  END DESC NULLS LAST,
    CASE WHEN p_sort_by = 'price_low'   THEN p.hourly_rate_cents     END ASC  NULLS LAST,
    CASE WHEN p_sort_by = 'price_high'  THEN p.hourly_rate_cents     END DESC NULLS LAST,
    p.id                                          -- deterministic tiebreaker
  LIMIT GREATEST(p_limit, 1)
  OFFSET GREATEST(p_offset, 0);
END;
$$;


ALTER FUNCTION "public"."get_marketplace_inspectors"("p_search" "text", "p_min_rating" numeric, "p_only_verified" boolean, "p_only_available" boolean, "p_location_city" "text", "p_ndt_methods" "text"[], "p_sort_by" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_marketplace_inspectors"("p_search" "text", "p_min_rating" numeric, "p_only_verified" boolean, "p_only_available" boolean, "p_location_city" "text", "p_ndt_methods" "text"[], "p_sort_by" "text", "p_limit" integer, "p_offset" integer) IS 'NX-AUTH-002 Step 2: paginated/filterable inspector marketplace projection. role=inspector AND is_active=true are non-overridable. Sort options: rating | reviews | experience | jobs | price_low | price_high.';



CREATE OR REPLACE FUNCTION "public"."get_monthly_breakdown"("p_inspector_id" "uuid") RETURNS TABLE("gross_halalas" bigint, "platform_fee_halalas" bigint, "net_halalas" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  select
    coalesce(sum(gross_amount_halalas),   0)::bigint,
    coalesce(sum(platform_fee_halalas),   0)::bigint,
    coalesce(sum(net_amount_halalas),     0)::bigint
  from public.transactions
  where inspector_id = p_inspector_id
    and status       = 'paid'
    and created_at  >= date_trunc('month', now());
$$;


