CREATE OR REPLACE FUNCTION "public"."get_my_application_quota"() RETURNS TABLE("used_today" integer, "daily_limit" integer, "remaining" integer, "resets_at" timestamp with time zone)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'auth'
    AS $$
  WITH effective AS (
    SELECT COALESCE(daily_application_limit, public._default_daily_application_limit()) AS lim
    FROM public.profiles
    WHERE id = auth.uid()
  ),
  used AS (
    SELECT count(*)::int AS n
    FROM public.applications
    WHERE applicant_id = auth.uid()
      AND created_at > now() - interval '24 hours'
  )
  SELECT
    used.n                                  AS used_today,
    effective.lim                            AS daily_limit,
    GREATEST(effective.lim - used.n, 0)      AS remaining,
    (SELECT min(created_at) + interval '24 hours'
       FROM public.applications
      WHERE applicant_id = auth.uid()
        AND created_at > now() - interval '24 hours') AS resets_at
  FROM effective, used;
$$;


ALTER FUNCTION "public"."get_my_application_quota"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_or_create_wallet"("p_user_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_wallet_id UUID;
BEGIN
  -- Try to get existing wallet
  SELECT id INTO v_wallet_id
  FROM public.wallets
  WHERE user_id = p_user_id;
  
  -- Create if not exists
  IF v_wallet_id IS NULL THEN
    INSERT INTO public.wallets (user_id, balance, frozen_balance, total_earned)
    VALUES (p_user_id, 0, 0, 0)
    RETURNING id INTO v_wallet_id;
  END IF;
  
  RETURN v_wallet_id;
END;
$$;


ALTER FUNCTION "public"."get_or_create_wallet"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_organization_members"("p_org_id" "uuid") RETURNS TABLE("id" "uuid", "organization_id" "uuid", "full_name" "text", "role" "text", "status" "text", "avatar_url" "text", "phone" "text", "email" "text", "last_active" timestamp with time zone, "current_project" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    p.id,
    p.organization_id,
    COALESCE(
      NULLIF(p.full_name, ''),
      NULLIF(
        TRIM(BOTH ' ' FROM
          COALESCE(p.first_name, '') || ' ' || COALESCE(p.last_name, '')
        ),
        ''
      ),
      'NEXPEC user'
    ) AS full_name,
    p.role,
    p.status,
    p.avatar_url,
    p.phone,
    p.email,
    p.last_active,
    p.current_project
  FROM public.profiles p
  WHERE p.organization_id = p_org_id
    AND p_org_id IS NOT NULL
    AND (
      public.nx_is_admin()
      OR EXISTS (
        SELECT 1
          FROM public.profiles me
         WHERE me.id = auth.uid()
           AND me.organization_id = p_org_id
      )
    )
  ORDER BY COALESCE(p.full_name, p.first_name, '') ASC;
$$;


ALTER FUNCTION "public"."get_organization_members"("p_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_organization_members"("p_org_id" "uuid") IS 'NX-AUTH-002 Step 2: intra-org roster read. Caller must be a member of the same organization OR an admin. Enforces the tenancy boundary: a member of org A cannot enumerate org B''s roster by guessing its uuid.';



CREATE OR REPLACE FUNCTION "public"."get_overdue_reports"() RETURNS TABLE("job_id" "uuid", "title" "text", "inspector_id" "uuid", "scheduled_date" timestamp with time zone, "hours_overdue" numeric, "max_stage" smallint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT public.nx_is_admin() THEN RAISE EXCEPTION 'not authorized' USING errcode = '42501'; END IF;
  RETURN QUERY
    SELECT jb.id, jb.title, jb.contractor_id, jb.scheduled_date,
           round((EXTRACT(EPOCH FROM (now() - jb.scheduled_date)) / 3600.0)::numeric, 1),
           (SELECT max(r.stage) FROM public.report_reminders r WHERE r.job_id = jb.id)
      FROM public.jobs jb
     WHERE jb.status IN ('assigned', 'in_progress')
       AND jb.contractor_id IS NOT NULL
       AND jb.scheduled_date IS NOT NULL
       AND jb.scheduled_date < now()
       AND NOT EXISTS (SELECT 1 FROM public.pi_report_seals s WHERE s.job_id = jb.id)
     ORDER BY jb.scheduled_date ASC;
END $$;


ALTER FUNCTION "public"."get_overdue_reports"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_project_dispute_stats"("p_project_id" "uuid") RETURNS TABLE("total_disputes" integer, "open_disputes" integer, "resolved_disputes" integer, "avg_resolution_time" interval)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        COUNT(*)::INTEGER as total_disputes,
        COUNT(*) FILTER (WHERE status = 'open')::INTEGER as open_disputes,
        COUNT(*) FILTER (WHERE status = 'resolved')::INTEGER as resolved_disputes,
        AVG(resolved_at - created_at) FILTER (WHERE resolved_at IS NOT NULL) as avg_resolution_time
    FROM public.disputes
    WHERE project_id = p_project_id;
END;
$$;


