CREATE OR REPLACE FUNCTION "public"."get_public_profile"("p_uid" "uuid") RETURNS TABLE("id" "uuid", "role" "text", "display_name" "text", "avatar_url" "text", "rating_average" numeric, "rating_count" integer, "is_verified" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT
    p.id,
    p.role,
    COALESCE(
      NULLIF(p.full_name, ''),
      NULLIF(
        TRIM(BOTH ' ' FROM
          COALESCE(p.first_name, '') || ' ' || COALESCE(p.last_name, '')
        ),
        ''
      ),
      'NEXPEC user'
    ) AS display_name,
    p.avatar_url,
    COALESCE(p.rating_average, 0)::numeric AS rating_average,
    COALESCE(p.rating_count,   0)::integer AS rating_count,
    COALESCE(p.is_verified,    false)      AS is_verified
  FROM public.profiles p
  WHERE p.id = p_uid
  LIMIT 1;
$$;


