CREATE OR REPLACE FUNCTION "public"."get_spending_dashboard"("p_project_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
    v_utilization   JSON;
    v_burn_rate     JSON;
    v_avg_monthly   NUMERIC(15,2);
    v_months_remaining NUMERIC(5,1);
BEGIN
    SELECT json_agg(row_to_json(u)) INTO v_utilization FROM public.get_utilization(p_project_id) u;
    SELECT json_agg(row_to_json(b)) INTO v_burn_rate FROM public.get_burn_rate(p_project_id, 12) b;
    SELECT COALESCE(AVG(total_paid), 0)::NUMERIC(15,2) INTO v_avg_monthly FROM public.get_burn_rate(p_project_id, 6);
    
    SELECT CASE WHEN v_avg_monthly > 0 THEN ROUND((proj.total_budget - COALESCE((SELECT SUM(amount) FROM public.payments WHERE project_id = p_project_id AND status = 'completed'), 0)) / v_avg_monthly, 1) ELSE NULL END
    INTO v_months_remaining FROM public.projects proj WHERE proj.id = p_project_id;

    RETURN json_build_object(
        'utilization',       v_utilization -> 0,
        'burn_rate',         COALESCE(v_burn_rate, '[]'::JSON),
        'avg_monthly_burn',  v_avg_monthly,
        'months_remaining',  v_months_remaining,
        'generated_at',      NOW()
    );
END;
$$;


