CREATE OR REPLACE FUNCTION "public"."get_template_for_job"("p_job_id" "uuid") RETURNS "public"."report_templates"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_job public.jobs%ROWTYPE;
  v_tpl public.report_templates%ROWTYPE;
BEGIN
  SELECT * INTO v_job FROM public.jobs WHERE id = p_job_id;
  IF NOT FOUND OR v_job.deleted_at IS NOT NULL THEN
    RETURN NULL;
  END IF;

  -- 1. Explicit assignment
  IF v_job.report_template_id IS NOT NULL THEN
    SELECT * INTO v_tpl FROM public.report_templates
     WHERE id = v_job.report_template_id
       AND deleted_at IS NULL
       AND is_active = true;
    IF FOUND THEN RETURN v_tpl; END IF;
  END IF;

  -- 2. Agency default
  IF v_job.agency_id IS NOT NULL THEN
    SELECT * INTO v_tpl FROM public.report_templates
     WHERE owner_id = v_job.agency_id
       AND scope = 'agency'
       AND is_default = true
       AND is_active = true
       AND deleted_at IS NULL
     LIMIT 1;
    IF FOUND THEN RETURN v_tpl; END IF;
  END IF;

  -- 3. Client default
  IF v_job.client_id IS NOT NULL THEN
    SELECT * INTO v_tpl FROM public.report_templates
     WHERE owner_id = v_job.client_id
       AND scope = 'client'
       AND is_default = true
       AND is_active = true
       AND deleted_at IS NULL
     LIMIT 1;
    IF FOUND THEN RETURN v_tpl; END IF;
  END IF;

  -- 4. None found — frontend uses built-in default
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."get_template_for_job"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_top_inspectors"("p_limit" integer DEFAULT 50, "p_min_jobs" integer DEFAULT 3, "p_min_rating" numeric DEFAULT 0) RETURNS SETOF "public"."mv_inspector_reputation"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT *
  FROM public.mv_inspector_reputation
  WHERE jobs_completed_count >= p_min_jobs
    AND COALESCE(weighted_avg_rating, 0) >= p_min_rating
  ORDER BY weighted_avg_rating DESC NULLS LAST,
           jobs_completed_count DESC
  LIMIT p_limit;
$$;


