CREATE OR REPLACE FUNCTION "public"."get_user_earnings"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_total DECIMAL := 0;
    v_balance DECIMAL := 0;
    v_pending DECIMAL := 0;
BEGIN
    -- Get total earnings
    SELECT COALESCE(SUM(amount), 0) INTO v_total 
    FROM transactions 
    WHERE user_id = p_user_id AND type = 'payment';

    -- Get current wallet balance
    SELECT COALESCE(balance, 0) INTO v_balance 
    FROM profiles 
    WHERE id = p_user_id;

    -- Get pending earnings from jobs under review
    SELECT COALESCE(SUM(price), 0) INTO v_pending 
    FROM jobs 
    WHERE contractor_id = p_user_id AND status IN ('under_review', 'senior_review');

    RETURN jsonb_build_object(
      'total_earnings', v_total, 
      'current_balance', v_balance, 
      'pending_earnings', v_pending
    );
END;
$$;


ALTER FUNCTION "public"."get_user_earnings"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_utilization"("p_project_id" "uuid") RETURNS TABLE("total_budget" numeric, "total_paid" numeric, "total_pending" numeric, "utilization_pct" numeric, "remaining_budget" numeric, "milestones_total" bigint, "milestones_paid" bigint, "milestones_pending" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
    SELECT
        proj.total_budget,
        COALESCE(pay_agg.total_paid, 0)::NUMERIC(15,2),
        COALESCE(ms_agg.pending_amount, 0)::NUMERIC(15,2),
        CASE
            WHEN proj.total_budget > 0
            THEN ROUND((COALESCE(pay_agg.total_paid, 0) / proj.total_budget) * 100, 2)
            ELSE 0
        END::NUMERIC(5,2),
        (proj.total_budget - COALESCE(pay_agg.total_paid, 0))::NUMERIC(15,2),
        COALESCE(ms_agg.total_count, 0),
        COALESCE(ms_agg.paid_count, 0),
        COALESCE(ms_agg.pending_count, 0)
    FROM public.projects proj
    LEFT JOIN LATERAL (
        SELECT SUM(p.amount) AS total_paid
        FROM public.payments p
        WHERE p.project_id = proj.id AND p.status = 'completed'
    ) pay_agg ON true
    LEFT JOIN LATERAL (
        SELECT
            COUNT(*)                                                  AS total_count,
            COUNT(*) FILTER (WHERE m.status = 'paid')                AS paid_count,
            COUNT(*) FILTER (WHERE m.status IN ('pending','in_progress','review','approved'))
                                                                     AS pending_count,
            COALESCE(SUM(m.amount) FILTER (WHERE m.status = 'approved'), 0)
                                                                     AS pending_amount
        FROM public.milestones m
        WHERE m.project_id = proj.id AND m.status != 'cancelled' -- <--- Fixed
    ) ms_agg ON true
    WHERE proj.id = p_project_id;
$$;


ALTER FUNCTION "public"."get_utilization"("p_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_weekly_earnings"("p_inspector_id" "uuid") RETURNS TABLE("day" "date", "net_halalas" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  with week_days as (
    select generate_series(
      date_trunc('week', now() at time zone 'Asia/Riyadh')::date,
      (date_trunc('week', now() at time zone 'Asia/Riyadh') + interval '6 days')::date,
      '1 day'::interval
    )::date as day
  )
  select
    wd.day,
    coalesce(sum(t.net_amount_halalas), 0)::bigint as net_halalas
  from week_days wd
  left join public.transactions t
    on  date_trunc('day', t.created_at at time zone 'Asia/Riyadh')::date = wd.day
    and t.inspector_id = p_inspector_id
    and t.status       = 'paid'
  group by wd.day
  order by wd.day;
$$;


ALTER FUNCTION "public"."get_weekly_earnings"("p_inspector_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."global_search"("p_query" "text", "p_limit" integer DEFAULT 8) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_query       tsquery;
  v_role        text;
  v_user        uuid := auth.uid();
  v_inspectors  jsonb := '[]'::jsonb;
  v_jobs        jsonb := '[]'::jsonb;
  v_scopes      jsonb := '[]'::jsonb;
  v_limit       integer := least(greatest(coalesce(p_limit, 8), 1), 24);
BEGIN
  IF p_query IS NULL OR length(trim(p_query)) < 2 THEN
    RETURN jsonb_build_object('query', coalesce(p_query, ''), 'results', '[]'::jsonb);
  END IF;

  v_query := websearch_to_tsquery('english', p_query);

  IF v_user IS NOT NULL THEN
    SELECT lower(role) INTO v_role FROM public.profiles WHERE id = v_user LIMIT 1;
  END IF;

  /* ─── 1) Inspectors ─────────────────────────────────────────────── */
  SELECT coalesce(jsonb_agg(row_to_jsonb(r) ORDER BY r.score DESC), '[]'::jsonb)
    INTO v_inspectors
  FROM (
    SELECT
      'inspector'::text                                    AS kind,
      i.id::text                                            AS id,
      coalesce(i.full_name, 'Inspector')                    AS title,
      coalesce(
        nullif(i.headline, ''),
        nullif(concat_ws(', ', i.location_city, i.location_province), ''),
        'Inspector profile'
      )                                                     AS subtitle,
      '/p/' || i.id::text                                  AS href,
      ts_rank(
        setweight(to_tsvector('english', coalesce(i.full_name, '')), 'A') ||
        setweight(to_tsvector('english', coalesce(i.headline, '')), 'B') ||
        setweight(to_tsvector('english', coalesce(i.bio, '')), 'C') ||
        setweight(to_tsvector('english', array_to_string(coalesce(i.specialty_slugs, '{}'), ' ')), 'B') ||
        setweight(to_tsvector('english', coalesce(i.location_city, '')), 'C'),
        v_query
      )                                                     AS score
    FROM public.inspectors_directory i
    WHERE
      to_tsvector('english',
        coalesce(i.full_name, '') || ' ' ||
        coalesce(i.headline, '') || ' ' ||
        coalesce(i.bio, '') || ' ' ||
        array_to_string(coalesce(i.specialty_slugs, '{}'), ' ') || ' ' ||
        coalesce(i.location_city, '')
      ) @@ v_query
    ORDER BY score DESC
    LIMIT v_limit
  ) r;

  /* ─── 2) Jobs ───────────────────────────────────────────────────── */
  IF v_user IS NOT NULL THEN
    SELECT coalesce(jsonb_agg(row_to_jsonb(r) ORDER BY r.score DESC), '[]'::jsonb)
      INTO v_jobs
    FROM (
      SELECT
        'job'::text                                         AS kind,
        j.id::text                                          AS id,
        coalesce(j.title, 'Untitled job')                   AS title,
        coalesce(
          nullif(concat_ws(' · ',
            nullif(j.location_city, ''),
            nullif(j.status, ''),
            nullif(j.domain, '')
          ), ''),
          'Job'
        )                                                   AS subtitle,
        CASE
          WHEN v_role IN ('admin','super_admin','support') THEN '/admin/jobs?focus=' || j.id::text
          WHEN j.contractor_id = v_user                     THEN '/inspector/jobs/' || j.id::text
          WHEN j.client_id = v_user                          THEN '/client/jobs/' || j.id::text
          ELSE '/p/' || j.id::text
        END                                                 AS href,
        ts_rank(
          setweight(to_tsvector('english', coalesce(j.title, '')), 'A') ||
          setweight(to_tsvector('english', coalesce(j.description, '')), 'B') ||
          setweight(to_tsvector('english', array_to_string(coalesce(j.specialty_slugs, '{}'), ' ')), 'B') ||
          setweight(to_tsvector('english', coalesce(j.location_city, '')), 'C') ||
          setweight(to_tsvector('english', coalesce(j.domain, '')), 'C'),
          v_query
        )                                                   AS score
      FROM public.jobs j
      WHERE
        (
          v_role IN ('admin','super_admin','support')
          OR j.contractor_id = v_user
          OR j.client_id = v_user
        )
        AND j.deleted_at IS NULL
        AND to_tsvector('english',
          coalesce(j.title, '') || ' ' ||
          coalesce(j.description, '') || ' ' ||
          array_to_string(coalesce(j.specialty_slugs, '{}'), ' ') || ' ' ||
          coalesce(j.location_city, '') || ' ' ||
          coalesce(j.domain, '')
        ) @@ v_query
      ORDER BY score DESC
      LIMIT v_limit
    ) r;
  END IF;

  /* ─── 3) Scope templates ────────────────────────────────────────── */
  IF v_user IS NOT NULL THEN
    SELECT coalesce(jsonb_agg(row_to_jsonb(r) ORDER BY r.score DESC), '[]'::jsonb)
      INTO v_scopes
    FROM (
      SELECT
        'scope_template'::text                              AS kind,
        t.id::text                                          AS id,
        coalesce(t.name, t.slug, 'Scope template')          AS title,
        coalesce(
          nullif(concat_ws(' · ',
            nullif(t.category, ''),
            nullif(t.domain, ''),
            t.requires_credential_tier::text
          ), ''),
          'Scope template'
        )                                                   AS subtitle,
        '/admin/scope-templates#' || t.slug                 AS href,
        ts_rank(
          setweight(to_tsvector('english', coalesce(t.name, '')), 'A') ||
          setweight(to_tsvector('english', coalesce(t.description_md, '')), 'B') ||
          setweight(to_tsvector('english', coalesce(t.category, '')), 'B') ||
          setweight(to_tsvector('english', coalesce(t.slug, '')), 'C') ||
          setweight(to_tsvector('english', coalesce(t.domain, '')), 'C'),
          v_query
        )                                                   AS score
      FROM public.inspection_scope_templates t
      WHERE t.is_active = true
        AND to_tsvector('english',
          coalesce(t.name, '') || ' ' ||
          coalesce(t.description_md, '') || ' ' ||
          coalesce(t.category, '') || ' ' ||
          coalesce(t.slug, '') || ' ' ||
          coalesce(t.domain, '')
        ) @@ v_query
      ORDER BY score DESC
      LIMIT v_limit
    ) r;
  END IF;

  RETURN jsonb_build_object(
    'query', trim(p_query),
    'results', jsonb_build_object(
      'inspectors', v_inspectors,
      'jobs',       v_jobs,
      'scopes',     v_scopes
    )
  );
END;
$$;


ALTER FUNCTION "public"."global_search"("p_query" "text", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."global_search"("p_query" "text", "p_limit" integer) IS 'Permission-aware cross-entity FTS across inspectors_directory, jobs, and inspection_scope_templates. SECURITY DEFINER with viewer-role + auth.uid() gating inside. Returns top-K (default 8) per kind sorted by ts_rank score.';



CREATE OR REPLACE FUNCTION "public"."guard_jobs_status_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text;
  v_legal boolean := false;
BEGIN
  -- No-op if status is unchanged (column wasn't touched, or set to itself).
  IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;

  -- Service-role / superuser bypass. Edge Functions and the admin
  -- dispatch RPC run under postgres or service_role and are the
  -- legitimate orchestration paths.
  v_role := current_setting('role', true);
  IF v_role IN ('service_role', 'postgres') THEN
    RETURN NEW;
  END IF;

  -- Block writes that drop status to NULL.
  IF NEW.status IS NULL THEN
    RAISE EXCEPTION 'jobs.status cannot be set to NULL (was: %)', OLD.status
      USING ERRCODE = '22000', HINT = 'Use a canonical RPC.';
  END IF;

  -- Legal transition table.
  v_legal := CASE OLD.status
    WHEN 'open'        THEN NEW.status IN ('assigned', 'cancelled')
    WHEN 'assigned'    THEN NEW.status IN ('in_progress', 'cancelled', 'disputed')
    WHEN 'in_progress' THEN NEW.status IN ('completed', 'disputed', 'cancelled')
    WHEN 'disputed'    THEN NEW.status IN ('completed', 'cancelled', 'in_progress')
    WHEN 'completed'   THEN false  -- terminal
    WHEN 'cancelled'   THEN false  -- terminal
    ELSE false
  END;

  IF NOT v_legal THEN
    RAISE EXCEPTION 'Illegal jobs.status transition: % → %', OLD.status, NEW.status
      USING ERRCODE = '22000',
            HINT = 'Use a canonical state-machine RPC (admin_dispatch_job, inspector_start_job, owner_cancel_job, admin_cancel_job, mark_job_completed, or open_dispute).';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."guard_jobs_status_transition"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."guard_jobs_status_transition"() IS 'BEFORE UPDATE trigger on jobs. Refuses any status change not in the legal transition table. Service-role / postgres callers bypass for orchestration.';



CREATE OR REPLACE FUNCTION "public"."handle_inspection_report_state_machine"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- الف: وقتی گزارش ارسال می‌شود (Submitted)
  IF NEW.status = 'submitted' AND (OLD.status IS NULL OR OLD.status != 'submitted') THEN
    NEW.submitted_at := NOW();
    
    -- به روز رسانی خودکار وضعیت پروژه برای کارفرما
    UPDATE public.jobs SET status = 'review_pending' WHERE id = NEW.job_id;
  END IF;

  -- ب: وقتی کارفرما درخواست اصلاح می‌دهد (Revision Requested)
  IF NEW.status = 'revision_requested' AND OLD.status != 'revision_requested' THEN
    NEW.revision_count := COALESCE(OLD.revision_count, 0) + 1;
    NEW.last_revision_at := NOW();
    
    -- ثبت تاریخچه اصلاح در آرایه JSONB
    NEW.revision_history := COALESCE(OLD.revision_history, '[]'::jsonb) || 
      jsonb_build_object(
        'requested_at', NOW(),
        'notes', NEW.revision_notes,
        'revision_number', NEW.revision_count
      );
    
    -- بازگرداندن پروژه به حالت در جریان برای بازرس
    UPDATE public.jobs SET status = 'in_progress' WHERE id = NEW.job_id;
  END IF;

  -- ج: وقتی گزارش تایید نهایی می‌شود (Approved)
  IF NEW.status = 'approved' AND (OLD.status IS NULL OR OLD.status != 'approved') THEN
    NEW.approved_at := NOW();
    
    -- این آپدیت باعث فعال شدن تریگر Escrow Release (trigger_job_completion) می‌شود
    UPDATE public.jobs SET status = 'completed' WHERE id = NEW.job_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_inspection_report_state_machine"() OWNER TO "postgres";


