CREATE OR REPLACE FUNCTION "public"."handle_job_cancellation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_application RECORD;
  v_client_wallet_id UUID;
  v_inspector_wallet_id UUID;
  v_price NUMERIC;
BEGIN
  -- Only process when status changes TO 'cancelled'
  IF NEW.status = 'cancelled' AND (OLD.status IS NULL OR OLD.status != 'cancelled') THEN
    
    -- Only refund if escrow was locked
    IF OLD.escrow_status = 'locked' THEN
      
      v_price := NEW.price;
      
      -- Get client wallet
      v_client_wallet_id := get_or_create_wallet(NEW.client_id);
      
      -- Get accepted application
      SELECT a.applicant_id INTO v_application
      FROM public.applications a
      WHERE a.job_id = NEW.id AND a.status = 'accepted'
      LIMIT 1;
      
      IF v_application IS NOT NULL THEN
        v_inspector_wallet_id := get_or_create_wallet(v_application.applicant_id);
        
        -- Remove from inspector's frozen balance
        UPDATE public.wallets
        SET 
          frozen_balance = frozen_balance - v_price,
          updated_at = NOW()
        WHERE id = v_inspector_wallet_id;
        
        -- Cancel pending transaction for inspector
        UPDATE public.transactions
        SET status = 'cancelled'
        WHERE wallet_id = v_inspector_wallet_id 
          AND reference_id = NEW.id 
          AND type = 'escrow_lock'
          AND status = 'pending';
      END IF;
      
      -- Refund to client's balance
      UPDATE public.wallets
      SET 
        balance = balance + v_price,
        updated_at = NOW()
      WHERE id = v_client_wallet_id;
      
      -- Create refund transaction for client
      INSERT INTO public.transactions (
        wallet_id, amount, type, status, description, reference_id
      ) VALUES (
        v_client_wallet_id,
        v_price,
        'refund',
        'completed',
        'Escrow refunded for cancelled job: ' || NEW.title,
        NEW.id
      );
      
      -- Update escrow status
      NEW.escrow_status := 'refunded';
      
      -- Log refund
      INSERT INTO public.escrow_logs (
        job_id, action, to_wallet_id, amount, status, metadata
      ) VALUES (
        NEW.id, 'refund', v_client_wallet_id, v_price, 'completed',
        jsonb_build_object(
          'reason', 'job_cancelled',
          'client_id', NEW.client_id
        )
      );
      
    END IF;
    
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_job_cancellation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_job_completion"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_application RECORD;
  v_inspector_wallet_id UUID;
  v_price NUMERIC;
  v_platform_fee NUMERIC;
  v_net_amount NUMERIC;
  v_fee_percentage NUMERIC := 0.10; -- 10% platform fee
BEGIN
  -- Only process when status changes TO 'completed'
  IF NEW.status = 'completed' AND (OLD.status IS NULL OR OLD.status != 'completed') THEN
    
    -- Validate escrow is locked
    IF OLD.escrow_status != 'locked' THEN
      RAISE EXCEPTION 'Cannot complete job: Escrow not locked. Current status: %', OLD.escrow_status;
    END IF;
    
    -- Get price
    v_price := NEW.price;
    IF v_price IS NULL OR v_price <= 0 THEN
      RAISE EXCEPTION 'Invalid job price';
    END IF;
    
    -- Calculate fees
    v_platform_fee := ROUND(v_price * v_fee_percentage, 2);
    v_net_amount := v_price - v_platform_fee;
    
    -- Get accepted application with inspector info
    SELECT a.id, a.applicant_id
    INTO v_application
    FROM public.applications a
    WHERE a.job_id = NEW.id AND a.status = 'accepted'
    LIMIT 1;
    
    IF v_application IS NULL THEN
      RAISE EXCEPTION 'No accepted application found for job: %', NEW.id;
    END IF;
    
    -- Get inspector wallet
    v_inspector_wallet_id := get_or_create_wallet(v_application.applicant_id);
    
    -- Move funds from frozen to available (minus fee)
    UPDATE public.wallets
    SET 
      frozen_balance = frozen_balance - v_price,
      balance = balance + v_net_amount,
      total_earned = total_earned + v_net_amount,
      updated_at = NOW()
    WHERE id = v_inspector_wallet_id;
    
    -- Add fee to platform wallet
    UPDATE public.platform_wallet
    SET 
      balance = balance + v_platform_fee,
      total_fees_collected = total_fees_collected + v_platform_fee,
      updated_at = NOW()
    WHERE id = '00000000-0000-0000-0000-000000000001';
    
    -- Update pending escrow transaction to completed
    UPDATE public.transactions
    SET 
      status = 'completed',
      net_amount = v_net_amount,
      fee_amount = v_platform_fee
    WHERE wallet_id = v_inspector_wallet_id 
      AND reference_id = NEW.id 
      AND type = 'escrow_lock'
      AND status = 'pending';
    
    -- Create escrow release transaction
    INSERT INTO public.transactions (
      wallet_id, amount, type, status, description, 
      reference_id, net_amount, fee_amount
    ) VALUES (
      v_inspector_wallet_id,
      v_net_amount,
      'escrow_release',
      'completed',
      'Payment released for job: ' || NEW.title || ' (after 10% fee)',
      NEW.id,
      v_net_amount,
      v_platform_fee
    );
    
    -- Create fee transaction record
    INSERT INTO public.transactions (
      wallet_id, amount, type, status, description, reference_id
    ) VALUES (
      v_inspector_wallet_id,
      -v_platform_fee,
      'fee',
      'completed',
      'Platform fee (10%) for job: ' || NEW.title,
      NEW.id
    );
    
    -- Update job escrow status
    NEW.escrow_status := 'released';
    
    -- Log successful escrow release
    INSERT INTO public.escrow_logs (
      job_id, action, to_wallet_id, amount, fee_amount, status, metadata
    ) VALUES (
      NEW.id, 'release', v_inspector_wallet_id, v_net_amount, v_platform_fee, 'completed',
      jsonb_build_object(
        'gross_amount', v_price,
        'fee_percentage', v_fee_percentage * 100,
        'fee_amount', v_platform_fee,
        'net_amount', v_net_amount,
        'inspector_id', v_application.applicant_id
      )
    );
    
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_job_completion"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT;
  v_full_name TEXT;
BEGIN
  v_full_name := NULLIF(TRIM(NEW.raw_user_meta_data ->> 'full_name'), '');
  v_role := COALESCE(
    NULLIF(TRIM(NEW.raw_user_meta_data ->> 'role'), ''),
    'client'
  );

  -- Whitelist the role. Anything outside the public-signup set collapses to
  -- 'client'. super_admin / admin / enterprise are administered via admin RPCs.
  IF v_role NOT IN ('client', 'inspector', 'agency', 'supplier') THEN
    v_role := 'client';
  END IF;

  INSERT INTO public.profiles (id, email, full_name, role)
  VALUES (NEW.id, NEW.email, v_full_name, v_role)
  ON CONFLICT (id) DO UPDATE SET
    role = CASE
      WHEN public.profiles.role = 'client' AND EXCLUDED.role <> 'client'
        THEN EXCLUDED.role
      ELSE public.profiles.role
    END,
    full_name = COALESCE(public.profiles.full_name, EXCLUDED.full_name);

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."handle_new_user"() IS 'Bootstraps public.profiles from auth.users.raw_user_meta_data on signup. Whitelists role to {client, inspector, agency, supplier}.';



