CREATE OR REPLACE FUNCTION "public"."handle_report_status_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- الف: تایید و اتمام پروژه (فعال کردن آزادسازی پول در Escrow)
  IF NEW.status = 'approved' AND (OLD.status IS NULL OR OLD.status != 'approved') THEN
    NEW.approved_at := NOW();
    -- تغییر وضعیت پروژه باعث فعال شدن تریگر نهایی پرداخت می‌شود
    UPDATE public.jobs SET status = 'completed' WHERE id = NEW.job_id;
  END IF;
  
  -- ب: درخواست اصلاح توسط کارفرما
  IF NEW.status = 'revision_requested' AND (OLD.status IS NULL OR OLD.status != 'revision_requested') THEN
    NEW.revision_requested_at := NOW();
    NEW.revision_count := COALESCE(OLD.revision_count, 0) + 1;
    NEW.revision_deadline := NOW() + INTERVAL '3 days';
    
    -- ثبت جزئیات اصلاح در تاریخچه JSONB
    NEW.revision_history := COALESCE(OLD.revision_history, '[]'::jsonb) || 
      jsonb_build_object(
        'requested_at', NOW(),
        'notes', NEW.revision_notes,
        'revision_number', NEW.revision_count
      );
    
    -- بازگرداندن پروژه به حالت در جریان
    UPDATE public.jobs SET status = 'in_progress' WHERE id = NEW.job_id;
  END IF;
  
  -- ج: ارسال مجدد توسط بازرس پس از اصلاح
  IF NEW.status = 'submitted' AND OLD.status = 'revision_requested' THEN
    NEW.submitted_at := NOW();
    NEW.revision_notes := NULL;
    UPDATE public.jobs SET status = 'review_pending' WHERE id = NEW.job_id;
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_report_status_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_report_submission"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- When report is submitted, update job status
  IF NEW.status = 'submitted' AND (OLD.status IS NULL OR OLD.status != 'submitted') THEN
    NEW.submitted_at := NOW();
    
    UPDATE public.jobs
    SET status = 'review_pending'
    WHERE id = NEW.job_id;
  END IF;
  
  -- When report is approved, trigger job completion
  IF NEW.status = 'approved' AND OLD.status != 'approved' THEN
    NEW.approved_at := NOW();
    
    UPDATE public.jobs
    SET status = 'completed'
    WHERE id = NEW.job_id;
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_report_submission"() OWNER TO "postgres";


