CREATE OR REPLACE FUNCTION "public"."haversine_km"("lat1" double precision, "lng1" double precision, "lat2" double precision, "lng2" double precision) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT (
    2 * 6371 * asin(
      sqrt(
        power(sin(radians((lat2 - lat1) / 2)), 2)
        + cos(radians(lat1)) * cos(radians(lat2))
        * power(sin(radians((lng2 - lng1) / 2)), 2)
      )
    )
  )::numeric
$$;


ALTER FUNCTION "public"."haversine_km"("lat1" double precision, "lng1" double precision, "lat2" double precision, "lng2" double precision) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."haversine_km"("lat1" double precision, "lng1" double precision, "lat2" double precision, "lng2" double precision) IS 'Great-circle distance in km between two lat/lng pairs (decimal degrees). Takes double precision so it matches jobs.latitude/longitude column types; numeric(9,6) values from profiles cast up implicitly.';



CREATE OR REPLACE FUNCTION "public"."heal_contract_to_active"("p_contract_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_c   RECORD;
  v_job RECORD;
BEGIN
  SELECT * INTO v_c FROM public.job_contracts WHERE id = p_contract_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_c.status IS DISTINCT FROM 'fully_executed' THEN
    RETURN;
  END IF;
  IF v_c.voided_at IS NOT NULL THEN
    RETURN;
  END IF;

  -- ── Heal jobs.status ────────────────────────────────────────────────
  SELECT * INTO v_job FROM public.jobs WHERE id = v_c.job_id;
  IF FOUND AND v_job.status IN (
    'open', 'assigned', 'awarded', 'pending_approval',
    'pending_review', 'draft', 'review'
  ) THEN
    BEGIN
      UPDATE public.jobs SET
        status                 = 'in_progress',
        hired_inspector_id     = COALESCE(hired_inspector_id, v_c.inspector_id),
        inspector_payout_cents = COALESCE(inspector_payout_cents, v_c.inspector_payout_cents),
        payout_amount_cents    = COALESCE(payout_amount_cents,    v_c.inspector_payout_cents),
        client_price_cents     = COALESCE(client_price_cents,     v_c.client_price_cents),
        updated_at             = NOW()
      WHERE id = v_c.job_id;
    EXCEPTION WHEN OTHERS THEN
      -- Guard trigger rejected the leap → step through 'assigned' first
      BEGIN
        UPDATE public.jobs SET
          status             = 'assigned',
          hired_inspector_id = COALESCE(hired_inspector_id, v_c.inspector_id),
          updated_at         = NOW()
        WHERE id = v_c.job_id
          AND status IN ('open','awarded','pending_approval','pending_review','draft','review');

        UPDATE public.jobs SET
          status                 = 'in_progress',
          hired_inspector_id     = COALESCE(hired_inspector_id, v_c.inspector_id),
          inspector_payout_cents = COALESCE(inspector_payout_cents, v_c.inspector_payout_cents),
          payout_amount_cents    = COALESCE(payout_amount_cents,    v_c.inspector_payout_cents),
          client_price_cents     = COALESCE(client_price_cents,     v_c.client_price_cents),
          updated_at             = NOW()
        WHERE id = v_c.job_id AND status = 'assigned';
      EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'heal_contract_to_active: could not advance jobs.status for job_id=%', v_c.job_id;
      END;
    END;
  END IF;

  -- ── Heal applications.status ────────────────────────────────────────
  IF v_c.application_id IS NOT NULL THEN
    UPDATE public.applications
       SET status     = 'hired',
           hired_at   = COALESCE(hired_at, NOW()),
           updated_at = NOW()
     WHERE id = v_c.application_id
       AND status NOT IN ('hired','accepted','completed','cancelled','rejected');
  ELSE
    UPDATE public.applications
       SET status     = 'hired',
           hired_at   = COALESCE(hired_at, NOW()),
           updated_at = NOW()
     WHERE job_id       = v_c.job_id
       AND applicant_id = v_c.inspector_id
       AND status NOT IN ('hired','accepted','completed','cancelled','rejected');
  END IF;
END
$$;


ALTER FUNCTION "public"."heal_contract_to_active"("p_contract_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."heal_contract_to_active"("p_contract_id" "uuid") IS 'Idempotent reconciliation: given a fully_executed contract id, ensures jobs.status >= in_progress and applications.status >= hired.';



CREATE OR REPLACE FUNCTION "public"."hydrate_identity"("p_provider" "text", "p_claims" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid    uuid := auth.uid();
  v_sub    text := coalesce(p_claims->>'sub', p_claims->>'provider_id', p_claims->>'id');
  v_name   text := coalesce(nullif(p_claims->>'name',''),
                            nullif(trim(coalesce(p_claims->>'given_name','') || ' ' || coalesce(p_claims->>'family_name','')),''));
  v_avatar text := coalesce(p_claims->>'picture', p_claims->>'avatar_url');
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_authenticated'); END IF;
  IF coalesce(p_provider,'') = '' THEN RETURN jsonb_build_object('ok', false, 'error', 'provider_required'); END IF;

  -- Fill ONLY blanks on the caller's own profile. Never overwrite user edits;
  -- never derive role/privileges from untrusted claims.
  UPDATE public.profiles p SET
    full_name  = CASE WHEN coalesce(p.full_name,'')  = '' THEN v_name   ELSE p.full_name  END,
    avatar_url = CASE WHEN coalesce(p.avatar_url,'') = '' THEN v_avatar ELSE p.avatar_url END
  WHERE p.id = v_uid;

  -- Record the identity link idempotently. The WHERE on the conflict path means
  -- a link already owned by ANOTHER user can never be hijacked/re-pointed.
  IF v_sub IS NOT NULL THEN
    INSERT INTO public.identity_links (provider, subject, actor_id, claims)
    VALUES (p_provider, v_sub, v_uid, coalesce(p_claims,'{}'))
    ON CONFLICT (provider, subject) DO UPDATE
      SET claims = EXCLUDED.claims, updated_at = now()
      WHERE public.identity_links.actor_id = v_uid;
  END IF;

  RETURN jsonb_build_object('ok', true, 'linked', v_sub IS NOT NULL);
END $$;


ALTER FUNCTION "public"."hydrate_identity"("p_provider" "text", "p_claims" "jsonb") OWNER TO "postgres";


