CREATE OR REPLACE FUNCTION "public"."inspector_integrity_analytics"("p_window_days" integer DEFAULT 90) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid         uuid    := auth.uid();
  v_is_admin    boolean := false;
  v_scope_all   boolean := false;
  v_window_days integer := GREATEST(1, LEAST(COALESCE(p_window_days, 90), 730));
  v_window_lo   timestamptz;
  v_result      jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.profiles
     WHERE id = v_uid AND role IN ('admin', 'super_admin')
  ) INTO v_is_admin;
  v_scope_all := v_is_admin;
  v_window_lo := now() - make_interval(days => v_window_days);

  WITH seal_base AS (
    SELECT s.inspector_id, s.job_id, s.captures_count, s.items_count,
           s.chain_verified, COALESCE(s.ai_count, 0) AS ai_count, s.inspector_sealed_at
      FROM public.pi_report_seals s
     WHERE s.inspector_sealed_at >= v_window_lo
  ),
  first_capture AS (
    SELECT c.job_id, min(c.captured_at) AS first_capture_at
      FROM public.inspection_captures c
     WHERE c.job_id IN (SELECT DISTINCT job_id FROM seal_base)
     GROUP BY c.job_id
  ),
  per_seal AS (
    SELECT sb.*,
           CASE WHEN fc.first_capture_at IS NOT NULL
                THEN EXTRACT(EPOCH FROM (sb.inspector_sealed_at - fc.first_capture_at)) / 3600.0
                ELSE NULL END AS turnaround_hours
      FROM seal_base sb
      LEFT JOIN first_capture fc ON fc.job_id = sb.job_id
  ),
  disputes_by AS (
    SELECT j.contractor_id AS inspector_id, count(DISTINCT d.id) AS disputes
      FROM public.disputes d
      JOIN public.jobs j ON j.id = d.job_id
     WHERE j.contractor_id IS NOT NULL
       AND d.job_id IN (SELECT DISTINCT job_id FROM seal_base)
     GROUP BY j.contractor_id
  ),
  revisions_by AS (
    SELECT j.contractor_id AS inspector_id, count(*) AS revisions
      FROM public.audit_events a
      JOIN public.jobs j ON j.id = a.job_id
     WHERE a.event_type = 'job.client_requested_revision'
       AND j.contractor_id IS NOT NULL
       AND a.job_id IN (SELECT DISTINCT job_id FROM seal_base)
     GROUP BY j.contractor_id
  ),
  per_inspector AS (
    SELECT ps.inspector_id,
           count(*)                                      AS seals,
           count(DISTINCT ps.job_id)                     AS jobs_sealed,
           count(*) FILTER (WHERE NOT ps.chain_verified) AS chain_breaks,
           round(avg(ps.captures_count), 2)              AS avg_captures,
           round(avg(ps.items_count), 2)                 AS avg_items,
           count(*) FILTER (WHERE ps.ai_count > 0)       AS ai_seals,
           COALESCE(sum(ps.ai_count), 0)                 AS ai_findings,
           round(avg(ps.turnaround_hours), 2)            AS avg_turnaround_hours,
           min(ps.inspector_sealed_at)                   AS first_seal_at,
           max(ps.inspector_sealed_at)                   AS last_seal_at
      FROM per_seal ps
     GROUP BY ps.inspector_id
  ),
  enriched AS (
    SELECT pin.*,
           round(pin.chain_breaks::numeric / NULLIF(pin.seals, 0), 4) AS chain_break_rate,
           COALESCE(db.disputes, 0)  AS disputes,
           COALESCE(rb.revisions, 0) AS revisions
      FROM per_inspector pin
      LEFT JOIN disputes_by  db ON db.inspector_id = pin.inspector_id
      LEFT JOIN revisions_by rb ON rb.inspector_id = pin.inspector_id
  )
  SELECT jsonb_build_object(
    'ok',           true,
    'scope',        CASE WHEN v_scope_all THEN 'platform' ELSE 'self' END,
    'window_days',  v_window_days,
    'generated_at', now(),

    'summary', (
      SELECT jsonb_build_object(
        'inspectors',            count(DISTINCT ps.inspector_id),
        'seals',                 count(*),
        'jobs_sealed',           count(DISTINCT ps.job_id),
        'chain_breaks',          count(*) FILTER (WHERE NOT ps.chain_verified),
        'chain_break_rate',      round(count(*) FILTER (WHERE NOT ps.chain_verified)::numeric / NULLIF(count(*), 0), 4),
        'avg_captures_per_seal', round(avg(ps.captures_count), 2),
        'avg_items_per_seal',    round(avg(ps.items_count), 2),
        'avg_turnaround_hours',  round(avg(ps.turnaround_hours), 2),
        'ai_seals',              count(*) FILTER (WHERE ps.ai_count > 0),
        'ai_findings',           COALESCE(sum(ps.ai_count), 0),
        'disputes',  (SELECT COALESCE(sum(disputes), 0)  FROM enriched e WHERE v_scope_all OR e.inspector_id = v_uid),
        'revisions', (SELECT COALESCE(sum(revisions), 0) FROM enriched e WHERE v_scope_all OR e.inspector_id = v_uid)
      )
      FROM per_seal ps
      WHERE v_scope_all OR ps.inspector_id = v_uid
    ),

    -- Anonymous cohort baseline over ALL inspectors (the z-score reference).
    'cohort', (
      SELECT jsonb_build_object(
        'inspectors',              count(*),
        'avg_captures_mean',       round(avg(avg_captures), 2),
        'avg_captures_stddev',     round(COALESCE(stddev_samp(avg_captures), 0), 2),
        'chain_break_rate_mean',   round(avg(chain_break_rate), 4),
        'chain_break_rate_stddev', round(COALESCE(stddev_samp(chain_break_rate), 0), 4),
        'turnaround_hours_mean',   round(avg(avg_turnaround_hours), 2),
        'turnaround_hours_stddev', round(COALESCE(stddev_samp(avg_turnaround_hours), 0), 2)
      )
      FROM enriched
    ),

    'inspectors', (
      SELECT COALESCE(jsonb_agg(
               jsonb_build_object(
                 'inspector_id',          e.inspector_id,
                 'inspector_label',       COALESCE(NULLIF(TRIM(p.full_name), ''), p.email, 'Unknown'),
                 'seals',                 e.seals,
                 'jobs_sealed',           e.jobs_sealed,
                 'chain_breaks',          e.chain_breaks,
                 'chain_break_rate',      e.chain_break_rate,
                 'avg_captures_per_seal', e.avg_captures,
                 'avg_items_per_seal',    e.avg_items,
                 'ai_seals',              e.ai_seals,
                 'ai_findings',           e.ai_findings,
                 'avg_turnaround_hours',  e.avg_turnaround_hours,
                 'disputes',              e.disputes,
                 'revisions',             e.revisions,
                 'first_seal_at',         e.first_seal_at,
                 'last_seal_at',          e.last_seal_at,
                 'risk_flags',
                   (CASE WHEN e.chain_breaks > 0                       THEN '["chain_breaks"]'::jsonb     ELSE '[]'::jsonb END)
                || (CASE WHEN e.disputes > 0                          THEN '["has_disputes"]'::jsonb     ELSE '[]'::jsonb END)
                || (CASE WHEN e.revisions > 0                         THEN '["client_revisions"]'::jsonb ELSE '[]'::jsonb END)
                || (CASE WHEN e.seals >= 3 AND e.avg_captures < 2     THEN '["low_evidence"]'::jsonb     ELSE '[]'::jsonb END)
               )
               ORDER BY e.chain_breaks DESC, e.disputes DESC, e.seals DESC
             ), '[]'::jsonb)
        FROM enriched e
        JOIN public.profiles p ON p.id = e.inspector_id
       WHERE v_scope_all OR e.inspector_id = v_uid
    ),

    'timeseries', (
      SELECT COALESCE(jsonb_agg(t ORDER BY (t->>'week')), '[]'::jsonb)
      FROM (
        SELECT jsonb_build_object(
                 'week',         to_char(date_trunc('week', ps.inspector_sealed_at), 'YYYY-MM-DD'),
                 'seals',        count(*),
                 'chain_breaks', count(*) FILTER (WHERE NOT ps.chain_verified),
                 'ai_findings',  COALESCE(sum(ps.ai_count), 0)
               ) AS t
          FROM per_seal ps
         WHERE v_scope_all OR ps.inspector_id = v_uid
         GROUP BY date_trunc('week', ps.inspector_sealed_at)
      ) weekly
    )
  )
  INTO v_result;

  RETURN COALESCE(
    v_result,
    jsonb_build_object(
      'ok', true,
      'scope', CASE WHEN v_scope_all THEN 'platform' ELSE 'self' END,
      'window_days', v_window_days,
      'generated_at', now(),
      'summary', '{}'::jsonb, 'cohort', '{}'::jsonb,
      'inspectors', '[]'::jsonb, 'timeseries', '[]'::jsonb
    )
  );
END;
$$;


ALTER FUNCTION "public"."inspector_integrity_analytics"("p_window_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."inspector_integrity_analytics"("p_window_days" integer) IS 'Predictive-Integrity (P2.1): per-inspector seal-history metrics + anonymous cohort baselines. Admin → platform scope; others → own row only. Read-only, SECURITY DEFINER, fail-closed.';



CREATE OR REPLACE FUNCTION "public"."inspector_respond_to_counter"("p_application_id" "uuid", "p_decision" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_app RECORD;
  v_uid uuid := auth.uid();
BEGIN
  IF p_decision NOT IN ('accepted','rejected') THEN
    RAISE EXCEPTION 'decision must be accepted or rejected';
  END IF;

  SELECT * INTO v_app FROM public.applications WHERE id = p_application_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'application not found';
  END IF;
  IF v_app.applicant_id <> v_uid THEN
    RAISE EXCEPTION 'only the applicant can decide on the counter';
  END IF;
  IF v_app.negotiation_status <> 'admin_countered' THEN
    RAISE EXCEPTION 'no outstanding counter offer';
  END IF;

  UPDATE public.applications SET
    inspector_decision      = p_decision,
    inspector_decision_note = p_note,
    inspector_decision_at   = NOW(),
    negotiation_status      = CASE
                                WHEN p_decision = 'accepted' THEN 'counter_accepted'
                                ELSE 'counter_rejected'
                              END,
    -- On acceptance, copy the counter into bid_amount_cents so the rest of
    -- the platform (dispatch table, payouts) sees a single canonical price.
    bid_amount_cents = CASE
                         WHEN p_decision = 'accepted' THEN admin_counter_cents
                         ELSE bid_amount_cents
                       END
  WHERE id = p_application_id
  RETURNING * INTO v_app;

  -- Notify the admins
  BEGIN
    PERFORM public.notify_admins(
      'application_status',
      CASE p_decision
        WHEN 'accepted' THEN 'Inspector accepted your counter'
        ELSE 'Inspector rejected your counter'
      END,
      COALESCE(p_note, 'Open the job to continue the negotiation.'),
      '/admin/jobs?inspect=' || v_app.job_id::text,
      v_app.job_id
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'notify_admins failed: %', SQLERRM;
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'application_id', v_app.id,
    'negotiation_status', v_app.negotiation_status
  );
END $$;


ALTER FUNCTION "public"."inspector_respond_to_counter"("p_application_id" "uuid", "p_decision" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."inspector_sign_job_contract"("p_contract_id" "uuid", "p_typed_name" "text", "p_ip" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_c RECORD;
BEGIN
  SELECT * INTO v_c FROM public.job_contracts WHERE id = p_contract_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'contract not found'; END IF;
  IF v_c.inspector_id <> auth.uid() THEN
    RAISE EXCEPTION 'only the assigned inspector can sign';
  END IF;
  IF v_c.status <> 'pending_inspector_signature' THEN
    RAISE EXCEPTION 'contract not awaiting inspector signature (status=%)', v_c.status;
  END IF;
  IF p_typed_name IS NULL OR length(trim(p_typed_name)) < 2 THEN
    RAISE EXCEPTION 'type your full legal name to sign';
  END IF;

  UPDATE public.job_contracts SET
    inspector_signed_at   = NOW(),
    inspector_signed_name = trim(p_typed_name),
    inspector_signed_ip   = p_ip,
    status                = 'fully_executed'
  WHERE id = p_contract_id;

  -- DEFENSIVE TWO-STEP TRANSITION:
  --   1. If somehow the client-sign step left jobs.status='open' (e.g. the
  --      contract was retroactively signed before this migration), promote
  --      to 'assigned' first.
  --   2. Then promote 'assigned' → 'in_progress'.
  -- Each UPDATE is gated by the current status so the guard trigger sees
  -- a legal hop every time.
  UPDATE public.jobs SET
    status             = 'assigned',
    hired_inspector_id = v_c.inspector_id,
    updated_at         = NOW()
  WHERE id = v_c.job_id AND status = 'open';

  UPDATE public.jobs SET
    status                 = 'in_progress',
    hired_inspector_id     = v_c.inspector_id,
    inspector_payout_cents = v_c.inspector_payout_cents,
    payout_amount_cents    = v_c.inspector_payout_cents,
    client_price_cents     = v_c.client_price_cents,
    updated_at             = NOW()
  WHERE id = v_c.job_id AND status = 'assigned';

  -- Notify everyone
  BEGIN
    PERFORM public.create_system_notification(
      v_c.client_id, 'Contract fully executed',
      'Inspector signed. Job is now in progress.',
      'contract_assigned',
      '/client/jobs/' || v_c.job_id::text, v_c.job_id);
    PERFORM public.create_system_notification(
      v_c.inspector_id, 'Job confirmed',
      'You signed the contract. Job is now in progress on your dashboard.',
      'assignment',
      '/inspector/jobs/' || v_c.job_id::text, v_c.job_id);
    PERFORM public.create_admin_notification(
      'Contract fully executed',
      'Both parties signed. Job moved to in_progress.',
      'contract_assigned',
      '/admin/jobs?inspect=' || v_c.job_id::text, v_c.job_id);
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object('ok', true, 'status', 'fully_executed');
END $$;


ALTER FUNCTION "public"."inspector_sign_job_contract"("p_contract_id" "uuid", "p_typed_name" "text", "p_ip" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."inspector_start_job"("p_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor       uuid;
  v_actor_role  text;
  v_job         public.jobs%ROWTYPE;
  v_correlation uuid := gen_random_uuid();
BEGIN
  -- ── 1. Auth ────────────────────────────────────────────────────────
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT role INTO v_actor_role
  FROM public.profiles
  WHERE id = v_actor;

  IF v_actor_role NOT IN ('inspector', 'contractor', 'super_admin') THEN
    RAISE EXCEPTION 'Only the assigned inspector can start a job' USING ERRCODE = '42501';
  END IF;

  -- ── 2. Input validation ───────────────────────────────────────────
  IF p_job_id IS NULL THEN
    RAISE EXCEPTION 'job_id is required' USING ERRCODE = '22000';
  END IF;

  -- ── 3. Audit annotation ───────────────────────────────────────────
  PERFORM public.audit_set_correlation(v_correlation);
  PERFORM public.audit_set_intent('Inspector started job');

  -- ── 4. Lock + validate ────────────────────────────────────────────
  SELECT * INTO v_job FROM public.jobs WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Job not found' USING ERRCODE = 'P0002';
  END IF;

  -- Self-auth: only the assigned contractor (or super_admin) may start.
  IF v_actor_role <> 'super_admin' AND v_job.contractor_id IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'You are not the assigned inspector for this job' USING ERRCODE = '42501';
  END IF;

  IF v_job.status <> 'assigned' THEN
    RAISE EXCEPTION 'Job is not in assigned state (current: %)', v_job.status
      USING ERRCODE = '22000',
            HINT = 'A job must be dispatched before it can be started.';
  END IF;

  -- ── 5. Flip status ────────────────────────────────────────────────
  UPDATE public.jobs
  SET status     = 'in_progress',
      started_at = COALESCE(started_at, now()),
      updated_at = now()
  WHERE id = p_job_id;

  RETURN jsonb_build_object(
    'ok',             true,
    'job_id',         p_job_id,
    'from_status',    v_job.status,
    'to_status',      'in_progress',
    'correlation_id', v_correlation
  );
END;
$$;


ALTER FUNCTION "public"."inspector_start_job"("p_job_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."inspector_start_job"("p_job_id" "uuid") IS 'Canonical assigned → in_progress transition. Caller must be the jobs.contractor_id (or super_admin). FOR UPDATE locks the row to prevent races. Audit-annotated.';



CREATE OR REPLACE FUNCTION "public"."inspectors_near_job"("p_job_id" "uuid", "p_max_km" numeric DEFAULT 100, "p_limit" integer DEFAULT 50) RETURNS TABLE("inspector_id" "uuid", "full_name" "text", "avatar_url" "text", "rating" numeric, "rating_count" integer, "completed_jobs_count" integer, "hourly_rate_cents" bigint, "is_verified" boolean, "is_available" boolean, "location_city" "text", "location_province" "text", "distance_km" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH job_loc AS (
    SELECT geog
    FROM public.jobs
    WHERE id = p_job_id
      AND deleted_at IS NULL
      AND geog IS NOT NULL
  )
  SELECT
    p.id                                AS inspector_id,
    p.full_name,
    p.avatar_url,
    COALESCE(p.rating_average, 0)       AS rating,
    COALESCE(p.rating_count, 0)         AS rating_count,
    COALESCE(p.completed_jobs_count, 0) AS completed_jobs_count,
    p.hourly_rate_cents,
    COALESCE(p.is_verified, false)      AS is_verified,
    COALESCE(p.is_available, false)     AS is_available,
    p.location_city,
    p.location_province,
    ROUND((ST_Distance(p.geog, j.geog) / 1000.0)::numeric, 2) AS distance_km
  FROM public.profiles p
  CROSS JOIN job_loc j
  WHERE p.role = 'inspector'
    AND COALESCE(p.is_available, false) = true
    AND p.geog IS NOT NULL
    AND ST_DWithin(p.geog, j.geog, p_max_km * 1000)
  ORDER BY p.geog <-> j.geog        -- KNN-friendly, uses GIST
  LIMIT p_limit;
$$;


ALTER FUNCTION "public"."inspectors_near_job"("p_job_id" "uuid", "p_max_km" numeric, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."invite_inspector_to_job"("p_job_id" "uuid", "p_inspector_id" "uuid", "p_message" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid          uuid := auth.uid();
  v_job          RECORD;
  v_inspector    RECORD;
  v_recent       timestamptz;
  v_event_id     uuid;
  v_buyer_label  text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'invite_inspector_to_job: not authenticated';
  END IF;

  SELECT id, client_id, agency_id, title, status
    INTO v_job
    FROM public.jobs
   WHERE id = p_job_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'invite_inspector_to_job: job not found';
  END IF;
  IF v_uid <> COALESCE(v_job.client_id, '00000000-0000-0000-0000-000000000000'::uuid)
     AND v_uid <> COALESCE(v_job.agency_id, '00000000-0000-0000-0000-000000000000'::uuid)
     AND NOT public.nx_is_admin()
  THEN
    RAISE EXCEPTION 'invite_inspector_to_job: only the job owner (or admin) may invite';
  END IF;
  IF v_job.status NOT IN ('open', 'pending_approval') THEN
    RAISE EXCEPTION 'invite_inspector_to_job: job is not accepting invitations (status=%)', v_job.status;
  END IF;

  SELECT id, role, full_name, is_verified
    INTO v_inspector
    FROM public.profiles
   WHERE id = p_inspector_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'invite_inspector_to_job: inspector not found';
  END IF;
  IF v_inspector.role <> 'inspector' THEN
    RAISE EXCEPTION 'invite_inspector_to_job: target profile is not an inspector (role=%)', v_inspector.role;
  END IF;

  IF to_regclass('public.audit_events') IS NOT NULL THEN
    SELECT MAX(created_at) INTO v_recent
      FROM public.audit_events
     WHERE event_kind = 'inspector_invited_to_job'
       AND payload->>'job_id'       = p_job_id::text
       AND payload->>'inspector_id' = p_inspector_id::text
       AND payload->>'invited_by'   = v_uid::text;
    IF v_recent IS NOT NULL AND v_recent > NOW() - INTERVAL '24 hours' THEN
      RAISE EXCEPTION 'invite_inspector_to_job: this inspector was already invited to this job in the last 24 hours';
    END IF;

    INSERT INTO public.audit_events(event_kind, actor_id, payload)
    VALUES (
      'inspector_invited_to_job',
      v_uid,
      jsonb_build_object(
        'job_id',       p_job_id,
        'job_title',    v_job.title,
        'inspector_id', p_inspector_id,
        'invited_by',   v_uid,
        'message',      NULLIF(trim(coalesce(p_message, '')), ''),
        'invited_at',   NOW()
      )
    )
    RETURNING id INTO v_event_id;
  END IF;

  SELECT COALESCE(NULLIF(trim(company_name), ''), NULLIF(trim(full_name), ''), 'A NEXPEC buyer')
    INTO v_buyer_label
    FROM public.profiles
   WHERE id = v_uid;

  BEGIN
    IF to_regprocedure('public.nx_notify(uuid, text, text, text, text, uuid)') IS NOT NULL THEN
      PERFORM public.nx_notify(
        p_inspector_id,
        v_buyer_label || ' invited you to bid on a job',
        COALESCE(p_message, 'Open the job to review the brief and apply if you''re interested.'),
        'inspector_invited_to_job',
        '/job-details/' || p_job_id::text,
        p_job_id
      );
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'invite_inspector_to_job: notify failed (non-fatal): %', SQLERRM;
  END;

  RETURN jsonb_build_object(
    'ok',            true,
    'invitation_id', v_event_id,
    'job_id',        p_job_id,
    'inspector_id',  p_inspector_id,
    'invited_at',    NOW()
  );
END
$$;


ALTER FUNCTION "public"."invite_inspector_to_job"("p_job_id" "uuid", "p_inspector_id" "uuid", "p_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_active_cci"("p_uid" "uuid", "p_min_tier" "public"."cci_credential_tier" DEFAULT 'cci_basic'::"public"."cci_credential_tier") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM public.inspector_credentials ic
     WHERE ic.inspector_id = p_uid
       AND ic.status = 'approved'
       AND (ic.expires_at IS NULL OR ic.expires_at > NOW())
       AND CASE ic.tier
             WHEN 'cci_basic'    THEN 1
             WHEN 'cci_advanced' THEN 2
             WHEN 'cci_lead'     THEN 3
           END
           >=
           CASE p_min_tier
             WHEN 'cci_basic'    THEN 1
             WHEN 'cci_advanced' THEN 2
             WHEN 'cci_lead'     THEN 3
           END
  );
$$;


