    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$SELECT EXISTS (SELECT 1 FROM public.contracts c WHERE c.job_id = p_job_id AND (c.contractor_id = p_uid))$$;


ALTER FUNCTION "public"."jobs_has_contractor_party"("p_job_id" "uuid", "p_uid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."jobs_near_inspector"("p_inspector_id" "uuid", "p_max_km" numeric DEFAULT 100, "p_limit" integer DEFAULT 50) RETURNS TABLE("job_id" "uuid", "title" "text", "status" "text", "client_id" "uuid", "agency_id" "uuid", "client_price_cents" bigint, "payout_amount_cents" bigint, "location" "text", "scheduled_date" timestamp with time zone, "distance_km" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH inspector_loc AS (
    SELECT geog
    FROM public.profiles
    WHERE id = p_inspector_id
      AND role = 'inspector'
      AND geog IS NOT NULL
  )
  SELECT
    j.id  AS job_id,
    j.title,
    j.status,
    j.client_id,
    j.agency_id,
    j.client_price_cents,
    j.payout_amount_cents,
    j.location,
    j.scheduled_date,
    ROUND((ST_Distance(j.geog, p.geog) / 1000.0)::numeric, 2) AS distance_km
  FROM public.jobs j
  CROSS JOIN inspector_loc p
  WHERE j.deleted_at IS NULL
    AND j.status = 'open'
    AND j.geog IS NOT NULL
    AND ST_DWithin(j.geog, p.geog, p_max_km * 1000)
  ORDER BY j.geog <-> p.geog
  LIMIT p_limit;
$$;


ALTER FUNCTION "public"."jobs_near_inspector"("p_inspector_id" "uuid", "p_max_km" numeric, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_organization_by_email_domain"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_domain text;
  v_org    uuid;
BEGIN
  -- Skip if organization already set (don't override existing assignments)
  IF NEW.organization_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  IF NEW.email IS NULL OR NEW.email = '' THEN
    RETURN NEW;
  END IF;

  v_domain := public._email_domain(NEW.email);

  SELECT organization_id INTO v_org
  FROM public.enterprise_domains
  WHERE domain = v_domain AND is_active = true;

  IF v_org IS NOT NULL THEN
    NEW.organization_id := v_org;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."link_organization_by_email_domain"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lock_report_template"("p_template_id" "uuid") RETURNS "public"."report_templates"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_tpl public.report_templates%ROWTYPE;
  v_hash text;
BEGIN
  SELECT * INTO v_tpl FROM public.report_templates WHERE id = p_template_id;
  IF v_tpl.id IS NULL THEN RAISE EXCEPTION 'template not found' USING ERRCODE='P0002'; END IF;
  IF NOT (v_tpl.client_id = auth.uid() OR public.nx_is_admin()) THEN
    RAISE EXCEPTION 'not authorized to lock this template' USING ERRCODE='42501';
  END IF;
  v_hash := encode(digest(public.pi_canonical_json(v_tpl.template_spec), 'sha256'), 'hex');
  UPDATE public.report_templates
     SET is_locked = true, spec_sha256 = v_hash, locked_at = now(), locked_by = auth.uid()
   WHERE id = p_template_id
   RETURNING * INTO v_tpl;
  RETURN v_tpl;
END $$;


ALTER FUNCTION "public"."lock_report_template"("p_template_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_application_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.job_events (
      job_id, actor_id, event_type, new_status, metadata
    )
    VALUES (NEW.job_id, v_actor, 'application_created', NEW.status, jsonb_build_object('application_id', NEW.id, 'applicant_id', NEW.applicant_id));
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
    INSERT INTO public.job_events (
      job_id, actor_id, event_type, old_status, new_status, metadata
    )
    VALUES (NEW.job_id, v_actor, 'application_status_change', OLD.status, NEW.status, jsonb_build_object('application_id', NEW.id, 'applicant_id', NEW.applicant_id));
    RETURN NEW;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."log_application_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_dispute_status_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    IF OLD.status IS DISTINCT FROM NEW.status THEN
        INSERT INTO public.dispute_activities (
            dispute_id,
            actor_id,
            action,
            old_value,
            new_value
        ) VALUES (
            NEW.id,
            COALESCE(NEW.resolved_by, NEW.raised_by),
            'status_change',
            jsonb_build_object('status', OLD.status),
            jsonb_build_object('status', NEW.status)
        );
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."log_dispute_status_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_job_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();   -- NULL when called outside an authed context
BEGIN
  -- Job creation: a single 'created' row at the head of the timeline.
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.job_events (
      job_id, actor_id, event_type, old_status, new_status, metadata
    )
    VALUES (
      NEW.id,
      v_actor,
      'created',
      NULL,
      NEW.status,
      jsonb_build_object(
        'client_id',     NEW.client_id,
        'contractor_id', NEW.contractor_id
      )
    );
    RETURN NEW;
  END IF;

  -- UPDATE branch: emit one row per kind of transition that fired.
  IF TG_OP = 'UPDATE' THEN
    -- Status transition
    IF NEW.status IS DISTINCT FROM OLD.status THEN
      INSERT INTO public.job_events (
        job_id, actor_id, event_type, old_status, new_status
      )
      VALUES (NEW.id, v_actor, 'status_change', OLD.status, NEW.status);
    END IF;

    -- Contractor assignment / unassignment
    IF NEW.contractor_id IS DISTINCT FROM OLD.contractor_id THEN
      INSERT INTO public.job_events (
        job_id, actor_id, event_type, old_value, new_value
      )
      VALUES (
        NEW.id,
        v_actor,
        CASE
          WHEN NEW.contractor_id IS NULL THEN 'contractor_unassigned'
          ELSE 'contractor_assigned'
        END,
        OLD.contractor_id::text,
        NEW.contractor_id::text
      );
    END IF;

    -- Soft delete / restore (uses the deleted_at column added in Task 1)
    IF NEW.deleted_at IS DISTINCT FROM OLD.deleted_at THEN
      INSERT INTO public.job_events (
        job_id, actor_id, event_type, old_value, new_value
      )
      VALUES (
        NEW.id,
        v_actor,
        CASE
          WHEN NEW.deleted_at IS NULL THEN 'restored'
          ELSE 'soft_deleted'
        END,
        OLD.deleted_at::text,
        NEW.deleted_at::text
      );
    END IF;

    RETURN NEW;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."log_job_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_verification_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
