CREATE OR REPLACE FUNCTION "public"."ml_register_model"("p_kind" "text", "p_slug" "text", "p_version" integer, "p_runtime" "text", "p_storage_path" "text", "p_size_bytes" bigint, "p_sha256" "text", "p_tier" "text" DEFAULT 'student'::"text", "p_semver" "text" DEFAULT NULL::"text", "p_signature" "text" DEFAULT NULL::"text", "p_signature_alg" "text" DEFAULT NULL::"text", "p_signing_key_id" "text" DEFAULT NULL::"text", "p_device_min_tier" "text" DEFAULT 'standard'::"text", "p_min_app_version" "text" DEFAULT NULL::"text", "p_os_constraint" "text" DEFAULT 'any'::"text", "p_license" "text" DEFAULT NULL::"text", "p_params" "jsonb" DEFAULT '{}'::"jsonb", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE v_id uuid;
BEGIN
  -- اضافه شدن اجازه عبور برای ربات سرور (Service Role)
  IF NOT public.nx_is_admin() AND coalesce(current_setting('request.jwt.claims', true)::jsonb->>'role', '') <> 'service_role' THEN
    RAISE EXCEPTION 'not authorized to register models' USING errcode = '42501';
  END IF;

  INSERT INTO public.model_artifacts (
    kind, slug, version, semver, tier, runtime, storage_path, size_bytes, sha256,
    signature, signature_alg, signing_key_id, device_min_tier, min_app_version,
    os_constraint, license, params, notes, created_by
  ) VALUES (
    p_kind, p_slug, p_version, p_semver, p_tier, p_runtime, p_storage_path, p_size_bytes, lower(p_sha256),
    p_signature, p_signature_alg, p_signing_key_id, p_device_min_tier, p_min_app_version,
    coalesce(p_os_constraint,'any'), p_license, coalesce(p_params,'{}'::jsonb), p_notes, auth.uid()
  ) RETURNING id INTO v_id;

  BEGIN
    INSERT INTO public.audit_events (event_type, actor_id, subject_table, subject_id, summary, metadata)
    VALUES ('ml.model.registered', auth.uid(), 'model_artifacts', v_id,
            'Model artifact registered: ' || p_kind || '/' || p_slug || ' v' || p_version,
            jsonb_build_object('kind',p_kind,'slug',p_slug,'version',p_version,'tier',p_tier,'runtime',p_runtime));
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."ml_register_model"("p_kind" "text", "p_slug" "text", "p_version" integer, "p_runtime" "text", "p_storage_path" "text", "p_size_bytes" bigint, "p_sha256" "text", "p_tier" "text", "p_semver" "text", "p_signature" "text", "p_signature_alg" "text", "p_signing_key_id" "text", "p_device_min_tier" "text", "p_min_app_version" "text", "p_os_constraint" "text", "p_license" "text", "p_params" "jsonb", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ml_resolve_models"("p_kind" "text" DEFAULT NULL::"text", "p_device_tier" "text" DEFAULT 'standard'::"text", "p_os" "text" DEFAULT 'any'::"text", "p_app_version" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_rank   int := CASE lower(coalesce(p_device_tier,'standard'))
                    WHEN 'low' THEN 1 WHEN 'high' THEN 3 ELSE 2 END;
  v_os     text := lower(coalesce(p_os,'any'));
  v_models jsonb;
BEGIN
  SELECT coalesce(jsonb_agg(to_jsonb(m) ORDER BY m.kind, m.slug), '[]'::jsonb)
    INTO v_models
  FROM (
    SELECT DISTINCT ON (a.kind, a.slug)
      a.id, a.kind, a.slug, a.version, a.semver, a.runtime, a.tier,
      a.storage_bucket, a.storage_path, a.size_bytes, a.sha256,
      a.signature, a.signature_alg, a.signing_key_id,
      a.device_min_tier, a.min_app_version, a.os_constraint, a.license, a.params
    FROM public.model_artifacts a
    WHERE a.status = 'published'
      AND a.tier   = 'student'
      AND (p_kind IS NULL OR a.kind = p_kind)
      AND (a.os_constraint = 'any' OR a.os_constraint = v_os)
      AND (CASE a.device_min_tier WHEN 'low' THEN 1 WHEN 'high' THEN 3 ELSE 2 END) <= v_rank
    ORDER BY a.kind, a.slug, a.version DESC
  ) m;

  RETURN jsonb_build_object(
    'generated_at', now(),
    'device',       jsonb_build_object('tier', lower(coalesce(p_device_tier,'standard')), 'os', v_os),
    'app_version',  p_app_version,
    'models',       v_models
  );
END;
$$;


ALTER FUNCTION "public"."ml_resolve_models"("p_kind" "text", "p_device_tier" "text", "p_os" "text", "p_app_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ml_set_model_status"("p_id" "uuid", "p_status" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE v_tier text;
BEGIN
  -- اضافه شدن اجازه عبور برای ربات سرور (Service Role)
  IF NOT public.nx_is_admin() AND coalesce(current_setting('request.jwt.claims', true)::jsonb->>'role', '') <> 'service_role' THEN
    RAISE EXCEPTION 'not authorized to change model status' USING errcode = '42501';
  END IF;

  IF p_status NOT IN ('draft','published','deprecated','revoked') THEN
    RAISE EXCEPTION 'invalid status: %', p_status USING errcode = '22023';
  END IF;

  SELECT tier INTO v_tier FROM public.model_artifacts WHERE id = p_id;
  IF v_tier IS NULL THEN
    RAISE EXCEPTION 'model not found' USING errcode = 'P0002';
  END IF;
  IF p_status = 'published' AND v_tier <> 'student' THEN
    RAISE EXCEPTION 'teacher artifacts can never be published / distributed' USING errcode = '42501';
  END IF;

  UPDATE public.model_artifacts
     SET status = p_status,
         published_at = CASE WHEN p_status = 'published' THEN now() ELSE published_at END,
         revoked_at   = CASE WHEN p_status = 'revoked'   THEN now() ELSE revoked_at END
   WHERE id = p_id;
END;
$$;


ALTER FUNCTION "public"."ml_set_model_status"("p_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."moderate_review"("p_review_id" "uuid", "p_action" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_review RECORD;
  v_new_status text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'moderate_review: not authenticated';
  END IF;
  IF NOT public.nx_is_admin() THEN
    RAISE EXCEPTION 'moderate_review: admin only';
  END IF;
  IF p_action NOT IN ('hide', 'unhide', 'dispute', 'flag', 'note') THEN
    RAISE EXCEPTION 'moderate_review: invalid action %', p_action;
  END IF;

  SELECT * INTO v_review FROM public.reviews WHERE id = p_review_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'moderate_review: review not found';
  END IF;

  IF p_action = 'hide' THEN
    v_new_status := 'hidden';
    UPDATE public.reviews SET
      moderation_status='hidden', hidden_at=NOW(), hidden_by=v_uid,
      moderator_notes=COALESCE(p_notes, moderator_notes),
      last_moderated_at=NOW(), last_moderated_by=v_uid
    WHERE id=p_review_id;

  ELSIF p_action = 'unhide' THEN
    v_new_status := 'visible';
    UPDATE public.reviews SET
      moderation_status='visible',
      hidden_at=NULL, hidden_by=NULL,
      disputed_at=NULL, disputed_reason=NULL,
      flagged_at=NULL, flagged_reason=NULL,
      moderator_notes=COALESCE(p_notes, moderator_notes),
      last_moderated_at=NOW(), last_moderated_by=v_uid
    WHERE id=p_review_id;

  ELSIF p_action = 'dispute' THEN
    v_new_status := 'disputed';
    UPDATE public.reviews SET
      moderation_status='disputed', disputed_at=NOW(),
      disputed_reason=COALESCE(p_notes, disputed_reason),
      last_moderated_at=NOW(), last_moderated_by=v_uid
    WHERE id=p_review_id;

  ELSIF p_action = 'flag' THEN
    v_new_status := 'flagged';
    UPDATE public.reviews SET
      moderation_status='flagged', flagged_at=NOW(),
      flagged_reason=COALESCE(p_notes, flagged_reason),
      last_moderated_at=NOW(), last_moderated_by=v_uid
    WHERE id=p_review_id;

  ELSIF p_action = 'note' THEN
    v_new_status := v_review.moderation_status;
    UPDATE public.reviews SET
      moderator_notes=COALESCE(p_notes, moderator_notes),
      last_moderated_at=NOW(), last_moderated_by=v_uid
    WHERE id=p_review_id;
  END IF;

  -- Recompute aggregates using ONLY visible rows
  WITH agg AS (
    SELECT AVG(rating)::numeric(3,2) AS avg_rating, COUNT(*)::int AS cnt
      FROM public.reviews
     WHERE reviewee_id = v_review.reviewee_id
       AND moderation_status = 'visible'
  )
  UPDATE public.profiles p
     SET rating_average = COALESCE((SELECT avg_rating FROM agg), 0),
         rating_count   = COALESCE((SELECT cnt        FROM agg), 0)
   WHERE p.id = v_review.reviewee_id;

  RETURN jsonb_build_object(
    'ok', true,
    'review_id', p_review_id,
    'new_status', v_new_status,
    'moderated_by', v_uid,
    'moderated_at', NOW()
  );
END
$$;


ALTER FUNCTION "public"."moderate_review"("p_review_id" "uuid", "p_action" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."move_department"("p_department_id" "uuid", "p_new_parent_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor       uuid := auth.uid();
  v_actor_role  text;
  v_actor_label text;
  v_org_id      uuid;
  v_old_parent  uuid;
  v_new_parent_org uuid;
  v_correlation uuid := gen_random_uuid();
  v_creates_cycle boolean;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT org_id, parent_department_id INTO v_org_id, v_old_parent
    FROM public.departments WHERE id = p_department_id FOR UPDATE;
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Department not found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.can_manage_org_structure(v_org_id, v_actor) THEN
    RAISE EXCEPTION 'You do not have permission to manage this organization''s structure'
      USING ERRCODE = '42501';
  END IF;

  IF p_new_parent_id IS NOT NULL THEN
    IF p_new_parent_id = p_department_id THEN
      RAISE EXCEPTION 'A department cannot be its own parent' USING ERRCODE = '22000';
    END IF;

    SELECT org_id INTO v_new_parent_org FROM public.departments WHERE id = p_new_parent_id;
    IF v_new_parent_org IS NULL THEN
      RAISE EXCEPTION 'New parent department not found' USING ERRCODE = 'P0002';
    END IF;
    IF v_new_parent_org <> v_org_id THEN
      RAISE EXCEPTION 'New parent belongs to a different organization' USING ERRCODE = '22000';
    END IF;

    WITH RECURSIVE ancestors AS (
      SELECT id, parent_department_id FROM public.departments WHERE id = p_new_parent_id
      UNION ALL
      SELECT d.id, d.parent_department_id
        FROM public.departments d
        JOIN ancestors a ON a.parent_department_id = d.id
    )
    SELECT EXISTS (SELECT 1 FROM ancestors WHERE id = p_department_id)
      INTO v_creates_cycle;

    IF v_creates_cycle THEN
      RAISE EXCEPTION 'Cannot move a department under one of its own descendants' USING ERRCODE = '22000';
    END IF;
  END IF;

  UPDATE public.departments
     SET parent_department_id = p_new_parent_id
   WHERE id = p_department_id;

  SELECT actor_role, actor_label INTO v_actor_role, v_actor_label
    FROM public._dept_actor_profile(v_actor);

  INSERT INTO public.audit_events (
    event_type, actor_id, actor_role, actor_label,
    subject_table, subject_id, summary, delta, metadata, correlation_id
  ) VALUES (
    'department.moved',
    v_actor,
    v_actor_role,
    v_actor_label,
    'departments',
    p_department_id,
    'Department re-parented',
    jsonb_build_object(
      'from_parent_id', v_old_parent,
      'to_parent_id',   p_new_parent_id
    ),
    jsonb_build_object('org_id', v_org_id),
    v_correlation
  );

  RETURN jsonb_build_object(
    'ok', true,
    'department_id', p_department_id,
    'new_parent_id', p_new_parent_id,
    'correlation_id', v_correlation
  );
END;
$$;


ALTER FUNCTION "public"."move_department"("p_department_id" "uuid", "p_new_parent_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notification_smoke_test"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_trigger_count int;
  v_admin_count   int;
  v_notif_count   int;
  v_my_unread     int;
BEGIN
  IF NOT public.nx_is_admin() THEN
    RAISE EXCEPTION 'admin only';
  END IF;

  SELECT count(*) INTO v_trigger_count
    FROM pg_trigger
   WHERE tgrelid = 'public.jobs'::regclass
     AND tgname  = 'trg_notify_on_job_change';

  SELECT count(*) INTO v_admin_count
    FROM public.profiles
   WHERE role IN ('admin','super_admin');

  SELECT count(*) INTO v_notif_count
    FROM public.notifications;

  SELECT COALESCE(unread_notifications_count, 0) INTO v_my_unread
    FROM public.profiles
   WHERE id = auth.uid();

  RETURN jsonb_build_object(
    'ok', true,
    'job_trigger_installed', v_trigger_count > 0,
    'admin_count',           v_admin_count,
    'total_notifications',   v_notif_count,
    'my_unread_count',       v_my_unread,
    'as_of',                 now()
  );
END $$;


ALTER FUNCTION "public"."notification_smoke_test"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_admins"("p_kind" "text", "p_title" "text", "p_body" "text" DEFAULT NULL::"text", "p_link" "text" DEFAULT NULL::"text", "p_job_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_count int := 0; r RECORD;
BEGIN
  FOR r IN
    SELECT id FROM public.profiles WHERE role IN ('admin','super_admin')
  LOOP
    PERFORM public.notify_safe(r.id, p_kind, p_title, p_body, p_link, p_job_id);
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'notify_admins(%, %): %', p_kind, p_title, SQLERRM;
  RETURN 0;
END $$;


ALTER FUNCTION "public"."notify_admins"("p_kind" "text", "p_title" "text", "p_body" "text", "p_link" "text", "p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_inspectors_about_existing_job"("p_job_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE r RECORD; v_title text;
BEGIN
  SELECT COALESCE(NULLIF(title,''), 'New inspection') INTO v_title
    FROM public.jobs WHERE id = p_job_id;
  FOR r IN SELECT id FROM public.profiles WHERE role = 'inspector'
  LOOP
    PERFORM public.notify_safe(
      r.id, 'assignment',
      'New job available',
      v_title,
      '/inspector/jobs/' || p_job_id::text,
      p_job_id
    );
  END LOOP;
END $$;


