CREATE OR REPLACE FUNCTION "public"."notify_inspectors_on_job_approved"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE r RECORD;
BEGIN
  -- Fire only on transition from non-approved → approved
  IF TG_OP = 'UPDATE'
     AND COALESCE(NEW.moderation_status,'') = 'approved'
     AND COALESCE(OLD.moderation_status,'') <> 'approved'
     AND NEW.status = 'open'
     AND NEW.deleted_at IS NULL
  THEN
    FOR r IN SELECT id FROM public.profiles WHERE role = 'inspector'
    LOOP
      PERFORM public.notify_safe(
        r.id,
        'assignment',
        'New job available',
        COALESCE(NEW.title, 'A new inspection just cleared moderation.'),
        '/inspector/jobs/' || NEW.id::text,
        NEW.id
      );
    END LOOP;
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'notify_inspectors_on_job_approved: %', SQLERRM;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."notify_inspectors_on_job_approved"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_job_event_webhook"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'net'
    AS $$
DECLARE
  v_url text;
  v_key text;
BEGIN
  v_url := public._app_config_get('notify_edge_fn_url');
  v_key := public._app_config_get('service_role_key');

  IF v_url IS NULL OR v_key IS NULL THEN
    RAISE WARNING '[notify_job_event_webhook] config missing; skipping push for event %', NEW.id;
    RETURN NEW;
  END IF;

  PERFORM net.http_post(
    url := v_url,
    headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_key),
    body := jsonb_build_object('event_id', NEW.id)
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING '[notify_job_event_webhook] failed for event %: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_job_event_webhook"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_on_application_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_client uuid;
  v_title  text;
BEGIN
  BEGIN
    SELECT COALESCE(client_id, agency_id), COALESCE(NULLIF(title,''), 'your job')
      INTO v_client, v_title
      FROM public.jobs WHERE id = NEW.job_id;
  EXCEPTION WHEN OTHERS THEN
    v_client := NULL; v_title := 'your job';
  END;

  IF TG_OP = 'INSERT' THEN
    IF v_client IS NOT NULL THEN
      PERFORM public.notify_safe(
        v_client, 'application_status',
        'New inspector application',
        'An inspector applied to ' || v_title || '.',
        '/client/jobs/' || NEW.job_id::text || '/applications',
        NEW.job_id
      );
    END IF;
  ELSIF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
    IF NEW.inspector_id IS NOT NULL THEN
      PERFORM public.notify_safe(
        NEW.inspector_id, 'application_status',
        CASE NEW.status
          WHEN 'accepted' THEN 'Application accepted'
          WHEN 'rejected' THEN 'Application not selected'
          WHEN 'withdrawn' THEN 'Application withdrawn'
          ELSE 'Application updated'
        END,
        v_title,
        '/inspector/jobs/' || NEW.job_id::text,
        NEW.job_id
      );
    END IF;
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'notify_on_application_change: %', SQLERRM;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."notify_on_application_change"() OWNER TO "postgres";


