CREATE OR REPLACE FUNCTION "public"."notify_on_transaction_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_amount numeric;
BEGIN
  IF NEW.inspector_id IS NULL THEN RETURN NEW; END IF;

  v_amount := COALESCE(NEW.net_amount_halalas, NEW.gross_amount_halalas, 0) / 100.0;

  IF TG_OP = 'INSERT' AND NEW.status IN ('completed','paid','released') THEN
    PERFORM public.notify_safe(
      NEW.inspector_id, 'payout_released',
      'Earnings credited',
      'SAR ' || v_amount::text || ' from ' || COALESCE(NEW.description, 'a recent inspection'),
      '/inspector/payouts',
      NEW.job_id
    );
  ELSIF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status
        AND NEW.status IN ('completed','paid','released') THEN
    PERFORM public.notify_safe(
      NEW.inspector_id, 'payout_released',
      'Payout sent',
      'SAR ' || v_amount::text || ' is on its way to your bank.',
      '/inspector/payouts',
      NEW.job_id
    );
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'notify_on_transaction_change: %', SQLERRM;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."notify_on_transaction_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_safe"("p_recipient" "uuid", "p_kind" "text", "p_title" "text", "p_body" "text" DEFAULT NULL::"text", "p_link" "text" DEFAULT NULL::"text", "p_job_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_id uuid;
BEGIN
  IF p_recipient IS NULL THEN RETURN NULL; END IF;
  INSERT INTO public.notifications(recipient_id, kind, title, body, link_href, job_id)
       VALUES (p_recipient, p_kind, p_title, p_body, p_link, p_job_id)
    RETURNING id INTO v_id;
  BEGIN
    UPDATE public.profiles
       SET unread_notifications_count = COALESCE(unread_notifications_count, 0) + 1
     WHERE id = p_recipient;
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'notify_safe: profile counter update failed: %', SQLERRM;
  END;
  RETURN v_id;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'notify_safe(%, %, %): %', p_kind, p_recipient, p_title, SQLERRM;
  RETURN NULL;
END $$;


ALTER FUNCTION "public"."notify_safe"("p_recipient" "uuid", "p_kind" "text", "p_title" "text", "p_body" "text", "p_link" "text", "p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nx_auto_approve_due_engagements"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE n int;
BEGIN
  UPDATE public.inspector_engagement_meta
     SET client_review = 'auto_approved', reviewed_at = now()
   WHERE client_review = 'pending' AND review_deadline IS NOT NULL AND review_deadline < now();
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $$;


ALTER FUNCTION "public"."nx_auto_approve_due_engagements"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nx_business_days_elapsed"("p_since" timestamp with time zone) RETURNS integer
    LANGUAGE "sql" STABLE
    AS $$
  SELECT CASE WHEN p_since IS NULL THEN 0 ELSE (
    SELECT count(*)::int
    FROM generate_series((p_since AT TIME ZONE 'UTC')::date + 1,
                         (now()    AT TIME ZONE 'UTC')::date,
                         interval '1 day') AS d
    WHERE extract(isodow FROM d) < 6   -- Mon..Fri (statutory holidays not modelled)
  ) END;
$$;


ALTER FUNCTION "public"."nx_business_days_elapsed"("p_since" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nx_can_see_job_dept_scoping"("p_user_id" "uuid", "p_job_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_job_owner       uuid;
  v_job_dept        uuid;
  v_owner_org       uuid;
  v_uses_scoping    boolean;
  v_caller_role     text;
BEGIN
  -- No user → no visibility (shouldn't happen via RLS but defensive)
  IF p_user_id IS NULL THEN RETURN false; END IF;

  -- Fetch the relevant job + owner-org context in one round trip
  SELECT j.client_id, j.department_id, p_owner.organization_id, o.uses_department_scoping
    INTO v_job_owner, v_job_dept, v_owner_org, v_uses_scoping
    FROM public.jobs j
    LEFT JOIN public.profiles p_owner ON p_owner.id = j.client_id
    LEFT JOIN public.organizations o  ON o.id = p_owner.organization_id
   WHERE j.id = p_job_id;

  -- Unknown job → permit (let other policies decide)
  IF v_job_owner IS NULL THEN RETURN true; END IF;

  -- Job owner is not in any org → SMB job, no scoping applies
  IF v_owner_org IS NULL THEN RETURN true; END IF;

  -- Owning org has not opted in → flat behaviour, no narrowing
  IF v_uses_scoping IS NOT TRUE THEN RETURN true; END IF;

  -- Caller is the job owner themselves → always visible to them
  IF v_job_owner = p_user_id THEN RETURN true; END IF;

  -- Caller is an inspector → cross-platform marketplace visibility preserved
  -- Caller is platform admin → universal visibility preserved
  SELECT role INTO v_caller_role FROM public.profiles WHERE id = p_user_id;
  IF v_caller_role IN ('inspector', 'admin', 'super_admin') THEN
    RETURN true;
  END IF;

  -- Caller is an org admin of the owning org → all org jobs visible
  IF public.nx_user_is_org_admin(p_user_id, v_owner_org) THEN
    RETURN true;
  END IF;

  -- Job has no department → "corporate / unassigned", visible to all org members
  IF v_job_dept IS NULL THEN RETURN true; END IF;

  -- Final case — caller's department subtree must contain the job's department
  RETURN v_job_dept IN (SELECT public.nx_user_visible_department_ids(p_user_id));
END
$$;


ALTER FUNCTION "public"."nx_can_see_job_dept_scoping"("p_user_id" "uuid", "p_job_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."nx_can_see_job_dept_scoping"("p_user_id" "uuid", "p_job_id" "uuid") IS 'Single source of truth for the department-scoping narrowing rule. Returns TRUE for every path except: org has scoping enabled AND caller is a non-admin org member AND the job has a department_id AND the caller''s department subtree does NOT contain that department.';



CREATE OR REPLACE FUNCTION "public"."nx_guard_contract_before_money"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE v_status text;
BEGIN
  IF NEW.status = 'released' AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'released') THEN
    IF NEW.agreement_id IS NULL THEN
      RAISE EXCEPTION 'CONTRACT-BEFORE-MONEY: money leg % has no gating agreement', NEW.id;
    END IF;
    SELECT status INTO v_status FROM public.agreements WHERE id = NEW.agreement_id;
    IF v_status IS DISTINCT FROM 'executed' THEN
      RAISE EXCEPTION 'CONTRACT-BEFORE-MONEY: gating agreement % is % (must be executed)', NEW.agreement_id, COALESCE(v_status,'missing');
    END IF;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."nx_guard_contract_before_money"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nx_is_admin"("p_uid" "uuid" DEFAULT "auth"."uid"()) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles
     WHERE id = p_uid AND role IN ('admin','super_admin')
  );
$$;


ALTER FUNCTION "public"."nx_is_admin"("p_uid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nx_mark_all_notifications_read"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
  UPDATE public.notifications SET is_read = true, read_at = NOW()
   WHERE recipient_id = auth.uid() AND is_read = false;
  UPDATE public.profiles SET unread_notifications_count = 0 WHERE id = auth.uid();
END $$;


ALTER FUNCTION "public"."nx_mark_all_notifications_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nx_mark_notification_read"("p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_was_unread boolean := false;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
  WITH upd AS (
    UPDATE public.notifications SET is_read = true, read_at = NOW()
     WHERE id = p_id AND recipient_id = auth.uid() AND is_read = false
     RETURNING 1
  ) SELECT EXISTS(SELECT 1 FROM upd) INTO v_was_unread;
  IF v_was_unread THEN
    UPDATE public.profiles
       SET unread_notifications_count = GREATEST(unread_notifications_count - 1, 0)
     WHERE id = auth.uid();
  END IF;
END $$;


ALTER FUNCTION "public"."nx_mark_notification_read"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nx_milestone_deemed_accepted"("p_deal_id" "uuid", "p_kind" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE v_delivered timestamptz; v_open int; v_sla int := 10;
BEGIN
  SELECT CASE WHEN p_kind = 'report' THEN report_delivered_at ELSE goods_delivered_at END
    INTO v_delivered FROM public.deals WHERE id = p_deal_id;
  IF v_delivered IS NULL THEN RETURN false; END IF;
  SELECT count(*) INTO v_open FROM public.deal_nonconformances
    WHERE deal_id = p_deal_id AND kind = p_kind AND status = 'open';
  IF v_open > 0 THEN RETURN false; END IF;                       -- a substantive NCR freezes escrow
  RETURN public.nx_business_days_elapsed(v_delivered) >= v_sla;  -- 10 business days of silence = acceptance
END $$;


ALTER FUNCTION "public"."nx_milestone_deemed_accepted"("p_deal_id" "uuid", "p_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nx_notify"("p_recipient" "uuid", "p_title" "text", "p_body" "text", "p_kind" "text", "p_link" "text" DEFAULT NULL::"text", "p_job_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_id uuid;
BEGIN
  IF p_recipient IS NULL THEN RAISE EXCEPTION 'nx_notify: p_recipient is null'; END IF;
  IF p_title IS NULL OR length(trim(p_title))=0 THEN RAISE EXCEPTION 'nx_notify: p_title required'; END IF;
  IF p_kind  IS NULL OR length(trim(p_kind ))=0 THEN RAISE EXCEPTION 'nx_notify: p_kind required'; END IF;

  INSERT INTO public.notifications(recipient_id, kind, title, body, link_href, job_id)
    VALUES (p_recipient, p_kind, p_title, p_body, p_link, p_job_id)
    RETURNING id INTO v_id;

  UPDATE public.profiles
     SET unread_notifications_count = unread_notifications_count + 1
   WHERE id = p_recipient;
  RETURN v_id;
END $$;


ALTER FUNCTION "public"."nx_notify"("p_recipient" "uuid", "p_title" "text", "p_body" "text", "p_kind" "text", "p_link" "text", "p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nx_notify_admins"("p_title" "text", "p_body" "text", "p_kind" "text", "p_link" "text" DEFAULT NULL::"text", "p_job_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE r RECORD; v_count int := 0;
BEGIN
  FOR r IN SELECT id FROM public.profiles WHERE role IN ('admin', 'super_admin')
  LOOP
    PERFORM public.nx_notify(r.id, p_title, p_body, p_kind, p_link, p_job_id);
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END $$;


ALTER FUNCTION "public"."nx_notify_admins"("p_title" "text", "p_body" "text", "p_kind" "text", "p_link" "text", "p_job_id" "uuid") OWNER TO "postgres";


