    LANGUAGE "plpgsql"
    AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END $$;


ALTER FUNCTION "public"."nx_set_updated_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nx_user_is_org_admin"("p_user_id" "uuid", "p_org_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.org_members
     WHERE user_id = p_user_id
       AND org_id  = p_org_id
       AND role IN ('owner', 'procurement_admin')
  );
$$;


ALTER FUNCTION "public"."nx_user_is_org_admin"("p_user_id" "uuid", "p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nx_user_visible_department_ids"("p_user_id" "uuid") RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH RECURSIVE roots AS (
    SELECT m.department_id, m.includes_descendants
      FROM public.org_department_members m
      JOIN public.org_departments d ON d.id = m.department_id
     WHERE m.user_id = p_user_id
       AND d.is_archived = false
  ),
  expanded AS (
    SELECT d.id, d.parent_department_id, r.includes_descendants
      FROM public.org_departments d
      JOIN roots r ON r.department_id = d.id

    UNION

    SELECT child.id, child.parent_department_id, e.includes_descendants
      FROM public.org_departments child
      JOIN expanded e ON child.parent_department_id = e.id
     WHERE e.includes_descendants = true
       AND child.is_archived = false
  )
  SELECT DISTINCT id FROM expanded;
$$;


ALTER FUNCTION "public"."nx_user_visible_department_ids"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."open_job_approval_request"("p_job_id" "uuid", "p_policy_id" "uuid", "p_amount_cents" bigint, "p_currency" "text", "p_min_approvers_required" integer, "p_required_approver_roles" "text"[], "p_requires_sod" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor       uuid := auth.uid();
  v_actor_role  text;
  v_actor_lbl   text;
  v_job         record;
  v_request_id  uuid;
  v_currency    public.currency_code;
  v_correlation uuid := gen_random_uuid();
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  -- Pull job context — the action just inserted this row.
  SELECT id, client_id, department_id, status, title
    INTO v_job
    FROM public.jobs WHERE id = p_job_id FOR UPDATE;
  IF v_job.id IS NULL THEN
    RAISE EXCEPTION 'Job not found' USING ERRCODE = 'P0002';
  END IF;

  -- Only the requester (the buyer) can open the request on their own job.
  IF v_job.client_id IS DISTINCT FROM v_actor AND NOT public._actor_is_super_admin() THEN
    RAISE EXCEPTION 'Only the job poster can open an approval request' USING ERRCODE = '42501';
  END IF;

  IF v_job.status <> 'pending_approval' THEN
    RAISE EXCEPTION 'Job must be in pending_approval status (got %)', v_job.status USING ERRCODE = '22000';
  END IF;

  v_currency := COALESCE(p_currency, 'USD')::public.currency_code;

  -- Resolve org_id via the department, falling through to NULL when
  -- there's no department attribution (the engine still routes; the
  -- request just records org as the requester's primary).
  DECLARE v_org_id uuid;
  BEGIN
    IF v_job.department_id IS NOT NULL THEN
      SELECT org_id INTO v_org_id FROM public.departments WHERE id = v_job.department_id;
    END IF;
    IF v_org_id IS NULL THEN
      SELECT org_id INTO v_org_id
        FROM public.org_members
       WHERE user_id = v_actor
       ORDER BY created_at ASC
       LIMIT 1;
    END IF;
    IF v_org_id IS NULL THEN
      RAISE EXCEPTION 'Could not resolve org for approval request' USING ERRCODE = '22000';
    END IF;
  END;

  INSERT INTO public.approval_requests (
    org_id, job_id, department_id, policy_id, requested_by, requested_at,
    amount_cents, currency, min_approvers_required, required_approver_roles, requires_sod
  ) VALUES (
    v_org_id, p_job_id, v_job.department_id, p_policy_id, v_actor, now(),
    p_amount_cents, v_currency, p_min_approvers_required, p_required_approver_roles, p_requires_sod
  )
  RETURNING id INTO v_request_id;

  IF to_regclass('public.audit_events') IS NOT NULL THEN
    SELECT actor_role, actor_label INTO v_actor_role, v_actor_lbl
      FROM public._dept_actor_profile(v_actor);

    INSERT INTO public.audit_events (
      event_type, actor_id, actor_role, actor_label,
      subject_table, subject_id, summary, delta, metadata, correlation_id
    ) VALUES (
      'job.approval.requested',
      v_actor, v_actor_role, v_actor_lbl,
      'approval_requests', v_request_id,
      format('Approval requested for job %L (%s %s)',
        v_job.title, v_currency, (p_amount_cents::numeric / 100)::text),
      jsonb_build_object(
        'amount_cents', p_amount_cents,
        'currency', v_currency,
        'min_approvers_required', p_min_approvers_required,
        'required_approver_roles', p_required_approver_roles
      ),
      jsonb_build_object('org_id', v_org_id, 'job_id', p_job_id),
      v_correlation
    );
  END IF;

  RETURN jsonb_build_object(
    'ok',             true,
    'request_id',     v_request_id,
    'org_id',         v_org_id,
    'job_id',         p_job_id,
    'correlation_id', v_correlation
  );
END;
$$;


ALTER FUNCTION "public"."open_job_approval_request"("p_job_id" "uuid", "p_policy_id" "uuid", "p_amount_cents" bigint, "p_currency" "text", "p_min_approvers_required" integer, "p_required_approver_roles" "text"[], "p_requires_sod" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_cancel_job"("p_job_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor        uuid;
  v_actor_role   text;
  v_job          public.jobs%ROWTYPE;
  v_correlation  uuid := gen_random_uuid();
  v_clean_reason text;
BEGIN
  -- ── 1. Auth ────────────────────────────────────────────────────────
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT role INTO v_actor_role
  FROM public.profiles
  WHERE id = v_actor;

  -- ── 2. Input validation ───────────────────────────────────────────
  IF p_job_id IS NULL THEN
    RAISE EXCEPTION 'job_id is required' USING ERRCODE = '22000';
  END IF;

  v_clean_reason := NULLIF(TRIM(COALESCE(p_reason, '')), '');
  IF v_clean_reason IS NOT NULL AND length(v_clean_reason) > 500 THEN
    v_clean_reason := left(v_clean_reason, 500);
  END IF;

  -- ── 3. Audit annotation (reason captured here) ────────────────────
  PERFORM public.audit_set_correlation(v_correlation);
  PERFORM public.audit_set_intent(
    'Client cancelled own job' ||
    COALESCE(' — ' || v_clean_reason, '')
  );

  -- ── 4. Lock + validate ────────────────────────────────────────────
  SELECT * INTO v_job FROM public.jobs WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Job not found' USING ERRCODE = 'P0002';
  END IF;

  -- Self-auth: only the owning client may call this path. Admins use
  -- admin_cancel_job below.
  IF v_job.client_id IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'Only the job owner can cancel via this RPC'
      USING ERRCODE = '42501',
            HINT = 'Admins should use admin_cancel_job.';
  END IF;

  -- Client cancellation window: pre-dispatch only. After 'assigned' the
  -- client must request admin cancellation so escrow / dispute handling
  -- can run through the proper channel.
  IF v_job.status <> 'open' THEN
    RAISE EXCEPTION 'Job can only be cancelled by the owner while open (current: %)', v_job.status
      USING ERRCODE = '22000',
            HINT = 'Once dispatched, contact support to cancel.';
  END IF;

  -- ── 5. Flip status ────────────────────────────────────────────────
  UPDATE public.jobs
  SET status         = 'cancelled',
      cancelled_at   = now(),
      cancelled_by   = v_actor,
      cancel_reason  = v_clean_reason,
      updated_at     = now()
  WHERE id = p_job_id;

  RETURN jsonb_build_object(
    'ok',             true,
    'job_id',         p_job_id,
    'from_status',    v_job.status,
    'to_status',      'cancelled',
    'correlation_id', v_correlation
  );
END;
$$;


ALTER FUNCTION "public"."owner_cancel_job"("p_job_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."owner_cancel_job"("p_job_id" "uuid", "p_reason" "text") IS 'Owning client cancels their own job. Allowed only in open state (pre-dispatch). Reason captured into audit event.';



CREATE OR REPLACE FUNCTION "public"."pi_canonical_json"("p" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_type   text;
  v_parts  text[] := ARRAY[]::text[];
  v_key    text;
  v_arr_len int;
  v_i      int;
BEGIN
  IF p IS NULL THEN
    RETURN 'null';
  END IF;

  v_type := jsonb_typeof(p);

  IF v_type = 'object' THEN
    FOR v_key IN SELECT k FROM jsonb_object_keys(p) k ORDER BY k LOOP
      v_parts := array_append(
        v_parts,
        to_jsonb(v_key)::text || ':' || public.pi_canonical_json(p -> v_key)
      );
    END LOOP;
    RETURN '{' || array_to_string(v_parts, ',') || '}';
  END IF;

  IF v_type = 'array' THEN
    v_arr_len := jsonb_array_length(p);
    FOR v_i IN 0..(v_arr_len - 1) LOOP
      v_parts := array_append(v_parts, public.pi_canonical_json(p -> v_i));
    END LOOP;
    RETURN '[' || array_to_string(v_parts, ',') || ']';
  END IF;

  -- Scalars: string / number / boolean / null. jsonb::text emits
  -- the JSON-encoded form for each.
  RETURN p::text;
END
$$;


ALTER FUNCTION "public"."pi_canonical_json"("p" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pi_canonical_json"("p" "jsonb") IS 'Deterministic JSON canonicalisation. Object keys sorted lexicographically; array order preserved; scalars via jsonb''s native encoding. Used to compute pi_report_seals hashes. Mirrors the web canonicalJson.ts algorithm.';



CREATE TABLE IF NOT EXISTS "public"."pi_report_seals" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "report_id" "uuid" NOT NULL,
    "job_id" "uuid" NOT NULL,
    "inspector_id" "uuid" NOT NULL,
    "algorithm" "text" DEFAULT 'sha256/canonical-json/v1'::"text" NOT NULL,
    "root_sha256" "text" NOT NULL,
    "captures_root_sha256" "text" NOT NULL,
    "items_root_sha256" "text" NOT NULL,
    "report_meta_sha256" "text" NOT NULL,
    "captures_count" integer NOT NULL,
    "items_count" integer NOT NULL,
    "chain_verified" boolean NOT NULL,
    "chain_break_at_capture_id" "uuid",
    "inspector_sealed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "inspector_signature_sha256" "text" NOT NULL,
    "client_signed_at" timestamp with time zone,
    "client_signed_by" "uuid",
    "client_signature_sha256" "text",
    "audit_event_id" "uuid",
    "ai_root_sha256" "text",
    "ai_count" integer DEFAULT 0 NOT NULL,
    "doc_root_sha256" "text",
    "doc_count" integer DEFAULT 0 NOT NULL,
    CONSTRAINT "pi_report_seals_break_pair" CHECK (((("chain_verified" IS TRUE) AND ("chain_break_at_capture_id" IS NULL)) OR ("chain_verified" IS FALSE))),
    CONSTRAINT "pi_report_seals_captures_count_check" CHECK (("captures_count" >= 0)),
    CONSTRAINT "pi_report_seals_client_sig_pair" CHECK (((("client_signed_at" IS NULL) AND ("client_signed_by" IS NULL) AND ("client_signature_sha256" IS NULL)) OR (("client_signed_at" IS NOT NULL) AND ("client_signed_by" IS NOT NULL) AND ("client_signature_sha256" IS NOT NULL)))),
    CONSTRAINT "pi_report_seals_items_count_check" CHECK (("items_count" >= 0))
);


ALTER TABLE "public"."pi_report_seals" OWNER TO "postgres";


COMMENT ON TABLE "public"."pi_report_seals" IS 'Cryptographic seal over an inspection_reports row + its captures + its items. One row per report. Sealing is idempotent; re-calling pi_seal_inspection_report returns the existing seal.';



COMMENT ON COLUMN "public"."pi_report_seals"."algorithm" IS 'Hash spec version tag. Bump when the canonical-JSON algorithm changes so older seals remain re-derivable under their original spec.';



COMMENT ON COLUMN "public"."pi_report_seals"."root_sha256" IS 'The anchor hash. Computed as SHA-256 over (captures_root || items_root || report_meta) sorted lexicographically. Any modification to the report, its items, or its captures will invalidate this on re-derivation.';



CREATE OR REPLACE FUNCTION "public"."pi_countersign_inspection_report"("p_report_id" "uuid") RETURNS "public"."pi_report_seals"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller        uuid := auth.uid();
  v_is_admin      boolean;
  v_seal          public.pi_report_seals%ROWTYPE;
  v_job_client_id uuid;
  v_signed_at     timestamptz := now();
  v_signature     text;
  v_audit_id      uuid;
  v_actor_role    text;
  v_result        public.pi_report_seals%ROWTYPE;
BEGIN
  -- ────────── Auth ──────────
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.profiles
     WHERE id = v_caller AND role IN ('admin','super_admin')
  ) INTO v_is_admin;

  v_actor_role := CASE WHEN v_is_admin THEN 'super_admin' ELSE 'client' END;

  -- ────────── Load seal ──────────
  SELECT * INTO v_seal
    FROM public.pi_report_seals
   WHERE report_id = p_report_id;

  IF v_seal.id IS NULL THEN
    RAISE EXCEPTION 'report % has not been sealed yet — inspector must seal first', p_report_id
      USING ERRCODE = 'P0002';
  END IF;

  -- Idempotency.
  IF v_seal.client_signed_at IS NOT NULL THEN
    RETURN v_seal;
  END IF;

  -- ────────── Authorization: client of the job, or admin ──────────
  SELECT client_id INTO v_job_client_id
    FROM public.jobs
   WHERE id = v_seal.job_id;

  IF NOT v_is_admin
     AND (v_job_client_id IS NULL OR v_job_client_id <> v_caller)
  THEN
    RAISE EXCEPTION 'only the client of this job or NEXPEC Admin may countersign'
      USING ERRCODE = '42501';
  END IF;

  -- ────────── Compute client signature ──────────
  v_signature := encode(
    digest(
      v_caller::text || '|'
      || to_char(v_signed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      || '|' || v_seal.root_sha256,
      'sha256'
    ),
    'hex'
  );

  -- ────────── Audit event ──────────
  INSERT INTO public.audit_events (
    event_type, severity, actor_id, actor_role,
    subject_table, subject_id, job_id, summary, delta, metadata
  )
  VALUES (
    'compliance.inspection_report.countersigned',
    'info',
    v_caller,
    v_actor_role,
    'pi_report_seals',
    v_seal.id,
    v_seal.job_id,
    format('Client countersigned seal %s for report %s', v_seal.id, p_report_id),
    jsonb_build_object(
      'seal_id',                 v_seal.id,
      'root_sha256',             v_seal.root_sha256,
      'client_signature_sha256', v_signature,
      'client_signed_at',        v_signed_at
    ),
    jsonb_build_object(
      'seal_id',   v_seal.id::text,
      'root_hash', v_seal.root_sha256
    )
  )
  RETURNING id INTO v_audit_id;

  -- ────────── Apply countersignature ──────────
  UPDATE public.pi_report_seals
     SET client_signed_at        = v_signed_at,
         client_signed_by        = v_caller,
         client_signature_sha256 = v_signature,
         updated_at              = now()
   WHERE id = v_seal.id
  RETURNING * INTO v_result;

  RETURN v_result;
END
$$;


ALTER FUNCTION "public"."pi_countersign_inspection_report"("p_report_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pi_countersign_inspection_report"("p_report_id" "uuid") IS 'Client co-sign on an already-sealed inspection report. Idempotent. Caller must be jobs.client_id or super_admin.';



CREATE OR REPLACE FUNCTION "public"."pi_fetch_report_seal"("p_report_id" "uuid") RETURNS "public"."pi_report_seals"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_caller   uuid := auth.uid();
  v_is_admin boolean;
  v_result   public.pi_report_seals%ROWTYPE;
  v_can_see  boolean;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_result
    FROM public.pi_report_seals
   WHERE report_id = p_report_id;

  IF v_result.id IS NULL THEN
    -- No seal — return all-NULL row. Caller checks id IS NULL.
    RETURN v_result;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.profiles
     WHERE id = v_caller AND role IN ('admin','super_admin')
  ) INTO v_is_admin;

  v_can_see :=
    v_is_admin
    OR v_result.inspector_id = v_caller
    OR EXISTS (
         SELECT 1 FROM public.jobs
          WHERE id = v_result.job_id AND client_id = v_caller
       );

  IF NOT v_can_see THEN
    RAISE EXCEPTION 'not authorised to view this seal' USING ERRCODE = '42501';
  END IF;

  RETURN v_result;
END
$$;


ALTER FUNCTION "public"."pi_fetch_report_seal"("p_report_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pi_record_ai_detection"("p_job_id" "uuid", "p_defect_id" "text", "p_label" "text", "p_confidence" numeric, "p_model_slug" "text", "p_model_version" integer, "p_report_id" "uuid" DEFAULT NULL::"uuid", "p_capture_id" "uuid" DEFAULT NULL::"uuid", "p_model_sha256" "text" DEFAULT NULL::"text", "p_severity" "text" DEFAULT NULL::"text", "p_severity_scale" "text" DEFAULT NULL::"text", "p_standard_refs" "text"[] DEFAULT NULL::"text"[], "p_accepted" boolean DEFAULT false, "p_raw" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_id       uuid;
  v_artifact public.model_artifacts%ROWTYPE;
BEGIN
  -- ── Authorization (unchanged): admin or the job's contractor ──
  IF NOT (public.nx_is_admin() OR EXISTS (
            SELECT 1 FROM public.jobs j WHERE j.id = p_job_id
              AND j.contractor_id = auth.uid())) THEN
    RAISE EXCEPTION 'not authorized for this job' USING errcode = '42501';
  END IF;

  -- ── ★ PROVABLE-AI BINDING (NEW) — bind the finding to a signed model ★ ──
  IF p_model_sha256 IS NULL THEN
    RAISE EXCEPTION
      'model_sha256 is required: a detection must name the exact signed model bytes that produced it'
      USING errcode = '23514';
  END IF;

  SELECT * INTO v_artifact
    FROM public.model_artifacts
   WHERE slug = p_model_slug
     AND version = p_model_version;

  IF v_artifact.id IS NULL THEN
    RAISE EXCEPTION
      'model %/v% is not in the registry — cannot attest a detection to an unregistered model',
      p_model_slug, p_model_version USING errcode = '42501';
  END IF;
  IF v_artifact.status <> 'published' THEN
    RAISE EXCEPTION
      'model %/v% is "%" (not published) — only published models may attest detections',
      p_model_slug, p_model_version, v_artifact.status USING errcode = '42501';
  END IF;
  IF v_artifact.tier <> 'student' THEN
    RAISE EXCEPTION
      'model %/v% is tier "%" — only student models run on-device and may attest detections',
      p_model_slug, p_model_version, v_artifact.tier USING errcode = '42501';
  END IF;
  IF v_artifact.signature IS NULL OR v_artifact.signature_alg IS NULL THEN
    RAISE EXCEPTION
      'model %/v% is unsigned — an unsigned model cannot attest a provable detection',
      p_model_slug, p_model_version USING errcode = '42501';
  END IF;
  IF lower(p_model_sha256) <> lower(v_artifact.sha256) THEN
    RAISE EXCEPTION
      'model-bytes mismatch for %/v%: detection sha256 % ≠ the registered signed artifact %',
      p_model_slug, p_model_version, lower(p_model_sha256), v_artifact.sha256
      USING errcode = '23514';
  END IF;

  -- ── Insert (unchanged shape; sha256 normalized to lowercase) ──
  INSERT INTO public.ai_detections (job_id, report_id, capture_id, inspector_id, model_slug,
    model_version, model_sha256, defect_id, label, confidence, severity, severity_scale,
    standard_refs, accepted_by_human, raw)
  VALUES (p_job_id, p_report_id, p_capture_id, auth.uid(), p_model_slug, p_model_version,
    lower(p_model_sha256), p_defect_id, p_label, p_confidence, p_severity, p_severity_scale,
    p_standard_refs, p_accepted, coalesce(p_raw,'{}'::jsonb))
  RETURNING id INTO v_id;

  BEGIN
    INSERT INTO public.audit_events (event_type, actor_id, subject_table, subject_id, job_id, summary, metadata)
    VALUES ('ai.detection.recorded', auth.uid(), 'ai_detections', v_id, p_job_id,
      'AI detection: '||p_defect_id||' ('||p_model_slug||' v'||p_model_version||')',
      jsonb_build_object('defect', p_defect_id, 'accepted', p_accepted, 'confidence', p_confidence,
                         'model_sha256', lower(p_model_sha256), 'signing_key_id', v_artifact.signing_key_id));
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN v_id;
END; $$;


ALTER FUNCTION "public"."pi_record_ai_detection"("p_job_id" "uuid", "p_defect_id" "text", "p_label" "text", "p_confidence" numeric, "p_model_slug" "text", "p_model_version" integer, "p_report_id" "uuid", "p_capture_id" "uuid", "p_model_sha256" "text", "p_severity" "text", "p_severity_scale" "text", "p_standard_refs" "text"[], "p_accepted" boolean, "p_raw" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pi_record_ai_detection"("p_job_id" "uuid", "p_defect_id" "text", "p_label" "text", "p_confidence" numeric, "p_model_slug" "text", "p_model_version" integer, "p_report_id" "uuid", "p_capture_id" "uuid", "p_model_sha256" "text", "p_severity" "text", "p_severity_scale" "text", "p_standard_refs" "text"[], "p_accepted" boolean, "p_raw" "jsonb") IS 'Records an AI detection ONLY if it references a published, signed, student artifact in model_artifacts whose sha256 matches the caller (server-enforced provable-AI binding, 20260715). Folded into the inspection seal''s ai_root.';



CREATE OR REPLACE FUNCTION "public"."pi_record_doc_validation"("p_job_id" "uuid", "p_model_slug" "text", "p_model_version" integer, "p_model_sha256" "text", "p_verdict" "jsonb", "p_conformance_score" numeric DEFAULT NULL::numeric, "p_report_id" "uuid" DEFAULT NULL::"uuid", "p_template_id" "uuid" DEFAULT NULL::"uuid", "p_report_file_sha256" "text" DEFAULT NULL::"text", "p_extracted_sha256" "text" DEFAULT NULL::"text", "p_template_sha256" "text" DEFAULT NULL::"text", "p_flagged_for_review" boolean DEFAULT false, "p_accepted" boolean DEFAULT false, "p_client_op_id" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_id       uuid;
  v_artifact public.model_artifacts%ROWTYPE;
  v_result_sha text;
BEGIN
  -- Authorization: admin or the job's assigned inspector.
  IF NOT (public.nx_is_admin() OR EXISTS (
            SELECT 1 FROM public.jobs j WHERE j.id = p_job_id
              AND j.contractor_id = auth.uid())) THEN
    RAISE EXCEPTION 'not authorized for this job' USING errcode = '42501';
  END IF;

  -- Idempotency — replay returns the original id (before binding checks, so a
  -- retry never re-fails if the model was retired meanwhile). Mirrors 20260717.
  IF p_client_op_id IS NOT NULL THEN
    SELECT id INTO v_id FROM public.doc_validations WHERE client_op_id = p_client_op_id LIMIT 1;
    IF v_id IS NOT NULL THEN RETURN v_id; END IF;
  END IF;

  -- Provable-AI binding — the verdict must name the exact signed model bytes.
  IF p_model_sha256 IS NULL THEN
    RAISE EXCEPTION 'model_sha256 is required: a validation must name the exact signed model that produced it'
      USING errcode = '23514';
  END IF;
  SELECT * INTO v_artifact FROM public.model_artifacts
   WHERE slug = p_model_slug AND version = p_model_version;
  IF v_artifact.id IS NULL THEN
    RAISE EXCEPTION 'model %/v% is not in the registry', p_model_slug, p_model_version USING errcode='42501';
  END IF;
  IF v_artifact.status <> 'published' THEN
    RAISE EXCEPTION 'model %/v% is "%" (not published)', p_model_slug, p_model_version, v_artifact.status USING errcode='42501';
  END IF;
  IF v_artifact.signature IS NULL OR v_artifact.signature_alg IS NULL THEN
    RAISE EXCEPTION 'model %/v% is unsigned — cannot attest a provable validation', p_model_slug, p_model_version USING errcode='42501';
  END IF;
  IF lower(p_model_sha256) <> lower(v_artifact.sha256) THEN
    RAISE EXCEPTION 'model-bytes mismatch for %/v%: % ≠ registered %',
      p_model_slug, p_model_version, lower(p_model_sha256), v_artifact.sha256 USING errcode='23514';
  END IF;

  -- result hash is authoritative: derived from the canonical verdict, not trusted.
  v_result_sha := encode(digest(public.pi_canonical_json(COALESCE(p_verdict,'{}'::jsonb)), 'sha256'), 'hex');

  BEGIN
    INSERT INTO public.doc_validations (
      job_id, report_id, template_id, inspector_id, model_slug, model_version, model_sha256,
      conformance_score, verdict, report_file_sha256, extracted_sha256, template_sha256,
      result_sha256, flagged_for_review, accepted_by_human, client_op_id)
    VALUES (
      p_job_id, p_report_id, p_template_id, auth.uid(), p_model_slug, p_model_version, lower(p_model_sha256),
      p_conformance_score, COALESCE(p_verdict,'{}'::jsonb), lower(p_report_file_sha256), lower(p_extracted_sha256),
      lower(p_template_sha256), v_result_sha, p_flagged_for_review, p_accepted, p_client_op_id)
    RETURNING id INTO v_id;
  EXCEPTION WHEN unique_violation THEN
    SELECT id INTO v_id FROM public.doc_validations WHERE client_op_id = p_client_op_id LIMIT 1;
    RETURN v_id;
  END;

  BEGIN
    INSERT INTO public.audit_events (event_type, actor_id, subject_table, subject_id, job_id, summary, metadata)
    VALUES ('ai.doc_validation.recorded', auth.uid(), 'doc_validations', v_id, p_job_id,
      'Document validation: '||p_model_slug||' v'||p_model_version||COALESCE(' score '||p_conformance_score::text,''),
      jsonb_build_object('template_id', p_template_id, 'flagged', p_flagged_for_review,
        'result_sha256', v_result_sha, 'model_sha256', lower(p_model_sha256), 'signing_key_id', v_artifact.signing_key_id));
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN v_id;
END $$;


ALTER FUNCTION "public"."pi_record_doc_validation"("p_job_id" "uuid", "p_model_slug" "text", "p_model_version" integer, "p_model_sha256" "text", "p_verdict" "jsonb", "p_conformance_score" numeric, "p_report_id" "uuid", "p_template_id" "uuid", "p_report_file_sha256" "text", "p_extracted_sha256" "text", "p_template_sha256" "text", "p_flagged_for_review" boolean, "p_accepted" boolean, "p_client_op_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pi_seal_inspection_report"("p_report_id" "uuid") RETURNS "public"."pi_report_seals"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_caller             uuid := auth.uid();
  v_is_admin           boolean;
  v_report             public.inspection_reports%ROWTYPE;
  v_existing           public.pi_report_seals%ROWTYPE;

  v_seal_id            uuid := gen_random_uuid();
  v_sealed_at          timestamptz := now();

  v_captures_count     integer := 0;
  v_items_count        integer := 0;
  v_chain_verified     boolean := true;
  v_chain_break_at     uuid;

  v_prev_hash          text;
  v_captures_concat    text := '';
  v_items_concat       text := '';
  v_vendor_concat      text := '';
  v_ai_concat          text := '';
  v_doc_concat         text := '';

  v_captures_root      text;
  v_items_root         text;
  v_report_meta_sha    text;
  v_vendor_root        text;
  v_ai_root            text;
  v_ai_count           integer := 0;
  v_doc_root           text;
  v_doc_count          integer := 0;
  v_root               text;
  v_inspector_sig      text;

  v_audit_id           uuid;
  v_actor_role         text;

  v_capture            RECORD;
  v_item               RECORD;
  v_vendor_doc         RECORD;
  v_ai                 RECORD;
  v_doc                RECORD;
  v_item_jsonb         jsonb;
  v_report_jsonb       jsonb;
  v_ai_jsonb           jsonb;
  v_doc_jsonb          jsonb;

  v_result             public.pi_report_seals%ROWTYPE;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING ERRCODE = '28000';
  END IF;
  -- God-mode: admin ≡ super_admin (Phase 1).
  SELECT EXISTS (SELECT 1 FROM public.profiles WHERE id = v_caller AND role IN ('admin','super_admin'))
    INTO v_is_admin;
  v_actor_role := CASE WHEN v_is_admin THEN 'admin' ELSE 'inspector' END;

  SELECT * INTO v_report FROM public.inspection_reports WHERE id = p_report_id;
  IF v_report.id IS NULL THEN
    RAISE EXCEPTION 'inspection report % not found', p_report_id USING ERRCODE = 'P0002';
  END IF;
  IF v_report.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'inspection report % is deleted', p_report_id USING ERRCODE = '22023';
  END IF;
  IF NOT v_is_admin AND v_report.inspector_id IS DISTINCT FROM v_caller THEN
    RAISE EXCEPTION 'only the report author or NEXPEC Admin may seal this report'
      USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_existing FROM public.pi_report_seals WHERE report_id = p_report_id;
  IF v_existing.id IS NOT NULL THEN
    RETURN v_existing;
  END IF;

  -- ── Captures root + chain ──
  v_prev_hash := NULL;
  FOR v_capture IN
    SELECT id, capture_sha256, prev_capture_sha256, sort_index, captured_at
      FROM public.inspection_captures
     WHERE job_id = v_report.job_id
     ORDER BY sort_index ASC, captured_at ASC NULLS LAST, id ASC
  LOOP
    v_captures_count := v_captures_count + 1;
    IF v_captures_count = 1 THEN
      IF v_capture.prev_capture_sha256 IS NOT NULL THEN
        v_chain_verified := false;
        v_chain_break_at := COALESCE(v_chain_break_at, v_capture.id);
      END IF;
    ELSE
      IF v_capture.prev_capture_sha256 IS DISTINCT FROM v_prev_hash THEN
        v_chain_verified := false;
        v_chain_break_at := COALESCE(v_chain_break_at, v_capture.id);
      END IF;
    END IF;
    IF v_capture.capture_sha256 IS NULL THEN
      v_chain_verified := false;
      v_chain_break_at := COALESCE(v_chain_break_at, v_capture.id);
    END IF;
    v_captures_concat := v_captures_concat || COALESCE(v_capture.capture_sha256, '') || '|';
    v_prev_hash := v_capture.capture_sha256;
  END LOOP;
  v_captures_root := encode(digest(v_captures_concat, 'sha256'), 'hex');

  -- ── Items root ──
  FOR v_item IN
    SELECT id, description, status, photo_url, notes, location, created_at
      FROM public.inspection_items
     WHERE report_id = p_report_id
     ORDER BY created_at ASC NULLS LAST, id ASC
  LOOP
    v_items_count := v_items_count + 1;
    v_item_jsonb := jsonb_build_object(
      'id', v_item.id, 'description', v_item.description, 'status', v_item.status,
      'photo_url', v_item.photo_url, 'notes', v_item.notes, 'location', v_item.location,
      'created_at', v_item.created_at
    );
    v_items_concat := v_items_concat || public.pi_canonical_json(v_item_jsonb) || '|';
  END LOOP;
  v_items_root := encode(digest(v_items_concat, 'sha256'), 'hex');

  -- ── Report metadata hash ──
  v_report_jsonb := jsonb_build_object(
    'id', v_report.id, 'job_id', v_report.job_id, 'inspector_id', v_report.inspector_id,
    'status', v_report.status, 'notes', v_report.notes, 'pdf_url', v_report.pdf_url,
    'final_report_doc', v_report.final_report_doc, 'is_published', v_report.is_published,
    'is_client_approved', v_report.is_client_approved, 'signed_docs_url', v_report.signed_docs_url,
    'created_at', v_report.created_at
  );
  v_report_meta_sha := encode(digest(public.pi_canonical_json(v_report_jsonb), 'sha256'), 'hex');

  -- ── Vendor-chain root ──
  IF to_regclass('public.bridge_documents') IS NOT NULL THEN
    FOR v_vendor_doc IN
      SELECT d.sha256_client_computed, d.accepted_at, d.id
        FROM public.bridge_documents d
        JOIN public.coordination_bridges cb ON cb.id = d.bridge_id
       WHERE cb.job_id = v_report.job_id
         AND d.uploaded_by_actor_kind = 'vendor'
         AND d.accepted_at IS NOT NULL
       ORDER BY d.accepted_at ASC NULLS LAST, d.id ASC
    LOOP
      v_vendor_concat := v_vendor_concat || COALESCE(v_vendor_doc.sha256_client_computed, '') || '|';
    END LOOP;
  END IF;
  v_vendor_root := encode(digest(v_vendor_concat, 'sha256'), 'hex');

  -- ── AI-detection root (human-accepted, model-bound) ──
  IF to_regclass('public.ai_detections') IS NOT NULL THEN
    FOR v_ai IN
      SELECT id, defect_id, label, confidence, severity, model_slug, model_version, model_sha256
        FROM public.ai_detections
       WHERE accepted_by_human = true
         AND ( report_id = p_report_id
               OR (report_id IS NULL AND job_id = v_report.job_id) )
       ORDER BY created_at ASC NULLS LAST, id ASC
    LOOP
      v_ai_count := v_ai_count + 1;
      v_ai_jsonb := jsonb_build_object(
        'id', v_ai.id, 'defect_id', v_ai.defect_id, 'label', v_ai.label,
        'confidence', v_ai.confidence, 'severity', v_ai.severity,
        'model_slug', v_ai.model_slug, 'model_version', v_ai.model_version,
        'model_sha256', v_ai.model_sha256
      );
      v_ai_concat := v_ai_concat || public.pi_canonical_json(v_ai_jsonb) || '|';
    END LOOP;
  END IF;
  v_ai_root := encode(digest(v_ai_concat, 'sha256'), 'hex');

  -- ── Document-validation root (NEW · Document Intelligence) ──
  -- Hash chain over every document validation for this report, each bound to the
  -- exact signed model (slug+version+sha256) + the rubric it was judged against
  -- (template_sha256, carried inside result). Tamper with a verdict after sealing
  -- → doc_root changes → seal root changes → detectable.
  IF to_regclass('public.doc_validations') IS NOT NULL THEN
    FOR v_doc IN
      SELECT id, template_id, model_slug, model_version, model_sha256,
             conformance_score, template_sha256, result_sha256
        FROM public.doc_validations
       WHERE ( report_id = p_report_id
               OR (report_id IS NULL AND job_id = v_report.job_id) )
       ORDER BY created_at ASC NULLS LAST, id ASC
    LOOP
      v_doc_count := v_doc_count + 1;
      v_doc_jsonb := jsonb_build_object(
        'id', v_doc.id, 'template_id', v_doc.template_id,
        'model_slug', v_doc.model_slug, 'model_version', v_doc.model_version,
        'model_sha256', v_doc.model_sha256, 'conformance_score', v_doc.conformance_score,
        'template_sha256', v_doc.template_sha256, 'result_sha256', v_doc.result_sha256
      );
      v_doc_concat := v_doc_concat || public.pi_canonical_json(v_doc_jsonb) || '|';
    END LOOP;
  END IF;
  v_doc_root := encode(digest(v_doc_concat, 'sha256'), 'hex');

  -- ── Compose root (6-component, lexicographic) ──
  WITH parts(s) AS (
    VALUES (v_captures_root), (v_items_root), (v_report_meta_sha),
           (v_vendor_root), (v_ai_root), (v_doc_root)
  )
  SELECT encode(digest(string_agg(s, '|' ORDER BY s), 'sha256'), 'hex')
    INTO v_root FROM parts;

  v_inspector_sig := encode(
    digest(
      v_report.inspector_id::text || '|'
      || to_char(v_sealed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      || '|' || v_root,
      'sha256'
    ), 'hex'
  );

  -- ── Audit + seal write ──
  INSERT INTO public.audit_events (
    event_type, severity, actor_id, actor_role, actor_label,
    subject_table, subject_id, job_id, summary, delta, metadata
  )
  VALUES (
    'compliance.inspection_report.sealed',
    'info',
    v_caller, v_actor_role, NULL,
    'inspection_reports', p_report_id, v_report.job_id,
    format('Sealed inspection report %s (captures=%s, items=%s, ai=%s, doc=%s, chain=%s)',
      p_report_id, v_captures_count, v_items_count, v_ai_count, v_doc_count,
      CASE WHEN v_chain_verified THEN 'intact' ELSE 'broken' END),
    jsonb_build_object(
      'seal_id',                   v_seal_id,
      'root_sha256',               v_root,
      'captures_root_sha256',      v_captures_root,
      'items_root_sha256',         v_items_root,
      'report_meta_sha256',        v_report_meta_sha,
      'vendor_chain_root_sha256',  v_vendor_root,
      'ai_root_sha256',            v_ai_root,
      'ai_count',                  v_ai_count,
      'doc_root_sha256',           v_doc_root,
      'doc_count',                 v_doc_count,
      'inspector_signature_sha256', v_inspector_sig,
      'captures_count',            v_captures_count,
      'items_count',               v_items_count,
      'chain_verified',            v_chain_verified,
      'chain_break_at_capture_id', v_chain_break_at,
      'algorithm',                 'sha256/canonical-json/v4'
    ),
    jsonb_build_object('seal_id', v_seal_id::text, 'root_hash', v_root)
  )
  RETURNING id INTO v_audit_id;

  INSERT INTO public.pi_report_seals (
    id, report_id, job_id, inspector_id,
    algorithm,
    root_sha256, captures_root_sha256, items_root_sha256, report_meta_sha256,
    ai_root_sha256, ai_count, doc_root_sha256, doc_count,
    captures_count, items_count,
    chain_verified, chain_break_at_capture_id,
    inspector_sealed_at, inspector_signature_sha256,
    audit_event_id
  )
  VALUES (
    v_seal_id,
    p_report_id, v_report.job_id, v_report.inspector_id,
    'sha256/canonical-json/v4',
    v_root, v_captures_root, v_items_root, v_report_meta_sha,
    v_ai_root, v_ai_count, v_doc_root, v_doc_count,
    v_captures_count, v_items_count,
    v_chain_verified, v_chain_break_at,
    v_sealed_at, v_inspector_sig,
    v_audit_id
  )
  RETURNING * INTO v_result;

  RETURN v_result;
END
$$;


ALTER FUNCTION "public"."pi_seal_inspection_report"("p_report_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pi_seal_inspection_report"("p_report_id" "uuid") IS 'Computes and stores a cryptographic seal for an inspection report. Idempotent. Caller must be the report''s inspector_id or super_admin.';



CREATE OR REPLACE FUNCTION "public"."process_withdrawal"("p_amount" numeric, "p_bank_details" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_user_id UUID;
    v_available_balance NUMERIC;
    v_new_tx_id UUID;
BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    SELECT available_balance INTO v_available_balance
    FROM public.wallets
    WHERE user_id = v_user_id
    FOR UPDATE;

    IF v_available_balance IS NULL THEN
        RAISE EXCEPTION 'Wallet not found for this user';
    END IF;

    IF v_available_balance < p_amount THEN
        RAISE EXCEPTION 'Insufficient funds. Your real balance is: %', v_available_balance;
    END IF;

    UPDATE public.wallets
    SET available_balance = available_balance - p_amount,
        updated_at = now()
    WHERE user_id = v_user_id;

    INSERT INTO public.transactions (user_id, type, amount, description, status, metadata)
    VALUES (
        v_user_id,
        'withdrawal',
        p_amount,
        'Withdrawal request to ' || COALESCE(p_bank_details->>'bank_name', 'Bank Account'),
        'pending',
        p_bank_details
    ) RETURNING id INTO v_new_tx_id;

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Withdrawal request submitted successfully',
        'transaction_id', v_new_tx_id,
        'new_balance', v_available_balance - p_amount
    );
END;
$$;


ALTER FUNCTION "public"."process_withdrawal"("p_amount" numeric, "p_bank_details" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."protect_certification_verification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    -- Allow service_role
    IF current_setting('request.jwt.claim.role', true) = 'service_role' THEN
        RETURN NEW;
    END IF;
    
    -- Check if is_verified is being changed by non-admin
    IF OLD.is_verified IS DISTINCT FROM NEW.is_verified THEN
        IF NOT is_admin() THEN
            RAISE EXCEPTION 'FORBIDDEN: Only administrators can verify certifications';
        END IF;
    END IF;
    
    NEW.updated_at := NOW();
    RETURN NEW;
END;
$$;


