CREATE OR REPLACE FUNCTION "public"."raise_nonconformance"("p_deal_id" "uuid", "p_kind" "text", "p_citation" "text", "p_basis" "text" DEFAULT 'schedule_a_spec'::"text", "p_code_ref" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_d public.deals; v_id uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF p_kind NOT IN ('goods','report') THEN RAISE EXCEPTION 'invalid_kind'; END IF;
  IF p_basis NOT IN ('schedule_a_spec','code') THEN RAISE EXCEPTION 'invalid_basis'; END IF;
  IF p_citation IS NULL OR length(btrim(p_citation)) < 20 THEN
    RAISE EXCEPTION 'NCR_NOT_SUBSTANTIVE: a rejection must cite a specific Schedule A spec or ASME/API code deviation';
  END IF;
  SELECT * INTO v_d FROM public.deals WHERE id = p_deal_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown_deal'; END IF;
  IF NOT (v_d.client_id = v_uid OR public.nx_is_admin()) THEN RAISE EXCEPTION 'not_authorized'; END IF;

  INSERT INTO public.deal_nonconformances (deal_id, kind, raised_by, basis, code_ref, citation)
  VALUES (p_deal_id, p_kind, v_uid, p_basis, p_code_ref, btrim(p_citation))
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('ncr_id', v_id, 'deal_id', p_deal_id, 'kind', p_kind, 'status', 'open');
END $$;


ALTER FUNCTION "public"."raise_nonconformance"("p_deal_id" "uuid", "p_kind" "text", "p_citation" "text", "p_basis" "text", "p_code_ref" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reassign_invoice_department"("p_invoice_id" "uuid", "p_new_department_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    DECLARE
      v_actor          uuid := auth.uid();
      v_actor_role     text;
      v_actor_label    text;
      v_invoice        record;
      v_job_client_id  uuid;
      v_target_org_id  uuid;
      v_old_org_id     uuid;
      v_reason         text;
      v_correlation    uuid := gen_random_uuid();
    BEGIN
      IF v_actor IS NULL THEN
        RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
      END IF;

      v_reason := NULLIF(TRIM(COALESCE(p_reason, '')), '');
      IF v_reason IS NULL THEN
        RAISE EXCEPTION 'A reason is required for invoice reassignment' USING ERRCODE = '22000';
      END IF;

      SELECT id, job_id, department_id, client_id
        INTO v_invoice
        FROM public.invoices
       WHERE id = p_invoice_id
       FOR UPDATE;

      IF v_invoice.id IS NULL THEN
        RAISE EXCEPTION 'Invoice not found' USING ERRCODE = 'P0002';
      END IF;

      -- Resolve the org_id we're authorising against.
      -- Path A: explicit new department supplied → use its org.
      -- Path B: clearing attribution → use the old department's org.
      -- Path C: neither old nor new dept → infer from any org the
      --         job's client_id belongs to (rare; refuse for safety).
      IF p_new_department_id IS NOT NULL THEN
        SELECT org_id INTO v_target_org_id
          FROM public.departments WHERE id = p_new_department_id;
        IF v_target_org_id IS NULL THEN
          RAISE EXCEPTION 'Target department not found' USING ERRCODE = 'P0002';
        END IF;
      ELSIF v_invoice.department_id IS NOT NULL THEN
        SELECT org_id INTO v_target_org_id
          FROM public.departments WHERE id = v_invoice.department_id;
      END IF;

      IF v_target_org_id IS NULL THEN
        RAISE EXCEPTION 'Cannot determine an organization context for this invoice. Specify a target department.' USING ERRCODE = '22000';
      END IF;

      IF NOT public.can_manage_org_structure(v_target_org_id, v_actor) THEN
        RAISE EXCEPTION 'You do not have permission to reassign invoices in this organization'
          USING ERRCODE = '42501';
      END IF;

      -- Belt-and-braces: prevent cross-org capture. When attaching to a
      -- dept in org X, the invoice's buyer must actually be a member of X.
      IF p_new_department_id IS NOT NULL THEN
        SELECT client_id INTO v_job_client_id
          FROM public.jobs WHERE id = v_invoice.job_id;
        IF v_job_client_id IS NOT NULL
           AND NOT EXISTS (
             SELECT 1 FROM public.org_members
              WHERE org_id = v_target_org_id
                AND user_id = v_job_client_id
           )
        THEN
          RAISE EXCEPTION 'Invoice buyer is not a member of the target organization'
            USING ERRCODE = '42501';
        END IF;
      END IF;

      -- Capture old org for the audit delta.
      IF v_invoice.department_id IS NOT NULL THEN
        SELECT org_id INTO v_old_org_id
          FROM public.departments WHERE id = v_invoice.department_id;
      END IF;

      -- Apply the update — trigger refreshes cost_center_snapshot.
      UPDATE public.invoices
         SET department_id = p_new_department_id
       WHERE id = p_invoice_id;

      -- Resolve actor identity for the audit row.
      SELECT actor_role, actor_label INTO v_actor_role, v_actor_label
        FROM public._dept_actor_profile(v_actor);

      INSERT INTO public.audit_events (
        event_type, actor_id, actor_role, actor_label,
        subject_table, subject_id, summary, delta, metadata, correlation_id
      ) VALUES (
        'invoice.department.reassigned',
        v_actor,
        v_actor_role,
        v_actor_label,
        'invoices',
        p_invoice_id,
        format('Invoice department reassigned · %s', v_reason),
        jsonb_build_object(
          'from_department_id', v_invoice.department_id,
          'to_department_id',   p_new_department_id,
          'from_org_id',        v_old_org_id,
          'to_org_id',          v_target_org_id,
          'reason',             v_reason
        ),
        jsonb_build_object(
          'org_id',     v_target_org_id,
          'invoice_id', p_invoice_id,
          'job_id',     v_invoice.job_id
        ),
        v_correlation
      );

      RETURN jsonb_build_object(
        'ok', true,
        'invoice_id', p_invoice_id,
        'from_department_id', v_invoice.department_id,
        'to_department_id', p_new_department_id,
        'correlation_id', v_correlation
      );
    END;
    $$;


ALTER FUNCTION "public"."reassign_invoice_department"("p_invoice_id" "uuid", "p_new_department_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recompute_reputation"("p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_avg          numeric;
  v_count        integer;
  v_weighted_sum numeric;
  v_weight_sum   numeric;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN;
  END IF;

  SELECT
    COALESCE(SUM(r.rating::numeric * r.weight), 0),
    COALESCE(SUM(r.weight), 0),
    COUNT(*)
  INTO v_weighted_sum, v_weight_sum, v_count
  FROM public.reviews r
  WHERE r.reviewee_id = p_user_id
    AND r.moderation_status = 'visible';

  IF v_weight_sum > 0 THEN
    v_avg := round(v_weighted_sum / v_weight_sum, 2);
  ELSE
    v_avg := 0;
  END IF;

  UPDATE public.profiles
  SET rating_average = v_avg,
      rating_count   = v_count
  WHERE id = p_user_id;
END;
$$;


ALTER FUNCTION "public"."recompute_reputation"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."recompute_reputation"("p_user_id" "uuid") IS 'Atomically updates profiles.rating_average + rating_count from the weighted average of VISIBLE reviews. Idempotent. Owned by postgres so it can write to profiles regardless of caller.';



