    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT is_super_admin() THEN
    RAISE EXCEPTION 'Only super-admins can manually refresh reputation'
      USING ERRCODE = '42501';
  END IF;
  REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_inspector_reputation;
END;
$$;


ALTER FUNCTION "public"."refresh_inspector_reputation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."regenerate_recovery_codes"() RETURNS "text"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_codes text[] := ARRAY[]::text[];
  v_code text;
  i int;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  -- Invalidate every prior unused code for this user. Old codes that
  -- were already consumed retain their used_at timestamps.
  UPDATE public.auth_recovery_codes
     SET used_at = now()
   WHERE user_id = v_user AND used_at IS NULL;

  FOR i IN 1..10 LOOP
    -- 8 base32 chars from 5 random bytes (5 bytes encodes to 8 chars).
    v_code := upper(encode(extensions.gen_random_bytes(5), 'base32'));
    v_code := substring(v_code from 1 for 4) || '-'
           || substring(v_code from 5 for 4);

    INSERT INTO public.auth_recovery_codes (user_id, code_hash)
      VALUES (v_user, public._recovery_code_hash(v_code))
      ON CONFLICT (user_id, code_hash) DO NOTHING;

    v_codes := array_append(v_codes, v_code);
  END LOOP;

  RETURN v_codes;
END;
$$;


ALTER FUNCTION "public"."regenerate_recovery_codes"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."regenerate_recovery_codes"() IS 'Invalidates the caller''s existing unused recovery codes, generates 10 fresh codes, stores their sha256 hashes, and returns the plaintext codes exactly once. The plaintext is never persisted.';



CREATE OR REPLACE FUNCTION "public"."reject_application"("p_application_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  UPDATE public.applications a
  SET status = 'rejected', updated_at = NOW()
  FROM public.jobs j
  WHERE a.id = p_application_id 
    AND a.job_id = j.id 
    AND j.client_id = auth.uid()
    AND a.status != 'accepted';
END;
$$;


