CREATE OR REPLACE FUNCTION "public"."release_deal_leg"("p_leg_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_leg public.deal_money_legs;
BEGIN
  IF NOT public.nx_is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  SELECT * INTO v_leg FROM public.deal_money_legs WHERE id = p_leg_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown_leg'; END IF;
  UPDATE public.deal_money_legs SET status = 'released', released_at = now() WHERE id = p_leg_id; -- trigger enforces executed
  RETURN jsonb_build_object('leg_id', p_leg_id, 'status', 'released');
END $$;


ALTER FUNCTION "public"."release_deal_leg"("p_leg_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_inspector_payout"("p_deal_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_d public.deals; v_a public.agreements; v_confirmed timestamptz; v_ok boolean;
BEGIN
  IF NOT public.nx_is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  SELECT * INTO v_d FROM public.deals WHERE id = p_deal_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown_deal'; END IF;

  SELECT admin_confirmed_at INTO v_confirmed FROM public.jobs WHERE id = v_d.job_id;
  v_ok := (v_confirmed IS NOT NULL) OR public.nx_milestone_deemed_accepted(p_deal_id, 'report');
  IF NOT v_ok THEN
    RAISE EXCEPTION 'REPORT_NOT_CONFIRMED: confirm the report, or wait out the 10-business-day deemed-acceptance window, before paying the inspector';
  END IF;

  SELECT * INTO v_a FROM public.agreements
   WHERE deal_id = p_deal_id AND kind = 'inspector_engagement' AND status <> 'voided'
   ORDER BY version DESC LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'no_inspector_agreement'; END IF;
  IF v_a.status <> 'executed' THEN RAISE EXCEPTION 'CONTRACT-BEFORE-MONEY: inspector agreement is % (must be executed)', v_a.status; END IF;

  INSERT INTO public.deal_money_legs (deal_id, agreement_id, kind, amount_cents, currency, status, released_at)
  VALUES (p_deal_id, v_a.id, 'inspector_payout', v_a.amount_cents, v_d.currency, 'released', now())
  ON CONFLICT (deal_id, kind) DO UPDATE
    SET status = 'released', released_at = now(), agreement_id = EXCLUDED.agreement_id, amount_cents = EXCLUDED.amount_cents;
  RETURN jsonb_build_object('deal_id', p_deal_id, 'kind', 'inspector_payout', 'status', 'released');
END $$;


ALTER FUNCTION "public"."release_inspector_payout"("p_deal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_stripe_webhook_event"("p_event_id" "text", "p_error" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  UPDATE public.stripe_webhook_events
     SET status = 'failed_retryable', claimed_at = NULL
   WHERE event_id = p_event_id;

  BEGIN
    INSERT INTO public.audit_events (
      event_type, severity, actor_id, actor_role, actor_label,
      subject_table, subject_id, summary, delta, metadata
    ) VALUES (
      'stripe.webhook_handler_failed', 'warning', NULL, 'system',
      'Stripe webhook', 'stripe_webhook_events',
      '00000000-0000-0000-0000-000000000000',
      'Handler released event for retry: ' || COALESCE(p_error, 'unspecified'),
      '{}'::jsonb,
      jsonb_build_object('stripe_event_id', p_event_id, 'error', p_error)
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
END;
$$;


ALTER FUNCTION "public"."release_stripe_webhook_event"("p_event_id" "text", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_supplier_contract"("p_quote_id" "uuid", "p_amount_cents" integer, "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_supplier_id uuid; v_rfq_id uuid; v_status text; v_quote jsonb;
  v_contract_cents bigint; v_already bigint; v_release_id uuid;
BEGIN
  IF NOT public.nx_is_admin() THEN RAISE EXCEPTION 'not authorised: admin only'; END IF;
  IF p_amount_cents IS NULL OR p_amount_cents <= 0 THEN RAISE EXCEPTION 'INVALID_AMOUNT'; END IF;

  SELECT supplier_id, rfq_id, status, quote
    INTO v_supplier_id, v_rfq_id, v_status, v_quote
    FROM public.supplier_quotes WHERE id = p_quote_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'QUOTE_NOT_FOUND'; END IF;
  IF v_status <> 'accepted' THEN RAISE EXCEPTION 'CONTRACT_NOT_AWARDED'; END IF;

  -- NEW: a signed, executed supplier agreement is mandatory before any release.
  IF NOT EXISTS (
    SELECT 1 FROM public.supplier_contracts
     WHERE quote_id = p_quote_id AND status = 'executed'
  ) THEN
    RAISE EXCEPTION 'CONTRACT_NOT_EXECUTED: a signed supplier agreement must be executed before releasing funds';
  END IF;

  v_contract_cents := public._supplier_quote_cents(v_quote);
  SELECT COALESCE(SUM(amount_halalas), 0) INTO v_already
    FROM public.supplier_releases WHERE quote_id = p_quote_id;
  IF v_contract_cents > 0 AND (v_already + p_amount_cents) > v_contract_cents THEN
    RAISE EXCEPTION 'OVER_RELEASE: contract %, already released %, attempted %', v_contract_cents, v_already, p_amount_cents;
  END IF;

  INSERT INTO public.supplier_releases (quote_id, rfq_id, supplier_id, amount_halalas, note, released_by)
    VALUES (p_quote_id, v_rfq_id, v_supplier_id, p_amount_cents, p_note, v_uid)
    RETURNING id INTO v_release_id;

  PERFORM public.credit_supplier_earnings(v_supplier_id, p_amount_cents, COALESCE(p_note, 'Milestone release'), v_rfq_id);

  RETURN jsonb_build_object('release_id', v_release_id, 'supplier_id', v_supplier_id,
    'amount_cents', p_amount_cents, 'contract_cents', v_contract_cents,
    'released_total_cents', v_already + p_amount_cents);
END $$;


ALTER FUNCTION "public"."release_supplier_contract"("p_quote_id" "uuid", "p_amount_cents" integer, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_supplier_payout"("p_deal_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_d public.deals; v_a public.agreements; v_accepted boolean;
BEGIN
  IF NOT public.nx_is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  SELECT * INTO v_d FROM public.deals WHERE id = p_deal_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown_deal'; END IF;

  v_accepted := (v_d.goods_accepted_at IS NOT NULL) OR public.nx_milestone_deemed_accepted(p_deal_id, 'goods');
  IF NOT v_accepted THEN
    RAISE EXCEPTION 'GOODS_NOT_ACCEPTED: accept goods, or wait out the 10-business-day deemed-acceptance window, before paying the supplier';
  END IF;

  SELECT * INTO v_a FROM public.agreements
   WHERE deal_id = p_deal_id AND kind = 'supplier_supply' AND status <> 'voided'
   ORDER BY version DESC LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'no_supplier_agreement'; END IF;
  IF v_a.status <> 'executed' THEN RAISE EXCEPTION 'CONTRACT-BEFORE-MONEY: supplier agreement is % (must be executed)', v_a.status; END IF;

  INSERT INTO public.deal_money_legs (deal_id, agreement_id, kind, amount_cents, currency, status, released_at)
  VALUES (p_deal_id, v_a.id, 'supplier_payout', v_a.amount_cents, v_d.currency, 'released', now())
  ON CONFLICT (deal_id, kind) DO UPDATE
    SET status = 'released', released_at = now(), agreement_id = EXCLUDED.agreement_id, amount_cents = EXCLUDED.amount_cents;
  RETURN jsonb_build_object('deal_id', p_deal_id, 'kind', 'supplier_payout', 'status', 'released');
END $$;


ALTER FUNCTION "public"."release_supplier_payout"("p_deal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rename_department"("p_department_id" "uuid", "p_name" "text", "p_cost_center" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor       uuid := auth.uid();
  v_actor_role  text;
  v_actor_label text;
  v_org_id      uuid;
  v_old_name    text;
  v_old_cost    text;
  v_name        text;
  v_cost        text;
  v_correlation uuid := gen_random_uuid();
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT org_id, name, cost_center INTO v_org_id, v_old_name, v_old_cost
    FROM public.departments WHERE id = p_department_id FOR UPDATE;
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Department not found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.can_manage_org_structure(v_org_id, v_actor) THEN
    RAISE EXCEPTION 'You do not have permission to manage this organization''s structure'
      USING ERRCODE = '42501';
  END IF;

  v_name := NULLIF(TRIM(COALESCE(p_name, '')), '');
  IF v_name IS NULL THEN
    RAISE EXCEPTION 'Department name is required' USING ERRCODE = '22000';
  END IF;

  v_cost := NULLIF(TRIM(COALESCE(p_cost_center, '')), '');

  UPDATE public.departments
     SET name = v_name,
         cost_center = v_cost
   WHERE id = p_department_id;

  SELECT actor_role, actor_label INTO v_actor_role, v_actor_label
    FROM public._dept_actor_profile(v_actor);

  INSERT INTO public.audit_events (
    event_type, actor_id, actor_role, actor_label,
    subject_table, subject_id, summary, delta, metadata, correlation_id
  ) VALUES (
    'department.renamed',
    v_actor,
    v_actor_role,
    v_actor_label,
    'departments',
    p_department_id,
    format('Department renamed %L → %L', v_old_name, v_name),
    jsonb_build_object(
      'from', jsonb_build_object('name', v_old_name, 'cost_center', v_old_cost),
      'to',   jsonb_build_object('name', v_name,     'cost_center', v_cost)
    ),
    jsonb_build_object('org_id', v_org_id),
    v_correlation
  );

  RETURN jsonb_build_object(
    'ok', true,
    'department_id', p_department_id,
    'from_name', v_old_name,
    'to_name', v_name,
    'cost_center', v_cost,
    'correlation_id', v_correlation
  );
END;
$$;


ALTER FUNCTION "public"."rename_department"("p_department_id" "uuid", "p_name" "text", "p_cost_center" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_milestone_release"("p_job_id" "uuid", "p_amount_cents" bigint DEFAULT NULL::bigint, "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid       uuid := auth.uid();
  v_job       RECORD;
  v_recent    timestamptz;
  v_event_id  uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'request_milestone_release: not authenticated';
  END IF;

  SELECT id, contractor_id, status, title
    INTO v_job
    FROM public.jobs
   WHERE id = p_job_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'request_milestone_release: job not found';
  END IF;
  IF v_job.contractor_id IS NULL OR v_job.contractor_id <> v_uid THEN
    RAISE EXCEPTION 'request_milestone_release: only the assigned inspector may request';
  END IF;
  IF v_job.status NOT IN ('in_progress', 'completed') THEN
    RAISE EXCEPTION 'request_milestone_release: job must be in_progress or completed (got %)', v_job.status;
  END IF;
  IF p_amount_cents IS NOT NULL AND p_amount_cents < 0 THEN
    RAISE EXCEPTION 'request_milestone_release: amount must be non-negative';
  END IF;

  IF to_regclass('public.audit_events') IS NOT NULL THEN
    SELECT MAX(created_at) INTO v_recent
      FROM public.audit_events
     WHERE event_kind = 'milestone_release_requested'
       AND payload->>'job_id'       = p_job_id::text
       AND payload->>'requested_by' = v_uid::text;
    IF v_recent IS NOT NULL AND v_recent > NOW() - INTERVAL '10 minutes' THEN
      RAISE EXCEPTION 'request_milestone_release: a request is already pending — please wait before retrying';
    END IF;

    INSERT INTO public.audit_events(event_kind, actor_id, payload)
    VALUES (
      'milestone_release_requested',
      v_uid,
      jsonb_build_object(
        'job_id',       p_job_id,
        'job_title',    v_job.title,
        'requested_by', v_uid,
        'amount_cents', p_amount_cents,
        'note',         NULLIF(trim(coalesce(p_note, '')), ''),
        'requested_at', NOW()
      )
    )
    RETURNING id INTO v_event_id;
  END IF;

  BEGIN
    IF to_regprocedure('public.nx_notify_admins(text, text, text, text, uuid)') IS NOT NULL THEN
      PERFORM public.nx_notify_admins(
        'Milestone release requested',
        'An inspector has requested a milestone payout on "' || COALESCE(v_job.title, 'a job') || '". Open the job to review.',
        'milestone_release_requested',
        '/admin/jobs?inspect=' || p_job_id::text,
        p_job_id
      );
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'request_milestone_release: notify_admins failed (non-fatal): %', SQLERRM;
  END;

  RETURN jsonb_build_object(
    'ok',           true,
    'request_id',   v_event_id,
    'job_id',       p_job_id,
    'amount_cents', p_amount_cents,
    'requested_at', NOW()
  );
END
$$;


ALTER FUNCTION "public"."request_milestone_release"("p_job_id" "uuid", "p_amount_cents" bigint, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_named_disclosure"("p_deal_id" "uuid", "p_fee_cents" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_d public.deals;
  v_title text; v_fee bigint; v_body text; v_sha text; v_agr_id uuid; v_version int; v_tier_label text;
  v_existing public.agreements;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT * INTO v_d FROM public.deals WHERE id = p_deal_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown_deal'; END IF;
  IF NOT (v_d.client_id = v_uid OR public.nx_is_admin()) THEN RAISE EXCEPTION 'not_authorized'; END IF;

  -- Tiered Administrative Amendment Fee, assessed by project (Contract Price) size.
  --   Base       < $10k            → flat $100
  --   Standard   $10k to $100k     → 1% of the Contract Price
  --   Enterprise $100k to $1M      → flat $350
  --   Elite      > $1M             → flat $500
  v_tier_label := CASE
    WHEN COALESCE(v_d.client_price_cents,0) <  1000000   THEN 'Base'
    WHEN v_d.client_price_cents             <  10000000  THEN 'Standard'
    WHEN v_d.client_price_cents             <= 100000000 THEN 'Enterprise'
    ELSE 'Elite' END;
  v_fee := COALESCE(p_fee_cents, CASE
    WHEN COALESCE(v_d.client_price_cents,0) <  1000000   THEN 10000
    WHEN v_d.client_price_cents             <  10000000  THEN GREATEST(1, (round(v_d.client_price_cents * 0.01))::bigint)
    WHEN v_d.client_price_cents             <= 100000000 THEN 35000
    ELSE 50000 END);

  IF NOT EXISTS (SELECT 1 FROM public.inspector_engagement_meta WHERE deal_id = p_deal_id) THEN
    RAISE EXCEPTION 'NO_ASSIGNED_INSPECTOR: assign an inspector before purchasing named disclosure';
  END IF;
  IF EXISTS (SELECT 1 FROM public.inspector_engagement_meta WHERE deal_id = p_deal_id AND identity_revealed_at IS NOT NULL) THEN
    RETURN jsonb_build_object('deal_id', p_deal_id, 'revealed', true, 'already', true);
  END IF;

  -- idempotent: reuse a pending amendment if one is already presented
  SELECT * INTO v_existing FROM public.agreements
   WHERE deal_id = p_deal_id AND kind = 'disclosure_amendment' AND status IN ('draft','presented')
   ORDER BY version DESC LIMIT 1;
  IF FOUND THEN
    RETURN jsonb_build_object('agreement_id', v_existing.id, 'fee_cents', v_existing.amount_cents,
                              'currency', v_existing.currency, 'body_md', v_existing.body_md,
                              'tier_label', v_tier_label, 'reused', true);
  END IF;

  SELECT r.title INTO v_title FROM public.supplier_rfqs r WHERE r.id = v_d.rfq_id;
  v_body := public._brokered_disclosure_amendment_md(v_title, v_fee, v_d.currency, v_tier_label);
  v_sha  := encode(extensions.digest(v_body, 'sha256'), 'hex');
  SELECT COALESCE(MAX(version), 0) + 1 INTO v_version FROM public.agreements WHERE deal_id = p_deal_id AND kind = 'disclosure_amendment';

  INSERT INTO public.agreements (deal_id, kind, version, status, counterparty_id, amount_cents, currency,
                                 body_md, content_sha256, ots_status, presented_at, generated_by)
  VALUES (p_deal_id, 'disclosure_amendment', v_version, 'presented', v_d.client_id, v_fee, v_d.currency,
          v_body, v_sha, 'unsubmitted', now(), v_uid)
  RETURNING id INTO v_agr_id;

  RETURN jsonb_build_object('agreement_id', v_agr_id, 'fee_cents', v_fee, 'currency', v_d.currency,
                            'body_md', v_body, 'tier_label', v_tier_label, 'reused', false);
END $_$;


ALTER FUNCTION "public"."request_named_disclosure"("p_deal_id" "uuid", "p_fee_cents" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_payout_advance"("p_job_id" "uuid", "p_fee_bps" integer DEFAULT 200) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_job public.jobs%ROWTYPE;
  v_gross bigint;
  v_fee bigint;
  v_net bigint;
  v_id uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'NOT_AUTHENTICATED' USING ERRCODE = '28000'; END IF;
  IF p_fee_bps < 0 OR p_fee_bps > 10000 THEN RAISE EXCEPTION 'INVALID_FEE'; END IF;

  SELECT * INTO v_job FROM public.jobs WHERE id = p_job_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'JOB_NOT_FOUND' USING ERRCODE = 'P0002'; END IF;
  IF v_job.contractor_id IS DISTINCT FROM v_uid THEN RAISE EXCEPTION 'NOT_YOUR_JOB' USING ERRCODE = '42501'; END IF;
  IF v_job.admin_confirmed_at IS NULL THEN RAISE EXCEPTION 'NOT_YET_EARNED'; END IF;
  IF COALESCE(v_job.payment_mode,'prepay') <> 'net_terms' OR v_job.client_settled_at IS NOT NULL THEN
    RAISE EXCEPTION 'ADVANCE_NOT_APPLICABLE';  -- only on accrued, not-yet-settled net_terms jobs
  END IF;

  v_gross := COALESCE(v_job.inspector_payout_cents, 0);
  IF v_gross <= 0 THEN RAISE EXCEPTION 'NO_ACCRUED_AMOUNT'; END IF;
  v_fee := round(v_gross::numeric * p_fee_bps / 10000.0)::bigint;
  v_net := v_gross - v_fee;
  IF v_net <= 0 THEN RAISE EXCEPTION 'FEE_EXCEEDS_AMOUNT'; END IF;

  IF EXISTS (SELECT 1 FROM public.payout_advances WHERE job_id = p_job_id AND status IN ('requested','approved','funded')) THEN
    RAISE EXCEPTION 'ADVANCE_ALREADY_OPEN';
  END IF;

  INSERT INTO public.payout_advances(requester_id, requester_role, job_id, gross_cents, fee_bps, fee_cents, net_cents, status)
  VALUES (v_uid, 'inspector', p_job_id, v_gross, p_fee_bps, v_fee, v_net, 'requested')
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('ok', true, 'advance_id', v_id, 'gross_cents', v_gross, 'fee_cents', v_fee, 'net_cents', v_net);
END $$;


ALTER FUNCTION "public"."request_payout_advance"("p_job_id" "uuid", "p_fee_bps" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_price_revision"("p_agreement_id" "uuid", "p_proposed_amount_cents" bigint, "p_reason_code" "text", "p_justification" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_a public.agreements; v_d public.deals; v_id uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF p_proposed_amount_cents IS NULL OR p_proposed_amount_cents < 0 THEN RAISE EXCEPTION 'invalid_amount'; END IF;
  IF p_reason_code NOT IN ('scope_change','material_cost','schedule_change','market_adjustment','regulatory','error_correction','other')
     THEN RAISE EXCEPTION 'invalid_reason_code'; END IF;
  IF p_justification IS NULL OR length(btrim(p_justification)) < 20 THEN
    RAISE EXCEPTION 'JUSTIFICATION_REQUIRED: provide a substantive formal justification (min 20 chars)';
  END IF;
  SELECT * INTO v_a FROM public.agreements WHERE id = p_agreement_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown_agreement'; END IF;
  IF v_a.counterparty_id <> v_uid THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF v_a.status NOT IN ('presented','executed') THEN RAISE EXCEPTION 'AGREEMENT_NOT_REVISABLE: status=%', v_a.status; END IF;
  SELECT * INTO v_d FROM public.deals WHERE id = v_a.deal_id;
  IF v_d.status IN ('closed','cancelled') THEN RAISE EXCEPTION 'DEAL_CLOSED'; END IF;
  IF EXISTS (SELECT 1 FROM public.deal_revisions WHERE agreement_id = p_agreement_id AND status IN ('requested','countered')) THEN
    RAISE EXCEPTION 'REVISION_ALREADY_OPEN: an open revision already exists for this agreement';
  END IF;

  INSERT INTO public.deal_revisions (deal_id, agreement_id, kind, counterparty_id, status, reason_code, justification,
                                     current_amount_cents, proposed_amount_cents, created_by)
  VALUES (v_a.deal_id, p_agreement_id, v_a.kind, v_uid, 'requested', p_reason_code, btrim(p_justification),
          v_a.amount_cents, p_proposed_amount_cents, v_uid)
  RETURNING id INTO v_id;
  PERFORM public._revision_log(v_id, v_uid, public._revision_role(v_a.kind), 'propose', p_proposed_amount_cents, p_reason_code, btrim(p_justification));
  PERFORM public._revision_notify(v_d.created_by, 'Commercial revision requested', 'A counterparty has requested a price revision.', v_a.deal_id);
  RETURN jsonb_build_object('revision_id', v_id, 'status', 'requested');
END $$;


ALTER FUNCTION "public"."request_price_revision"("p_agreement_id" "uuid", "p_proposed_amount_cents" bigint, "p_reason_code" "text", "p_justification" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_senior_review"("p_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    UPDATE public.jobs SET status = 'senior_review', is_senior_review = TRUE, updated_at = NOW()
    WHERE id = p_job_id AND client_id = auth.uid();
    RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."request_senior_review"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_withdrawal"("p_amount" numeric, "p_bank_details" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    IF (SELECT balance FROM public.wallets WHERE user_id = auth.uid()) < p_amount THEN
        RAISE EXCEPTION 'Insufficient balance';
    END IF;
    UPDATE public.wallets SET balance = balance - p_amount, pending_withdrawal = pending_withdrawal + p_amount WHERE user_id = auth.uid();
    INSERT INTO public.withdrawals (user_id, wallet_id, amount, bank_details)
    VALUES (auth.uid(), (SELECT id FROM public.wallets WHERE user_id = auth.uid()), p_amount, p_bank_details);
END;
$$;


ALTER FUNCTION "public"."request_withdrawal"("p_amount" numeric, "p_bank_details" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_withdrawal"("p_amount_cents" bigint, "p_method" "text" DEFAULT 'bank_transfer'::"text", "p_note" "text" DEFAULT NULL::"text", "p_client_op_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_role text;
  v_kind text;
  v_dollars numeric(12,2);
  v_avail numeric;
  v_avail_h bigint;
  v_id uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'NOT_AUTHENTICATED' USING ERRCODE = '28000'; END IF;
  IF p_amount_cents IS NULL OR p_amount_cents <= 0 THEN RAISE EXCEPTION 'INVALID_AMOUNT'; END IF;
  IF p_method NOT IN ('bank_transfer','stripe_manual','other') THEN RAISE EXCEPTION 'INVALID_METHOD'; END IF;

  SELECT role INTO v_role FROM public.profiles WHERE id = v_uid;
  IF v_role = 'inspector' THEN v_kind := 'inspector';
  ELSIF v_role = 'supplier' THEN v_kind := 'supplier';
  ELSE RAISE EXCEPTION 'NOT_ELIGIBLE_FOR_PAYOUT'; END IF;

  -- Idempotent replay.
  IF p_client_op_id IS NOT NULL THEN
    SELECT id INTO v_id FROM public.withdrawal_requests WHERE client_op_id = p_client_op_id;
    IF v_id IS NOT NULL THEN RETURN jsonb_build_object('ok', true, 'idempotent', true, 'request_id', v_id); END IF;
  END IF;

  -- One open request at a time (also enforced by a partial unique index).
  IF EXISTS (SELECT 1 FROM public.withdrawal_requests WHERE requester_id = v_uid AND status IN ('requested','approved')) THEN
    RAISE EXCEPTION 'OPEN_REQUEST_EXISTS';
  END IF;

  v_dollars := round(p_amount_cents::numeric / 100.0, 2);

  IF v_kind = 'inspector' THEN
    INSERT INTO public.wallets(user_id) VALUES (v_uid) ON CONFLICT (user_id) DO NOTHING;
    SELECT available_balance INTO v_avail FROM public.wallets WHERE user_id = v_uid FOR UPDATE;
    IF COALESCE(v_avail,0) < v_dollars THEN RAISE EXCEPTION 'INSUFFICIENT_BALANCE' USING ERRCODE = 'P0001'; END IF;
    UPDATE public.wallets
       SET available_balance = available_balance - v_dollars,
           pending_payouts   = COALESCE(pending_payouts,0) + v_dollars,
           updated_at = now()
     WHERE user_id = v_uid;
  ELSE  -- supplier ledger (halalas minor units)
    SELECT available_balance_halalas INTO v_avail_h FROM public.supplier_earnings WHERE supplier_id = v_uid FOR UPDATE;
    IF COALESCE(v_avail_h,0) < p_amount_cents THEN RAISE EXCEPTION 'INSUFFICIENT_BALANCE' USING ERRCODE = 'P0001'; END IF;
    UPDATE public.supplier_earnings
       SET available_balance_halalas = available_balance_halalas - p_amount_cents,
           pending_halalas           = COALESCE(pending_halalas,0) + p_amount_cents,
           updated_at = now()
     WHERE supplier_id = v_uid;
  END IF;

  INSERT INTO public.withdrawal_requests(requester_id, requester_role, amount_cents, status, method, destination_note, client_op_id)
  VALUES (v_uid, v_kind, p_amount_cents, 'requested', p_method, p_note, p_client_op_id)
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('ok', true, 'request_id', v_id, 'reserved_cents', p_amount_cents);
END $$;


ALTER FUNCTION "public"."request_withdrawal"("p_amount_cents" bigint, "p_method" "text", "p_note" "text", "p_client_op_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_job_dispute"("p_dispute_id" "uuid", "p_outcome" "text", "p_resolution_notes" "text" DEFAULT NULL::"text") RETURNS "public"."job_disputes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_actor              uuid := auth.uid();
  v_dispute            public.job_disputes;
  v_new_job_status     text;
  v_new_dispute_status text;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT is_super_admin() THEN
    RAISE EXCEPTION 'Only super-admins can resolve disputes'
      USING ERRCODE = '42501';
  END IF;

  IF p_outcome NOT IN ('pay_inspector','refund_client') THEN
    RAISE EXCEPTION 'Outcome must be pay_inspector or refund_client (got %)', p_outcome
      USING ERRCODE = 'P0001';
  END IF;

  -- Lock the dispute
  SELECT * INTO v_dispute
  FROM public.job_disputes
  WHERE id = p_dispute_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Dispute % not found', p_dispute_id USING ERRCODE = 'P0002';
  END IF;
  IF v_dispute.status <> 'open' THEN
    RAISE EXCEPTION 'Dispute % already resolved (current status: %)',
      p_dispute_id, v_dispute.status USING ERRCODE = 'P0001';
  END IF;

  -- Lock the job too — prevents racy concurrent payout attempts.
  PERFORM 1 FROM public.jobs WHERE id = v_dispute.job_id FOR UPDATE;

  IF p_outcome = 'pay_inspector' THEN
    v_new_job_status     := 'completed';
    v_new_dispute_status := 'resolved_paid';
  ELSE
    v_new_job_status     := 'cancelled';
    v_new_dispute_status := 'resolved_refunded';
  END IF;

  -- Resolve the dispute
  UPDATE public.job_disputes
     SET status           = v_new_dispute_status,
         resolution_notes = p_resolution_notes,
         resolved_by      = v_actor,
         resolved_at      = now(),
         updated_at       = now()
   WHERE id = p_dispute_id
  RETURNING * INTO v_dispute;

  -- Update the job. Task 2's audit trigger fires automatically.
  UPDATE public.jobs
     SET status     = v_new_job_status,
         updated_at = now()
   WHERE id = v_dispute.job_id;

  RETURN v_dispute;
END;
$$;


ALTER FUNCTION "public"."resolve_job_dispute"("p_dispute_id" "uuid", "p_outcome" "text", "p_resolution_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."respond_to_counter"("p_revision_id" "uuid", "p_decision" "text", "p_amount_cents" bigint DEFAULT NULL::bigint, "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_r public.deal_revisions; v_role text; v_n int;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF p_decision NOT IN ('accept','reject','counter') THEN RAISE EXCEPTION 'invalid_decision'; END IF;
  SELECT * INTO v_r FROM public.deal_revisions WHERE id = p_revision_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown_revision'; END IF;
  IF v_r.counterparty_id <> v_uid THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF v_r.status <> 'countered' THEN RAISE EXCEPTION 'NO_COUNTER_TO_RESPOND_TO: status=%', v_r.status; END IF;
  v_role := public._revision_role(v_r.kind);

  IF p_decision = 'accept' THEN
    -- party consents to NEXPEC's counter → apply at the counter figure
    PERFORM public._revision_log(p_revision_id, v_uid, v_role, 'accept', v_r.counter_amount_cents, NULL, p_note);
    PERFORM public._apply_revision(p_revision_id, v_r.counter_amount_cents, v_uid);
    PERFORM public._revision_notify(v_r.created_by, 'Counter accepted', 'The counterparty accepted the counter; a superseding contract has been issued.', v_r.deal_id);
    RETURN jsonb_build_object('revision_id', p_revision_id, 'status', 'applied', 'agreed_amount_cents', v_r.counter_amount_cents);
  ELSIF p_decision = 'reject' THEN
    UPDATE public.deal_revisions SET status = 'rejected', decided_at = now() WHERE id = p_revision_id;
    PERFORM public._revision_log(p_revision_id, v_uid, v_role, 'reject', NULL, NULL, p_note);
    PERFORM public._revision_notify(v_r.created_by, 'Revision closed', 'The counterparty declined the counter; the revision is closed.', v_r.deal_id);
    RETURN jsonb_build_object('revision_id', p_revision_id, 'status', 'rejected');
  END IF;

  -- counter back → new party proposal, awaiting NEXPEC again
  IF p_amount_cents IS NULL OR p_amount_cents < 0 THEN RAISE EXCEPTION 'invalid_amount'; END IF;
  SELECT count(*) INTO v_n FROM public.deal_revision_events WHERE revision_id = p_revision_id;
  IF v_n >= 10 THEN RAISE EXCEPTION 'REVISION_ROUNDS_EXCEEDED'; END IF;
  UPDATE public.deal_revisions SET status = 'requested', proposed_amount_cents = p_amount_cents, rounds = rounds + 1
   WHERE id = p_revision_id;
  PERFORM public._revision_log(p_revision_id, v_uid, v_role, 'propose', p_amount_cents, v_r.reason_code, p_note);
  PERFORM public._revision_notify(v_r.created_by, 'Counter-proposal received', 'The counterparty proposed a revised figure for your review.', v_r.deal_id);
  RETURN jsonb_build_object('revision_id', p_revision_id, 'status', 'requested');
END $$;


ALTER FUNCTION "public"."respond_to_counter"("p_revision_id" "uuid", "p_decision" "text", "p_amount_cents" bigint, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_wallet_balance"("p_user_id" "uuid", "p_amount_cents" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  UPDATE public.wallets
     SET available_balance = available_balance + (p_amount_cents::numeric / 100.0),
         updated_at = now()
   WHERE user_id = p_user_id;
END;
$$;


ALTER FUNCTION "public"."restore_wallet_balance"("p_user_id" "uuid", "p_amount_cents" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reviews_populate_generalized"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Legacy insert sites only set client_id / inspector_id. Mirror them
  -- into the generalized columns when the caller didn't provide them.
  IF NEW.reviewer_id IS NULL THEN
    NEW.reviewer_id := NEW.client_id;
  END IF;
  IF NEW.reviewee_id IS NULL THEN
    NEW.reviewee_id := NEW.inspector_id;
  END IF;

  -- Make sure inspector_id / client_id reflect the actual inspector +
  -- non-inspector party for the new general case where an inspector is
  -- the REVIEWER. This keeps legacy SELECTs that filter by inspector_id
  -- = userId returning the right set of rows for that user.
  IF NEW.inspector_id IS NULL THEN
    IF NEW.reviewer_role_snap = 'inspector' THEN
      NEW.inspector_id := NEW.reviewer_id;
    ELSIF NEW.reviewee_role_snap = 'inspector' THEN
      NEW.inspector_id := NEW.reviewee_id;
    END IF;
  END IF;
  IF NEW.client_id IS NULL THEN
    IF NEW.reviewer_role_snap IN ('client', 'agency', 'enterprise') THEN
      NEW.client_id := NEW.reviewer_id;
    ELSIF NEW.reviewee_role_snap IN ('client', 'agency', 'enterprise') THEN
      NEW.client_id := NEW.reviewee_id;
    END IF;
  END IF;

  -- Defaults for the rest. The column-level DEFAULTs handle most cases;
  -- this is the safety net.
  NEW.reviewer_role_snap       := COALESCE(NEW.reviewer_role_snap, 'client');
  NEW.reviewee_role_snap       := COALESCE(NEW.reviewee_role_snap, 'inspector');
  NEW.reviewer_verified_snap   := COALESCE(NEW.reviewer_verified_snap, false);
  NEW.reviewer_jobs_count_snap := COALESCE(NEW.reviewer_jobs_count_snap, 0);
  NEW.weight                   := COALESCE(NEW.weight, 1.0);
  NEW.moderation_status        := COALESCE(NEW.moderation_status, 'visible');

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."reviews_populate_generalized"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reviews_recompute_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_old_reviewee uuid;
  v_new_reviewee uuid;
BEGIN
  -- Use the generalized column; legacy backfill ensures it's populated.
  v_old_reviewee := CASE WHEN TG_OP <> 'INSERT' THEN OLD.reviewee_id END;
  v_new_reviewee := CASE WHEN TG_OP <> 'DELETE' THEN NEW.reviewee_id END;

  IF TG_OP = 'DELETE' THEN
    PERFORM public.recompute_reputation(v_old_reviewee);
    RETURN OLD;
  ELSIF TG_OP = 'INSERT' THEN
    PERFORM public.recompute_reputation(v_new_reviewee);
  ELSE -- UPDATE
    IF v_old_reviewee IS DISTINCT FROM v_new_reviewee THEN
      PERFORM public.recompute_reputation(v_old_reviewee);
      PERFORM public.recompute_reputation(v_new_reviewee);
    ELSE
      PERFORM public.recompute_reputation(v_new_reviewee);
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."reviews_recompute_trigger"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."job_meetings" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "job_id" "uuid",
    "rfq_id" "uuid",
    "organizer_id" "uuid" NOT NULL,
    "title" "text" NOT NULL,
    "provider" "text" DEFAULT 'other'::"text" NOT NULL,
    "url" "text" NOT NULL,
    "scheduled_at" timestamp with time zone NOT NULL,
    "duration_min" integer DEFAULT 30 NOT NULL,
    "status" "text" DEFAULT 'scheduled'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "job_meetings_anchor_chk" CHECK ((("job_id" IS NOT NULL) OR ("rfq_id" IS NOT NULL))),
    CONSTRAINT "job_meetings_provider_check" CHECK (("provider" = ANY (ARRAY['zoom'::"text", 'teams'::"text", 'meet'::"text", 'jitsi'::"text", 'other'::"text"]))),
    CONSTRAINT "job_meetings_status_check" CHECK (("status" = ANY (ARRAY['scheduled'::"text", 'live'::"text", 'ended'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."job_meetings" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."schedule_meeting"("p_title" "text", "p_url" "text", "p_scheduled_at" timestamp with time zone, "p_participant_ids" "uuid"[], "p_job_id" "uuid" DEFAULT NULL::"uuid", "p_rfq_id" "uuid" DEFAULT NULL::"uuid", "p_provider" "text" DEFAULT 'other'::"text", "p_duration_min" integer DEFAULT 30) RETURNS "public"."job_meetings"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid          uuid := auth.uid();
  v_all          uuid[];
  v_has_buyer    boolean;
  v_has_inspector boolean;
  v_has_admin    boolean;
  v_meeting      public.job_meetings;
  v_pid          uuid;
  v_link         text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF coalesce(p_title,'') = '' THEN RAISE EXCEPTION 'title_required'; END IF;
  IF coalesce(p_url,'') !~* '^https?://' THEN RAISE EXCEPTION 'valid_meeting_url_required'; END IF;
  IF p_job_id IS NULL AND p_rfq_id IS NULL THEN RAISE EXCEPTION 'job_or_rfq_required'; END IF;
  IF p_provider NOT IN ('zoom','teams','meet','jitsi','other') THEN p_provider := 'other'; END IF;

  -- participant set always includes the organizer
  v_all := ARRAY(SELECT DISTINCT x FROM unnest(coalesce(p_participant_ids,'{}') || v_uid) AS x WHERE x IS NOT NULL);

  -- classify the room by role
  SELECT bool_or(role IN ('client','agency','enterprise')),
         bool_or(role IN ('inspector','senior')),
         bool_or(role IN ('admin','super_admin'))
    INTO v_has_buyer, v_has_inspector, v_has_admin
    FROM public.profiles WHERE id = ANY(v_all);

  -- ★ THE GUARD: a buyer + inspector in the same room REQUIRES an admin host.
  IF coalesce(v_has_buyer,false) AND coalesce(v_has_inspector,false) AND NOT coalesce(v_has_admin,false) THEN
    RAISE EXCEPTION 'admin_host_required: a client+inspector meeting must include an admin host (anti-poaching)';
  END IF;

  INSERT INTO public.job_meetings (job_id, rfq_id, organizer_id, title, provider, url, scheduled_at, duration_min)
  VALUES (p_job_id, p_rfq_id, v_uid, p_title, p_provider, p_url, p_scheduled_at, greatest(coalesce(p_duration_min,30), 5))
  RETURNING * INTO v_meeting;

  v_link := CASE WHEN p_job_id IS NOT NULL THEN '/jobs/' || p_job_id::text ELSE '/rfqs/' || p_rfq_id::text END;

  -- participant rows (role mapped to the meeting taxonomy) + notify everyone but the organizer
  FOREACH v_pid IN ARRAY v_all LOOP
    INSERT INTO public.job_meeting_participants (meeting_id, user_id, party_role)
    SELECT v_meeting.id, v_pid,
           CASE WHEN pr.role IN ('client','agency','enterprise') THEN 'client'
                WHEN pr.role IN ('inspector','senior')           THEN 'inspector'
                WHEN pr.role = 'supplier'                        THEN 'vendor'
                WHEN pr.role IN ('admin','super_admin')          THEN 'admin'
                ELSE 'client' END
      FROM public.profiles pr WHERE pr.id = v_pid
    ON CONFLICT (meeting_id, user_id) DO NOTHING;

    IF v_pid <> v_uid THEN
      BEGIN
        PERFORM public.nx_notify(v_pid, 'Meeting scheduled',
          p_title || ' — ' || to_char(p_scheduled_at, 'Mon DD, HH24:MI') || ' UTC',
          'meeting_scheduled', v_link, p_job_id);
      EXCEPTION WHEN OTHERS THEN NULL; END;
    END IF;
  END LOOP;

  RETURN v_meeting;
END $$;


ALTER FUNCTION "public"."schedule_meeting"("p_title" "text", "p_url" "text", "p_scheduled_at" timestamp with time zone, "p_participant_ids" "uuid"[], "p_job_id" "uuid", "p_rfq_id" "uuid", "p_provider" "text", "p_duration_min" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_inspectors"("p_search_query" "text" DEFAULT NULL::"text", "p_ndt_methods" "text"[] DEFAULT NULL::"text"[], "p_location" "text" DEFAULT NULL::"text", "p_min_rating" numeric DEFAULT NULL::numeric, "p_is_verified" boolean DEFAULT NULL::boolean, "p_sort_by" "text" DEFAULT 'rating'::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "full_name" "text", "professional_title" "text", "avatar_url" "text", "bio" "text", "is_verified" boolean, "is_available" boolean, "hourly_rate" numeric, "years_experience" integer, "ndt_methods" "text"[], "location_city" "text", "rating_average" numeric, "rating_count" integer, "is_featured" boolean, "relevance_score" real)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    im.id, im.full_name, im.professional_title, im.avatar_url, im.bio, 
    im.is_verified, im.is_available, im.hourly_rate, im.years_experience, 
    im.ndt_methods, im.location_city, im.rating_average, im.rating_count, 
    im.is_featured,
    CASE 
      WHEN p_search_query IS NOT NULL AND p_search_query != '' 
      THEN ts_rank(im.search_vector, plainto_tsquery('english', p_search_query))
      ELSE 1.0
    END AS relevance_score
  FROM public.inspector_marketplace im
  WHERE 
    (p_search_query IS NULL OR p_search_query = '' OR im.search_vector @@ plainto_tsquery('english', p_search_query))
    AND (p_ndt_methods IS NULL OR im.ndt_methods && p_ndt_methods)
    AND (p_location IS NULL OR p_location = '' OR im.location_city ILIKE '%' || p_location || '%')
    AND (p_min_rating IS NULL OR im.rating_average >= p_min_rating)
    AND (p_is_verified IS NULL OR im.is_verified = p_is_verified)
  ORDER BY
    im.is_featured DESC,
    CASE WHEN p_sort_by = 'rating' THEN im.rating_average END DESC NULLS LAST,
    CASE WHEN p_sort_by = 'experience' THEN im.years_experience END DESC NULLS LAST,
    CASE WHEN p_sort_by = 'price_low' THEN im.hourly_rate END ASC NULLS LAST,
    im.rating_average DESC NULLS LAST
  LIMIT p_limit OFFSET p_offset;
END;
$$;


ALTER FUNCTION "public"."search_inspectors"("p_search_query" "text", "p_ndt_methods" "text"[], "p_location" "text", "p_min_rating" numeric, "p_is_verified" boolean, "p_sort_by" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_offer"("p_application_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- تغییر وضعیت به offered (این کار معمولاً پیش‌نیاز Escrow است)
  UPDATE public.applications a
  SET status = 'offered', updated_at = NOW()
  FROM public.jobs j
  WHERE a.id = p_application_id 
    AND a.job_id = j.id 
    AND j.client_id = auth.uid()
    AND j.status = 'open'
    AND a.status IN ('pending', 'shortlisted');
END;
$$;


ALTER FUNCTION "public"."send_offer"("p_application_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_active_org"("p_org_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor       uuid := auth.uid();
  v_actor_role  text;
  v_actor_label text;
  v_org         record;
  v_member      record;
  v_old_org_id  uuid;
  v_correlation uuid := gen_random_uuid();
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_org_id IS NULL THEN
    RAISE EXCEPTION 'org_id is required (use clear_active_org() to unset)'
      USING ERRCODE = '22000';
  END IF;

  -- Org must exist and be active.
  SELECT id, name, slug, kind, is_active
    INTO v_org
    FROM public.organizations WHERE id = p_org_id;
  IF v_org.id IS NULL THEN
    RAISE EXCEPTION 'Organization not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_org.is_active IS DISTINCT FROM TRUE THEN
    RAISE EXCEPTION 'Organization is inactive' USING ERRCODE = '42501';
  END IF;

  -- Caller must be a current member of the target org. Super-admin can
  -- also switch into any org (useful for support / impersonation flows).
  SELECT m.role::text AS role
    INTO v_member
    FROM public.org_members m
   WHERE m.org_id = p_org_id AND m.user_id = v_actor;

  IF v_member.role IS NULL THEN
    -- Allow super_admin even without a membership row.
    SELECT role INTO v_actor_role FROM public.profiles WHERE id = v_actor;
    IF v_actor_role IS DISTINCT FROM 'super_admin' THEN
      RAISE EXCEPTION 'You are not a member of this organization'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  SELECT active_org_id INTO v_old_org_id
    FROM public.profiles WHERE id = v_actor FOR UPDATE;

  UPDATE public.profiles
     SET active_org_id = p_org_id
   WHERE id = v_actor;

  -- Audit (best-effort: skip if audit_events isn't installed).
  IF to_regclass('public.audit_events') IS NOT NULL THEN
    SELECT COALESCE(NULLIF(TRIM(p.full_name), ''), p.email, 'Unknown')
      INTO v_actor_label
      FROM public.profiles p WHERE p.id = v_actor;

    INSERT INTO public.audit_events (
      event_type, actor_id, actor_role, actor_label,
      subject_table, subject_id, summary, delta, metadata, correlation_id
    ) VALUES (
      'user.active_org.changed',
      v_actor,
      COALESCE(v_actor_role, v_member.role, 'authenticated'),
      v_actor_label,
      'profiles',
      v_actor,
      format('Active org switched to %L', v_org.name),
      jsonb_build_object(
        'from_org_id', v_old_org_id,
        'to_org_id',   p_org_id,
        'to_org_name', v_org.name
      ),
      jsonb_build_object('org_id', p_org_id),
      v_correlation
    );
  END IF;

  RETURN jsonb_build_object(
    'ok',            true,
    'active_org_id', p_org_id,
    'org_name',      v_org.name,
    'org_slug',      v_org.slug,
    'org_kind',      v_org.kind,
    'role',          v_member.role,
    'correlation_id', v_correlation
  );
END;
$$;


ALTER FUNCTION "public"."set_active_org"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_approval_policy"("p_org_id" "uuid", "p_name" "text", "p_min_amount_cents" bigint, "p_max_amount_cents" bigint, "p_currency" "text", "p_required_approver_roles" "text"[], "p_min_approvers_count" integer DEFAULT 1, "p_requires_sod" boolean DEFAULT true, "p_scope_department_id" "uuid" DEFAULT NULL::"uuid", "p_is_active" boolean DEFAULT true, "p_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor       uuid := auth.uid();
  v_actor_role  text;
  v_actor_lbl   text;
  v_currency    public.currency_code;
  v_id          uuid;
  v_correlation uuid := gen_random_uuid();
  v_op          text := CASE WHEN p_id IS NULL THEN 'created' ELSE 'updated' END;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.can_manage_org_structure(p_org_id, v_actor) THEN
    RAISE EXCEPTION 'You do not have permission to set approval policies for this organization'
      USING ERRCODE = '42501';
  END IF;

  IF p_name IS NULL OR length(trim(p_name)) = 0 THEN
    RAISE EXCEPTION 'policy name is required' USING ERRCODE = '22000';
  END IF;
  IF p_min_amount_cents IS NULL OR p_min_amount_cents < 0 THEN
    RAISE EXCEPTION 'min_amount_cents must be >= 0' USING ERRCODE = '22000';
  END IF;
  IF p_max_amount_cents IS NOT NULL AND p_max_amount_cents <= p_min_amount_cents THEN
    RAISE EXCEPTION 'max_amount_cents must be > min_amount_cents (or NULL)' USING ERRCODE = '22000';
  END IF;
  IF p_min_approvers_count IS NULL OR p_min_approvers_count < 1 THEN
    RAISE EXCEPTION 'min_approvers_count must be >= 1' USING ERRCODE = '22000';
  END IF;
  IF p_required_approver_roles IS NULL OR array_length(p_required_approver_roles, 1) < 1 THEN
    RAISE EXCEPTION 'required_approver_roles must include at least one role' USING ERRCODE = '22000';
  END IF;
  -- Validate roles against the org_member_role enum (defensive — text[] storage)
  IF EXISTS (
    SELECT 1 FROM unnest(p_required_approver_roles) r
    WHERE r NOT IN ('owner','procurement_admin','project_lead','viewer')
  ) THEN
    RAISE EXCEPTION 'required_approver_roles contains an unknown org_member_role' USING ERRCODE = '22000';
  END IF;

  v_currency := p_currency::public.currency_code;

  IF p_scope_department_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.departments
       WHERE id = p_scope_department_id AND org_id = p_org_id
    ) THEN
      RAISE EXCEPTION 'scope_department_id does not belong to this organization' USING ERRCODE = '22000';
    END IF;
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO public.approval_policies (
      org_id, name, min_amount_cents, max_amount_cents, currency,
      required_approver_roles, min_approvers_count, requires_sod,
      scope_department_id, is_active, created_by
    ) VALUES (
      p_org_id, trim(p_name), p_min_amount_cents, p_max_amount_cents, v_currency,
      p_required_approver_roles, p_min_approvers_count, p_requires_sod,
      p_scope_department_id, p_is_active, v_actor
    )
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.approval_policies
       SET name                    = trim(p_name),
           min_amount_cents        = p_min_amount_cents,
           max_amount_cents        = p_max_amount_cents,
           currency                = v_currency,
           required_approver_roles = p_required_approver_roles,
           min_approvers_count     = p_min_approvers_count,
           requires_sod            = p_requires_sod,
           scope_department_id     = p_scope_department_id,
           is_active               = p_is_active,
           updated_at              = now()
     WHERE id = p_id AND org_id = p_org_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Approval policy not found' USING ERRCODE = 'P0002';
    END IF;
    v_id := p_id;
  END IF;

  IF to_regclass('public.audit_events') IS NOT NULL THEN
    SELECT actor_role, actor_label INTO v_actor_role, v_actor_lbl
      FROM public._dept_actor_profile(v_actor);

    INSERT INTO public.audit_events (
      event_type, actor_id, actor_role, actor_label,
      subject_table, subject_id, summary, delta, metadata, correlation_id
    ) VALUES (
      format('approval_policy.%s', v_op),
      v_actor, v_actor_role, v_actor_lbl,
      'approval_policies', v_id,
      format('Approval policy %L %s: %s %s..%s',
        trim(p_name), v_op, v_currency,
        (p_min_amount_cents::numeric / 100)::text,
        COALESCE((p_max_amount_cents::numeric / 100)::text, '∞')),
      jsonb_build_object(
        'min_amount_cents', p_min_amount_cents,
        'max_amount_cents', p_max_amount_cents,
        'currency', v_currency,
        'required_approver_roles', p_required_approver_roles,
        'min_approvers_count', p_min_approvers_count,
        'requires_sod', p_requires_sod
      ),
      jsonb_build_object('org_id', p_org_id),
      v_correlation
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'policy_id', v_id,
    'org_id', p_org_id,
    'correlation_id', v_correlation
  );
END;
$$;


ALTER FUNCTION "public"."set_approval_policy"("p_org_id" "uuid", "p_name" "text", "p_min_amount_cents" bigint, "p_max_amount_cents" bigint, "p_currency" "text", "p_required_approver_roles" "text"[], "p_min_approvers_count" integer, "p_requires_sod" boolean, "p_scope_department_id" "uuid", "p_is_active" boolean, "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_default_template"("p_template_id" "uuid") RETURNS "public"."report_templates"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_tpl   public.report_templates;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_tpl FROM public.report_templates
   WHERE id = p_template_id
     AND deleted_at IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Template % not found', p_template_id USING ERRCODE = 'P0002';
  END IF;
  IF v_tpl.owner_id <> v_actor AND NOT is_super_admin() THEN
    RAISE EXCEPTION 'Not the owner of this template' USING ERRCODE = '42501';
  END IF;

  -- Clear any other default in the same (scope, owner) group
  UPDATE public.report_templates
     SET is_default = false, updated_at = now()
   WHERE owner_id   = v_tpl.owner_id
     AND scope      = v_tpl.scope
     AND is_default = true
     AND id <> v_tpl.id;

  -- Set this one as default
  UPDATE public.report_templates
     SET is_default = true, updated_at = now()
   WHERE id = p_template_id
  RETURNING * INTO v_tpl;

  RETURN v_tpl;
END;
$$;


ALTER FUNCTION "public"."set_default_template"("p_template_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_department_budget"("p_department_id" "uuid", "p_fiscal_period_start" "date", "p_fiscal_period_end" "date", "p_currency" "text", "p_allocated_cents" bigint, "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor      uuid := auth.uid();
  v_actor_role text;
  v_actor_lbl  text;
  v_org_id     uuid;
  v_currency   public.currency_code;
  v_id         uuid;
  v_existing   record;
  v_correlation uuid := gen_random_uuid();
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT org_id INTO v_org_id FROM public.departments WHERE id = p_department_id;
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Department not found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.can_manage_org_structure(v_org_id, v_actor) THEN
    RAISE EXCEPTION 'You do not have permission to set budgets for this organization'
      USING ERRCODE = '42501';
  END IF;

  IF p_allocated_cents IS NULL OR p_allocated_cents < 0 THEN
    RAISE EXCEPTION 'allocated_cents must be >= 0 (got %)', p_allocated_cents USING ERRCODE = '22000';
  END IF;
  IF p_fiscal_period_end <= p_fiscal_period_start THEN
    RAISE EXCEPTION 'fiscal_period_end must be after fiscal_period_start' USING ERRCODE = '22000';
  END IF;

  v_currency := p_currency::public.currency_code;

  -- Capture existing for the audit delta.
  SELECT id, allocated_cents, currency
    INTO v_existing
    FROM public.department_budgets
   WHERE department_id = p_department_id
     AND fiscal_period_start = p_fiscal_period_start
     AND fiscal_period_end   = p_fiscal_period_end
   FOR UPDATE;

  IF v_existing.id IS NULL THEN
    INSERT INTO public.department_budgets (
      org_id, department_id, fiscal_period_start, fiscal_period_end,
      currency, allocated_cents, notes, created_by
    ) VALUES (
      v_org_id, p_department_id, p_fiscal_period_start, p_fiscal_period_end,
      v_currency, p_allocated_cents, p_notes, v_actor
    )
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.department_budgets
       SET currency        = v_currency,
           allocated_cents = p_allocated_cents,
           notes           = p_notes,
           updated_at      = now()
     WHERE id = v_existing.id;
    v_id := v_existing.id;
  END IF;

  -- Audit
  IF to_regclass('public.audit_events') IS NOT NULL THEN
    SELECT actor_role, actor_label INTO v_actor_role, v_actor_lbl
      FROM public._dept_actor_profile(v_actor);

    INSERT INTO public.audit_events (
      event_type, actor_id, actor_role, actor_label,
      subject_table, subject_id, summary, delta, metadata, correlation_id
    ) VALUES (
      CASE WHEN v_existing.id IS NULL THEN 'department.budget.created' ELSE 'department.budget.updated' END,
      v_actor, v_actor_role, v_actor_lbl,
      'department_budgets', v_id,
      format('Department budget %s for %L..%L: %s %s',
        CASE WHEN v_existing.id IS NULL THEN 'created' ELSE 'updated' END,
        p_fiscal_period_start, p_fiscal_period_end, v_currency,
        (p_allocated_cents::numeric / 100)::text),
      jsonb_build_object(
        'from_allocated_cents', v_existing.allocated_cents,
        'to_allocated_cents',   p_allocated_cents,
        'currency',             v_currency,
        'period_start',         p_fiscal_period_start,
        'period_end',           p_fiscal_period_end
      ),
      jsonb_build_object('org_id', v_org_id, 'department_id', p_department_id),
      v_correlation
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'budget_id', v_id,
    'org_id', v_org_id,
    'department_id', p_department_id,
    'allocated_cents', p_allocated_cents,
    'currency', v_currency,
    'correlation_id', v_correlation
  );
END;
$$;


ALTER FUNCTION "public"."set_department_budget"("p_department_id" "uuid", "p_fiscal_period_start" "date", "p_fiscal_period_end" "date", "p_currency" "text", "p_allocated_cents" bigint, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_dispute_resolved_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF NEW.status IN ('resolved', 'rejected') AND OLD.status NOT IN ('resolved', 'rejected') THEN
        NEW.resolved_at = NOW();
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_dispute_resolved_at"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."profiles" (
    "id" "uuid" NOT NULL,
    "email" "text" NOT NULL,
    "role" "text" DEFAULT 'client'::"text" NOT NULL,
    "full_name" "text",
    "avatar_url" "text",
    "terms_accepted" boolean DEFAULT false,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "company_name" "text",
    "professional_title" "text",
    "first_name" "text",
    "last_name" "text",
    "phone" "text",
    "bio" "text",
    "specialties" "text",
    "years_of_experience" "text",
    "is_verified" boolean DEFAULT false,
    "headline" "text",
    "title" "text",
    "skills" "text"[] DEFAULT '{}'::"text"[],
    "resume_url" "text",
    "rating_average" numeric DEFAULT 0,
    "reviews_count" integer DEFAULT 0,
    "completed_jobs_count" integer DEFAULT 0,
    "balance_cents" bigint DEFAULT 0,
    "cv_url" "text",
    "verification_status" "text" DEFAULT 'unverified'::"text",
    "verified_at" timestamp with time zone,
    "verified_by" "uuid",
    "location" "text",
    "rejection_reason" "text",
    "push_token" "text",
    "unread_notifications_count" integer DEFAULT 0,
    "avg_rating" numeric(3,2) DEFAULT 0.0,
    "total_reviews" integer DEFAULT 0,
    "organization_id" "uuid",
    "status" "text" DEFAULT 'active'::"text",
    "last_active" timestamp with time zone DEFAULT "now"(),
    "current_project" "text",
    "rating" numeric(3,2) DEFAULT 0,
    "experience_years" integer DEFAULT 0,
    "referral_code" "text",
    "company_logo_url" "text",
    "report_header_text" "text",
    "report_footer_text" "text",
    "use_custom_branding" boolean DEFAULT false,
    "stripe_connect_id" "text",
    "hourly_rate_cents" bigint,
    "ndt_methods" "text"[] DEFAULT '{}'::"text"[],
    "certifications" "text"[] DEFAULT '{}'::"text"[],
    "location_city" "text",
    "location_province" "text",
    "response_time_hours" integer DEFAULT 24,
    "rating_count" integer DEFAULT 0,
    "is_available" boolean DEFAULT true,
    "availability_status" "text" DEFAULT 'offline'::"text",
    "recommend_percent" integer DEFAULT 0,
    "total_jobs" integer DEFAULT 0,
    "latitude" double precision,
    "longitude" double precision,
    "geog" "public"."geography"(Point,4326) GENERATED ALWAYS AS (
CASE
    WHEN (("latitude" IS NOT NULL) AND ("longitude" IS NOT NULL)) THEN ("public"."st_setsrid"("public"."st_makepoint"("longitude", "latitude"), 4326))::"public"."geography"
    ELSE NULL::"public"."geography"
END) STORED,
    "daily_application_limit" integer,
    "stripe_connect_status" "text" DEFAULT 'not_connected'::"text",
    "stripe_connect_payouts_enabled" boolean DEFAULT false,
    "stripe_connect_onboarded_at" timestamp with time zone,
    "home_base_lat" numeric(9,6),
    "home_base_lng" numeric(9,6),
    "home_base_label" "text",
    "travel_radius_km" integer,
    "specialty_slugs" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "country_of_residence" "text",
    "work_authorized_countries" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "open_to_sponsored_work" boolean DEFAULT false NOT NULL,
    "sponsored_countries" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "work_auth_verified_at" timestamp with time zone,
    "work_auth_verified_by" "uuid",
    "suspension_reason" "text",
    "suspended_at" timestamp with time zone,
    "suspended_by" "uuid",
    "resume_path" "text",
    "custom_specialties" "text"[] DEFAULT '{}'::"text"[],
    "custom_ndt_methods" "text"[] DEFAULT '{}'::"text"[],
    "contact_person_name" "text",
    "terms_accepted_at" timestamp with time zone,
    "terms_version" "text",
    "onboarding_completed_at" timestamp with time zone,
    "onboarding_role" "text",
    "active_org_id" "uuid",
    "onboarding_checklist_dismissed_at" timestamp with time zone,
    "client_payment_terms" "text" DEFAULT 'prepay'::"text" NOT NULL,
    "client_credit_limit_cents" bigint DEFAULT 0 NOT NULL,
    CONSTRAINT "profiles_home_base_coords_check" CHECK (((("home_base_lat" IS NULL) AND ("home_base_lng" IS NULL)) OR (("home_base_lat" IS NOT NULL) AND ("home_base_lng" IS NOT NULL) AND (("home_base_lat" >= ('-90'::integer)::numeric) AND ("home_base_lat" <= (90)::numeric)) AND (("home_base_lng" >= ('-180'::integer)::numeric) AND ("home_base_lng" <= (180)::numeric))))),
    CONSTRAINT "profiles_role_allowed" CHECK (("role" = ANY (ARRAY['inspector'::"text", 'client'::"text", 'agency'::"text", 'enterprise'::"text", 'supplier'::"text", 'senior'::"text", 'admin'::"text", 'super_admin'::"text"]))),
    CONSTRAINT "profiles_sponsored_countries_cap" CHECK (("cardinality"("sponsored_countries") <= 60)),
    CONSTRAINT "profiles_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'suspended'::"text"]))),
    CONSTRAINT "profiles_stripe_connect_status_check" CHECK (("stripe_connect_status" = ANY (ARRAY['not_connected'::"text", 'pending'::"text", 'verified'::"text", 'restricted'::"text", 'disabled'::"text"]))),
    CONSTRAINT "profiles_travel_radius_km_check" CHECK ((("travel_radius_km" IS NULL) OR ("travel_radius_km" > 0))),
    CONSTRAINT "profiles_verification_status_check" CHECK (("verification_status" = ANY (ARRAY['unverified'::"text", 'pending'::"text", 'verified'::"text", 'rejected'::"text"]))),
    CONSTRAINT "profiles_verified_pair_or_neither" CHECK (((("work_auth_verified_at" IS NULL) AND ("work_auth_verified_by" IS NULL)) OR (("work_auth_verified_at" IS NOT NULL) AND ("work_auth_verified_by" IS NOT NULL)))),
    CONSTRAINT "profiles_work_authorized_countries_cap" CHECK (("cardinality"("work_authorized_countries") <= 60))
);


ALTER TABLE "public"."profiles" OWNER TO "postgres";


COMMENT ON COLUMN "public"."profiles"."stripe_connect_id" IS 'Stripe Connect Custom Account ID, created lazily on first approved payout';



COMMENT ON COLUMN "public"."profiles"."daily_application_limit" IS 'Per-inspector daily application cap. NULL = use system default (6). Set by super-admin via set_inspector_daily_limit() RPC.';



COMMENT ON COLUMN "public"."profiles"."home_base_lat" IS 'Inspector home base latitude (decimal degrees). NULL until set.';



COMMENT ON COLUMN "public"."profiles"."home_base_lng" IS 'Inspector home base longitude (decimal degrees). NULL until set.';



COMMENT ON COLUMN "public"."profiles"."home_base_label" IS 'Display label for the home base (e.g. "Montreal, QC").';



COMMENT ON COLUMN "public"."profiles"."travel_radius_km" IS 'Inspector travel radius in km. NULL = unlimited (will travel anywhere).';



COMMENT ON COLUMN "public"."profiles"."specialty_slugs" IS 'Canonical specialty taxonomy slugs (see src/data/specialties.ts). Set by inspectors in profile edit. Supersedes the legacy free-form profiles.specialties text column for matching purposes; the legacy column is retained for backward compatibility but no longer authoritative.';



COMMENT ON COLUMN "public"."profiles"."country_of_residence" IS 'JURISDICTION-001: Inspector tax home (ISO 3166-1 α-2). Drives 1099/W-8BEN selection in a future strike. NULL until declared.';



COMMENT ON COLUMN "public"."profiles"."work_authorized_countries" IS 'JURISDICTION-001: Atomic ISO codes where the inspector can legally accept paid work WITHOUT sponsorship. Empty array is legal (none declared yet).';



COMMENT ON COLUMN "public"."profiles"."open_to_sponsored_work" IS 'JURISDICTION-001: True iff inspector accepts jobs that require client-paid visa/relocation.';



COMMENT ON COLUMN "public"."profiles"."sponsored_countries" IS 'JURISDICTION-001: Optional preferred sponsored destinations. Empty + open_to_sponsored_work=true means "anywhere with sponsorship".';



COMMENT ON COLUMN "public"."profiles"."work_auth_verified_at" IS 'JURISDICTION-001: Set by super_admin after document review. Trust signal — never a gate (Phase 5).';



COMMENT ON COLUMN "public"."profiles"."active_org_id" IS 'The user''s currently-selected organization context. Drives which org''s data is shown on /client/structure, /client/budget, /client/jobs/new, etc. NULL = use the election fallback (elevated-role > enterprise > first-of-any).';



COMMENT ON COLUMN "public"."profiles"."onboarding_checklist_dismissed_at" IS 'When the user clicked Dismiss on the post-signup onboarding checklist widget. NULL = checklist is still visible (default). Per-step completion is derived at read time from other columns / related tables; only this dismissal flag is persisted.';



COMMENT ON COLUMN "public"."profiles"."client_payment_terms" IS 'B2B credit posture this client gets when POSTING jobs: prepay (default, unvetted) or net_15/30/45/60 (granted privilege). Separate from profiles.payment_terms which is the inspector rate-card term.';



COMMENT ON COLUMN "public"."profiles"."client_credit_limit_cents" IS 'Max outstanding (invoiced-but-unsettled) net_terms exposure NEXPEC will extend this client. 0 = no credit (prepay only).';



CREATE OR REPLACE FUNCTION "public"."set_inspector_daily_limit"("p_user_id" "uuid", "p_new_limit" integer) RETURNS "public"."profiles"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_profile public.profiles;
BEGIN
  IF NOT is_super_admin() THEN
    RAISE EXCEPTION 'Only super-admins can change application limits'
      USING ERRCODE = '42501';
  END IF;

  IF p_new_limit IS NOT NULL AND p_new_limit < 0 THEN
    RAISE EXCEPTION 'Limit must be NULL or non-negative (got %)', p_new_limit
      USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.profiles
     SET daily_application_limit = p_new_limit,
         updated_at = now()
   WHERE id = p_user_id
  RETURNING * INTO v_profile;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'User % not found', p_user_id USING ERRCODE = 'P0002';
  END IF;

  RETURN v_profile;
END;
$$;


ALTER FUNCTION "public"."set_inspector_daily_limit"("p_user_id" "uuid", "p_new_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_org_base_currency"("p_org_id" "uuid", "p_currency" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor      uuid := auth.uid();
  v_actor_role text;
  v_actor_lbl  text;
  v_old        public.currency_code;
  v_new        public.currency_code;
  v_correlation uuid := gen_random_uuid();
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.can_manage_org_structure(p_org_id, v_actor) THEN
    RAISE EXCEPTION 'You do not have permission to change this organization''s base currency'
      USING ERRCODE = '42501';
  END IF;

  BEGIN
    v_new := p_currency::public.currency_code;
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'Unsupported currency: %', p_currency USING ERRCODE = '22000';
  END;

  SELECT base_currency INTO v_old
    FROM public.organizations WHERE id = p_org_id FOR UPDATE;

  IF v_old IS NULL THEN
    RAISE EXCEPTION 'Organization not found' USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.organizations
     SET base_currency = v_new,
         updated_at = now()
   WHERE id = p_org_id;

  -- Best-effort audit.
  IF to_regclass('public.audit_events') IS NOT NULL THEN
    SELECT actor_role, actor_label INTO v_actor_role, v_actor_lbl
      FROM public._dept_actor_profile(v_actor);

    INSERT INTO public.audit_events (
      event_type, actor_id, actor_role, actor_label,
      subject_table, subject_id, summary, delta, metadata, correlation_id
    ) VALUES (
      'organization.base_currency.changed',
      v_actor,
      v_actor_role,
      v_actor_lbl,
      'organizations',
      p_org_id,
      format('Org base currency changed: %s → %s', v_old, v_new),
      jsonb_build_object('from', v_old, 'to', v_new),
      jsonb_build_object('org_id', p_org_id),
      v_correlation
    );
  END IF;

  RETURN jsonb_build_object(
    'ok',            true,
    'org_id',        p_org_id,
    'base_currency', v_new,
    'from',          v_old,
    'correlation_id', v_correlation
  );
END;
$$;


ALTER FUNCTION "public"."set_org_base_currency"("p_org_id" "uuid", "p_currency" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_project_client_id"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  IF NEW.client_id IS NULL THEN
    NEW.client_id := auth.uid();
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_project_client_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."settle_client_payment"("p_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_job public.jobs%ROWTYPE;
  v_inspector uuid;
  v_cents bigint;
  v_dollars numeric(12,2);
  v_adv public.payout_advances%ROWTYPE;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.nx_is_admin() THEN
    RAISE EXCEPTION 'NOT_AUTHORIZED' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_job FROM public.jobs WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'JOB_NOT_FOUND' USING ERRCODE = 'P0002'; END IF;
  IF v_job.client_settled_at IS NOT NULL THEN
    RETURN jsonb_build_object('ok', true, 'idempotent', true, 'job_id', p_job_id);  -- already settled
  END IF;

  v_inspector := v_job.contractor_id;
  v_cents := COALESCE(v_job.inspector_payout_cents, 0);
  v_dollars := round(v_cents::numeric / 100.0, 2);

  -- If an advance was already funded for this job, the inspector was paid net
  -- early from pending; settling just recovers it (platform keeps the client cash).
  SELECT * INTO v_adv FROM public.payout_advances
    WHERE job_id = p_job_id AND status = 'funded' ORDER BY funded_at DESC LIMIT 1;

  IF v_inspector IS NOT NULL AND v_cents > 0 AND v_adv.id IS NULL
     AND COALESCE(v_job.payment_mode,'prepay') = 'net_terms' THEN
    INSERT INTO public.wallets(user_id) VALUES (v_inspector) ON CONFLICT (user_id) DO NOTHING;
    PERFORM 1 FROM public.wallets WHERE user_id = v_inspector FOR UPDATE;
    UPDATE public.wallets
       SET pending_amount    = GREATEST(COALESCE(pending_amount,0) - v_dollars, 0),
           available_balance = COALESCE(available_balance,0) + v_dollars,
           updated_at = now()
     WHERE user_id = v_inspector;
    INSERT INTO public.transactions(user_id, inspector_id, job_id, type, amount,
          gross_amount_halalas, platform_fee_halalas, net_amount_halalas, status, description)
    VALUES (v_inspector, v_inspector, p_job_id, 'settlement', v_dollars, v_cents, 0, v_cents,
            'completed', 'Client settled — inspector funds cleared to available');
  ELSIF v_adv.id IS NOT NULL THEN
    UPDATE public.payout_advances SET status = 'recovered', recovered_at = now(), updated_at = now()
     WHERE id = v_adv.id;
  END IF;

  UPDATE public.jobs SET client_settled_at = now(), updated_at = now() WHERE id = p_job_id;
  RETURN jsonb_build_object('ok', true, 'job_id', p_job_id, 'cleared_cents', v_cents, 'advance_recovered', (v_adv.id IS NOT NULL));
END $$;


ALTER FUNCTION "public"."settle_client_payment"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."shortlist_application"("p_application_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  UPDATE public.applications a
  SET status = 'shortlisted', updated_at = NOW()
  FROM public.jobs j
  WHERE a.id = p_application_id 
    AND a.job_id = j.id 
    AND j.client_id = auth.uid()
    AND a.status = 'pending';
END;
$$;


ALTER FUNCTION "public"."shortlist_application"("p_application_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."should_deliver"("p_recipient" "uuid", "p_kind" "text", "p_channel" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_prefs       jsonb;
  v_channel_key text;
  v_cat_key     text;
BEGIN
  -- The in-app bell is always reliable.
  IF p_channel = 'in_app' THEN RETURN true; END IF;
  -- Defensive: unknown recipient/kind must never be suppressed.
  IF p_recipient IS NULL OR p_kind IS NULL THEN RETURN true; END IF;
  -- Hard-critical safety/security always delivers on every channel.
  IF p_kind IN ('system','system_updates','urgent_safety','security') THEN
    RETURN true;
  END IF;

  SELECT preferences INTO v_prefs
    FROM public.notification_preferences
   WHERE user_id = p_recipient;

  -- No prefs row → opt-out default = deliver.
  IF v_prefs IS NULL THEN RETURN true; END IF;

  -- Master channel switch (default ON; SMS defaults OFF to match the UI).
  v_channel_key := CASE p_channel
                     WHEN 'push'  THEN 'push_notifications'
                     WHEN 'email' THEN 'email_notifications'
                     WHEN 'sms'   THEN 'sms_alerts'
                     ELSE NULL END;
  IF v_channel_key IS NOT NULL
     AND COALESCE((v_prefs ->> v_channel_key)::boolean,
                  CASE WHEN p_channel = 'sms' THEN false ELSE true END) IS FALSE
  THEN
    RETURN false;
  END IF;

  -- Map notification kind → UI category toggle id.
  v_cat_key := CASE p_kind
    WHEN 'message'            THEN 'new_message'
    WHEN 'new_message'        THEN 'new_message'
    WHEN 'payout_released'    THEN 'payout_processed'
    WHEN 'payout_processed'   THEN 'payout_processed'
    WHEN 'assignment'         THEN 'contract_assigned'
    WHEN 'contract_assigned'  THEN 'contract_assigned'
    WHEN 'report_submitted'   THEN 'report_approved_rejected'
    WHEN 'report_approved'    THEN 'report_approved_rejected'
    WHEN 'document_uploaded'  THEN 'document_uploaded'
    WHEN 'application_status'  THEN 'new_applicant'
    WHEN 'invoice'            THEN 'invoice_generated'
    WHEN 'invoice_generated'  THEN 'invoice_generated'
    ELSE NULL END;

  -- Unknown/transactional kind → governed only by the master switch above.
  IF v_cat_key IS NULL THEN RETURN true; END IF;

  RETURN COALESCE((v_prefs ->> v_cat_key)::boolean, true);
EXCEPTION WHEN OTHERS THEN
  -- FAIL OPEN — a consent-predicate error must never silently drop a message.
  RETURN true;
END
$$;


ALTER FUNCTION "public"."should_deliver"("p_recipient" "uuid", "p_kind" "text", "p_channel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sign_agreement"("p_agreement_id" "uuid", "p_signed_name" "text", "p_ip" "text" DEFAULT NULL::"text", "p_user_agent" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_a   public.agreements;
  v_d   public.deals;
  v_q   public.supplier_quotes;
  v_role text;
  v_job public.jobs;
  v_cost bigint;
  v_deposit bigint;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT * INTO v_a FROM public.agreements WHERE id = p_agreement_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown_agreement'; END IF;
  IF NOT (v_a.counterparty_id = v_uid OR public.nx_is_admin()) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF v_a.status <> 'presented' THEN RAISE EXCEPTION 'AGREEMENT_NOT_PRESENTED: status=%', v_a.status; END IF;

  v_role := CASE v_a.kind WHEN 'client_supply' THEN 'client'
                          WHEN 'supplier_supply' THEN 'supplier'
                          WHEN 'disclosure_amendment' THEN 'client'
                          ELSE 'inspector' END;

  INSERT INTO public.agreement_signatures (agreement_id, signer_id, party_role, signed_name, signed_sha256, ip, user_agent)
  VALUES (p_agreement_id, v_uid, v_role, p_signed_name, v_a.content_sha256, p_ip, p_user_agent);

  UPDATE public.agreements
     SET status = 'executed', signed_at = now(), countersigned_at = now(), executed_at = now()
   WHERE id = p_agreement_id;

  IF v_a.kind = 'client_supply' THEN
    SELECT * INTO v_d FROM public.deals WHERE id = v_a.deal_id FOR UPDATE;
    PERFORM public._brokered_ensure_payment_schedule(v_d.id, v_d.client_price_cents, v_d.currency);

    -- HYBRID FUNDING: hold the 30% mobilization deposit now; balance at FAT-readiness.
    v_deposit := (round(coalesce(v_d.client_price_cents,0) * 0.30))::bigint;
    INSERT INTO public.deal_money_legs (deal_id, agreement_id, kind, amount_cents, currency, status)
    VALUES (v_d.id, v_a.id, 'client_escrow_in', v_deposit, v_d.currency, 'held')
    ON CONFLICT (deal_id, kind) DO NOTHING;
    UPDATE public.deals SET deposit_funded_at = COALESCE(deposit_funded_at, now()), status = 'funded' WHERE id = v_d.id;

    IF v_d.awarded_quote_id IS NOT NULL THEN
      SELECT * INTO v_q FROM public.supplier_quotes WHERE id = v_d.awarded_quote_id;
      BEGIN
        v_job := public.award_quote(v_d.awarded_quote_id);
      EXCEPTION WHEN OTHERS THEN v_job := NULL;
      END;
      IF v_job.id IS NOT NULL THEN
        UPDATE public.deals SET job_id = v_job.id WHERE id = v_d.id;
        UPDATE public.jobs  SET escrow_status = 'funded' WHERE id = v_job.id;
      END IF;

      v_cost := public._quote_raw_cents(v_q.quote);
      INSERT INTO public.agreements (deal_id, kind, status, counterparty_id, amount_cents, currency, generated_by)
      VALUES (v_d.id, 'supplier_supply', 'draft', v_q.supplier_id, coalesce(v_cost,0), v_d.currency, v_uid)
      ON CONFLICT (deal_id, kind, version) DO NOTHING;
    END IF;

    UPDATE public.deals SET status = 'dispatched' WHERE id = v_d.id;

  ELSIF v_a.kind = 'disclosure_amendment' THEN
    -- Layer E: collect the premium fee (ledger), upgrade tier, and lift identity escrow EARLY.
    SELECT * INTO v_d FROM public.deals WHERE id = v_a.deal_id FOR UPDATE;
    INSERT INTO public.deal_money_legs (deal_id, agreement_id, kind, amount_cents, currency, status)
    VALUES (v_d.id, v_a.id, 'vip_disclosure_fee', v_a.amount_cents, v_d.currency, 'held')
    ON CONFLICT (deal_id, kind) DO UPDATE
      SET amount_cents = EXCLUDED.amount_cents, agreement_id = EXCLUDED.agreement_id;
    UPDATE public.deals SET transparency_tier = 'named' WHERE id = v_d.id;
    UPDATE public.inspector_engagement_meta
       SET identity_revealed_at = COALESCE(identity_revealed_at, now())
     WHERE deal_id = v_d.id;
  END IF;

  RETURN jsonb_build_object('agreement_id', p_agreement_id, 'status', 'executed',
                            'deal_id', v_a.deal_id, 'job_id', (SELECT job_id FROM public.deals WHERE id = v_a.deal_id));
END $$;


ALTER FUNCTION "public"."sign_agreement"("p_agreement_id" "uuid", "p_signed_name" "text", "p_ip" "text", "p_user_agent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."soft_delete"("p_table" "text", "p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $_$
DECLARE
  allowed text[] := ARRAY[
    'jobs','applications','contracts','messages','inspection_reports'
  ];
BEGIN
  IF NOT (p_table = ANY(allowed)) THEN
    RAISE EXCEPTION 'soft_delete not enabled for table %', p_table
      USING ERRCODE = 'check_violation';
  END IF;
  EXECUTE format(
    'UPDATE public.%I SET deleted_at = now() WHERE id = $1 AND deleted_at IS NULL',
    p_table
  ) USING p_id;
END;
$_$;


ALTER FUNCTION "public"."soft_delete"("p_table" "text", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_inspection_report"("p_job_id" "uuid", "p_photo_url" "text", "p_notes" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    INSERT INTO public.inspection_reports (job_id, inspector_id, photo_url, notes)
    VALUES (p_job_id, auth.uid(), p_photo_url, p_notes)
    ON CONFLICT (job_id, inspector_id) DO UPDATE SET photo_url = EXCLUDED.photo_url, notes = EXCLUDED.notes;
    
    UPDATE public.jobs SET status = 'under_review', updated_at = NOW() WHERE id = p_job_id;
    
    RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."submit_inspection_report"("p_job_id" "uuid", "p_photo_url" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_job_approval"("p_job_id" "uuid", "p_decision" "text", "p_comment" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor       uuid := auth.uid();
  v_actor_role  text;
  v_actor_lbl   text;
  v_request     record;
  v_my_org_role text;
  v_approved_count int;
  v_rejected_count int;
  v_now         timestamptz := now();
  v_correlation uuid := gen_random_uuid();
  v_decision_id uuid;
  v_final       text;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_decision NOT IN ('approved', 'rejected') THEN
    RAISE EXCEPTION 'decision must be approved or rejected' USING ERRCODE = '22000';
  END IF;

  SELECT *
    INTO v_request
    FROM public.approval_requests
   WHERE job_id = p_job_id
   FOR UPDATE;

  IF v_request.id IS NULL THEN
    RAISE EXCEPTION 'No approval request found for this job' USING ERRCODE = 'P0002';
  END IF;

  IF v_request.status <> 'pending' THEN
    RAISE EXCEPTION 'Approval request is already %', v_request.status USING ERRCODE = '22000';
  END IF;

  -- SoD — friendly check (the trigger catches the table-level write too,
  -- but failing here gives a better error message to the UI).
  IF v_request.requires_sod IS TRUE AND v_actor = v_request.requested_by THEN
    RAISE EXCEPTION 'Segregation of Duties: you cannot approve your own request'
      USING ERRCODE = '42501',
            HINT = 'A different authorised approver must decide.';
  END IF;

  -- Authorisation — Platform Owner bypasses role match for override
  -- purposes (audit-visible); otherwise the actor must hold a current
  -- org_members.role that's in the request's required_approver_roles set.
  IF public._actor_is_super_admin() THEN
    v_my_org_role := 'super_admin';
  ELSE
    SELECT m.role::text
      INTO v_my_org_role
      FROM public.org_members m
     WHERE m.org_id  = v_request.org_id
       AND m.user_id = v_actor;

    IF v_my_org_role IS NULL THEN
      RAISE EXCEPTION 'You are not a member of this organization' USING ERRCODE = '42501';
    END IF;

    IF NOT (v_my_org_role = ANY(v_request.required_approver_roles)) THEN
      RAISE EXCEPTION 'Your role (%) is not in the list of permitted approvers (%)',
        v_my_org_role, v_request.required_approver_roles USING ERRCODE = '42501';
    END IF;
  END IF;

  -- Record the decision. The unique-constraint catches duplicates.
  BEGIN
    INSERT INTO public.approval_decisions (
      approval_request_id, decided_by, decided_at, decision, comment, decider_role_at_time
    ) VALUES (
      v_request.id, v_actor, v_now, p_decision, p_comment, v_my_org_role
    )
    RETURNING id INTO v_decision_id;
  EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION 'You have already decided on this request' USING ERRCODE = '23505';
  END;

  -- Recompute counters AFTER the insert.
  SELECT
    COUNT(*) FILTER (WHERE decision = 'approved'),
    COUNT(*) FILTER (WHERE decision = 'rejected')
    INTO v_approved_count, v_rejected_count
    FROM public.approval_decisions
   WHERE approval_request_id = v_request.id;

  -- Resolve final outcome.
  IF v_rejected_count > 0 THEN
    -- Any single rejection short-circuits.
    v_final := 'rejected';
    UPDATE public.approval_requests
       SET status            = 'rejected',
           final_decision_at = v_now,
           final_decision_by = v_actor,
           rejection_reason  = COALESCE(p_comment, 'Rejected by approver'),
           updated_at        = v_now
     WHERE id = v_request.id;
    -- Park the job in cancelled — keeps the timeline visible without
    -- letting it leak into the marketplace.
    UPDATE public.jobs
       SET status = 'cancelled'
     WHERE id = p_job_id;
  ELSIF v_approved_count >= v_request.min_approvers_required THEN
    -- Quorum met — release the job.
    v_final := 'approved';
    UPDATE public.approval_requests
       SET status            = 'approved',
           final_decision_at = v_now,
           final_decision_by = v_actor,
           updated_at        = v_now
     WHERE id = v_request.id;
    UPDATE public.jobs
       SET status = 'open'
     WHERE id = p_job_id;
  ELSE
    v_final := 'pending';
  END IF;

  -- Audit
  IF to_regclass('public.audit_events') IS NOT NULL THEN
    SELECT actor_role, actor_label INTO v_actor_role, v_actor_lbl
      FROM public._dept_actor_profile(v_actor);

    INSERT INTO public.audit_events (
      event_type, actor_id, actor_role, actor_label,
      subject_table, subject_id, summary, delta, metadata, correlation_id, severity
    ) VALUES (
      CASE
        WHEN v_final = 'approved'  THEN 'job.approval.granted'
        WHEN v_final = 'rejected'  THEN 'job.approval.rejected'
        ELSE                            'job.approval.decision_recorded'
      END,
      v_actor, v_actor_role, v_actor_lbl,
      'approval_requests', v_request.id,
      format('%s by %s (role %s)',
        CASE p_decision WHEN 'approved' THEN 'Approval recorded' ELSE 'Rejection recorded' END,
        COALESCE(v_actor_lbl, 'Unknown'), v_my_org_role),
      jsonb_build_object(
        'decision', p_decision,
        'comment',  p_comment,
        'approved_count', v_approved_count,
        'rejected_count', v_rejected_count,
        'min_approvers_required', v_request.min_approvers_required,
        'final', v_final
      ),
      jsonb_build_object(
        'org_id', v_request.org_id,
        'job_id', p_job_id,
        'request_id', v_request.id
      ),
      v_correlation,
      CASE WHEN v_final = 'rejected' THEN 'warning' ELSE 'info' END
    );
  END IF;

  RETURN jsonb_build_object(
    'ok',              true,
    'decision_id',     v_decision_id,
    'request_id',      v_request.id,
    'final',           v_final,
    'approved_count',  v_approved_count,
    'rejected_count',  v_rejected_count,
    'min_required',    v_request.min_approvers_required,
    'correlation_id',  v_correlation
  );
END;
$$;


ALTER FUNCTION "public"."submit_job_approval"("p_job_id" "uuid", "p_decision" "text", "p_comment" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."supplier_quotes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "rfq_id" "uuid" NOT NULL,
    "supplier_id" "uuid" NOT NULL,
    "quote" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" "text" DEFAULT 'submitted'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "client_price_cents" bigint,
    "presented_at" timestamp with time zone,
    "presented_by" "uuid",
    "admin_note" "text",
    CONSTRAINT "supplier_quotes_status_check" CHECK (("status" = ANY (ARRAY['submitted'::"text", 'shortlisted'::"text", 'presented'::"text", 'accepted'::"text", 'declined'::"text", 'withdrawn'::"text"])))
);


ALTER TABLE "public"."supplier_quotes" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_quote"("p_rfq_id" "uuid", "p_quote" "jsonb") RETURNS "public"."supplier_quotes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_row public.supplier_quotes;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.supplier_profiles WHERE id = v_uid AND is_active) THEN RAISE EXCEPTION 'not_a_supplier'; END IF;
  -- accept bids while the RFQ is still collecting: open OR already quoted (many suppliers + resubmits)
  IF NOT EXISTS (SELECT 1 FROM public.supplier_rfqs WHERE id = p_rfq_id AND status IN ('open','quoted')) THEN RAISE EXCEPTION 'rfq_not_open'; END IF;
  INSERT INTO public.supplier_quotes (rfq_id, supplier_id, quote)
  VALUES (p_rfq_id, v_uid, coalesce(p_quote,'{}'))
  ON CONFLICT (rfq_id, supplier_id) DO UPDATE SET quote=EXCLUDED.quote, status='submitted', created_at=now()
  RETURNING * INTO v_row;
  UPDATE public.supplier_rfqs SET status='quoted' WHERE id = p_rfq_id AND status='open';
  RETURN v_row;
END $$;


ALTER FUNCTION "public"."submit_quote"("p_rfq_id" "uuid", "p_quote" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_review"("p_job_id" "uuid", "p_reviewee_id" "uuid", "p_rating" integer, "p_comment" "text" DEFAULT NULL::"text", "p_is_public" boolean DEFAULT true, "p_private_admin_note" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_reviewer_id          uuid;
  v_job                  public.jobs%ROWTYPE;
  v_reviewer_role        text;
  v_reviewee_role        text;
  v_reviewer_verified    boolean;
  v_reviewer_jobs        integer;
  v_weight               numeric;
  v_review_id            uuid;
  v_client_id_for_legacy uuid;
  v_inspector_id_for_legacy uuid;
BEGIN
  v_reviewer_id := auth.uid();
  IF v_reviewer_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  IF p_rating IS NULL OR p_rating < 1 OR p_rating > 5 THEN
    RAISE EXCEPTION 'Rating must be between 1 and 5' USING ERRCODE = '22000';
  END IF;
  IF p_reviewee_id IS NULL THEN
    RAISE EXCEPTION 'Reviewee is required' USING ERRCODE = '22000';
  END IF;
  IF v_reviewer_id = p_reviewee_id THEN
    RAISE EXCEPTION 'Cannot review yourself' USING ERRCODE = '22000';
  END IF;

  -- Load job
  SELECT * INTO v_job FROM public.jobs WHERE id = p_job_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Job not found' USING ERRCODE = '02000';
  END IF;

  -- Strict gatekeeping: admin-confirmed completion only
  IF v_job.status <> 'completed' OR v_job.admin_confirmed_at IS NULL THEN
    RAISE EXCEPTION 'Job must be fully completed (admin-confirmed) before review' USING ERRCODE = '22000';
  END IF;

  -- Reviewer must be a party
  IF v_reviewer_id NOT IN (
    COALESCE(v_job.client_id,     '00000000-0000-0000-0000-000000000000'::uuid),
    COALESCE(v_job.agency_id,     '00000000-0000-0000-0000-000000000000'::uuid),
    COALESCE(v_job.contractor_id, '00000000-0000-0000-0000-000000000000'::uuid)
  ) THEN
    RAISE EXCEPTION 'Only parties to the job can submit reviews' USING ERRCODE = '42501';
  END IF;

  -- Reviewee must also be a party (the OTHER party — checked via inequality above)
  IF p_reviewee_id NOT IN (
    COALESCE(v_job.client_id,     '00000000-0000-0000-0000-000000000000'::uuid),
    COALESCE(v_job.agency_id,     '00000000-0000-0000-0000-000000000000'::uuid),
    COALESCE(v_job.contractor_id, '00000000-0000-0000-0000-000000000000'::uuid)
  ) THEN
    RAISE EXCEPTION 'Reviewee was not a party to this job' USING ERRCODE = '22000';
  END IF;

  -- Snapshot reviewer + reviewee roles + verification
  SELECT COALESCE(role, 'client'), COALESCE(is_verified, false)
    INTO v_reviewer_role, v_reviewer_verified
  FROM public.profiles WHERE id = v_reviewer_id;
  v_reviewer_role := COALESCE(v_reviewer_role, 'client');

  SELECT COALESCE(role, 'inspector') INTO v_reviewee_role
  FROM public.profiles WHERE id = p_reviewee_id;
  v_reviewee_role := COALESCE(v_reviewee_role, 'inspector');

  -- Count reviewer's completed jobs across roles (party = client OR agency OR contractor)
  SELECT COUNT(*) INTO v_reviewer_jobs
  FROM public.jobs
  WHERE status = 'completed'
    AND (
         client_id     = v_reviewer_id
      OR agency_id     = v_reviewer_id
      OR contractor_id = v_reviewer_id
    );

  v_weight := public.compute_review_weight(v_reviewer_verified, v_reviewer_jobs, v_reviewer_role);

  -- Populate legacy inspector_id / client_id based on roles.
  IF v_reviewer_role = 'inspector' THEN
    v_inspector_id_for_legacy := v_reviewer_id;
    v_client_id_for_legacy    := p_reviewee_id;
  ELSE
    v_inspector_id_for_legacy := p_reviewee_id;
    v_client_id_for_legacy    := v_reviewer_id;
  END IF;

  BEGIN
    INSERT INTO public.reviews (
      job_id,
      client_id, inspector_id,                    -- legacy mirror
      reviewer_id, reviewee_id,
      reviewer_role_snap, reviewee_role_snap,
      reviewer_verified_snap, reviewer_jobs_count_snap, weight,
      rating, comment, is_public, private_admin_note,
      moderation_status
    ) VALUES (
      p_job_id,
      v_client_id_for_legacy, v_inspector_id_for_legacy,
      v_reviewer_id, p_reviewee_id,
      v_reviewer_role, v_reviewee_role,
      v_reviewer_verified, v_reviewer_jobs, v_weight,
      p_rating,
      NULLIF(TRIM(COALESCE(p_comment, '')), ''),
      COALESCE(p_is_public, true),
      NULLIF(TRIM(COALESCE(p_private_admin_note, '')), ''),
      'visible'
    )
    RETURNING id INTO v_review_id;
  EXCEPTION
    WHEN unique_violation THEN
      RAISE EXCEPTION 'You have already reviewed this job' USING ERRCODE = '23505';
  END;

  RETURN v_review_id;
END;
$$;


ALTER FUNCTION "public"."submit_review"("p_job_id" "uuid", "p_reviewee_id" "uuid", "p_rating" integer, "p_comment" "text", "p_is_public" boolean, "p_private_admin_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."submit_review"("p_job_id" "uuid", "p_reviewee_id" "uuid", "p_rating" integer, "p_comment" "text", "p_is_public" boolean, "p_private_admin_note" "text") IS 'Canonical entry point for submitting a review. Validates job completion + party membership, snapshots reviewer attributes, computes weight. Returns the new review id.';



