    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.supplier_quotes
     WHERE rfq_id = p_rfq AND supplier_id = p_uid
  );
$$;


