CREATE OR REPLACE FUNCTION "public"."supplier_onboard"("p_legal_name" "text", "p_capabilities" "text"[] DEFAULT '{}'::"text"[], "p_attributes" "jsonb" DEFAULT '{}'::"jsonb", "p_lat" double precision DEFAULT NULL::double precision, "p_lng" double precision DEFAULT NULL::double precision, "p_country" "text" DEFAULT NULL::"text", "p_headline" "text" DEFAULT NULL::"text") RETURNS "public"."supplier_profiles"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_row public.supplier_profiles;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF coalesce(p_legal_name,'') = '' THEN RAISE EXCEPTION 'legal_name_required'; END IF;

  INSERT INTO public.supplier_profiles (id, legal_name, headline, capabilities, attributes, geo_lat, geo_lng, country_code)
  VALUES (v_uid, p_legal_name, nullif(btrim(coalesce(p_headline,'')), ''), coalesce(p_capabilities,'{}'),
          coalesce(p_attributes,'{}'), p_lat, p_lng, p_country)
  ON CONFLICT (id) DO UPDATE SET
    legal_name   = EXCLUDED.legal_name,
    headline     = EXCLUDED.headline,
    capabilities = EXCLUDED.capabilities,
    attributes   = EXCLUDED.attributes,
    geo_lat      = EXCLUDED.geo_lat,
    geo_lng      = EXCLUDED.geo_lng,
    country_code = EXCLUDED.country_code,
    updated_at   = now()
  RETURNING * INTO v_row;

  RETURN v_row;
END $$;


ALTER FUNCTION "public"."supplier_onboard"("p_legal_name" "text", "p_capabilities" "text"[], "p_attributes" "jsonb", "p_lat" double precision, "p_lng" double precision, "p_country" "text", "p_headline" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."supplier_sign_contract"("p_contract_id" "uuid", "p_typed_name" "text", "p_ip" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_c RECORD;
BEGIN
  SELECT * INTO v_c FROM public.supplier_contracts WHERE id = p_contract_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'contract_not_found'; END IF;
  IF v_c.supplier_id <> auth.uid() THEN RAISE EXCEPTION 'only the awarded supplier may sign'; END IF;
  IF v_c.status <> 'pending_supplier_signature' THEN RAISE EXCEPTION 'contract not awaiting supplier signature (status=%)', v_c.status; END IF;
  IF p_typed_name IS NULL OR length(trim(p_typed_name)) < 2 THEN RAISE EXCEPTION 'type your full legal name to sign'; END IF;

  UPDATE public.supplier_contracts
     SET supplier_signed_at = now(), supplier_signed_name = trim(p_typed_name),
         supplier_signed_ip = p_ip, status = 'pending_admin_countersignature'
   WHERE id = p_contract_id;

  BEGIN
    PERFORM public.create_admin_notification(
      'Supplier signed an agreement', 'Awaiting NEXPEC countersignature to execute.',
      'contract_assigned', '/admin/supplier-payouts', v_c.job_id);
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object('ok', true, 'status', 'pending_admin_countersignature');
END $$;


ALTER FUNCTION "public"."supplier_sign_contract"("p_contract_id" "uuid", "p_typed_name" "text", "p_ip" "text") OWNER TO "postgres";


