CREATE OR REPLACE FUNCTION "public"."sweep_overdue_reports"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  j           RECORD;
  v_overdue_h numeric;
  v_target    smallint;
  v_link      text;
  v_title     text;
  v_count     int := 0;
BEGIN
  FOR j IN
    SELECT jb.id, jb.title, jb.contractor_id, jb.scheduled_date
      FROM public.jobs jb
     WHERE jb.status IN ('assigned', 'in_progress')
       AND jb.contractor_id IS NOT NULL
       AND jb.scheduled_date IS NOT NULL
       AND jb.scheduled_date < now()
       AND NOT EXISTS (SELECT 1 FROM public.pi_report_seals s WHERE s.job_id = jb.id)
  LOOP
    v_overdue_h := EXTRACT(EPOCH FROM (now() - j.scheduled_date)) / 3600.0;
    v_target := CASE WHEN v_overdue_h >= 72 THEN 3 WHEN v_overdue_h >= 24 THEN 2 ELSE 1 END;

    -- already chased at this stage? skip (the ledger is the idempotency key)
    IF EXISTS (SELECT 1 FROM public.report_reminders r WHERE r.job_id = j.id AND r.stage = v_target) THEN
      CONTINUE;
    END IF;

    v_link  := '/jobs/' || j.id::text;
    v_title := coalesce(nullif(j.title, ''), 'an inspection');

    -- notifications never abort the sweep
    BEGIN
      IF v_target = 1 THEN
        PERFORM public.nx_notify(j.contractor_id, 'Report due',
          'Your inspection report for "' || v_title || '" is past its scheduled date. Please submit it.',
          'report_overdue', v_link, j.id);
      ELSIF v_target = 2 THEN
        PERFORM public.nx_notify(j.contractor_id, 'Report still outstanding',
          'Your report for "' || v_title || '" is more than 24h overdue. Please submit it as soon as possible.',
          'report_overdue', v_link, j.id);
        PERFORM public.nx_notify_admins('Report overdue 24h+',
          'Inspector report for "' || v_title || '" is more than 24h late.',
          'report_overdue_admin', v_link, j.id);
      ELSE
        PERFORM public.nx_notify(j.contractor_id, 'Final reminder — report overdue',
          'Your report for "' || v_title || '" is more than 72h overdue and has been escalated to NEXPEC operations.',
          'report_at_risk', v_link, j.id);
        PERFORM public.nx_notify_admins('At-risk report (72h+)',
          'Inspector has not submitted the report for "' || v_title || '". Please intervene.',
          'report_at_risk', v_link, j.id);
      END IF;
    EXCEPTION WHEN OTHERS THEN NULL; END;

    INSERT INTO public.report_reminders (job_id, stage) VALUES (j.id, v_target)
      ON CONFLICT (job_id, stage) DO NOTHING;
    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END $$;


ALTER FUNCTION "public"."sweep_overdue_reports"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_onboarding_metadata_to_profile"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_meta jsonb;
  v_specialties text[];
BEGIN
  SELECT raw_user_meta_data INTO v_meta FROM auth.users WHERE id = NEW.id;
  IF v_meta IS NULL THEN
    RETURN NEW;
  END IF;

  -- Pull role-specific fields out of the metadata blob.
  IF v_meta ? 'full_name' AND NEW.full_name IS NULL THEN
    NEW.full_name := v_meta->>'full_name';
  END IF;
  IF v_meta ? 'company_name' THEN
    NEW.company_name := COALESCE(NEW.company_name, v_meta->>'company_name');
  END IF;
  IF v_meta ? 'contact_person_name' THEN
    NEW.contact_person_name := COALESCE(
      NEW.contact_person_name,
      v_meta->>'contact_person_name'
    );
  END IF;
  IF v_meta ? 'onboarding_role' THEN
    NEW.onboarding_role := COALESCE(NEW.onboarding_role, v_meta->>'onboarding_role');
    IF NEW.role IS NULL OR NEW.role = '' OR NEW.role = 'client' THEN
      -- Promote the role only if it was the default. Admins set role manually.
      NEW.role := COALESCE(v_meta->>'onboarding_role', NEW.role);
    END IF;
  END IF;
  IF v_meta ? 'specialty_slugs' THEN
    BEGIN
      v_specialties := ARRAY(
        SELECT jsonb_array_elements_text(v_meta->'specialty_slugs')
      );
      IF array_length(v_specialties, 1) IS NOT NULL THEN
        NEW.specialty_slugs := v_specialties;
      END IF;
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;
  IF v_meta ? 'terms_accepted_at' THEN
    NEW.terms_accepted_at := COALESCE(
      NEW.terms_accepted_at,
      (v_meta->>'terms_accepted_at')::timestamptz
    );
  END IF;
  IF v_meta ? 'terms_version' THEN
    NEW.terms_version := COALESCE(NEW.terms_version, v_meta->>'terms_version');
  END IF;

  NEW.onboarding_completed_at := COALESCE(NEW.onboarding_completed_at, NOW());

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'sync_onboarding_metadata_to_profile: %', SQLERRM;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."sync_onboarding_metadata_to_profile"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_app_sync_job_payout_to_bid"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- When an application is in a winning state and carries a real bid, push that
  -- agreed price into its job's payout columns (both the canonical
  -- inspector_payout_cents the inspector UI reads and the legacy mirror).
  IF NEW.status IN ('hired', 'accepted', 'CLIENT_SELECTED')
     AND NEW.bid_amount_cents IS NOT NULL
     AND NEW.bid_amount_cents > 0 THEN
    UPDATE public.jobs
       SET inspector_payout_cents = NEW.bid_amount_cents,
           payout_amount_cents    = NEW.bid_amount_cents,
           updated_at             = now()
     WHERE id = NEW.job_id
       AND ( inspector_payout_cents IS DISTINCT FROM NEW.bid_amount_cents
          OR payout_amount_cents    IS DISTINCT FROM NEW.bid_amount_cents );
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."tg_app_sync_job_payout_to_bid"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_applications_notifications_v2"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_client uuid; v_title text;
BEGIN
  SELECT COALESCE(client_id, agency_id), COALESCE(NULLIF(title,''), 'your job')
    INTO v_client, v_title
    FROM public.jobs WHERE id = NEW.job_id;

  IF TG_OP = 'INSERT' THEN
    IF v_client IS NOT NULL THEN
      PERFORM public.create_system_notification(
        v_client, 'New inspector application',
        'An inspector applied to ' || v_title || '. Review their profile.',
        'application_status',
        '/client/jobs/' || NEW.job_id::text || '/applications',
        NEW.job_id);
    END IF;
    PERFORM public.create_admin_notification(
      'New application',
      'Inspector applied to "' || v_title || '".',
      'application_status',
      '/admin/jobs?inspect=' || NEW.job_id::text, NEW.job_id);
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.status IS DISTINCT FROM OLD.status AND NEW.applicant_id IS NOT NULL THEN
      PERFORM public.create_system_notification(
        NEW.applicant_id,
        CASE NEW.status
          WHEN 'accepted'        THEN 'Application accepted'
          WHEN 'rejected'        THEN 'Application not selected'
          WHEN 'CLIENT_SELECTED' THEN 'Client picked you — admin reviewing'
          WHEN 'withdrawn'       THEN 'Application withdrawn'
          ELSE 'Application updated'
        END,
        v_title, 'application_status',
        '/inspector/jobs/' || NEW.job_id::text, NEW.job_id);
    END IF;
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'tg_applications_notifications_v2: %', SQLERRM;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."tg_applications_notifications_v2"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_approval_decisions_enforce_sod"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_requester    uuid;
  v_requires_sod boolean;
BEGIN
  SELECT requested_by, requires_sod
    INTO v_requester, v_requires_sod
    FROM public.approval_requests
   WHERE id = NEW.approval_request_id;

  IF v_requester IS NULL THEN
    -- Should not happen with FK in place; defensive.
    RAISE EXCEPTION 'approval request not found' USING ERRCODE = 'P0002';
  END IF;

  IF COALESCE(v_requires_sod, true) IS TRUE AND NEW.decided_by = v_requester THEN
    RAISE EXCEPTION 'Segregation of Duties violation: the request poster cannot approve their own request'
      USING ERRCODE = '42501',
            HINT = 'SOX 404 — schema-enforced. Another authorised approver must decide.';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."tg_approval_decisions_enforce_sod"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_approval_policies_no_overlap"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_overlap_count int;
BEGIN
  IF NEW.is_active IS DISTINCT FROM TRUE THEN
    RETURN NEW; -- inactive bands don't participate in the ladder
  END IF;

  SELECT COUNT(*)
    INTO v_overlap_count
    FROM public.approval_policies p
   WHERE p.id <> NEW.id
     AND p.org_id = NEW.org_id
     AND p.is_active = true
     AND p.currency = NEW.currency
     AND COALESCE(p.scope_department_id, '00000000-0000-0000-0000-000000000000'::uuid)
       = COALESCE(NEW.scope_department_id, '00000000-0000-0000-0000-000000000000'::uuid)
     -- Range overlap: [a_min, a_max) overlaps [b_min, b_max) when a_min < b_max AND b_min < a_max
     -- max NULL means +infinity for that side.
     AND NEW.min_amount_cents < COALESCE(p.max_amount_cents, 9223372036854775807::bigint)
     AND p.min_amount_cents   < COALESCE(NEW.max_amount_cents, 9223372036854775807::bigint);

  IF v_overlap_count > 0 THEN
    RAISE EXCEPTION 'approval policy band overlaps an existing active band for this scope/currency'
      USING ERRCODE = '23P01'; -- exclusion_violation
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."tg_approval_policies_no_overlap"() OWNER TO "postgres";


