CREATE OR REPLACE FUNCTION "public"."tg_auto_issue_invoice_on_contract_executed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_existing_invoice_id uuid;
  v_new_invoice_number  text;
BEGIN
  IF NEW.status <> 'fully_executed' THEN RETURN NEW; END IF;
  IF OLD.status = 'fully_executed' THEN RETURN NEW; END IF;

  -- Idempotency: skip if an invoice for this contract already exists
  SELECT id INTO v_existing_invoice_id
    FROM public.invoices
   WHERE contract_id = NEW.id
   LIMIT 1;
  IF v_existing_invoice_id IS NOT NULL THEN RETURN NEW; END IF;

  -- Generate human-readable invoice number: NX-YYYYMM-{first 6 of contract id}
  v_new_invoice_number := 'NX-' || to_char(NOW(), 'YYYYMM') || '-' || substr(NEW.id::text, 1, 6);

  INSERT INTO public.invoices (
    invoice_number, job_id, contract_id, client_id, inspector_id,
    client_amount_cents, inspector_amount_cents, platform_fee_cents, total_cents,
    status, issued_at, due_date,
    line_items_json
  ) VALUES (
    v_new_invoice_number, NEW.job_id, NEW.id, NEW.client_id, NEW.inspector_id,
    COALESCE(NEW.client_price_cents, 0),
    COALESCE(NEW.inspector_payout_cents, 0),
    GREATEST(COALESCE(NEW.client_price_cents,0) - COALESCE(NEW.inspector_payout_cents,0), 0),
    COALESCE(NEW.client_price_cents, 0),
    'pending_review',
    NOW(),
    (NOW() + interval '14 days')::date,
    jsonb_build_array(
      jsonb_build_object(
        'kind', 'inspection_fee',
        'description', 'Inspection services per executed contract',
        'amount_cents', COALESCE(NEW.client_price_cents, 0),
        'contract_id', NEW.id::text
      )
    )
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'tg_auto_issue_invoice_on_contract_executed: %', SQLERRM;
  RETURN NEW;
END
$$;


ALTER FUNCTION "public"."tg_auto_issue_invoice_on_contract_executed"() OWNER TO "postgres";


