CREATE OR REPLACE FUNCTION "public"."tg_notifications_consent_gate"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.email_required IS NOT TRUE THEN RETURN NEW; END IF;
  -- External/transactional recipients aren't NEXPEC users → not user-mutable.
  IF COALESCE(NEW.email_template_data, '{}'::jsonb) ? 'override_to' THEN
    RETURN NEW;
  END IF;
  -- Old-shape rows without recipient/kind: leave untouched.
  IF NEW.recipient_id IS NULL OR NEW.kind IS NULL THEN RETURN NEW; END IF;

  IF NOT public.should_deliver(NEW.recipient_id, NEW.kind, 'email') THEN
    NEW.email_required := false;   -- suppress email; the in-app row still lands
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;                       -- fail open
END
$$;


ALTER FUNCTION "public"."tg_notifications_consent_gate"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_notify_applications"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE v_client uuid; v_title text;
BEGIN
  SELECT COALESCE(client_id, agency_id), COALESCE(NULLIF(title,''), 'your job')
    INTO v_client, v_title
    FROM public.jobs WHERE id = NEW.job_id;

  IF TG_OP = 'INSERT' THEN
    IF v_client IS NOT NULL THEN
      BEGIN
        PERFORM public.nx_notify(v_client, 'New inspector application',
          'An inspector applied to ' || v_title || '.', 'application_status',
          '/client/jobs/' || NEW.job_id::text || '/applications', NEW.job_id);
      EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'tg_notify_applications client failed: %', SQLERRM;
      END;
    END IF;
    BEGIN
      PERFORM public.nx_notify_admins('New application',
        'Inspector applied to "' || v_title || '".', 'application_status',
        '/admin/jobs?inspect=' || NEW.job_id::text, NEW.job_id);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'tg_notify_applications admin failed: %', SQLERRM;
    END;
  ELSIF TG_OP = 'UPDATE'
        AND NEW.status IS DISTINCT FROM OLD.status
        AND NEW.applicant_id IS NOT NULL THEN
    BEGIN
      PERFORM public.nx_notify(NEW.applicant_id,
        CASE NEW.status
          WHEN 'accepted'        THEN 'Application accepted'
          WHEN 'rejected'        THEN 'Application not selected'
          WHEN 'CLIENT_SELECTED' THEN 'Client picked you — admin reviewing'
          WHEN 'withdrawn'       THEN 'Application withdrawn'
          ELSE 'Application updated' END,
        v_title, 'application_status',
        '/inspector/jobs/' || NEW.job_id::text, NEW.job_id);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'tg_notify_applications inspector failed: %', SQLERRM;
    END;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."tg_notify_applications"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_notify_approval_decided"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_req         RECORD;
  v_decider     RECORD;
  v_job         RECORD;
  v_amount_str  text;
  v_template_data jsonb;
  v_link_requester text;
  v_link_approver  text;
BEGIN
  SELECT id, org_id, job_id, department_id, requested_by,
         amount_cents, currency, status,
         min_approvers_required, required_approver_roles
    INTO v_req
    FROM public.approval_requests
   WHERE id = NEW.approval_request_id;

  IF v_req.id IS NULL THEN
    -- FK should prevent this; defensive only.
    RETURN NEW;
  END IF;

  SELECT id, full_name, email
    INTO v_decider
    FROM public.profiles
   WHERE id = NEW.decided_by;

  SELECT id, title
    INTO v_job
    FROM public.jobs
   WHERE id = v_req.job_id;

  v_amount_str := public.format_amount_for_notification(
    v_req.amount_cents,
    v_req.currency::text
  );

  v_link_requester := '/client/jobs/' || v_req.job_id::text;
  v_link_approver  := '/client/approvals?request=' || v_req.id::text;

  v_template_data := jsonb_build_object(
    'approval_request_id', v_req.id,
    'job_id',              v_req.job_id,
    'job_title',           COALESCE(NULLIF(v_job.title, ''), 'Inspection job'),
    'org_id',              v_req.org_id,
    'department_id',       v_req.department_id,
    'requester_id',        v_req.requested_by,
    'decider_id',          NEW.decided_by,
    'decider_name',        COALESCE(NULLIF(v_decider.full_name, ''), v_decider.email),
    'decider_role_at_time', NEW.decider_role_at_time,
    'decision',            NEW.decision,
    'comment',             NEW.comment,
    'amount_cents',        v_req.amount_cents,
    'currency',            v_req.currency::text,
    'amount_display',      v_amount_str,
    'requester_link',      v_link_requester,
    'approver_link',       v_link_approver
  );

  -- Tell the requester this approver weighed in. In-app only; the
  -- email goes from trigger B-2 once the terminal state lands.
  PERFORM public.enqueue_notification(
    v_req.requested_by,
    'approval_progress',
    CASE NEW.decision
      WHEN 'approved' THEN 'Approval received: ' || COALESCE(NULLIF(v_job.title, ''), 'Inspection job')
      WHEN 'rejected' THEN 'Approval rejected: '  || COALESCE(NULLIF(v_job.title, ''), 'Inspection job')
      ELSE 'Approval updated'
    END,
    COALESCE(NULLIF(v_decider.full_name, ''), v_decider.email)
      || ' ' || NEW.decision
      || CASE WHEN NEW.comment IS NOT NULL AND length(NEW.comment) > 0
              THEN ' — "' || LEFT(NEW.comment, 180) || '"' ELSE '' END,
    v_link_requester,
    v_req.job_id,
    false,
    NULL,
    v_template_data
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'tg_notify_approval_decided: %', SQLERRM;
  RETURN NEW;
END
$$;


ALTER FUNCTION "public"."tg_notify_approval_decided"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_notify_approval_finalised"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_job          RECORD;
  v_amount_str   text;
  v_decider      RECORD;
  v_other        RECORD;
  v_link_requester text;
  v_link_approver  text;
  v_verdict_text   text;
  v_template_kind  text;
  v_template_data  jsonb;
  v_last_comment   text;
BEGIN
  -- Only act when status FLIPS into a terminal state.
  IF NOT (OLD.status = 'pending' AND NEW.status IN ('approved', 'rejected')) THEN
    RETURN NEW;
  END IF;

  v_verdict_text  := NEW.status;
  v_template_kind := CASE NEW.status
                       WHEN 'approved' THEN 'approval.decided.approved'
                       WHEN 'rejected' THEN 'approval.decided.rejected'
                     END;

  SELECT id, title
    INTO v_job
    FROM public.jobs
   WHERE id = NEW.job_id;

  v_amount_str := public.format_amount_for_notification(
    NEW.amount_cents,
    NEW.currency::text
  );

  -- The decider that pushed us into terminal state.
  IF NEW.final_decision_by IS NOT NULL THEN
    SELECT id, full_name, email
      INTO v_decider
      FROM public.profiles
     WHERE id = NEW.final_decision_by;
  END IF;

  -- Last comment, in case the requester needs context (rejection reason
  -- or the closing approver's note).
  SELECT comment
    INTO v_last_comment
    FROM public.approval_decisions
   WHERE approval_request_id = NEW.id
   ORDER BY decided_at DESC
   LIMIT 1;

  v_link_requester := '/client/jobs/' || NEW.job_id::text;
  v_link_approver  := '/client/approvals?request=' || NEW.id::text;

  v_template_data := jsonb_build_object(
    'approval_request_id', NEW.id,
    'job_id',              NEW.job_id,
    'job_title',           COALESCE(NULLIF(v_job.title, ''), 'Inspection job'),
    'org_id',              NEW.org_id,
    'department_id',       NEW.department_id,
    'requester_id',        NEW.requested_by,
    'decider_id',          NEW.final_decision_by,
    'decider_name',        COALESCE(NULLIF(v_decider.full_name, ''), v_decider.email),
    'comment',             v_last_comment,
    'amount_cents',        NEW.amount_cents,
    'currency',            NEW.currency::text,
    'amount_display',      v_amount_str,
    'requester_link',      v_link_requester,
    'approver_link',       v_link_approver,
    'request_status',      NEW.status,
    'final_decision_at',   NEW.final_decision_at,
    'rejection_reason',    NEW.rejection_reason
  );

  -- A) Loud notification to the requester (in-app + email).
  PERFORM public.enqueue_notification(
    NEW.requested_by,
    CASE NEW.status
      WHEN 'approved' THEN 'approval_granted'
      WHEN 'rejected' THEN 'approval_denied'
    END,
    CASE NEW.status
      WHEN 'approved' THEN 'Approved: ' || COALESCE(NULLIF(v_job.title, ''), 'Inspection job')
      WHEN 'rejected' THEN 'Not approved: ' || COALESCE(NULLIF(v_job.title, ''), 'Inspection job')
    END,
    CASE NEW.status
      WHEN 'approved' THEN 'Your '
        || v_amount_str
        || ' request cleared approvals and the job is now live.'
      WHEN 'rejected' THEN 'Your '
        || v_amount_str
        || ' request was not approved'
        || CASE WHEN NEW.rejection_reason IS NOT NULL AND length(NEW.rejection_reason) > 0
                THEN ' — ' || LEFT(NEW.rejection_reason, 180) ELSE '' END
        || '.'
    END,
    v_link_requester,
    NEW.job_id,
    true,
    v_template_kind,
    v_template_data
  );

  -- B) Broadcast to the OTHER approvers so the pending queue clears.
  FOR v_other IN
    SELECT om.user_id, p.full_name, p.email, om.role
      FROM public.org_members om
      JOIN public.profiles    p ON p.id = om.user_id
     WHERE om.org_id = NEW.org_id
       AND om.role::text = ANY (NEW.required_approver_roles)
       AND om.user_id <> NEW.requested_by
       AND om.user_id <> COALESCE(NEW.final_decision_by, '00000000-0000-0000-0000-000000000000'::uuid)
  LOOP
    PERFORM public.enqueue_notification(
      v_other.user_id,
      'approval_finalised',
      'Approval ' || v_verdict_text || ': '
        || COALESCE(NULLIF(v_job.title, ''), 'Inspection job'),
      COALESCE(NULLIF(v_decider.full_name, ''), v_decider.email)
        || ' ' || v_verdict_text || ' the request — no action needed.',
      v_link_approver,
      NEW.job_id,
      false,
      NULL,
      v_template_data || jsonb_build_object(
        'recipient_role', v_other.role,
        'recipient_full_name', COALESCE(NULLIF(v_other.full_name, ''), v_other.email)
      )
    );
  END LOOP;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'tg_notify_approval_finalised: %', SQLERRM;
  RETURN NEW;
END
$$;


ALTER FUNCTION "public"."tg_notify_approval_finalised"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_notify_approval_requested"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_job        RECORD;
  v_org        RECORD;
  v_dept_name  text;
  v_requester  RECORD;
  v_amount_str text;
  v_approver   RECORD;
  v_link_approver text;
  v_link_requester text;
  v_template_data jsonb;
BEGIN
  -- Job context.
  SELECT id, title, client_id, agency_id
    INTO v_job
    FROM public.jobs
   WHERE id = NEW.job_id;

  -- Org context.
  SELECT id, name
    INTO v_org
    FROM public.organizations
   WHERE id = NEW.org_id;

  -- Department label (optional).
  IF NEW.department_id IS NOT NULL THEN
    SELECT name INTO v_dept_name
      FROM public.departments
     WHERE id = NEW.department_id;
  END IF;

  -- Requester profile.
  SELECT id, full_name, email
    INTO v_requester
    FROM public.profiles
   WHERE id = NEW.requested_by;

  v_amount_str := public.format_amount_for_notification(
    NEW.amount_cents,
    NEW.currency::text
  );

  v_link_approver  := '/client/approvals?request=' || NEW.id::text;
  v_link_requester := '/client/jobs/' || NEW.job_id::text;

  v_template_data := jsonb_build_object(
    'approval_request_id',   NEW.id,
    'job_id',                NEW.job_id,
    'job_title',             COALESCE(NULLIF(v_job.title, ''), 'Inspection job'),
    'org_id',                NEW.org_id,
    'org_name',              COALESCE(NULLIF(v_org.name, ''), 'Your organization'),
    'department_id',         NEW.department_id,
    'department_name',       v_dept_name,
    'requester_id',          NEW.requested_by,
    'requester_name',        COALESCE(NULLIF(v_requester.full_name, ''), v_requester.email),
    'amount_cents',          NEW.amount_cents,
    'currency',              NEW.currency::text,
    'amount_display',        v_amount_str,
    'min_approvers_required', NEW.min_approvers_required,
    'required_approver_roles', to_jsonb(NEW.required_approver_roles),
    'requires_sod',          NEW.requires_sod,
    'requested_at',          NEW.requested_at,
    'approver_link',         v_link_approver,
    'requester_link',        v_link_requester
  );

  -- Fan out to every eligible approver. SoD: skip the requester
  -- (they cannot approve their own request, ever).
  FOR v_approver IN
    SELECT om.user_id, p.full_name, p.email, om.role
      FROM public.org_members om
      JOIN public.profiles    p ON p.id = om.user_id
     WHERE om.org_id = NEW.org_id
       AND om.role::text = ANY (NEW.required_approver_roles)
       AND om.user_id <> NEW.requested_by
  LOOP
    PERFORM public.enqueue_notification(
      v_approver.user_id,
      'approval_requested',
      'Approval needed: ' || COALESCE(NULLIF(v_job.title, ''), 'Inspection job'),
      COALESCE(NULLIF(v_requester.full_name, ''), v_requester.email)
        || ' submitted '
        || v_amount_str
        || CASE WHEN v_dept_name IS NOT NULL THEN ' for ' || v_dept_name ELSE '' END
        || '.',
      v_link_approver,
      NEW.job_id,
      true,
      'approval.requested',
      v_template_data || jsonb_build_object(
        'recipient_role', v_approver.role,
        'recipient_full_name', COALESCE(NULLIF(v_approver.full_name, ''), v_approver.email)
      )
    );
  END LOOP;

  -- Receipt to requester (in-app only; no email — they just clicked
  -- "submit", they don't need their inbox flooded).
  PERFORM public.enqueue_notification(
    NEW.requested_by,
    'approval_submitted',
    'Approval request submitted',
    'Your '
      || v_amount_str
      || ' job is queued for review. We''ll notify you once a decision is made.',
    v_link_requester,
    NEW.job_id,
    false,
    NULL,
    v_template_data
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Notifications must never block the underlying business write.
  RAISE NOTICE 'tg_notify_approval_requested: %', SQLERRM;
  RETURN NEW;
END
$$;


ALTER FUNCTION "public"."tg_notify_approval_requested"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_notify_bridge_document_requested"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bridge RECORD;
  v_vendor RECORD;
  v_job    RECORD;
  v_inspector RECORD;
  v_template_data jsonb;
BEGIN
  -- Only fire for genuine document_request slots created by the inspector.
  IF NEW.kind <> 'document_request' THEN RETURN NEW; END IF;
  IF NEW.created_by_actor_kind <> 'inspector' THEN RETURN NEW; END IF;

  SELECT * INTO v_bridge FROM public.coordination_bridges WHERE id = NEW.bridge_id;
  IF v_bridge.id IS NULL OR v_bridge.status IN ('completed','cancelled') THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_vendor FROM public.vendor_contacts WHERE id = v_bridge.vendor_contact_id;
  SELECT id, title INTO v_job FROM public.jobs WHERE id = v_bridge.job_id;
  SELECT id, COALESCE(NULLIF(full_name, ''), email) AS display_name
    INTO v_inspector FROM public.profiles WHERE id = v_bridge.inspector_id;

  v_template_data := jsonb_build_object(
    'bridge_id',      v_bridge.id,
    'job_id',         v_bridge.job_id,
    'job_title',      COALESCE(NULLIF(v_job.title, ''), 'Inspection'),
    'inspector_name', v_inspector.display_name,
    'vendor_company', v_vendor.company_name,
    'vendor_contact', v_vendor.contact_name,
    'vendor_email',   v_vendor.contact_email,
    'document_title', NEW.title,
    'document_description', NEW.description,
    'required',       NEW.required,
    'override_to',    v_vendor.contact_email
  );

  INSERT INTO public.notifications (
    recipient_id, kind, title, body, link_href, job_id,
    email_required, email_template_kind, email_template_data
  )
  VALUES (
    v_bridge.inspector_id,
    'bridge_document_requested',
    format('Document requested from vendor: %s', NEW.title),
    format('Vendor %s has been notified to upload %s.', v_vendor.company_name, NEW.title),
    '/inspector/coordination-bridge?bridge_id=' || v_bridge.id::text,
    v_bridge.job_id,
    true,
    'coordination_bridge.document_requested',
    v_template_data
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'tg_notify_bridge_document_requested: %', SQLERRM;
  RETURN NEW;
END
$$;


ALTER FUNCTION "public"."tg_notify_bridge_document_requested"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_notify_bridge_document_uploaded"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bridge RECORD;
  v_vendor RECORD;
  v_job    RECORD;
  v_template_data jsonb;
BEGIN
  IF NEW.uploaded_by_actor_kind <> 'vendor' THEN RETURN NEW; END IF;

  SELECT * INTO v_bridge FROM public.coordination_bridges WHERE id = NEW.bridge_id;
  IF v_bridge.id IS NULL THEN RETURN NEW; END IF;
  SELECT * INTO v_vendor FROM public.vendor_contacts WHERE id = v_bridge.vendor_contact_id;
  SELECT id, title INTO v_job FROM public.jobs WHERE id = v_bridge.job_id;

  v_template_data := jsonb_build_object(
    'bridge_id',     v_bridge.id,
    'job_id',        v_bridge.job_id,
    'job_title',     COALESCE(NULLIF(v_job.title, ''), 'Inspection'),
    'vendor_company', v_vendor.company_name,
    'document_id',   NEW.id,
    'filename',      NEW.original_filename,
    'mime_type',     NEW.mime_type,
    'size_bytes',    NEW.file_size_bytes,
    'sha256',        NEW.sha256_client_computed,
    'review_link',   '/inspector/coordination-bridge?bridge_id=' || v_bridge.id::text
  );

  -- In-app ping; email is optional here (inspector usually has push).
  PERFORM public.enqueue_notification(
    v_bridge.inspector_id,
    'bridge_document_uploaded',
    format('Vendor uploaded: %s', NEW.original_filename),
    format('%s submitted %s. Review and accept or reject.',
      v_vendor.company_name, NEW.original_filename),
    '/inspector/coordination-bridge?bridge_id=' || v_bridge.id::text,
    v_bridge.job_id,
    false,
    NULL,
    v_template_data
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'tg_notify_bridge_document_uploaded: %', SQLERRM;
  RETURN NEW;
END
$$;


ALTER FUNCTION "public"."tg_notify_bridge_document_uploaded"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_notify_bridge_schedule_changed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bridge RECORD;
  v_vendor RECORD;
  v_job    RECORD;
  v_template_data jsonb;
  v_target_email text;
  v_subject text;
  v_body text;
BEGIN
  IF NEW.kind <> 'schedule' THEN RETURN NEW; END IF;
  IF OLD.status = NEW.status AND OLD.payload_json = NEW.payload_json THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_bridge FROM public.coordination_bridges WHERE id = NEW.bridge_id;
  IF v_bridge.id IS NULL OR v_bridge.status IN ('completed','cancelled') THEN
    RETURN NEW;
  END IF;
  SELECT * INTO v_vendor FROM public.vendor_contacts WHERE id = v_bridge.vendor_contact_id;
  SELECT id, title INTO v_job FROM public.jobs WHERE id = v_bridge.job_id;

  v_template_data := jsonb_build_object(
    'bridge_id',      v_bridge.id,
    'job_id',         v_bridge.job_id,
    'job_title',      COALESCE(NULLIF(v_job.title, ''), 'Inspection'),
    'vendor_company', v_vendor.company_name,
    'slot_payload',   NEW.payload_json,
    'slot_status',    NEW.status::text
  );

  IF NEW.status = 'awaiting_vendor' THEN
    -- Inspector proposed; email vendor.
    v_target_email := v_vendor.contact_email;
    INSERT INTO public.notifications (
      recipient_id, kind, title, body, link_href, job_id,
      email_required, email_template_kind, email_template_data
    )
    VALUES (
      v_bridge.inspector_id,
      'bridge_schedule_to_vendor',
      'Inspection date sent to vendor',
      format('Your proposed inspection date has been sent to %s.', v_vendor.company_name),
      '/inspector/coordination-bridge?bridge_id=' || v_bridge.id::text,
      v_bridge.job_id,
      true,
      'coordination_bridge.schedule_proposed_to_vendor',
      v_template_data || jsonb_build_object('override_to', v_target_email)
    );

  ELSIF NEW.status = 'awaiting_inspector' THEN
    -- Vendor counter-proposed; ping inspector (in-app).
    PERFORM public.enqueue_notification(
      v_bridge.inspector_id,
      'bridge_schedule_counter',
      format('Vendor proposed a new inspection date'),
      format('%s suggested a different date. Review and confirm or counter.', v_vendor.company_name),
      '/inspector/coordination-bridge?bridge_id=' || v_bridge.id::text,
      v_bridge.job_id,
      false,
      NULL,
      v_template_data
    );

  ELSIF NEW.status = 'completed' THEN
    -- Both parties agreed. Ping both.
    PERFORM public.enqueue_notification(
      v_bridge.inspector_id,
      'bridge_schedule_locked',
      'Inspection date confirmed by vendor',
      format('Date locked with %s.', v_vendor.company_name),
      '/inspector/coordination-bridge?bridge_id=' || v_bridge.id::text,
      v_bridge.job_id,
      false,
      NULL,
      v_template_data
    );
    IF v_bridge.client_id IS NOT NULL THEN
      PERFORM public.enqueue_notification(
        v_bridge.client_id,
        'bridge_schedule_locked',
        'Vendor coordination: inspection date locked',
        format('Your inspector and vendor %s have confirmed a date for %s.',
          v_vendor.company_name, COALESCE(v_job.title, 'the inspection')),
        '/client/jobs/' || v_bridge.job_id::text,
        v_bridge.job_id,
        false,
        NULL,
        v_template_data
      );
    END IF;
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'tg_notify_bridge_schedule_changed: %', SQLERRM;
  RETURN NEW;
END
$$;


ALTER FUNCTION "public"."tg_notify_bridge_schedule_changed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_notify_evidence_pack_assembled"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_job         RECORD;
  v_org_id      uuid;
  v_assembler   RECORD;
  v_member      RECORD;
  v_link        text;
  v_root_hash   text;
  v_pack_id     text;
  v_template_data jsonb;
BEGIN
  -- Filter at the function body level (rather than WHEN clause) so we
  -- can keep the trigger definition simple and not depend on event_type
  -- being a stable text literal in pg_catalog.
  IF NEW.event_type IS DISTINCT FROM 'compliance.evidence_pack.assembled' THEN
    RETURN NEW;
  END IF;

  -- Pull job + org.
  IF NEW.job_id IS NOT NULL THEN
    SELECT id, title, COALESCE(client_id, agency_id) AS org_id
      INTO v_job
      FROM public.jobs
     WHERE id = NEW.job_id;
    v_org_id := v_job.org_id;
  END IF;

  -- Pull assembler.
  SELECT id, full_name, email
    INTO v_assembler
    FROM public.profiles
   WHERE id = NEW.actor_id;

  v_root_hash := COALESCE(NEW.metadata ->> 'root_hash', NEW.delta ->> 'root_hash');
  v_pack_id   := COALESCE(NEW.metadata ->> 'pack_id',   NEW.delta ->> 'pack_id');
  v_link      := CASE
                   WHEN NEW.job_id IS NOT NULL
                     THEN '/client/jobs/' || NEW.job_id::text || '#evidence'
                   ELSE '/client/compliance'
                 END;

  v_template_data := jsonb_build_object(
    'audit_event_id',  NEW.id,
    'event_type',      NEW.event_type,
    'job_id',          NEW.job_id,
    'job_title',       COALESCE(NULLIF(v_job.title, ''), 'Inspection job'),
    'org_id',          v_org_id,
    'assembler_id',    NEW.actor_id,
    'assembler_name',  COALESCE(NULLIF(v_assembler.full_name, ''), v_assembler.email),
    'root_hash',       v_root_hash,
    'pack_id',         v_pack_id,
    'assembled_at',    NEW.created_at,
    'pack_link',       v_link,
    'verify_link',     '/verify'
  );

  -- Receipt to the assembler.
  IF NEW.actor_id IS NOT NULL THEN
    PERFORM public.enqueue_notification(
      NEW.actor_id,
      'evidence_pack_assembled',
      'Evidence pack ready',
      'Pack ' || COALESCE(LEFT(v_root_hash, 12), 'verified')
        || ' for ' || COALESCE(NULLIF(v_job.title, ''), 'this job')
        || ' is ready to share.',
      v_link,
      NEW.job_id,
      true,
      'evidence_pack.assembled',
      v_template_data || jsonb_build_object('recipient_role', 'assembler')
    );
  END IF;

  -- Broadcast to compliance leadership for the same org.
  IF v_org_id IS NOT NULL THEN
    FOR v_member IN
      SELECT om.user_id, p.full_name, p.email, om.role
        FROM public.org_members om
        JOIN public.profiles    p ON p.id = om.user_id
       WHERE om.org_id = v_org_id
         AND om.role IN ('owner', 'procurement_admin')
         AND om.user_id <> COALESCE(NEW.actor_id, '00000000-0000-0000-0000-000000000000'::uuid)
    LOOP
      PERFORM public.enqueue_notification(
        v_member.user_id,
        'evidence_pack_assembled',
        'New evidence pack assembled',
        COALESCE(NULLIF(v_assembler.full_name, ''), v_assembler.email)
          || ' assembled an evidence pack for '
          || COALESCE(NULLIF(v_job.title, ''), 'an inspection job') || '.',
        v_link,
        NEW.job_id,
        false,   -- In-app only for leadership; assembler already got the email.
        NULL,
        v_template_data || jsonb_build_object(
          'recipient_role', v_member.role,
          'recipient_full_name', COALESCE(NULLIF(v_member.full_name, ''), v_member.email)
        )
      );
    END LOOP;
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'tg_notify_evidence_pack_assembled: %', SQLERRM;
  RETURN NEW;
END
$$;


ALTER FUNCTION "public"."tg_notify_evidence_pack_assembled"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_notify_flash_report_raised"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_job          RECORD;
  v_admin        RECORD;
  v_is_critical  boolean;
  v_sev_label    text;
  v_admin_link   text;
  v_client_link  text;
  v_template     jsonb;
BEGIN
  SELECT id, title, client_id
    INTO v_job
    FROM public.jobs
   WHERE id = NEW.job_id;

  IF v_job.id IS NULL THEN
    RETURN NEW;
  END IF;

  v_is_critical := (NEW.severity = 'critical');
  v_sev_label   := initcap(NEW.severity);   -- "Critical" / "Major" / "Minor" / "Observation"
  v_admin_link  := '/admin/jobs?inspect=' || NEW.job_id::text || '#moderation';
  v_client_link := '/client/jobs/' || NEW.job_id::text;

  -- Identity-safe payload — role + severity + category only, never a name.
  v_template := jsonb_build_object(
    'flash_report_id', NEW.id,
    'job_id',          NEW.job_id,
    'job_title',       COALESCE(NULLIF(v_job.title, ''), 'Inspection job'),
    'severity',        NEW.severity,
    'category',        NEW.category,
    'report_title',    NEW.title,
    'reporter_role',   NEW.reporter_role,
    'status',          NEW.status,
    'raised_at',       NEW.created_at
  );

  -- 1) Every admin / super_admin (except the reporter). Email on critical only.
  --    role::text guards against enum-label-not-found; admin == super_admin per
  --    the Singular Platform Owner doctrine, so cover both labels.
  FOR v_admin IN
    SELECT id
      FROM public.profiles
     WHERE role::text IN ('admin', 'super_admin')
       AND id <> NEW.reporter_id
  LOOP
    PERFORM public.enqueue_notification(
      v_admin.id,
      'flash_report_raised',
      v_sev_label || ' flash report — '
        || COALESCE(NULLIF(v_job.title, ''), 'Inspection job'),
      'A ' || NEW.severity || ' ' || replace(NEW.category, '_', ' ')
        || ' flash report was raised: ' || NEW.title,
      v_admin_link,
      NEW.job_id,
      v_is_critical,                       -- email only when critical
      'flash_report.raised',
      v_template
    );
  END LOOP;

  -- 2) Client — CRITICAL severities only (in-app + email). Excludes the
  --    reporter if the client raised it themselves. Identity-free body.
  IF v_is_critical
     AND v_job.client_id IS NOT NULL
     AND v_job.client_id <> NEW.reporter_id THEN
    PERFORM public.enqueue_notification(
      v_job.client_id,
      'flash_report_critical',
      'Critical issue raised on your job',
      'A critical ' || replace(NEW.category, '_', ' ')
        || ' issue was raised on '
        || COALESCE(NULLIF(v_job.title, ''), 'your job')
        || '. Open the job to review and acknowledge.',
      v_client_link,
      NEW.job_id,
      true,                                -- always email the client on critical
      'flash_report.critical_client',
      v_template
    );
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- A notification failure must never abort the underlying raise.
  RAISE NOTICE 'tg_notify_flash_report_raised: %', SQLERRM;
  RETURN NEW;
END
$$;


ALTER FUNCTION "public"."tg_notify_flash_report_raised"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_notify_inspection_report_sealed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_job        RECORD;
  v_link       text;
  v_verify     text;
  v_template_data jsonb;
BEGIN
  -- Job context — bail silently if we can't resolve the client.
  SELECT id, title, client_id
    INTO v_job
    FROM public.jobs
   WHERE id = NEW.job_id;

  IF v_job.id IS NULL OR v_job.client_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_link   := '/client/jobs/' || NEW.job_id::text || '#countersign';
  v_verify := '/verify?seal_id=' || NEW.id::text
              || '&hash=' || NEW.root_sha256;

  -- ANTI-POACHING: the client is PRE-REVEAL at seal time (before admin
  -- confirms the report). Never place the inspector's real name in any
  -- client-facing notification text or email. `inspector_id` (opaque UUID) is
  -- retained for internal correlation; the human-readable label is generic.
  v_template_data := jsonb_build_object(
    'seal_id',                    NEW.id,
    'report_id',                  NEW.report_id,
    'job_id',                     NEW.job_id,
    'job_title',                  COALESCE(NULLIF(v_job.title, ''), 'Inspection job'),
    'inspector_id',               NEW.inspector_id,
    'inspector_name',             'Your assigned inspector',
    'root_sha256',                NEW.root_sha256,
    'captures_count',             NEW.captures_count,
    'items_count',                NEW.items_count,
    'chain_verified',             NEW.chain_verified,
    'algorithm',                  NEW.algorithm,
    'inspector_sealed_at',        NEW.inspector_sealed_at,
    'inspector_signature_sha256', NEW.inspector_signature_sha256,
    'countersign_link',           v_link,
    'verify_link',                v_verify
  );

  -- Pings client + queues email (identity-free body).
  PERFORM public.enqueue_notification(
    v_job.client_id,
    'inspection_sealed_awaiting_countersign',
    'Your inspection report is sealed — ready to countersign',
    'Your assigned inspector sealed the report for '
      || COALESCE(NULLIF(v_job.title, ''), 'this job')
      || '. Open it to review and add your countersignature.',
    v_link,
    NEW.job_id,
    true,
    'inspection_report.sealed_awaiting_countersign',
    v_template_data
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'tg_notify_inspection_report_sealed: %', SQLERRM;
  RETURN NEW;
END
$$;


ALTER FUNCTION "public"."tg_notify_inspection_report_sealed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_notify_jobs"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_client    uuid := COALESCE(NEW.client_id, NEW.agency_id);
  v_inspector uuid := COALESCE(NEW.hired_inspector_id, NEW.inspector_id);
  v_title     text := COALESCE(NULLIF(NEW.title, ''), 'Inspection job');
BEGIN
  IF TG_OP = 'INSERT' THEN
    BEGIN
      PERFORM public.nx_notify_admins('New job posted', v_title, 'job_moderated',
        '/admin/jobs?inspect=' || NEW.id::text, NEW.id);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'tg_notify_jobs INSERT failed: %', SQLERRM;
    END;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF NEW.moderation_status IS DISTINCT FROM OLD.moderation_status AND v_client IS NOT NULL THEN
      BEGIN
        PERFORM public.nx_notify(v_client,
          CASE NEW.moderation_status
            WHEN 'approved' THEN 'Job approved'
            WHEN 'rejected' THEN 'Job rejected'
            WHEN 'edits_requested' THEN 'Edits requested on your job'
            ELSE 'Job moderation updated' END,
          v_title, 'job_moderated',
          '/client/jobs/' || NEW.id::text, NEW.id);
      EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'tg_notify_jobs moderation failed: %', SQLERRM;
      END;
    END IF;
    IF NEW.status IS DISTINCT FROM OLD.status AND v_inspector IS NOT NULL THEN
      BEGIN
        PERFORM public.nx_notify(v_inspector,
          CASE NEW.status
            WHEN 'in_progress' THEN 'Job in progress'
            WHEN 'completed'   THEN 'Job marked complete'
            WHEN 'cancelled'   THEN 'Job cancelled'
            ELSE 'Job status updated' END,
          v_title, 'assignment',
          '/inspector/jobs/' || NEW.id::text, NEW.id);
      EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'tg_notify_jobs status failed: %', SQLERRM;
      END;
    END IF;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."tg_notify_jobs"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_notify_messages"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_conv    RECORD;
  v_preview text;
BEGIN
  SELECT id, user_id, kind, title, job_id INTO v_conv
    FROM public.conversations WHERE id = NEW.conversation_id;
  IF NOT FOUND THEN RETURN NEW; END IF;

  v_preview := COALESCE(
    NULLIF(LEFT(NEW.content, 140), ''),
    CASE WHEN NEW.attachment_url IS NOT NULL THEN '📎 Attachment' ELSE 'New message' END
  );

  IF NEW.sender_id = v_conv.user_id THEN
    BEGIN
      PERFORM public.nx_notify_admins(
        COALESCE(NULLIF(v_conv.title, ''), 'New message'),
        v_preview, 'message',
        '/admin/messages/' || v_conv.id::text, v_conv.job_id);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'tg_notify_messages admin notify failed: %', SQLERRM;
    END;
  ELSE
    BEGIN
      PERFORM public.nx_notify(
        v_conv.user_id, 'NEXPEC Admin replied', v_preview, 'message',
        CASE
          WHEN v_conv.kind LIKE 'job_%inspector%' THEN '/inspector/messages/' || v_conv.id::text
          ELSE '/client/messages/' || v_conv.id::text
        END,
        v_conv.job_id);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'tg_notify_messages user notify failed: %', SQLERRM;
    END;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."tg_notify_messages"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_org_departments_compute_depth"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_parent_depth integer;
BEGIN
  IF NEW.parent_department_id IS NULL THEN
    NEW.depth := 0;
  ELSE
    SELECT depth INTO v_parent_depth
      FROM public.org_departments
     WHERE id = NEW.parent_department_id;
    NEW.depth := COALESCE(v_parent_depth, 0) + 1;
  END IF;
  RETURN NEW;
END
$$;


ALTER FUNCTION "public"."tg_org_departments_compute_depth"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_org_departments_no_cycle"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_cur uuid;
  v_hops integer := 0;
BEGIN
  IF NEW.parent_department_id IS NULL THEN
    RETURN NEW;
  END IF;
  v_cur := NEW.parent_department_id;
  WHILE v_cur IS NOT NULL AND v_hops < 50 LOOP
    IF v_cur = NEW.id THEN
      RAISE EXCEPTION 'org_departments cycle detected: % is an ancestor of itself', NEW.id;
    END IF;
    SELECT parent_department_id INTO v_cur
      FROM public.org_departments WHERE id = v_cur;
    v_hops := v_hops + 1;
  END LOOP;
  RETURN NEW;
END
$$;


ALTER FUNCTION "public"."tg_org_departments_no_cycle"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tg_org_dept_members_org_consistency"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_dept_org uuid;
BEGIN
  SELECT org_id INTO v_dept_org
    FROM public.org_departments
   WHERE id = NEW.department_id;
  IF v_dept_org IS NULL THEN
    RAISE EXCEPTION 'department % not found', NEW.department_id;
  END IF;
  IF v_dept_org <> NEW.org_id THEN
    RAISE EXCEPTION 'org_id (%) on membership does not match department''s org_id (%)',
      NEW.org_id, v_dept_org;
  END IF;
  RETURN NEW;
END
$$;


