CREATE OR REPLACE FUNCTION "public"."track_push_token_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    -- New token registered
    IF OLD.expo_push_token IS NULL AND NEW.expo_push_token IS NOT NULL THEN
        INSERT INTO public.push_token_history (contractor_id, token, action)
        VALUES (NEW.id, NEW.expo_push_token, 'registered');
    
    -- Token replaced
    ELSIF OLD.expo_push_token IS NOT NULL AND NEW.expo_push_token IS NOT NULL 
          AND OLD.expo_push_token != NEW.expo_push_token THEN
        INSERT INTO public.push_token_history (contractor_id, token, action, reason)
        VALUES (NEW.id, OLD.expo_push_token, 'replaced', 'New token registered');
        INSERT INTO public.push_token_history (contractor_id, token, action)
        VALUES (NEW.id, NEW.expo_push_token, 'registered');
    
    -- Token invalidated
    ELSIF OLD.expo_push_token IS NOT NULL AND NEW.expo_push_token IS NULL THEN
        INSERT INTO public.push_token_history (contractor_id, token, action, reason)
        VALUES (NEW.id, OLD.expo_push_token, 'invalidated', 'Token cleared');
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."track_push_token_changes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trigger_certification_check"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    project_url TEXT;
    service_key TEXT;
    response_status INTEGER;
BEGIN
    -- Get configuration from environment or vault
    -- In production, use Supabase Vault or environment variables
    project_url := current_setting('app.settings.supabase_url', true);
    service_key := current_setting('app.settings.service_role_key', true);
    
    -- If not set, use defaults (replace with your actual values)
    IF project_url IS NULL THEN
        project_url := 'https://YOUR_PROJECT_REF.supabase.co';
    END IF;
    
    IF service_key IS NULL THEN
        service_key := 'YOUR_SUPABASE_SERVICE_ROLE_KEY';
    END IF;

    -- Make HTTP request to Edge Function
    SELECT status INTO response_status
    FROM net.http_post(
        url := project_url || '/functions/v1/certification-expiry-check',
        headers := jsonb_build_object(
            'Content-Type', 'application/json',
            'Authorization', 'Bearer ' || service_key
        ),
        body := jsonb_build_object(
            'source', 'pg_cron',
            'triggered_at', NOW()::text
        )::text,
        timeout_milliseconds := 60000
    );

    -- Log the result
    INSERT INTO notification_logs (type, sent_at, details)
    VALUES (
        'cron_trigger',
        NOW(),
        jsonb_build_object(
            'response_status', response_status,
            'triggered_by', 'pg_cron'
        )
    );

EXCEPTION WHEN OTHERS THEN
    -- Log any errors
    INSERT INTO notification_logs (type, sent_at, details, error_messages)
    VALUES (
        'cron_trigger_error',
        NOW(),
        jsonb_build_object('triggered_by', 'pg_cron'),
        ARRAY[SQLERRM]
    );
END;
$$;


ALTER FUNCTION "public"."trigger_certification_check"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trigger_contract_generation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    IF NEW.status = 'hired' AND (OLD.status IS NULL OR OLD.status != 'hired') THEN
        PERFORM net.http_post(
            url := current_setting('app.settings.supabase_url') || '/functions/v1/generate-contract',
            headers := jsonb_build_object(
                'Content-Type', 'application/json',
                'Authorization', 'Bearer ' || current_setting('app.settings.service_role_key')
            ),
            body := jsonb_build_object('job_id', NEW.id)
        );
    END IF;
    RETURN NEW;
END;
$$;


