CREATE OR REPLACE FUNCTION "public"."unassign_member_from_department"("p_department_id" "uuid", "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor       uuid := auth.uid();
  v_actor_role  text;
  v_actor_label text;
  v_org_id      uuid;
  v_dept_name   text;
  v_user_label  text;
  v_correlation uuid := gen_random_uuid();
  v_removed     int;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT org_id, name INTO v_org_id, v_dept_name
    FROM public.departments WHERE id = p_department_id;
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Department not found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.can_manage_org_structure(v_org_id, v_actor) THEN
    RAISE EXCEPTION 'You do not have permission to manage this organization''s structure'
      USING ERRCODE = '42501';
  END IF;

  WITH del AS (
    DELETE FROM public.department_members
    WHERE department_id = p_department_id AND user_id = p_user_id
    RETURNING 1
  )
  SELECT count(*)::int INTO v_removed FROM del;

  IF v_removed > 0 THEN
    SELECT COALESCE(NULLIF(TRIM(full_name), ''), email, 'Unknown') INTO v_user_label
      FROM public.profiles WHERE id = p_user_id;

    SELECT actor_role, actor_label INTO v_actor_role, v_actor_label
      FROM public._dept_actor_profile(v_actor);

    INSERT INTO public.audit_events (
      event_type, actor_id, actor_role, actor_label,
      subject_table, subject_id, summary, delta, metadata, correlation_id
    ) VALUES (
      'department_member.unassigned',
      v_actor,
      v_actor_role,
      v_actor_label,
      'department_members',
      p_department_id,
      format('%s unassigned from %L', COALESCE(v_user_label, 'User'), v_dept_name),
      jsonb_build_object(
        'department_id', p_department_id,
        'department_name', v_dept_name,
        'user_id', p_user_id,
        'user_label', v_user_label
      ),
      jsonb_build_object('org_id', v_org_id),
      v_correlation
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'department_id', p_department_id,
    'user_id', p_user_id,
    'removed', v_removed,
    'correlation_id', v_correlation
  );
END;
$$;


ALTER FUNCTION "public"."unassign_member_from_department"("p_department_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_average_rating"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    new_avg DECIMAL(3,2);
    review_count INTEGER;
BEGIN
    -- Calculate new average and count for the reviewee
    SELECT 
        COALESCE(AVG(rating), 0.0)::DECIMAL(3,2),
        COUNT(*)::INTEGER
    INTO new_avg, review_count
    FROM public.reviews
    WHERE reviewee_id = NEW.reviewee_id;
    
    -- Update the profiles table
    UPDATE public.profiles
    SET 
        average_rating = new_avg,
        total_reviews = review_count
    WHERE id = NEW.reviewee_id;
    
    -- Log for debugging (optional)
    RAISE NOTICE 'Updated profile % with avg rating: % from % reviews', 
        NEW.reviewee_id, new_avg, review_count;
    
    RETURN NEW;
END;
$$;


