CREATE OR REPLACE FUNCTION "public"."upsert_fx_rate"("p_base_currency" "text", "p_quote_currency" "text", "p_rate" numeric, "p_effective_date" "date" DEFAULT CURRENT_DATE, "p_source" "text" DEFAULT 'manual'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor      uuid := auth.uid();
  v_actor_role text;
  v_base       public.currency_code;
  v_quote      public.currency_code;
  v_id         uuid;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  -- Singular Platform Owner doctrine — only the NEXPEC Platform Owner
  -- writes FX rates. Tenant-level operators cannot influence the
  -- exchange-rate set; that would let an org rewrite its own dashboards.
  SELECT role INTO v_actor_role FROM public.profiles WHERE id = v_actor;
  IF v_actor_role IS DISTINCT FROM 'super_admin' THEN
    RAISE EXCEPTION 'Only the NEXPEC Platform Owner can set FX rates'
      USING ERRCODE = '42501';
  END IF;

  IF p_rate IS NULL OR p_rate <= 0 THEN
    RAISE EXCEPTION 'rate must be > 0 (got %)', p_rate USING ERRCODE = '22000';
  END IF;

  v_base  := p_base_currency::public.currency_code;
  v_quote := p_quote_currency::public.currency_code;

  INSERT INTO public.fx_rates (base_currency, quote_currency, rate, effective_date, source)
    VALUES (v_base, v_quote, p_rate, p_effective_date, COALESCE(p_source, 'manual'))
    ON CONFLICT (base_currency, quote_currency, effective_date) DO UPDATE
      SET rate = EXCLUDED.rate,
          source = EXCLUDED.source,
          created_at = now()
    RETURNING id INTO v_id;

  RETURN jsonb_build_object(
    'ok',             true,
    'fx_rate_id',     v_id,
    'base',           v_base,
    'quote',          v_quote,
    'rate',           p_rate,
    'effective_date', p_effective_date
  );
END;
$$;


ALTER FUNCTION "public"."upsert_fx_rate"("p_base_currency" "text", "p_quote_currency" "text", "p_rate" numeric, "p_effective_date" "date", "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_application_status_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Auto-set timestamps
  IF NEW.status = 'offered' AND OLD.status != 'offered' THEN
    NEW.offered_at = NOW();
  END IF;
  
  IF NEW.status = 'accepted' AND OLD.status != 'accepted' THEN
    NEW.hired_at = NOW();
    UPDATE public.jobs SET status = 'in_progress' WHERE id = NEW.job_id;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_application_status_transition"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_balance"("p_wallet_id" "uuid", "p_amount" numeric) RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_balance NUMERIC;
BEGIN
  SELECT balance INTO v_balance
  FROM public.wallets
  WHERE id = p_wallet_id
  FOR UPDATE; -- Lock row for transaction safety
  
  RETURN COALESCE(v_balance, 0) >= p_amount;
END;
$$;


ALTER FUNCTION "public"."validate_balance"("p_wallet_id" "uuid", "p_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vendor_document_record_anchor"("p_doc_id" "uuid", "p_status" "text", "p_calendar" "text" DEFAULT NULL::"text", "p_ots_proof" "text" DEFAULT NULL::"text", "p_block_height" bigint DEFAULT NULL::bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  IF NOT public.nx_is_admin() THEN RAISE EXCEPTION 'not authorized' USING errcode='42501'; END IF;
  IF p_status NOT IN ('pending','submitted','bitcoin_confirmed','failed') THEN RAISE EXCEPTION 'bad_status'; END IF;
  UPDATE public.vendor_documents SET
    ots_status           = p_status,
    ots_calendar         = coalesce(p_calendar, ots_calendar),
    ots_proof            = coalesce(p_ots_proof, ots_proof),
    ots_submitted_at     = CASE WHEN p_status = 'submitted' AND ots_submitted_at IS NULL THEN now() ELSE ots_submitted_at END,
    ots_confirmed_at     = CASE WHEN p_status = 'bitcoin_confirmed' THEN now() ELSE ots_confirmed_at END,
    bitcoin_block_height = coalesce(p_block_height, bitcoin_block_height),
    updated_at           = now()
  WHERE id = p_doc_id;
END $$;


ALTER FUNCTION "public"."vendor_document_record_anchor"("p_doc_id" "uuid", "p_status" "text", "p_calendar" "text", "p_ots_proof" "text", "p_block_height" bigint) OWNER TO "postgres";


