CREATE OR REPLACE FUNCTION "public"."vendor_document_seal"("p_storage_path" "text", "p_content_sha256" "text", "p_doc_type" "text" DEFAULT 'other'::"text", "p_title" "text" DEFAULT NULL::"text", "p_mime_type" "text" DEFAULT NULL::"text", "p_byte_size" bigint DEFAULT NULL::bigint, "p_bound_type" "text" DEFAULT 'vendor'::"text", "p_bound_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."vendor_documents"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid        uuid := auth.uid();
  v_existing   public.vendor_documents;
  v_payload    jsonb;
  v_seal       text;
  v_doc_type   text := lower(coalesce(p_doc_type,'other'));
  v_bound_type text := lower(coalesce(p_bound_type,'vendor'));
  v_row        public.vendor_documents;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF coalesce(p_storage_path,'')   = '' THEN RAISE EXCEPTION 'storage_path_required'; END IF;
  IF coalesce(p_content_sha256,'') = '' THEN RAISE EXCEPTION 'content_hash_required'; END IF;
  IF v_doc_type NOT IN ('iso_cert','accreditation','insurance','financial','nda','msa','technical_proposal','mill_cert','other') THEN
    v_doc_type := 'other'; END IF;
  IF v_bound_type NOT IN ('vendor','quote','contract','job') THEN v_bound_type := 'vendor'; END IF;

  -- idempotent: identical content already sealed by this vendor → return it
  SELECT * INTO v_existing FROM public.vendor_documents
    WHERE vendor_id = v_uid AND content_sha256 = lower(p_content_sha256) AND status = 'active' LIMIT 1;
  IF FOUND THEN RETURN v_existing; END IF;

  -- canonical-JSON SEAL over content hash + metadata + identity (same spine as pi_seal)
  v_payload := jsonb_build_object(
    'kind','vendor_document', 'v', 1,
    'vendor_id',      v_uid,
    'doc_type',       v_doc_type,
    'content_sha256', lower(p_content_sha256),
    'byte_size',      p_byte_size,
    'mime_type',      p_mime_type,
    'storage_path',   p_storage_path,
    'bound_type',     v_bound_type,
    'bound_id',       p_bound_id,
    'issued_at',      now()
  );
  v_seal := encode(digest(public.pi_canonical_json(v_payload), 'sha256'), 'hex');

  INSERT INTO public.vendor_documents (
    vendor_id, doc_type, title, storage_path, mime_type, byte_size,
    content_sha256, seal_sha256, seal_payload, ots_status, bound_type, bound_id
  ) VALUES (
    v_uid, v_doc_type, p_title, p_storage_path, p_mime_type, p_byte_size,
    lower(p_content_sha256), v_seal, v_payload, 'pending', v_bound_type, p_bound_id
  ) RETURNING * INTO v_row;

  RETURN v_row;
END $$;


ALTER FUNCTION "public"."vendor_document_seal"("p_storage_path" "text", "p_content_sha256" "text", "p_doc_type" "text", "p_title" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_bound_type" "text", "p_bound_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wallet_credit_topup"("p_user_id" "uuid", "p_amount_halalas" bigint, "p_stripe_payment_intent_id" "text", "p_transaction_ref_id" "uuid", "p_correlation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_correlation        uuid := COALESCE(p_correlation_id, gen_random_uuid());
  v_already_credited   boolean := false;
  v_new_balance        bigint;
  v_row_exists         boolean;
BEGIN
  -- ── 1. Input validation ─────────────────────────────────────────
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'user_id is required' USING ERRCODE = '22000';
  END IF;
  IF p_amount_halalas IS NULL OR p_amount_halalas <= 0 THEN
    RAISE EXCEPTION 'amount_halalas must be positive' USING ERRCODE = '22000';
  END IF;
  IF p_amount_halalas > 1000000 THEN
    RAISE EXCEPTION 'amount_halalas exceeds per-topup cap (1,000,000)'
      USING ERRCODE = '22000';
  END IF;
  IF p_stripe_payment_intent_id IS NULL
     OR length(trim(p_stripe_payment_intent_id)) = 0 THEN
    RAISE EXCEPTION 'stripe_payment_intent_id is required' USING ERRCODE = '22000';
  END IF;
  IF p_transaction_ref_id IS NULL THEN
    RAISE EXCEPTION 'transaction_ref_id is required' USING ERRCODE = '22000';
  END IF;

  -- ── 2. Idempotency check ────────────────────────────────────────
  IF EXISTS (
    SELECT 1 FROM public.transactions
    WHERE description = ('wallet_topup:' || p_stripe_payment_intent_id)
  ) THEN
    v_already_credited := true;

    -- ★ DRIFT FIX: read by user_id, not inspector_id.
    SELECT available_balance_halalas
      INTO v_new_balance
      FROM public.inspector_earnings
     WHERE user_id = p_user_id;

    PERFORM public.audit_set_correlation(v_correlation);
    PERFORM public.audit_set_intent(
      'Wallet top-up duplicate (pi=' || p_stripe_payment_intent_id || ')'
    );
    INSERT INTO public.audit_events (
      event_type, severity,
      actor_id, actor_role, actor_label,
      subject_table, subject_id, job_id,
      summary, delta, metadata, correlation_id
    ) VALUES (
      'wallet.topup_duplicate',
      'info',
      NULL, 'system', 'Stripe webhook (wallet topup)',
      'profiles', p_user_id, NULL,
      'Wallet top-up duplicate event received — no double credit',
      '{}'::jsonb,
      jsonb_build_object(
        'user_id', p_user_id,
        'payment_intent_id', p_stripe_payment_intent_id,
        'transaction_ref_id', p_transaction_ref_id,
        'amount_halalas', p_amount_halalas
      ),
      v_correlation
    );

    RETURN jsonb_build_object(
      'ok', true,
      'user_id', p_user_id,
      'amount_halalas', p_amount_halalas,
      'already_credited', true,
      'new_balance_halalas', v_new_balance,
      'correlation_id', v_correlation
    );
  END IF;

  -- ── 3. Ensure the inspector_earnings row exists ─────────────────
  -- ★ DRIFT FIX: replaced the ON CONFLICT (inspector_id) UPSERT with a
  --   defensive NOT-EXISTS pattern. ON CONFLICT requires a unique
  --   constraint on the target column; we don't have a confirmed
  --   UNIQUE on user_id in the live schema (the on-disk migration only
  --   declares a non-unique index). The NOT EXISTS pattern works
  --   regardless and is safe under the SECURITY DEFINER scope.
  SELECT EXISTS (
    SELECT 1 FROM public.inspector_earnings WHERE user_id = p_user_id
  ) INTO v_row_exists;

  IF NOT v_row_exists THEN
    INSERT INTO public.inspector_earnings (
      user_id, available_balance_halalas, total_earned_halalas
    )
    VALUES (p_user_id, 0, 0);
  END IF;

  -- ── 4. Credit the wallet ────────────────────────────────────────
  PERFORM public.audit_set_correlation(v_correlation);
  PERFORM public.audit_set_intent(
    'Wallet top-up credited (pi=' || p_stripe_payment_intent_id || ')'
  );

  UPDATE public.inspector_earnings
     SET available_balance_halalas = available_balance_halalas + p_amount_halalas,
         updated_at = now()
   WHERE user_id = p_user_id
  RETURNING available_balance_halalas INTO v_new_balance;

  -- Note: deliberately NOT bumping total_earned_halalas — that tracks
  -- money earned FROM jobs, not money pre-loaded by the inspector. Same
  -- rationale as the original migration.

  -- ── 5. Record the transaction ──────────────────────────────────
  -- ★ DRIFT FIX: insert into BOTH user_id (canonical) and inspector_id
  --   (legacy NOT NULL) with the same value. The information_schema
  --   probe confirmed both columns exist on transactions in the live
  --   schema; the original CREATE TABLE migration declared inspector_id
  --   as NOT NULL, so we must populate it or the INSERT fails.
  INSERT INTO public.transactions (
    user_id,
    inspector_id,
    job_id,
    description,
    gross_amount_halalas,
    platform_fee_halalas,
    status
  ) VALUES (
    p_user_id,
    p_user_id,
    NULL,
    'wallet_topup:' || p_stripe_payment_intent_id,
    p_amount_halalas,
    0,
    'paid'
  );

  -- ── 6. Audit event ──────────────────────────────────────────────
  INSERT INTO public.audit_events (
    event_type, severity,
    actor_id, actor_role, actor_label,
    subject_table, subject_id, job_id,
    summary, delta, metadata, correlation_id
  ) VALUES (
    'wallet.topup_credited',
    'info',
    NULL, 'system', 'Stripe webhook (wallet topup)',
    'profiles', p_user_id, NULL,
    'Wallet credited: ' ||
      to_char(p_amount_halalas::numeric / 100, 'FM999G999G990D00') ||
      ' SAR',
    jsonb_build_object(
      'after', jsonb_build_object(
        'available_balance_halalas', v_new_balance
      )
    ),
    jsonb_build_object(
      'user_id', p_user_id,
      'amount_halalas', p_amount_halalas,
      'payment_intent_id', p_stripe_payment_intent_id,
      'transaction_ref_id', p_transaction_ref_id
    ),
    v_correlation
  );

  RETURN jsonb_build_object(
    'ok', true,
    'user_id', p_user_id,
    'amount_halalas', p_amount_halalas,
    'already_credited', false,
    'new_balance_halalas', v_new_balance,
    'correlation_id', v_correlation
  );
END;
$$;


ALTER FUNCTION "public"."wallet_credit_topup"("p_user_id" "uuid", "p_amount_halalas" bigint, "p_stripe_payment_intent_id" "text", "p_transaction_ref_id" "uuid", "p_correlation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."wallet_credit_topup"("p_user_id" "uuid", "p_amount_halalas" bigint, "p_stripe_payment_intent_id" "text", "p_transaction_ref_id" "uuid", "p_correlation_id" "uuid") IS 'WALLET-DEPOSIT-001 + WALLET-SCHEMA-DRIFT-001 fix: aligns reads/writes with the live inspector_earnings.user_id column (not inspector_id) and populates both transactions.user_id + transactions.inspector_id for legacy NOT NULL compat.';



CREATE OR REPLACE FUNCTION "public"."withdraw_revision"("p_revision_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_r public.deal_revisions;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT * INTO v_r FROM public.deal_revisions WHERE id = p_revision_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown_revision'; END IF;
  IF v_r.counterparty_id <> v_uid THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF v_r.status NOT IN ('requested','countered') THEN RAISE EXCEPTION 'REVISION_NOT_OPEN'; END IF;
  UPDATE public.deal_revisions SET status = 'withdrawn', decided_at = now() WHERE id = p_revision_id;
  PERFORM public._revision_log(p_revision_id, v_uid, public._revision_role(v_r.kind), 'withdraw', NULL, NULL, p_note);
  RETURN jsonb_build_object('revision_id', p_revision_id, 'status', 'withdrawn');
END $$;


