CREATE OR REPLACE VIEW "public"."admin_dispute_summary" AS
 SELECT "d"."id" AS "dispute_id",
    "d"."status" AS "dispute_status",
    "d"."priority",
    "d"."reason_category",
    "d"."created_at",
    "p"."title" AS "project_title",
    "p"."status" AS "project_status",
    "client"."full_name" AS "client_name",
    "inspector"."full_name" AS "inspector_name"
   FROM ((("public"."disputes" "d"
     JOIN "public"."work_orders" "p" ON (("d"."project_id" = "p"."id")))
     JOIN "public"."profiles" "client" ON (("d"."raised_by" = "client"."id")))
     LEFT JOIN "public"."profiles" "inspector" ON (("p"."inspector_id" = "inspector"."id")));


