COMMENT ON TABLE "public"."certifications" IS 'Stores professional certifications for inspectors';



COMMENT ON COLUMN "public"."certifications"."name" IS 'Name of the certification (e.g., CGSB MT Level 2)';



COMMENT ON COLUMN "public"."certifications"."issuing_organization" IS 'Organization that issued the certification';



COMMENT ON COLUMN "public"."certifications"."issue_date" IS 'Date when the certification was issued';



COMMENT ON COLUMN "public"."certifications"."expiry_date" IS 'Date when the certification expires';



COMMENT ON COLUMN "public"."certifications"."credential_id" IS 'Optional credential or certificate ID number';



COMMENT ON COLUMN "public"."certifications"."file_url" IS 'URL to the uploaded certificate document';



COMMENT ON COLUMN "public"."certifications"."status" IS 'Verification status: pending, verified, or rejected';



COMMENT ON COLUMN "public"."certifications"."rejection_reason" IS 'Reason for rejection if status is rejected';



COMMENT ON COLUMN "public"."certifications"."verified_at" IS 'Timestamp when certification was verified';



COMMENT ON COLUMN "public"."certifications"."verified_by" IS 'Admin user who verified the certification';



CREATE OR REPLACE VIEW "public"."certification_stats" AS
 SELECT "user_id",
    "count"(*) AS "total_certifications",
    "count"(*) FILTER (WHERE ("status" = 'verified'::"text")) AS "verified_count",
    "count"(*) FILTER (WHERE ("status" = 'pending'::"text")) AS "pending_count",
    "count"(*) FILTER (WHERE ("status" = 'rejected'::"text")) AS "rejected_count",
    "count"(*) FILTER (WHERE ("expiry_date" < CURRENT_DATE)) AS "expired_count",
    "count"(*) FILTER (WHERE (("expiry_date" >= CURRENT_DATE) AND ("expiry_date" <= (CURRENT_DATE + '90 days'::interval)))) AS "expiring_soon_count"
   FROM "public"."certifications"
  GROUP BY "user_id";


