    CONSTRAINT "inspector_engagement_meta_object_reason_check" CHECK ((("object_reason" IS NULL) OR ("object_reason" = ANY (ARRAY['scope_mismatch'::"text", 'certification_concern'::"text", 'conflict_of_interest'::"text", 'prior_issue'::"text", 'other'::"text"]))))
);


