CREATE OR REPLACE VIEW "public"."client_assigned_inspector_view" WITH ("security_barrier"='true') AS
 SELECT "m"."deal_id",
    ('NX-'::"text" || "upper"("substr"("encode"("extensions"."digest"(("m"."inspector_id")::"text", 'sha256'::"text"), 'hex'::"text"), 1, 8))) AS "handle",
    "m"."dossier",
    "m"."certificate",
    "m"."independence",
    "m"."artifacts_seal_id",
    "m"."client_review",
    "m"."review_deadline",
    "m"."identity_revealed_at",
    "a"."status" AS "engagement_status",
    "d"."transparency_tier",
    "j"."admin_confirmed_at" AS "report_confirmed_at",
        CASE
            WHEN ("public"."nx_is_admin"() OR ("j"."admin_confirmed_at" IS NOT NULL) OR ("m"."identity_revealed_at" IS NOT NULL)) THEN "p"."full_name"
            ELSE NULL::"text"
        END AS "inspector_legal_name",
        CASE
            WHEN ("public"."nx_is_admin"() OR ("j"."admin_confirmed_at" IS NOT NULL) OR ("m"."identity_revealed_at" IS NOT NULL)) THEN "sig"."signed_name"
            ELSE NULL::"text"
        END AS "inspector_signature"
   FROM ((((("public"."inspector_engagement_meta" "m"
     JOIN "public"."agreements" "a" ON (("a"."id" = "m"."agreement_id")))
     JOIN "public"."deals" "d" ON (("d"."id" = "m"."deal_id")))
     JOIN "public"."profiles" "p" ON (("p"."id" = "m"."inspector_id")))
     LEFT JOIN "public"."jobs" "j" ON (("j"."id" = "d"."job_id")))
     LEFT JOIN LATERAL ( SELECT "s"."signed_name"
           FROM "public"."agreement_signatures" "s"
          WHERE (("s"."agreement_id" = "m"."agreement_id") AND ("s"."party_role" = 'inspector'::"text"))
          ORDER BY "s"."signed_at" DESC
         LIMIT 1) "sig" ON (true))
  WHERE (("d"."client_id" = "auth"."uid"()) OR "public"."nx_is_admin"());


ALTER VIEW "public"."client_assigned_inspector_view" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."client_deal_view" WITH ("security_barrier"='true') AS
 SELECT "d"."id" AS "deal_id",
    "d"."status" AS "deal_status",
    "d"."client_price_cents",
    "d"."currency",
    "d"."transparency_tier",
    "d"."rfq_id",
    "d"."job_id",
    "d"."created_at",
    "a"."id" AS "client_agreement_id",
    "a"."status" AS "client_agreement_status",
    "a"."seal_id" AS "client_agreement_seal_id",
    "a"."presented_at",
    "a"."executed_at"
   FROM ("public"."deals" "d"
     LEFT JOIN LATERAL ( SELECT "x"."id",
            "x"."deal_id",
            "x"."kind",
            "x"."status",
            "x"."version",
            "x"."supersedes_id",
            "x"."counterparty_id",
            "x"."amount_cents",
            "x"."currency",
            "x"."body_md",
            "x"."content_sha256",
            "x"."ots_proof",
            "x"."ots_status",
            "x"."seal_id",
            "x"."presented_at",
            "x"."signed_at",
            "x"."countersigned_at",
            "x"."executed_at",
            "x"."voided_at",
            "x"."voided_reason",
            "x"."generated_by",
            "x"."created_at",
            "x"."updated_at"
           FROM "public"."agreements" "x"
          WHERE (("x"."deal_id" = "d"."id") AND ("x"."kind" = 'client_supply'::"text"))
          ORDER BY "x"."version" DESC
         LIMIT 1) "a" ON (true))
  WHERE (("d"."client_id" = "auth"."uid"()) OR "public"."nx_is_admin"());


