CREATE OR REPLACE VIEW "public"."dev_sso_signup_check" AS
 SELECT "u"."id" AS "auth_user_id",
    "u"."email",
    "u"."created_at" AS "auth_created_at",
    "p"."role" AS "profile_role",
    "p"."organization_id" AS "profile_org_id",
    "ed"."display_name" AS "expected_org_display_name",
    "ed"."organization_id" AS "expected_org_id",
        CASE
            WHEN ("p"."id" IS NULL) THEN 'PROFILE_MISSING — trigger did not fire'::"text"
            WHEN ("ed"."organization_id" IS NULL) THEN 'NO_ENTERPRISE_DOMAIN — domain not in table'::"text"
            WHEN ("p"."organization_id" IS DISTINCT FROM "ed"."organization_id") THEN 'ORG_MISMATCH — trigger fired but lookup failed'::"text"
            ELSE 'OK'::"text"
        END AS "verdict"
   FROM (("auth"."users" "u"
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "u"."id")))
     LEFT JOIN "public"."enterprise_domains" "ed" ON ((("ed"."domain" = "lower"("split_part"(("u"."email")::"text", '@'::"text", 2))) AND ("ed"."is_active" = true))))
  ORDER BY "u"."created_at" DESC;


ALTER VIEW "public"."dev_sso_signup_check" OWNER TO "postgres";


