CREATE TABLE IF NOT EXISTS "public"."flash_reports" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "job_id" "uuid" NOT NULL,
    "reporter_id" "uuid" NOT NULL,
    "reporter_role" "text" NOT NULL,
