    "severity" "text" NOT NULL,
    "title" "text" NOT NULL,
    "description" "text" NOT NULL,
    "location_text" "text",
    "occurred_at" timestamp with time zone,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "acknowledged_at" timestamp with time zone,
    "acknowledged_by" "uuid",
    "resolved_at" timestamp with time zone,
    "resolved_by" "uuid",
    "resolution_notes" "text",
    "correlation_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "flash_reports_acknowledgement_pair" CHECK (((("acknowledged_at" IS NULL) AND ("acknowledged_by" IS NULL)) OR (("acknowledged_at" IS NOT NULL) AND ("acknowledged_by" IS NOT NULL)))),
    CONSTRAINT "flash_reports_category_check" CHECK (("category" = ANY (ARRAY['calibration'::"text", 'documentation'::"text", 'safety'::"text", 'procedure'::"text", 'defect'::"text", 'client_interference'::"text", 'other'::"text"]))),
    CONSTRAINT "flash_reports_description_len" CHECK ((("length"("description") >= 20) AND ("length"("description") <= 5000))),
    CONSTRAINT "flash_reports_reporter_role_check" CHECK (("reporter_role" = ANY (ARRAY['inspector'::"text", 'client'::"text", 'agency'::"text", 'super_admin'::"text"]))),
    CONSTRAINT "flash_reports_resolution_pair" CHECK (((("resolved_at" IS NULL) AND ("resolved_by" IS NULL)) OR (("resolved_at" IS NOT NULL) AND ("resolved_by" IS NOT NULL)))),
    CONSTRAINT "flash_reports_severity_check" CHECK (("severity" = ANY (ARRAY['observation'::"text", 'minor'::"text", 'major'::"text", 'critical'::"text"]))),
    CONSTRAINT "flash_reports_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'acknowledged'::"text", 'in_remediation'::"text", 'resolved'::"text", 'closed'::"text", 'disputed'::"text"]))),
    CONSTRAINT "flash_reports_title_len" CHECK ((("length"("title") >= 8) AND ("length"("title") <= 160)))
);


ALTER TABLE "public"."flash_reports" OWNER TO "postgres";


