CREATE OR REPLACE VIEW "public"."inspector_profile_smoke_test" AS
 SELECT 'profiles.specialty_slugs'::"text" AS "check",
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM "information_schema"."columns"
              WHERE ((("columns"."table_schema")::"name" = 'public'::"name") AND (("columns"."table_name")::"name" = 'profiles'::"name") AND (("columns"."column_name")::"name" = 'specialty_slugs'::"name")))) THEN 'ok'::"text"
            ELSE 'MISSING'::"text"
        END AS "status"
UNION ALL
 SELECT 'profiles.ndt_methods'::"text" AS "check",
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM "information_schema"."columns"
              WHERE ((("columns"."table_schema")::"name" = 'public'::"name") AND (("columns"."table_name")::"name" = 'profiles'::"name") AND (("columns"."column_name")::"name" = 'ndt_methods'::"name")))) THEN 'ok'::"text"
            ELSE 'MISSING'::"text"
        END AS "status"
UNION ALL
 SELECT 'profiles.resume_path'::"text" AS "check",
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM "information_schema"."columns"
              WHERE ((("columns"."table_schema")::"name" = 'public'::"name") AND (("columns"."table_name")::"name" = 'profiles'::"name") AND (("columns"."column_name")::"name" = 'resume_path'::"name")))) THEN 'ok'::"text"
            ELSE 'MISSING'::"text"
        END AS "status"
UNION ALL
 SELECT 'bucket: resumes'::"text" AS "check",
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM "storage"."buckets"
              WHERE ("buckets"."id" = 'resumes'::"text"))) THEN 'ok'::"text"
            ELSE 'MISSING'::"text"
        END AS "status"
UNION ALL
 SELECT 'bucket: avatars'::"text" AS "check",
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM "storage"."buckets"
              WHERE ("buckets"."id" = 'avatars'::"text"))) THEN 'ok'::"text"
            ELSE 'MISSING'::"text"
        END AS "status"
UNION ALL
 SELECT 'bucket: chat_attachments'::"text" AS "check",
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM "storage"."buckets"
              WHERE ("buckets"."id" = 'chat_attachments'::"text"))) THEN 'ok'::"text"
            ELSE 'MISSING'::"text"
        END AS "status";


ALTER VIEW "public"."inspector_profile_smoke_test" OWNER TO "postgres";


