    CONSTRAINT "model_artifacts_size_bytes_check" CHECK (("size_bytes" > 0)),
    CONSTRAINT "model_artifacts_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'published'::"text", 'deprecated'::"text", 'revoked'::"text"]))),
    CONSTRAINT "model_artifacts_tier_check" CHECK (("tier" = ANY (ARRAY['teacher'::"text", 'student'::"text"]))),
