CREATE OR REPLACE VIEW "public"."rfq_client_offers_view" AS
 SELECT "q"."id",
    "q"."rfq_id",
    "q"."client_price_cents" AS "price_cents",
    "q"."status",
    "q"."presented_at",
    "q"."created_at",
    NULLIF(("q"."quote" ->> 'lead_time'::"text"), ''::"text") AS "lead_time",
    ('NX-'::"text" || "upper"("substr"("encode"("extensions"."digest"(("q"."supplier_id")::"text", 'sha256'::"text"), 'hex'::"text"), 1, 6))) AS "supplier_handle"
   FROM ("public"."supplier_quotes" "q"
     JOIN "public"."supplier_rfqs" "r" ON (("r"."id" = "q"."rfq_id")))
  WHERE (("q"."status" = ANY (ARRAY['presented'::"text", 'accepted'::"text", 'declined'::"text"])) AND ("q"."client_price_cents" IS NOT NULL) AND (("r"."client_id" = "auth"."uid"()) OR "public"."nx_is_admin"()));


