CREATE OR REPLACE VIEW "public"."v_certifications_with_status" AS
 SELECT "cc"."id",
    "cc"."contractor_id",
    "cc"."title",
    "cc"."issued_by",
    "cc"."expiry_date",
    "cc"."cert_url",
    "cc"."status",
    "cc"."created_at",
    "c"."full_name" AS "contractor_name",
    "c"."email" AS "contractor_email",
    ("cc"."expiry_date" - CURRENT_DATE) AS "days_until_expiry",
        CASE
            WHEN ("cc"."expiry_date" < CURRENT_DATE) THEN 'expired'::"text"
            WHEN ("cc"."expiry_date" = CURRENT_DATE) THEN 'expires_today'::"text"
            WHEN ("cc"."expiry_date" <= (CURRENT_DATE + 7)) THEN 'critical'::"text"
            WHEN ("cc"."expiry_date" <= (CURRENT_DATE + 30)) THEN 'warning'::"text"
            ELSE 'valid'::"text"
        END AS "expiry_status"
   FROM ("public"."contractor_certifications" "cc"
     JOIN "public"."contractors" "c" ON (("cc"."contractor_id" = "c"."id")))
  WHERE ("cc"."status" = 'active'::"text");


ALTER VIEW "public"."v_certifications_with_status" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_cron_job_status" AS
 SELECT "j"."jobname",
    "j"."schedule",
    "j"."command",
    "jrd"."status",
    "jrd"."start_time",
    "jrd"."end_time",
    "jrd"."return_message",
    ("jrd"."end_time" - "jrd"."start_time") AS "duration"
   FROM ("cron"."job" "j"
     LEFT JOIN "cron"."job_run_details" "jrd" ON (("j"."jobid" = "jrd"."jobid")))
  ORDER BY "jrd"."start_time" DESC;


